function shouldSuppressDuplicateFrontendChatMessage(topic = '', payload = {}) {
  if (topic !== 'chat.message.sent' && topic !== 'chat.message.received' && topic !== 'chat.message.anchored') return false;
  const safePayload = payload && typeof payload === 'object' ? payload : {};
  const key = [
    topic,
    String(safePayload.selfWalletId || '').trim(),
    String(safePayload.peerWalletId || '').trim(),
    String(safePayload.msgId || '').trim(),
    String(safePayload.txid || '').trim(),
    String(safePayload.status || '').trim(),
    String(safePayload.transport || '').trim(),
  ].join('|');
  if (!key.includes('wallet-') && !String(safePayload.msgId || '').trim()) return false;
  const now = Date.now();
  for (const [existingKey, seenAt] of recentFrontendChatMessageEvents.entries()) {
    if (now - Number(seenAt || 0) > 30000) recentFrontendChatMessageEvents.delete(existingKey);
  }
  const previousAt = Math.max(0, Number(recentFrontendChatMessageEvents.get(key) || 0));
  recentFrontendChatMessageEvents.set(key, now);
  return previousAt > 0 && (now - previousAt) < 30000;
}

