function loadLocalEnvFile() {
  if (process.platform !== 'win32') return;
  const envPath = path.join(__dirname, '.env.market');
  if (!fs.existsSync(envPath)) return;
  try {
    const lines = fs.readFileSync(envPath, 'utf8').split(/\r?\n/);
    for (const raw of lines) {
      const line = String(raw || '').trim();
      if (!line || line.startsWith('#')) continue;
      const eq = line.indexOf('=');
      if (eq <= 0) continue;
      const key = line.slice(0, eq).trim();
      if (!key || Object.prototype.hasOwnProperty.call(process.env, key)) continue;
      let val = line.slice(eq + 1).trim();
      if (
        (val.startsWith('"') && val.endsWith('"'))
        || (val.startsWith("'") && val.endsWith("'"))
      ) {
        val = val.slice(1, -1);
      }
      process.env[key] = val;
    }
  } catch (_) {}
}
loadLocalEnvFile();

function updateRuntimeBhsTipSnapshot(payload = {}, meta = {}) {
  const tipHeight = Math.max(0, Number(payload?.tipHeight || 0));
  const tipHash = String(payload?.tipHash || '').trim().toLowerCase();
  const updatedAt = String(meta?.ts || payload?.updatedAt || new Date().toISOString());
  if (tipHeight <= 0) return runtimeBhsTipSnapshot;
  const currentHeight = Math.max(0, Number(runtimeBhsTipSnapshot?.tipHeight || 0));
  const currentTs = Date.parse(String(runtimeBhsTipSnapshot?.updatedAt || '')) || 0;
  const nextTs = Date.parse(updatedAt) || 0;
  if (tipHeight < currentHeight) return runtimeBhsTipSnapshot;
  if (tipHeight === currentHeight && nextTs > 0 && currentTs > nextTs) return runtimeBhsTipSnapshot;
  runtimeBhsTipSnapshot = {
    tipHeight,
    tipHash: /^[0-9a-f]{64}$/i.test(tipHash) ? tipHash : String(runtimeBhsTipSnapshot?.tipHash || ''),
    updatedAt,
  };
  return runtimeBhsTipSnapshot;
}

function ensureRuntimeBhsTipSubscription() {
  if (runtimeBhsTipSubscribed) return;
  runtimeBhsTipSubscribed = true;
  messageQueue.subscribe('bhs.tip.changed', (payload, meta) => {
    updateRuntimeBhsTipSnapshot(payload, meta);
  });
}

ensureRuntimeBhsTipSubscription();

function ensureFrontendEventGatewaySubscriptions() {
  if (frontendEventGatewaySubscribed) return;
  frontendEventGatewaySubscribed = true;
  messageQueue.subscribe('*', (_payload, meta = {}) => {
    const topic = String(meta?.topic || '').trim();
    const reason = String(meta?.reason || topic || '').trim();
    if (!topic) return;
    if (
      frontendEventGateway
      && (topic === 'chat.message.sent' || topic === 'chat.message.received' || topic === 'chat.message.anchored')
    ) {
      const payload = _payload && typeof _payload === 'object' ? _payload : {};
      if (shouldSuppressDuplicateFrontendChatMessage(topic, payload)) return;
      const selfWalletId = String(payload.selfWalletId || '').trim();
      const peerWalletId = String(payload.peerWalletId || '').trim();
      const msgId = String(payload.msgId || '').trim();
      if (selfWalletId && peerWalletId && msgId) {
        frontendEventGateway.publishInfo('chat.message.appended', 'chat', {
          message: {
            selfWalletId,
            walletId: peerWalletId,
            peerWalletId,
            msgId,
            sessionId: String(payload.sessionId || '').trim(),
            direction: String(payload.direction || '').trim(),
            transport: topic === 'chat.message.anchored' && msgId.startsWith('p2p:') && String(payload.transport || '').trim() === 'onchain'
              ? 'p2p'
              : String(payload.transport || '').trim(),
            text: String(payload.text || ''),
            orderId: String(payload.orderId || '').trim(),
            ts: String(payload.ts || meta?.ts || new Date().toISOString()),
            status: String(payload.status || '').trim(),
            txid: String(payload.txid || '').trim(),
            displayName: String(payload.displayName || peerWalletId).trim(),
          },
        });
      }
    }
    if (frontendEventGateway && topic.startsWith('catalog.category.')) {
      const payload = _payload && typeof _payload === 'object' ? _payload : {};
      const id = String(payload.id || '').trim();
      if (id) {
        const type = topic === 'catalog.category.deleted'
          ? 'catalog.category.deleted'
          : (Number(payload.version || 0) <= 1 ? 'catalog.category.added' : 'catalog.category.updated');
        frontendEventGateway.publishInfo(type, 'catalog', { category: payload });
      }
      return;
    }
    if (frontendEventGateway && topic.startsWith('catalog.product.')) {
      const payload = _payload && typeof _payload === 'object' ? _payload : {};
      const id = String(payload.id || '').trim();
      if (id) {
        const type = topic === 'catalog.product.deleted'
          ? 'catalog.product.deleted'
          : (Number(payload.version || 0) <= 1 ? 'catalog.product.added' : 'catalog.product.updated');
        frontendEventGateway.publishInfo(type, 'catalog', { product: payload });
      }
      return;
    }
    if (frontendEventGateway && topic === 'order.updated') {
      const payload = _payload && typeof _payload === 'object' ? _payload : {};
      const id = String(payload.id || payload.orderId || '').trim();
      if (id) {
        frontendEventGateway.publishInfo('order.updated', 'order', { order: payload });
      }
      return;
    }
    if (
      topic === 'sync.runtime.updated'
      || topic === 'wallet.index.updated'
      || topic === 'wallet.read_model.updated'
      || topic === 'profile.updated'
      || topic === 'local_state.updated'
      || topic.startsWith('chat.')
      || topic.startsWith('bhs.')
    ) {
      scheduleMappedFrontendBroadcast(topic, reason, topic === 'sync.runtime.updated' ? 180 : 80, true, 'message_queue', _payload);
    }
  });
}

