function handleViewStateWorkerMessage(msg) {
  if (!msg || typeof msg !== 'object') return;
  const type = String(msg.type || '').trim();
  const activity = type
    ? beginRuntimeActivity('view_state_worker_message', { type })
    : null;
  try {
    if (type === 'auth.query') {
      notifyWorkerAuthSnapshot(viewStateWorker, 'auth.snapshot', { source: 'view_state_query_reply' });
      return;
    }
    if (type === 'market_db_proxy_request') {
      void handleWorkerMarketDbProxyRequest(viewStateWorker, msg, 'view_state');
      return;
    }
    if (type === 'wallet_tx_context_upsert') {
      handleWorkerWalletTxContextUpsert(msg, 'view_state');
      return;
    }
    if (type !== 'publicStateCacheUpdated') return;
    if (!msg.envelope || typeof msg.envelope !== 'object') return;
    getPublicViewCacheService().setEnvelope(msg.envelope);
    invalidateStateLiteSnapshotCache('view_state_worker_cache_updated');
    scheduleMappedFrontendBroadcast('view_state_worker_cache_updated', String(msg.reason || 'view_state_worker_cache_updated'), 60, true, 'view_state_worker');
  } finally {
    if (activity) endRuntimeActivity(activity, { type });
  }
}

function getBestSpvSnapshot(limit = 8, options = {}) {
  const cap = Math.max(1, Math.min(Number(limit) || 8, 100));
  const allowLiveFallback = options?.allowLiveFallback !== false;
  const now = Date.now();
  const mergeWithLiveFallback = (baseSnapshot) => {
    if (!allowLiveFallback) return baseSnapshot;
    const needConnected = Number(baseSnapshot?.connectedCount || 0) > 0 && (!Array.isArray(baseSnapshot?.connected) || baseSnapshot.connected.length === 0);
    const needCandidates = Number(baseSnapshot?.candidateCount || 0) > 0 && (!Array.isArray(baseSnapshot?.candidates) || baseSnapshot.candidates.length === 0);
    if (!needConnected && !needCandidates) return baseSnapshot;
    try {
      const live = wallet.getSpvNodeSnapshot(cap);
      return {
        connectedCount: Math.max(Number(baseSnapshot?.connectedCount || 0), Number(live?.connectedCount || 0)),
        candidateCount: Math.max(Number(baseSnapshot?.candidateCount || 0), Number(live?.candidateCount || 0)),
        totalCount: Math.max(Number(baseSnapshot?.totalCount || 0), Number(live?.totalCount || 0)),
        recentConnected: Math.max(Number(baseSnapshot?.recentConnected || 0), Number(live?.recentConnected || 0)),
        connected: (Array.isArray(baseSnapshot?.connected) && baseSnapshot.connected.length > 0)
          ? baseSnapshot.connected.slice(0, cap)
          : (Array.isArray(live?.connected) ? live.connected.slice(0, cap) : []),
        candidates: (Array.isArray(baseSnapshot?.candidates) && baseSnapshot.candidates.length > 0)
          ? baseSnapshot.candidates.slice(0, cap)
          : (Array.isArray(live?.candidates) ? live.candidates.slice(0, cap) : []),
      };
    } catch (_) {
      return baseSnapshot;
    }
  };
  const snapshotEnvelope = (() => {
    const workerTs = stewardWorkerSpvSnapshot?.ts ? new Date(stewardWorkerSpvSnapshot.ts).getTime() : 0;
    if (workerTs > 0 && (now - workerTs) <= 30000 && stewardWorkerSpvSnapshot?.snapshot) {
      return stewardWorkerSpvSnapshot;
    }
    const fileSnapshot = loadStewardWorkerHeartbeatSnapshot();
    const fileTs = fileSnapshot?.ts ? new Date(fileSnapshot.ts).getTime() : 0;
    if (fileTs > 0 && (now - fileTs) <= 10 * 60 * 1000 && fileSnapshot?.snapshot) {
      return fileSnapshot;
    }
    return null;
  })();
  if (snapshotEnvelope?.snapshot) {
    const snapshot = snapshotEnvelope.snapshot;
    return mergeWithLiveFallback({
      connectedCount: Number(snapshot.connectedCount || 0),
      candidateCount: Number(snapshot.candidateCount || 0),
      totalCount: Number(snapshot.totalCount || 0),
      recentConnected: Number(snapshot.recentConnected || 0),
      connected: Array.isArray(snapshot.connected) ? snapshot.connected.slice(0, cap) : [],
      candidates: Array.isArray(snapshot.candidates) ? snapshot.candidates.slice(0, cap) : [],
    });
  }
  if (!allowLiveFallback) {
    return {
      connectedCount: 0,
      candidateCount: 0,
      totalCount: 0,
      recentConnected: 0,
      connected: [],
      candidates: [],
    };
  }
  try {
    return wallet.getSpvNodeSnapshot(cap);
  } catch (_) {
    return {
      connectedCount: 0,
      candidateCount: 0,
      totalCount: 0,
      recentConnected: 0,
      connected: [],
      candidates: [],
    };
  }
}

function getEffectiveSpvWorkingCount(snapshot) {
  const connectedCount = Number(snapshot?.connectedCount || 0);
  const connectedLen = Array.isArray(snapshot?.connected) ? snapshot.connected.length : 0;
  return Math.max(connectedCount, connectedLen);
}

function getWalletDisplayNodeSnapshot(limit = 20, options = {}) {
  try {
    if (typeof wallet.getWalletDisplayNodeSnapshot === 'function') {
      return wallet.getWalletDisplayNodeSnapshot(limit);
    }
  } catch (_) {}
  return getBestSpvSnapshot(limit, options);
}

function getUnifiedOnlineNodeSnapshot(limit = 20) {
  const cap = Math.max(1, Math.min(Number(limit) || 20, 100));
  const spv = getBestSpvSnapshot(cap, { allowLiveFallback: false });
  const selectorSnapshot = typeof p2pNodeSelector?.getSnapshot === 'function'
    ? p2pNodeSelector.getSnapshot()
    : { activeLeases: [], health: {} };
  const syncWorker = getIndependentSyncDisplaySnapshot();
  const now = Date.now();
  const recentSuccessWindowMs = 10 * 60 * 1000;
  const nodes = [];
  const pushNode = (endpoint) => {
    const value = String(endpoint || '').trim();
    if (!value) return;
    if (!nodes.includes(value)) nodes.push(value);
  };

  (Array.isArray(spv.connected) ? spv.connected : []).forEach((row) => pushNode(row?.endpoint || row));
  (Array.isArray(selectorSnapshot.activeLeases) ? selectorSnapshot.activeLeases : [])
    .forEach((lease) => pushNode(lease?.node));
  (Array.isArray(syncWorker.activeNodes) ? syncWorker.activeNodes : []).forEach((node) => pushNode(node));

  return {
    count: nodes.length,
    nodes: nodes.slice(0, cap),
  };
}

function getUnifiedNodeRuntimeSnapshot(limit = 20, options = {}) {
  const cap = Math.max(1, Math.min(Number(limit) || 20, 100));
  const walletSnapshot = options?.walletSnapshot && typeof options.walletSnapshot === 'object'
    ? options.walletSnapshot
    : getWalletDisplayNodeSnapshot(Math.max(cap, 100));
  const selectorSnapshot = typeof p2pNodeSelector?.getSnapshot === 'function'
    ? p2pNodeSelector.getSnapshot()
    : { activeLeases: [] };
  const syncWorker = getIndependentSyncDisplaySnapshot();
  const rows = new Map();
  const ensureNode = (endpoint) => {
    const key = String(endpoint || '').trim();
    if (!key) return null;
    if (!rows.has(key)) {
      rows.set(key, {
        endpoint: key,
        roles: [],
        score: 0,
        listenerScore: 0,
        syncScore: 0,
        sendScore: 0,
        available: false,
        source: '',
      });
    }
    return rows.get(key);
  };
  const addRole = (endpoint, role) => {
    const row = ensureNode(endpoint);
    if (!row) return null;
    if (!row.roles.includes(role)) row.roles.push(role);
    return row;
  };
  const mergeWalletRow = (input, defaultRole) => {
    const endpoint = String(input?.endpoint || '').trim();
    if (!endpoint) return;
    const row = ensureNode(endpoint);
    row.score = Math.max(Number(row.score || 0), Number(input?.score || 0));
    row.listenerScore = Math.max(Number(row.listenerScore || 0), Number(input?.listenerScore || 0));
    row.syncScore = Math.max(Number(row.syncScore || 0), Number(input?.syncScore || 0));
    row.sendScore = Math.max(Number(row.sendScore || 0), Number(input?.sendScore || 0));
    row.available = row.available || input?.available === true;
    row.source = row.source || 'wallet';
    const roles = Array.isArray(input?.roles) && input.roles.length ? input.roles : [defaultRole];
    roles.forEach((role) => {
      const normalized = String(role || '').trim();
      if (!normalized) return;
      if (normalized === 'candidate' && (row.roles.includes('listener') || row.roles.includes('sync_active'))) return;
      addRole(endpoint, normalized);
    });
  };

  (Array.isArray(walletSnapshot.connected) ? walletSnapshot.connected : []).forEach((row) => mergeWalletRow(row, 'listener'));
  (Array.isArray(walletSnapshot.candidates) ? walletSnapshot.candidates : []).forEach((row) => mergeWalletRow(row, 'candidate'));
  (Array.isArray(syncWorker.activeNodes) ? syncWorker.activeNodes : []).forEach((endpoint) => addRole(endpoint, 'sync_active'));
  (Array.isArray(selectorSnapshot.activeLeases) ? selectorSnapshot.activeLeases : []).forEach((lease) => {
    const row = addRole(lease?.node, String(lease?.purpose || '').trim() === 'broadcast' ? 'broadcast' : 'sync_active');
    if (row) row.source = row.source || 'selector';
  });

  const all = Array.from(rows.values()).sort((a, b) => {
    const aConnected = (a.roles.includes('listener') || a.roles.includes('sync_active')) ? 1 : 0;
    const bConnected = (b.roles.includes('listener') || b.roles.includes('sync_active')) ? 1 : 0;
    if (aConnected !== bConnected) return bConnected - aConnected;
    const aPriority = Math.max(Number(a.syncScore || 0), Number(a.listenerScore || 0), Number(a.score || 0));
    const bPriority = Math.max(Number(b.syncScore || 0), Number(b.listenerScore || 0), Number(b.score || 0));
    return bPriority - aPriority;
  });
  const connectedOnly = all.filter((row) => row.roles.includes('listener') || row.roles.includes('sync_active'));

  return {
    connectedCount: connectedOnly.length,
    nodes: connectedOnly.slice(0, cap),
  };
}

function getSelectorActiveNodesByPurpose(purpose = '') {
  const targetPurpose = String(purpose || '').trim();
  const selectorSnapshot = typeof p2pNodeSelector?.getSnapshot === 'function'
    ? p2pNodeSelector.getSnapshot()
    : { activeLeases: [] };
  return Array.from(new Set(
    (Array.isArray(selectorSnapshot.activeLeases) ? selectorSnapshot.activeLeases : [])
      .filter((lease) => !targetPurpose || String(lease?.purpose || '').trim() === targetPurpose)
      .map((lease) => String(lease?.node || '').trim())
      .filter(Boolean),
  ));
}

function countUnifiedNodesByRole(snapshot, role) {
  const target = String(role || '').trim();
  if (!target) return 0;
  return (Array.isArray(snapshot?.nodes) ? snapshot.nodes : [])
    .filter((row) => Array.isArray(row?.roles) && row.roles.includes(target))
    .length;
}

