function notifyStewardSyncNow() {
  if (!stewardWorker || stewardWorker.killed) return;
  const sendNow = () => {
    if (!stewardWorker || stewardWorker.killed) return false;
    stewardSyncNowLastSentAt = Date.now();
    messageQueue.publish('sync.now', {
      reason: 'sync_now_signal',
    }, {
      mode: 'transient',
      source: 'server_market',
    });
    return true;
  };
  if (STEWARD_SYNCNOW_DEBOUNCE_MS <= 0) {
    if (stewardSyncNowTimer) {
      clearTimeout(stewardSyncNowTimer);
      stewardSyncNowTimer = null;
    }
    sendNow();
    return;
  }
  const elapsedMs = Date.now() - stewardSyncNowLastSentAt;
  if (elapsedMs >= STEWARD_SYNCNOW_DEBOUNCE_MS) {
    if (stewardSyncNowTimer) {
      clearTimeout(stewardSyncNowTimer);
      stewardSyncNowTimer = null;
    }
    sendNow();
    return;
  }
  if (stewardSyncNowTimer) return;
  stewardSyncNowTimer = setTimeout(() => {
    stewardSyncNowTimer = null;
    sendNow();
  }, Math.max(1, STEWARD_SYNCNOW_DEBOUNCE_MS - elapsedMs));
  stewardSyncNowTimer.unref?.();
}

async function hasPendingOrClaimedWalletSendCommand() {
  try {
    const [pending, claimed] = await Promise.all([
      messageQueue.listDurable('sync.command', { status: 'pending', limit: 50 }),
      messageQueue.listDurable('sync.command', { status: 'claimed', limit: 50 }),
    ]);
    return [...(Array.isArray(pending) ? pending : []), ...(Array.isArray(claimed) ? claimed : [])]
      .some((row) => String(row?.topic || row?.commandType || '').trim() === 'wallet_send');
  } catch (_) {
    return syncDomain.hasPendingOrClaimedCommand('wallet_send', { fresh: true });
  }
}

function scheduleStewardSyncNow(delayMs = 0) {
  const waitMs = Math.max(0, Number(delayMs || 0));
  if (waitMs <= 0) {
    notifyStewardSyncNow();
    return;
  }
  const timer = setTimeout(() => {
    notifyStewardSyncNow();
  }, waitMs);
  timer.unref?.();
}

function buildSyncDomainConnectedNodeSnapshot() {
  const spv = getWalletDisplayNodeSnapshot(8, { allowLiveFallback: false });
  const onlineNodes = getUnifiedNodeRuntimeSnapshot(20);
  const spvWorkingCount = getEffectiveSpvWorkingCount(spv);
  const syncWorker = getIndependentSyncDisplaySnapshot();
  const allowActiveSyncDisplay = syncWorker.active === true || Number(syncWorker.activeNodeCount || 0) > 0;
  const selectorActiveSyncNodes = allowActiveSyncDisplay ? getSelectorActiveNodesByPurpose('sync_block') : [];
  const activeSyncNodeList = Array.from(new Set([
    ...(Array.isArray(syncWorker.activeNodes) ? syncWorker.activeNodes : []),
    ...selectorActiveSyncNodes,
    ...((allowActiveSyncDisplay && Array.isArray(onlineNodes.nodes) ? onlineNodes.nodes : [])
      .filter((row) => Array.isArray(row?.roles) && row.roles.includes('sync_active'))
      .map((row) => String(row?.endpoint || '').trim())
      .filter(Boolean)),
  ]));
  const heartbeatSnapshot = readJsonFile(STEWARD_HEARTBEAT_FILE, null);
  const spvSnapshot = heartbeatSnapshot?.spvSnapshot || null;
  // Do not call buildLiveSyncPublicSnapshot() here: sync_domain runtime refresh
  // already depends on this adapter, so that path would recurse back into
  // syncDomain.getSyncStatus() and amplify CPU / memory use under load.
  const runtimePolicySync = getTrustedSyncSnapshot(
    applySqliteSyncStateRow({}, loadSyncStateRowFromSqlite()),
  );
  const runtimePolicy = getLagDrivenSyncPolicy({ sync: runtimePolicySync });
  return {
    connectedCount: Math.max(
      0,
      Number(onlineNodes.connectedCount || 0),
      spvWorkingCount + activeSyncNodeList.length,
    ),
    activeSyncNodeCount: activeSyncNodeList.length,
    activeSyncNodeList,
    syncWorkerNodes: allowActiveSyncDisplay ? Number(syncWorker.successNodeCount || 0) : 0,
    syncWorkerNodeList: allowActiveSyncDisplay && Array.isArray(syncWorker.successNodes) ? syncWorker.successNodes : [],
    spvWorkingNodes: spvWorkingCount,
    onlineNodeList: Array.isArray(onlineNodes.nodes)
      ? onlineNodes.nodes.map((row) => {
        if (!row || typeof row !== 'object') return row;
        if (allowActiveSyncDisplay) return row;
        const roles = Array.isArray(row.roles)
          ? row.roles.filter((role) => String(role || '') !== 'sync_active')
          : [];
        return { ...row, roles };
      })
      : [],
    candidateNodeList: Array.isArray(spv.candidates) ? spv.candidates : [],
    candidateNodes: Number(spv.candidateCount || 0),
    totalNodes: Number(spv.totalCount || 0),
    wallet: spvSnapshot
      ? {
          policy: {
            listenerEnabled: runtimePolicy.walletListenerEnabled,
            listenerTarget: runtimePolicy.walletListenerTarget,
            sendEnabled: runtimePolicy.walletSendEnabled,
            reason: runtimePolicy.walletReason,
          },
          peerCount: Number(spvSnapshot.connectedCount || 0),
          connectingCount: 0,
          connectedNodes: Array.isArray(spvSnapshot.connected)
            ? spvSnapshot.connected.map((row) => String(row?.endpoint || '').trim()).filter(Boolean)
            : [],
        }
      : null,
    stewardObservedP2P: spvSnapshot
      ? {
          connectedCount: Number(spvSnapshot.connectedCount || 0),
          recentConnected: Number(spvSnapshot.recentConnected || 0),
          candidateCount: Number(spvSnapshot.candidateCount || 0),
          totalCount: Number(spvSnapshot.totalCount || 0),
          connectedNodes: Array.isArray(spvSnapshot.connected)
            ? spvSnapshot.connected.map((row) => String(row?.endpoint || '').trim()).filter(Boolean)
            : [],
        }
      : null,
  };
}

