function getStewardRestartSyncLag() {
  try {
    const syncRow = loadSyncStateRowFromSqlite();
    const bhsSnapshot = getBhsTipSnapshot();
    const localHeight = Math.max(0, Number(syncRow?.local_height || 0));
    const highestBlock = Math.max(localHeight, Number(bhsSnapshot?.tipHeight || 0));
    return Math.max(0, highestBlock - localHeight);
  } catch (_) {
    return Number.POSITIVE_INFINITY;
  }
}

function getStewardRestartQueueCounts() {
  try {
    const queueState = loadCommandQueueState({ fresh: true });
    const commands = Array.isArray(queueState?.commands) ? queueState.commands : [];
    return {
      pendingCount: commands.filter((row) => String(row?.status || '') === 'pending').length,
      claimedCount: commands.filter((row) => String(row?.status || '') === 'claimed').length,
    };
  } catch (_) {
    return { pendingCount: 0, claimedCount: 0 };
  }
}

function maybeRestartStewardAfterSync(msg = {}) {
  const now = Date.now();
  const rssMb = Math.max(0, Number(msg?.vmRssMb || msg?.rssMb || 0));
  if (rssMb >= STEWARD_RESTART_AFTER_SYNC_RSS_MB) {
    if (!stewardMemoryRestartPending) {
      stewardMemoryRestartPending = true;
      stewardMemoryRestartRequestedAt = now;
      appendMarketDebug('steward_memory_restart_armed', {
        rssMb,
        thresholdMb: STEWARD_RESTART_AFTER_SYNC_RSS_MB,
        phase: String(msg?.phase || ''),
      });
    }
  }
  if (!stewardMemoryRestartPending) return;
  if ((now - stewardLastMemoryRestartAt) < STEWARD_RESTART_COOLDOWN_MS) return;
  const lag = getStewardRestartSyncLag();
  const queueCounts = getStewardRestartQueueCounts();
  const idleLongEnough = (now - stewardMemoryRestartRequestedAt) >= STEWARD_RESTART_MIN_IDLE_MS;
  const queueBusy = Number(queueCounts.pendingCount || 0) > 0 || Number(queueCounts.claimedCount || 0) > 0;
  const syncDone = String(msg?.phase || '') === 'idle';
  if (!idleLongEnough || queueBusy || lag > 0 || !syncDone) return;
  appendMarketDebug('steward_memory_restart_triggered', {
    rssMb,
    thresholdMb: STEWARD_RESTART_AFTER_SYNC_RSS_MB,
    lag,
    queuePendingCount: Number(queueCounts.pendingCount || 0),
    queueClaimedCount: Number(queueCounts.claimedCount || 0),
    phase: String(msg?.phase || ''),
    armedForMs: Math.max(0, now - stewardMemoryRestartRequestedAt),
  });
  stewardMemoryRestartPending = false;
  stewardMemoryRestartRequestedAt = 0;
  stewardLastMemoryRestartAt = now;
  restartStewardWorker('post_sync_memory_reclaim');
}

