function clearChatProjectionBackfillAfterLoginTimer() {
  return getChatPostLoginRuntime().clearChatProjectionBackfillAfterLoginTimer();
}

function isDeferredPostLoginBusy() {
  if (isHeavySyncActivityInProgress()) {
    return { busy: true, reason: 'heavy_sync' };
  }
  if (isLagCircuitBreakerActive()) {
    const snapshot = getLagCircuitBreakerSnapshot();
    return {
      busy: true,
      reason: 'lag_breaker',
      lagMs: Number(snapshot.lastLagMs || 0),
      remainingMs: Number(snapshot.remainingMs || 0),
    };
  }
  const lagMs = Math.max(0, Number(eventLoopLagStats?.lastLagMs || 0));
  if (lagMs >= Math.max(750, EVENT_LOOP_LAG_SLOW_MS * 3)) {
    return { busy: true, reason: 'event_loop_lag', lagMs };
  }
  return { busy: false, reason: '' };
}

function getLagAdjustedDelayMs(baseDelayMs = 0, options = {}) {
  const base = Math.max(0, Number(baseDelayMs || 0));
  if (!isLagCircuitBreakerActive()) return base;
  const snapshot = getLagCircuitBreakerSnapshot();
  const minimumDelayMs = Math.max(base, Number(options.minimumDelayMs || 0));
  return Math.max(minimumDelayMs, Number(snapshot.remainingMs || 0), EVENT_LOOP_LAG_BREAKER_BACKOFF_MS);
}

function isRetriableDeferredPostLoginError(err) {
  const message = String(err?.message || '').toLowerCase();
  if (!message) return false;
  return message.includes('timed out')
    || message.includes('timeout')
    || message.includes('database is locked')
    || message.includes('sqlite_busy')
    || message.includes('busy');
}

