async function runWalletProjectionRefreshNow(reason = 'runtime_wallet_refresh', stateSnapshot = null, req = null) {
  const effectiveReason = String(reason || 'runtime_wallet_refresh').trim() || 'runtime_wallet_refresh';
  const runtimeReq = req?.session?.walletPassword ? req : buildRuntimeAuthReq();
  const runtimeState = getRuntimeProjectionStateSnapshot(runtimeReq);
  const effectiveState = stateSnapshot && typeof stateSnapshot === 'object'
    ? (runtimeState ? chooseRicherStateSnapshot(stateSnapshot, runtimeState, `${effectiveReason}_wallet_refresh`) : stateSnapshot)
    : (runtimeState || buildProjectionBackedState(runtimeReq));
  const walletKey = await bridgeWalletFactsToDomainSafe(effectiveState, effectiveReason);
  if (!walletKey) {
    appendMarketDebug('wallet_projection_refresh_skipped', {
      reason: effectiveReason,
    });
    return null;
  }
  appendMarketDebug('wallet_projection_refresh_done', {
    reason: effectiveReason,
    walletKey,
  });
  scheduleFrontendDomainBroadcast('wallet', effectiveReason, 60);
  return walletKey;
}

function scheduleWalletProjectionRefresh(reason = 'runtime_wallet_refresh', stateSnapshot = null) {
  const effectiveReason = String(reason || 'runtime_wallet_refresh');
  const run = () => {
    void Promise.resolve()
      .then(() => runWalletProjectionRefreshNow(effectiveReason, stateSnapshot))
      .catch((err) => {
        appendMarketDebug('wallet_projection_refresh_failed', {
          reason: effectiveReason,
          message: String(err?.message || 'wallet_projection_refresh_failed'),
        });
      });
  };
  if (isLagCircuitBreakerActive()) {
    const delayMs = getLagAdjustedDelayMs(2000, { minimumDelayMs: 2000 });
    appendMarketDebug('wallet_projection_refresh_deferred_for_lag', {
      reason: effectiveReason,
      delayMs,
    });
    const timer = setTimeout(run, delayMs);
    timer.unref?.();
    return;
  }
  run();
}

function scoreStateSnapshotRichness(state) {
  if (!state || typeof state !== 'object') return -1;
  const categories = Array.isArray(state.categories) ? state.categories.length : 0;
  const products = Array.isArray(state.products) ? state.products.length : 0;
  const orders = Array.isArray(state.orders) ? state.orders.length : 0;
  const merchants = Array.isArray(state.merchants) ? state.merchants.length : 0;
  const users = Array.isArray(state.users) ? state.users.length : 0;
  const pendingAnchors = Array.isArray(state.pendingAnchors) ? state.pendingAnchors.length : 0;
  const localChanges = Array.isArray(state?.localChanges?.queue) ? state.localChanges.queue.length : 0;
  const localHeight = Math.max(0, Number(state?.sync?.localHeight || 0));
  return (localHeight * 1000000)
    + (categories * 10000)
    + (products * 1000)
    + (orders * 500)
    + (merchants * 100)
    + (users * 10)
    + pendingAnchors
    + Math.min(9, localChanges);
}

function isOrderChainMoreComplete(candidate = null, baseline = null) {
  const candidateChain = candidate?.chain && typeof candidate.chain === 'object' ? candidate.chain : {};
  const baselineChain = baseline?.chain && typeof baseline.chain === 'object' ? baseline.chain : {};
  const importantKeys = [
    'placeTxid',
    'buyerLockTxid',
    'buyerLockRedeemScriptHex',
    'buyerRefundAddress',
    'buyerChatPubKey',
    'sellerMerchantId',
    'sellerLockTxid',
    'sellerLockRedeemScriptHex',
    'sellerReceiveAddress',
    'sellerRefundAddress',
  ];
  let candidateCount = 0;
  let baselineCount = 0;
  importantKeys.forEach((key) => {
    if (String(candidateChain?.[key] || '').trim()) candidateCount += 1;
    if (String(baselineChain?.[key] || '').trim()) baselineCount += 1;
  });
  if (candidateCount !== baselineCount) return candidateCount > baselineCount;
  return false;
}

function mergeRicherOrdersIntoState(baseState, fallbackState) {
  if (!baseState || typeof baseState !== 'object' || !fallbackState || typeof fallbackState !== 'object') return baseState;
  const baseOrders = Array.isArray(baseState.orders) ? baseState.orders.map((row) => migrateOrderModel(row)) : [];
  const fallbackOrders = Array.isArray(fallbackState.orders) ? fallbackState.orders.map((row) => migrateOrderModel(row)) : [];
  if (!fallbackOrders.length) return baseState;
  const mergedById = new Map(baseOrders.map((row) => [String(row?.id || '').trim(), row]));
  for (const fallbackOrder of fallbackOrders) {
    const orderId = String(fallbackOrder?.id || '').trim();
    if (!orderId) continue;
    const current = mergedById.get(orderId);
    if (!current) {
      mergedById.set(orderId, fallbackOrder);
      continue;
    }
    if (isOrderChainMoreComplete(fallbackOrder, current)) {
      mergedById.set(orderId, fallbackOrder);
    }
  }
  baseState.orders = sortOrdersForDisplay(Array.from(mergedById.values()));
  return baseState;
}

function mergeChatStateArtifacts(baseState, fallbackState, req = null) {
  if (!baseState || typeof baseState !== 'object' || !fallbackState || typeof fallbackState !== 'object') {
    return baseState;
  }
  ensureChatState(baseState, req);
  ensureChatState(fallbackState, req);

  const fallbackManualPeerEndpoints = fallbackState.chatConfig?.manualPeerEndpoints
    && typeof fallbackState.chatConfig.manualPeerEndpoints === 'object'
    ? fallbackState.chatConfig.manualPeerEndpoints
    : {};
  const baseManualPeerEndpoints = baseState.chatConfig?.manualPeerEndpoints
    && typeof baseState.chatConfig.manualPeerEndpoints === 'object'
    ? baseState.chatConfig.manualPeerEndpoints
    : {};
  baseState.chatConfig.manualPeerEndpoints = {
    ...fallbackManualPeerEndpoints,
    ...baseManualPeerEndpoints,
  };

  const fallbackManualDisconnects = fallbackState.chatConfig?.manualDisconnects
    && typeof fallbackState.chatConfig.manualDisconnects === 'object'
    ? fallbackState.chatConfig.manualDisconnects
    : {};
  const baseManualDisconnects = baseState.chatConfig?.manualDisconnects
    && typeof baseState.chatConfig.manualDisconnects === 'object'
    ? baseState.chatConfig.manualDisconnects
    : {};
  baseState.chatConfig.manualDisconnects = {
    ...fallbackManualDisconnects,
    ...baseManualDisconnects,
  };

  const fallbackProfiles = fallbackState.chatDiscovery?.profiles
    && typeof fallbackState.chatDiscovery.profiles === 'object'
    ? fallbackState.chatDiscovery.profiles
    : {};
  const baseProfiles = baseState.chatDiscovery?.profiles
    && typeof baseState.chatDiscovery.profiles === 'object'
    ? baseState.chatDiscovery.profiles
    : {};
  baseState.chatDiscovery.profiles = {
    ...fallbackProfiles,
    ...baseProfiles,
  };

  const fallbackInvites = fallbackState.chatDiscovery?.invites
    && typeof fallbackState.chatDiscovery.invites === 'object'
    ? fallbackState.chatDiscovery.invites
    : {};
  const baseInvites = baseState.chatDiscovery?.invites
    && typeof baseState.chatDiscovery.invites === 'object'
    ? baseState.chatDiscovery.invites
    : {};
  baseState.chatDiscovery.invites = {
    ...fallbackInvites,
    ...baseInvites,
  };

  const fallbackThreads = fallbackState.chatThreads && typeof fallbackState.chatThreads === 'object'
    ? fallbackState.chatThreads
    : {};
  const baseThreads = baseState.chatThreads && typeof baseState.chatThreads === 'object'
    ? baseState.chatThreads
    : {};
  baseState.chatThreads = {
    ...fallbackThreads,
    ...baseThreads,
  };

  const fallbackSessions = fallbackState.chatSessions && typeof fallbackState.chatSessions === 'object'
    ? fallbackState.chatSessions
    : {};
  const baseSessions = baseState.chatSessions && typeof baseState.chatSessions === 'object'
    ? baseState.chatSessions
    : {};
  baseState.chatSessions = {
    ...fallbackSessions,
    ...baseSessions,
  };

  if (
    !String(baseState.chatIdentity?.self?.chatPubKey || '').trim()
    && String(fallbackState.chatIdentity?.self?.chatPubKey || '').trim()
  ) {
    baseState.chatIdentity.self = {
      ...baseState.chatIdentity.self,
      ...fallbackState.chatIdentity.self,
    };
  }
  if (
    (!baseState.chatIdentity?.pubkeyBindings || Object.keys(baseState.chatIdentity.pubkeyBindings).length <= 0)
    && fallbackState.chatIdentity?.pubkeyBindings
    && typeof fallbackState.chatIdentity.pubkeyBindings === 'object'
  ) {
    baseState.chatIdentity.pubkeyBindings = { ...fallbackState.chatIdentity.pubkeyBindings };
  }
  if (
    (!baseState.chatIdentity?.walletKeyIndex || Object.keys(baseState.chatIdentity.walletKeyIndex).length <= 0)
    && fallbackState.chatIdentity?.walletKeyIndex
    && typeof fallbackState.chatIdentity.walletKeyIndex === 'object'
  ) {
    baseState.chatIdentity.walletKeyIndex = { ...fallbackState.chatIdentity.walletKeyIndex };
  }

  rebuildWalletKeyBindingsFromAnchors(baseState, req);
  rebuildRegisteredPeerProfilesFromAnchors(baseState, req);
  rebuildChatUiSummary(baseState);
  return baseState;
}

function chooseRicherStateSnapshot(primaryState, secondaryState, reason = 'runtime') {
  const primaryScore = scoreStateSnapshotRichness(primaryState);
  const secondaryScore = scoreStateSnapshotRichness(secondaryState);
  appendMarketDebug('state_snapshot_compare', {
    reason: String(reason || 'runtime'),
    primaryScore,
    secondaryScore,
    primaryLocalHeight: Math.max(0, Number(primaryState?.sync?.localHeight || 0)),
    secondaryLocalHeight: Math.max(0, Number(secondaryState?.sync?.localHeight || 0)),
    primaryCategories: Array.isArray(primaryState?.categories) ? primaryState.categories.length : 0,
    secondaryCategories: Array.isArray(secondaryState?.categories) ? secondaryState.categories.length : 0,
    primaryProducts: Array.isArray(primaryState?.products) ? primaryState.products.length : 0,
    secondaryProducts: Array.isArray(secondaryState?.products) ? secondaryState.products.length : 0,
    primaryOrders: Array.isArray(primaryState?.orders) ? primaryState.orders.length : 0,
    secondaryOrders: Array.isArray(secondaryState?.orders) ? secondaryState.orders.length : 0,
  });
  if (secondaryScore > primaryScore) {
    appendMarketDebug('state_snapshot_replaced_with_richer_runtime', {
      reason: String(reason || 'runtime'),
      primaryScore,
      secondaryScore,
      primaryLocalHeight: Math.max(0, Number(primaryState?.sync?.localHeight || 0)),
      secondaryLocalHeight: Math.max(0, Number(secondaryState?.sync?.localHeight || 0)),
      primaryCategories: Array.isArray(primaryState?.categories) ? primaryState.categories.length : 0,
      secondaryCategories: Array.isArray(secondaryState?.categories) ? secondaryState.categories.length : 0,
      primaryProducts: Array.isArray(primaryState?.products) ? primaryState.products.length : 0,
      secondaryProducts: Array.isArray(secondaryState?.products) ? secondaryState.products.length : 0,
      primaryOrders: Array.isArray(primaryState?.orders) ? primaryState.orders.length : 0,
      secondaryOrders: Array.isArray(secondaryState?.orders) ? secondaryState.orders.length : 0,
    });
    return mergeRicherOrdersIntoState(secondaryState, primaryState);
  }
  return mergeRicherOrdersIntoState(primaryState, secondaryState);
}

