function scheduleWalletFactsRefresh(reason = 'runtime_wallet_facts_refresh', cooldownMs = 8000) {
  const effectiveReason = String(reason || 'runtime_wallet_facts_refresh').trim() || 'runtime_wallet_facts_refresh';
  if (!wallet.walletExists()) return false;
  const now = Date.now();
  const last = Number(walletFactsRefreshCooldown.get(effectiveReason) || 0);
  if ((now - last) < Math.max(0, Number(cooldownMs || 0))) return false;
  walletFactsRefreshCooldown.set(effectiveReason, now);
  if (walletFactsRefreshPromise) {
    walletFactsRefreshQueuedReason = effectiveReason;
    appendMarketDebug('wallet_facts_refresh_queued', {
      reason: effectiveReason,
    });
    return true;
  }
  const forceBootstrap = false;
  appendMarketDebug('wallet_facts_refresh_start', {
    reason: effectiveReason,
    forceBootstrap,
  });
  walletFactsRefreshPromise = Promise.resolve()
    .then(async () => {
      await bridgeWalletFactsToDomainSafe(null, effectiveReason);
      appendMarketDebug('wallet_facts_refresh_done', {
        reason: effectiveReason,
        forceBootstrap,
      });
      scheduleFrontendDomainBroadcast('wallet', effectiveReason, 60);
    })
    .catch((err) => {
      appendMarketDebug('wallet_facts_refresh_failed', {
        reason: effectiveReason,
        message: String(err?.message || 'wallet_facts_refresh_failed'),
      });
    })
    .finally(() => {
      walletFactsRefreshPromise = null;
      const queuedReason = String(walletFactsRefreshQueuedReason || '').trim();
      walletFactsRefreshQueuedReason = '';
      if (queuedReason) scheduleWalletFactsRefresh(queuedReason, 0);
    });
  return true;
}

function scheduleWalletProjectionRefreshThrottled(reason = 'runtime_wallet_refresh', stateSnapshot = null, cooldownMs = 5000) {
  let walletKey = '';
  try {
    walletKey = wallet.walletExists() ? String(wallet.getReceiveAddress() || '').trim() : '';
  } catch (_) {
    walletKey = '';
  }
  const rawReason = String(reason || '').trim();
  const normalizedReason = rawReason.includes('wallet_projection')
    ? 'wallet_projection'
    : rawReason;
  const throttleKey = `${walletKey}|${normalizedReason}`;
  const now = Date.now();
  const last = Number(walletProjectionRefreshCooldown.get(throttleKey) || 0);
  if ((now - last) < Math.max(0, Number(cooldownMs || 0))) return false;
  walletProjectionRefreshCooldown.set(throttleKey, now);
  scheduleWalletProjectionRefresh(reason, stateSnapshot);
  return true;
}

function propagateWalletEventToViews(reason = 'wallet_event', stateSnapshot = null, cooldownMs = 5000) {
  const effectiveReason = String(reason || 'wallet_event').trim() || 'wallet_event';
  return scheduleWalletProjectionRefreshThrottled(effectiveReason, stateSnapshot, cooldownMs);
}

function maybeRefreshWalletForCommittedSyncState(state, options = {}) {
  if (!state || typeof state !== 'object' || !wallet.walletExists()) return false;
  const reason = String(options.reason || 'sync_state_saved').trim() || 'sync_state_saved';
  let triggered = false;
  const forceSyncRefresh = reason.includes('sync_final_state_saved');
  const walletImpact = options?.walletImpact && typeof options.walletImpact === 'object'
    ? options.walletImpact
    : {};
  const walletProjectionNeeded = (
    Number(walletImpact.walletAppliedCount || 0) > 0
    || Number(walletImpact.walletSummaryCount || 0) > 0
    || walletImpact.recentRawtxChanged === true
    || walletImpact.forceWalletProjection === true
  );
  try {
    if (forceSyncRefresh || shouldRefreshWalletIndexForSync(state)) {
      triggered = Boolean(triggerWalletIndexRefreshInBackground(state));
    }
  } catch (error) {
    appendMarketDebug('wallet_index_refresh_after_sync_failed', {
      reason,
      message: String(error?.message || error || 'wallet_index_refresh_after_sync_failed'),
      localHeight: Number(state?.sync?.localHeight || 0),
      targetHeight: Number(state?.sync?.targetHeight || 0),
    });
  }
  if (forceSyncRefresh) {
    if (walletProjectionNeeded) {
      scheduleWalletProjectionRefreshThrottled(`${reason}_wallet_projection`, state, 20000);
    } else {
      appendMarketDebug('wallet_projection_refresh_skipped_no_wallet_impact', {
        reason,
        mode: 'final',
        localHeight: Number(state?.sync?.localHeight || 0),
        targetHeight: Number(state?.sync?.targetHeight || 0),
      });
    }
    appendMarketDebug('wallet_facts_refresh_skipped_policy', {
      reason,
      policy: 'manual_recovery_only',
    });
  }
  else if (walletProjectionNeeded) {
    scheduleWalletProjectionRefreshThrottled(`${reason}_wallet_projection`, state, 8000);
  } else {
    appendMarketDebug('wallet_projection_refresh_skipped_no_wallet_impact', {
      reason,
      mode: 'incremental',
      localHeight: Number(state?.sync?.localHeight || 0),
      targetHeight: Number(state?.sync?.targetHeight || 0),
    });
  }
  return triggered;
}

