function summarizeJobStage(jobType, stage, extra = {}) {
  const stageName = String(stage || '').trim() || 'running';
  const base = {
    stage: stageName,
    progressCurrent: 0,
    progressTotal: 1,
  };
  if (jobType === 'run_chain_sync' || jobType === 'rebuild_chain_indexes') {
    const order = [
      'prepare_saved',
      'p2p_header_sync',
      'p2p_forward_probe',
      'p2p_task_queue_ready',
      'p2p_block_workers_done',
      'p2p_service_window',
      'merge_anchors_done',
      'reconcile_local_changes_done',
      'reconcile_chat_messages_done',
      'catalog_rebuilt',
      'final_state_merged',
      'final_state_saved',
      'wallet_index_refreshed',
      'done',
    ];
    const index = Math.max(0, order.indexOf(stageName));
    base.progressCurrent = index >= 0 ? index : 0;
    base.progressTotal = order.length - 1;
  } else if (jobType === 'import_wallet_bootstrap') {
    const order = [
      'wallet_import_start',
      'wallet_materialized',
      'market_state_reset',
      'chain_sync_queued',
      'done',
    ];
    const index = Math.max(0, order.indexOf(stageName));
    base.progressCurrent = index >= 0 ? index : 0;
    base.progressTotal = order.length - 1;
  } else if (jobType === 'wallet_send') {
    const order = [
      'wallet_send_start',
      'wallet_send_composed',
      'wallet_send_signed',
      'wallet_send_broadcasting',
      'wallet_send_broadcasted',
      'done',
    ];
    const index = Math.max(0, order.indexOf(stageName));
    base.progressCurrent = index >= 0 ? index : 0;
    base.progressTotal = order.length - 1;
  }
  return {
    ...base,
    ...(extra || {}),
  };
}

