const SQLITE_SNAPSHOT_PERSIST_DEBOUNCE_MS = Math.max(
  25,
  Number(process.env.BSV_MARKET_SQLITE_SNAPSHOT_DEBOUNCE_MS || 1500),
);
const SYNC_STATE_NOW_DEBOUNCE_MS = Math.max(
  250,
  Number(process.env.BSV_MARKET_SYNC_STATE_NOW_DEBOUNCE_MS || 1500),
);
const SQLITE_SNAPSHOT_PERSIST_DEBOUNCE_BY_MODULE = {
  sync: Math.max(250, Math.min(SQLITE_SNAPSHOT_PERSIST_DEBOUNCE_MS, 2000)),
  catalog: Math.max(SQLITE_SNAPSHOT_PERSIST_DEBOUNCE_MS, 5000),
  profile: Math.max(SQLITE_SNAPSHOT_PERSIST_DEBOUNCE_MS, 4000),
  localState: Math.max(SQLITE_SNAPSHOT_PERSIST_DEBOUNCE_MS, 5000),
};
const sqliteSnapshotPersistTimers = new Map();
const sqliteSnapshotPersistStates = new Map();
const sqliteSnapshotPersistHashes = new Map();
const syncStateImmediatePersistControl = {
  nextSeq: 0,
  pending: null,
  active: false,
  waiters: [],
  timer: null,
  lastPersistedHash: '',
};

function hashSnapshotPayload(payload) {
  try {
    let normalized = payload;
    if (
      payload &&
      typeof payload === 'object' &&
      !Array.isArray(payload) &&
      String(payload.scope || '') === 'main'
    ) {
      normalized = { ...payload };
      delete normalized.updatedAt;
    }
    return crypto.createHash('sha1').update(JSON.stringify(normalized)).digest('hex');
  } catch (_) {
    return '';
  }
}

function buildCatalogSnapshotPayload(state) {
  return getCatalogSnapshotService().buildCatalogSnapshotPayload(state);
}

function buildProfileSnapshotPayload(state) {
  const profile = state?.profile && typeof state.profile === 'object' ? state.profile : {};
  const currentMerchantId = sanitizeMerchantId(state?.currentMerchantId || '');
  return {
    profileKey: 'self',
    merchantId: currentMerchantId,
    walletId: currentMerchantId ? walletIdByMerchant(currentMerchantId) : '',
    name: String(profile.name || ''),
    localStatus: String(profile.localStatus || ''),
    localUpdatedAt: String(profile.localUpdatedAt || ''),
    updatedAt: new Date().toISOString(),
  };
}

function getSqliteSnapshotModuleConfig(moduleName, state) {
  switch (String(moduleName || '')) {
    case 'sync': {
      const payload = buildSyncStateDbPayload(state?.sync || {});
      return {
        payload,
        persist: () => syncDomain.emitSyncStateSnapshot(payload, {
          producer: 'save_state.sync',
          dedupeKey: `sync.state.snapshot:${hashSnapshotPayload(payload)}`,
        }),
        onError: (error) => appendMarketDebug('sqlite_sync_state_persist_failed', {
          message: String(error?.message || error || 'sqlite_sync_state_persist_failed'),
          localHeight: Number(payload.localHeight || 0),
          networkHeight: Number(payload.networkHeight || 0),
          fixedSyncLastHeight: Number(payload.fixedSyncLastHeight || 0),
        }),
      };
    }
    case 'catalog': {
      const payload = buildCatalogSnapshotPayload(state);
      return {
        payload,
        persist: () => catalogDomain.emitCatalogSnapshot(payload, {
          producer: 'save_state.catalog',
          dedupeKey: `catalog.snapshot:${hashSnapshotPayload(payload)}`,
        }),
        onError: (error) => appendMarketDebug('sqlite_catalog_persist_failed', {
          message: String(error?.message || error || 'sqlite_catalog_persist_failed'),
          categoryCount: payload.categories.length,
          productCount: payload.products.length,
        }),
      };
    }
    case 'profile': {
      const payload = buildProfileSnapshotPayload(state);
      return {
        payload,
        persist: () => profileDomain.emitProfileUpsert(payload, {
          producer: 'save_state.profile',
          dedupeKey: `profile.upsert:${payload.profileKey}:${hashSnapshotPayload(payload)}`,
        }),
        onError: (error) => appendMarketDebug('sqlite_profile_persist_failed', {
          message: String(error?.message || error || 'sqlite_profile_persist_failed'),
          merchantId: payload.merchantId,
          name: payload.name,
        }),
      };
    }
    case 'localState': {
      const payload = buildLocalStateSnapshotPayload(state);
      return {
        payload,
        persist: () => localStateDomain.emitLocalStateSnapshot(payload, {
          producer: 'save_state.local_state',
          dedupeKey: `local_state.snapshot:${hashSnapshotPayload(payload)}`,
        }),
        onError: (error) => appendMarketDebug('sqlite_local_state_persist_failed', {
          message: String(error?.message || error || 'sqlite_local_state_persist_failed'),
          localChangeCount: Array.isArray(payload.localChanges) ? payload.localChanges.length : 0,
          recentRawtxCount: Array.isArray(payload.recentRawtxs) ? payload.recentRawtxs.length : 0,
          pendingAnchorCount: Array.isArray(payload.pendingAnchors) ? payload.pendingAnchors.length : 0,
        }),
      };
    }
    default:
      return null;
  }
}

function flushSqliteSnapshotPersist(moduleName) {
  const timer = sqliteSnapshotPersistTimers.get(moduleName);
  if (timer) {
    clearTimeout(timer);
    sqliteSnapshotPersistTimers.delete(moduleName);
  }
  const state = sqliteSnapshotPersistStates.get(moduleName);
  if (!state) return;
  const config = getSqliteSnapshotModuleConfig(moduleName, state);
  if (!config) return;
  const payloadHash = hashSnapshotPayload(config.payload);
  if (payloadHash && sqliteSnapshotPersistHashes.get(moduleName) === payloadHash) return;
  void Promise.resolve()
    .then(() => config.persist())
    .then(() => {
      if (payloadHash) sqliteSnapshotPersistHashes.set(moduleName, payloadHash);
    })
    .catch((error) => {
      if (typeof config.onError === 'function') config.onError(error);
    });
}

function scheduleSqliteSnapshotPersist(moduleName, state, options = {}) {
  sqliteSnapshotPersistStates.set(moduleName, state);
  const existingTimer = sqliteSnapshotPersistTimers.get(moduleName);
  if (existingTimer) clearTimeout(existingTimer);
  const delayMs = Math.max(
    0,
    Number(options.delayMs ?? SQLITE_SNAPSHOT_PERSIST_DEBOUNCE_BY_MODULE[moduleName] ?? SQLITE_SNAPSHOT_PERSIST_DEBOUNCE_MS),
  );
  if (delayMs === 0) {
    flushSqliteSnapshotPersist(moduleName);
    return;
  }
  const timer = setTimeout(() => flushSqliteSnapshotPersist(moduleName), delayMs);
  timer.unref?.();
  sqliteSnapshotPersistTimers.set(moduleName, timer);
}

function cancelSqliteSnapshotPersist(moduleName) {
  const timer = sqliteSnapshotPersistTimers.get(moduleName);
  if (timer) {
    clearTimeout(timer);
    sqliteSnapshotPersistTimers.delete(moduleName);
  }
  sqliteSnapshotPersistStates.delete(moduleName);
}

function persistSyncStateAsync(syncLike = {}) {
  scheduleSqliteSnapshotPersist('sync', { sync: syncLike });
}

async function writeSyncNodeStatsSnapshot(syncLike = {}) {
  try {
    const payload = buildSyncStateDbPayload(syncLike);
    const snapshot = {
      scope: String(payload.scope || 'main'),
      bootstrapHeight: Math.max(0, Number(payload.bootstrapHeight || 0)),
      localHeight: Math.max(0, Number(payload.localHeight || 0)),
      networkHeight: Math.max(0, Number(payload.networkHeight || 0)),
      p2pTipHeight: Math.max(0, Number(payload.p2pTipHeight || 0)),
      p2pHeaderCursorHeight: Number.isFinite(Number(payload.p2pHeaderCursorHeight))
        ? Number(payload.p2pHeaderCursorHeight)
        : -1,
      lastP2PGoodNodes: Math.max(0, Number(payload.lastP2PGoodNodes || 0)),
      p2pHeightHashCache: payload.p2pHeightHashCache && typeof payload.p2pHeightHashCache === 'object'
        ? payload.p2pHeightHashCache
        : {},
      p2pNodeStats: payload.p2pNodeStats && typeof payload.p2pNodeStats === 'object'
        ? payload.p2pNodeStats
        : {},
      updatedAt: String(payload.updatedAt || nowIso()),
    };
    const request = {
      file: SYNC_NODE_STATS_SNAPSHOT_FILE,
      serialized: JSON.stringify(snapshot, null, 2),
    };
    await queueCoalescedSnapshotWrite(coalescedSnapshotWrites.syncNodeStats, request, (nextPayload) =>
      marketDb.writeSyncNodeStatsSnapshot(nextPayload));
  } catch (error) {
    appendMarketDebug('sync_node_stats_snapshot_write_failed', {
      message: String(error?.message || 'sync node stats snapshot write failed'),
    });
  }
}

async function persistSyncStateNow(syncLike = {}, options = {}) {
  cancelSqliteSnapshotPersist('sync');
  const payload = buildSyncStateDbPayload(syncLike);
  const reason = String(options.reason || 'sync_state_saved');
  const source = String(options.source || 'server_market');
  const payloadHash = hashSnapshotPayload(payload);
  const request = { payload, reason, source, payloadHash };
  const force = (
    options.force === true
    || reason === 'sync_final_state_saved'
    || reason.includes('wallet_switch')
    || reason.includes('shutdown')
    || reason.includes('reset')
  );
  const control = syncStateImmediatePersistControl;
  if (!force && payloadHash && control.lastPersistedHash === payloadHash && !control.pending && !control.active) {
    appendMarketDebug('sync_state_persist_skipped_unchanged', {
      reason,
      source,
      localHeight: Number(payload.localHeight || 0),
      fixedSyncLastHeight: Number(payload.fixedSyncLastHeight || 0),
    });
    return payload;
  }
  return queueSyncStateImmediatePersist(request, { force });
}

async function performSyncStateImmediatePersist(request = {}) {
  const payload = request.payload && typeof request.payload === 'object' ? request.payload : {};
  const reason = String(request.reason || 'sync_state_saved');
  const source = String(request.source || 'server_market');
  appendMarketDebug('sync_state_persist_attempt', {
    reason,
    source,
    localHeight: Number(payload.localHeight || 0),
    networkHeight: Number(payload.networkHeight || 0),
    fixedSyncLastHeight: Number(payload.fixedSyncLastHeight || 0),
  });
  try {
    await marketDb.ensureWriterService();
    await marketDb.upsertSyncState(payload);
    try {
      await syncDomain.emitSyncStateSnapshot(payload, {
        producer: 'persist_sync_state_now',
        dedupeKey: `sync.state.snapshot:${hashSnapshotPayload(payload)}`,
        correlationId: reason,
        causationId: source,
      });
    } catch (emitError) {
      appendMarketDebug('sync_state_emit_fallback_to_direct_persist', {
        message: String(emitError?.message || emitError || 'sync state emit failed'),
        reason,
        source,
      });
    }
    await writeSyncNodeStatsSnapshot(payload);
    if (request.payloadHash) syncStateImmediatePersistControl.lastPersistedHash = request.payloadHash;
    return payload;
  } catch (error) {
    appendMarketDebug('sqlite_sync_state_persist_failed', {
      message: String(error?.message || error || 'sqlite_sync_state_persist_failed'),
      reason,
      source,
      localHeight: Number(payload.localHeight || 0),
      networkHeight: Number(payload.networkHeight || 0),
      fixedSyncLastHeight: Number(payload.fixedSyncLastHeight || 0),
      immediate: true,
    });
    throw error;
  }
}

function scheduleSyncStateImmediatePersistFlush(delayMs = SYNC_STATE_NOW_DEBOUNCE_MS) {
  const control = syncStateImmediatePersistControl;
  if (control.timer) clearTimeout(control.timer);
  control.timer = setTimeout(() => {
    control.timer = null;
    void flushSyncStateImmediatePersistQueue().catch(() => {});
  }, Math.max(0, Number(delayMs || 0)));
  control.timer.unref?.();
}

async function flushSyncStateImmediatePersistQueue() {
  const control = syncStateImmediatePersistControl;
  if (control.timer) {
    clearTimeout(control.timer);
    control.timer = null;
  }
  if (control.active) return;
  control.active = true;
  try {
    while (control.pending) {
      const current = control.pending;
      control.pending = null;
      try {
        await new Promise((resolve) => setImmediate(resolve));
        const result = await performSyncStateImmediatePersist(current.request);
        const waiters = Array.isArray(control.waiters) ? control.waiters.splice(0, control.waiters.length) : [];
        const deferred = [];
        waiters.forEach((entry) => {
          if (Number(entry?.seq || 0) <= current.seq) entry.resolve(result);
          else deferred.push(entry);
        });
        control.waiters = deferred;
      } catch (error) {
        const waiters = Array.isArray(control.waiters) ? control.waiters.splice(0, control.waiters.length) : [];
        const deferred = [];
        waiters.forEach((entry) => {
          if (Number(entry?.seq || 0) <= current.seq) entry.reject(error);
          else deferred.push(entry);
        });
        control.waiters = deferred;
      }
    }
  } finally {
    control.active = false;
  }
}

function queueSyncStateImmediatePersist(request, options = {}) {
  const control = syncStateImmediatePersistControl;
  const seq = Math.max(1, Number(control.nextSeq || 0) + 1);
  control.nextSeq = seq;
  control.pending = { seq, request };
  const promise = new Promise((resolve, reject) => {
    control.waiters.push({ seq, resolve, reject });
  });
  if (options.force === true) {
    void flushSyncStateImmediatePersistQueue().catch(() => {});
    return promise;
  }
  scheduleSyncStateImmediatePersistFlush(SYNC_STATE_NOW_DEBOUNCE_MS);
  return promise;
}

function loadCatalogSnapshotFromSqlite() {
  return getCatalogSnapshotService().loadCatalogSnapshotFromSqlite();
}

function persistCatalogSnapshotAsync(state) {
  scheduleSqliteSnapshotPersist('catalog', state);
}

function loadProfileSnapshotFromSqlite() {
  try {
    const dbFile = marketDb.getDbFilePath();
    if (!fs.existsSync(dbFile)) return null;
    const db = marketDb.openReadDb();
    try {
      const row = db.prepare(`
        SELECT
          profile_key,
          merchant_id,
          wallet_id,
          name,
          payload_json,
          updated_at
        FROM profiles
        WHERE profile_key = 'self'
      `).get();
      if (!row) return null;
      let payload = {};
      try {
        payload = JSON.parse(String(row.payload_json || '{}'));
      } catch (_) {
        payload = {};
      }
      return {
        name: String(row.name || ''),
        merchantId: String(row.merchant_id || ''),
        walletId: String(row.wallet_id || ''),
        localStatus: String(payload.localStatus || ''),
        localUpdatedAt: String(payload.localUpdatedAt || row.updated_at || ''),
      };
    } finally {
      db.close();
    }
  } catch (_) {
    return null;
  }
}

function loadRegisteredChatProfilesFromSqlite() {
  try {
    const dbFile = marketDb.getDbFilePath();
    if (!fs.existsSync(dbFile)) return {};
    const db = marketDb.openReadDb();
    try {
      const namesByMerchantId = new Map();
      const profileRows = db.prepare(`
        SELECT merchant_id, payload_json, ts
        FROM anchor_events
        WHERE event_type = 'profile_set'
        ORDER BY ts ASC, event_id ASC
      `).all();
      for (const row of profileRows) {
        const merchantId = String(row?.merchant_id || '').trim();
        if (!merchantId) continue;
        let payload = {};
        try {
          payload = JSON.parse(String(row?.payload_json || '{}'));
        } catch (_) {
          payload = {};
        }
        const name = String(payload?.name || '').trim();
        if (name) namesByMerchantId.set(merchantId, name);
      }
      const profiles = {};
      const bindRows = db.prepare(`
        SELECT
          wallet_id,
          merchant_id,
          chat_pub_key,
          endpoint_hints_json,
          relay_hints_json,
          signature_ok,
          updated_at
        FROM wallet_key_binds
      `).all();
      for (const row of bindRows) {
        const walletId = String(row?.wallet_id || '').trim();
        if (!walletId) continue;
        const merchantId = String(row?.merchant_id || '').trim();
        let endpointHints = [];
        let relayHints = [];
        try { endpointHints = JSON.parse(String(row?.endpoint_hints_json || '[]')); } catch (_) {}
        try { relayHints = JSON.parse(String(row?.relay_hints_json || '[]')); } catch (_) {}
        const name = String(namesByMerchantId.get(merchantId) || '').trim();
        profiles[walletId] = {
          walletId,
          merchantId,
          name,
          displayName: firstUsefulChatDisplayName(walletId, [name, merchantId, walletId]),
          chatPubKeys: [String(row?.chat_pub_key || '').trim()].filter(Boolean),
          endpointHints: Array.isArray(endpointHints) ? endpointHints.slice(0, 8) : [],
          relayHints: Array.isArray(relayHints) ? relayHints.slice(0, 8) : [],
          updatedAt: String(row?.updated_at || ''),
          verified: Number(row?.signature_ok || 0) === 1,
        };
      }
      const anchorBindRows = db.prepare(`
        SELECT
          event_id,
          txid,
          block_height,
          confirmed,
          payload_json,
          ts
        FROM anchor_events
        WHERE event_type = 'wallet_key_bind'
        ORDER BY ts ASC, event_id ASC
      `).all();
      const winningBindByPubKey = new Map();
      for (const row of anchorBindRows) {
        let rawPayload = {};
        try {
          rawPayload = JSON.parse(String(row?.payload_json || '{}'));
        } catch (_) {
          rawPayload = {};
        }
        const payload = normalizeEventPayload('wallet_key_bind', rawPayload, String(row?.ts || ''));
        const walletId = String(payload?.walletId || '').trim();
        const merchantId = String(payload?.merchantId || '').trim();
        const chatPubKey = String(payload?.chatPubKey || '').trim();
        if (!walletId || !chatPubKey || !verifyWalletKeyBindPayload(payload)) continue;
        const candidate = {
          walletId,
          merchantId,
          chatPubKey,
          endpointHints: Array.isArray(payload.endpointHints) ? payload.endpointHints.slice(0, 8) : [],
          relayHints: Array.isArray(payload.relayHints) ? payload.relayHints.slice(0, 8) : [],
          firstBindTxid: String(row?.txid || '').trim(),
          firstBindHeight: Math.max(0, Number(row?.block_height || 0)),
          firstBindConfirmed: Number(row?.confirmed || 0) === 1,
          firstBindCreatedAt: String(payload?._updatedAt || row?.ts || ''),
        };
        const existing = winningBindByPubKey.get(chatPubKey);
        if (!existing || compareWalletKeyBindPriority(candidate, existing) < 0) {
          winningBindByPubKey.set(chatPubKey, candidate);
        }
      }
      for (const bind of winningBindByPubKey.values()) {
        const walletId = String(bind?.walletId || '').trim();
        const merchantId = String(bind?.merchantId || '').trim();
        if (!walletId) continue;
        const name = String(namesByMerchantId.get(merchantId) || '').trim();
        profiles[walletId] = {
          ...(profiles[walletId] && typeof profiles[walletId] === 'object' ? profiles[walletId] : {}),
          walletId,
          merchantId,
          name,
          displayName: firstUsefulChatDisplayName(walletId, [
            profiles[walletId]?.displayName,
            profiles[walletId]?.name,
            name,
            merchantId,
            walletId,
          ]),
          chatPubKeys: [String(bind?.chatPubKey || '').trim()].filter(Boolean),
          endpointHints: Array.isArray(bind?.endpointHints) ? bind.endpointHints.slice(0, 8) : [],
          relayHints: Array.isArray(bind?.relayHints) ? bind.relayHints.slice(0, 8) : [],
          updatedAt: String(bind?.firstBindCreatedAt || profiles[walletId]?.updatedAt || ''),
          verified: true,
        };
      }
      return profiles;
    } finally {
      db.close();
    }
  } catch (_) {
    return {};
  }
}

function persistProfileSnapshotAsync(state, options = {}) {
  scheduleSqliteSnapshotPersist('profile', state, options);
}

function buildProjectionStateFromSqlite(req = null) {
  const state = defaultState();
  const rawState = loadParsedJsonFileCached(STATE_FILE) || {};
  if (rawState?.steward && typeof rawState.steward === 'object') {
    state.steward = {
      ...state.steward,
      ...rawState.steward,
    };
  }
  applySqliteSyncStateRow(state.sync, loadSyncStateRowFromSqlite());
  const sqliteCatalog = loadCatalogSnapshotFromSqlite();
  if (sqliteCatalog) {
    state.categories = sqliteCatalog.categories;
    state.products = sqliteCatalog.products;
  }
  const sqliteProfile = loadProfileSnapshotFromSqlite();
  if (sqliteProfile) {
    state.profile = {
      ...state.profile,
      name: String(sqliteProfile.name || state.profile?.name || ''),
      localStatus: String(sqliteProfile.localStatus || state.profile?.localStatus || ''),
      localUpdatedAt: String(sqliteProfile.localUpdatedAt || state.profile?.localUpdatedAt || ''),
    };
  }
  const sqliteLocalState = localStateDomain.getLocalStateSync('main');
  if (sqliteLocalState && typeof sqliteLocalState === 'object') {
    state.pendingAnchors = (Array.isArray(sqliteLocalState.pendingAnchors) ? sqliteLocalState.pendingAnchors : [])
      .filter((row) => row?.confirmed !== true)
      .map((row) => ({
        ...row,
        payload: row?.payload && typeof row.payload === 'object' ? row.payload : {},
      }));
    state.recentRawtxs = Array.isArray(sqliteLocalState.recentRawtxs)
      ? sqliteLocalState.recentRawtxs.map((row) => ({ ...row }))
      : [];
    state.localChanges = {
      seq: Math.max(1, Number(sqliteLocalState.seq || 1)),
      queue: Array.isArray(sqliteLocalState.localChanges)
        ? sqliteLocalState.localChanges.map((row) => ({ ...row }))
        : [],
    };
  }
  if (!Array.isArray(state.pendingAnchors)) state.pendingAnchors = [];
  if (!Array.isArray(state.recentRawtxs)) state.recentRawtxs = [];
  if (!state.localChanges || typeof state.localChanges !== 'object') state.localChanges = { seq: 1, queue: [] };
  if (!Array.isArray(state.localChanges.queue)) state.localChanges.queue = [];
  state.orders = listActiveProtocolOrdersSync();
  const sessionMerchantId = req ? sanitizeMerchantId(deriveMerchantIdForSession(req)) : '';
  const profileMerchantId = sanitizeMerchantId(sqliteProfile?.merchantId || '');
  state.currentMerchantId = sessionMerchantId || profileMerchantId || state.currentMerchantId || 'm-local';
  state.users = [{ id: 'buyer', name: String(state.profile?.name || '买家A'), role: 'buyer' }];
  const sqliteChatProfiles = loadRegisteredChatProfilesFromSqlite();
  if (sqliteChatProfiles && typeof sqliteChatProfiles === 'object' && Object.keys(sqliteChatProfiles).length > 0) {
    state.chatDiscovery.profiles = {
      ...(state.chatDiscovery?.profiles && typeof state.chatDiscovery.profiles === 'object' ? state.chatDiscovery.profiles : {}),
      ...sqliteChatProfiles,
    };
  }
  if (state.currentMerchantId && state.currentMerchantId !== 'm-local') {
    const merchantName = merchantDisplayName(state.currentMerchantId, String(state.profile?.name || ''));
    state.merchants = [{ id: state.currentMerchantId, name: merchantName, downloadedAt: Date.now() }];
    getOrCreateSellerUser(state, state.currentMerchantId, merchantName);
  } else {
    state.merchants = [];
  }
  enrichCatalogMerchantsFromVisibleCatalog(state);
  applyPendingChangesOnTop(state);
  enrichCatalogMerchantsFromVisibleCatalog(state);
  return state;
}

function applyCatalogAnchorOverlayOnSnapshot(state, req = null) {
  if (!state || typeof state !== 'object') return state;
  const walletTxidSet = getWalletTxidSetSafe();
  const currentMerchantId = ensureCurrentMerchantId(state, req || {});
  const sameMerchantId = (a = '', b = '') => String(a || '').trim().toLowerCase() === String(b || '').trim().toLowerCase();
  const isCurrentMerchantRow = (merchantId = '') => Boolean(currentMerchantId && merchantId && sameMerchantId(merchantId, currentMerchantId));
  const hasPayloadField = (payload, field) => Object.prototype.hasOwnProperty.call(payload || {}, field);
  const eventMomentMs = (row) => payloadUpdatedAtMs(row?.payload || {}, String(row?.ts || ''));
  const categoryMap = new Map((Array.isArray(state.categories) ? state.categories : [])
    .map((row) => [String(row?.id || ''), { ...row }])
    .filter(([id]) => id));
  const productMap = new Map((Array.isArray(state.products) ? state.products : [])
    .map((row) => [String(row?.id || ''), { ...row }])
    .filter(([id]) => id));
  const categoryVersionMeta = new Map();
  const productVersionMeta = new Map();
  categoryMap.forEach((row, id) => {
    categoryVersionMeta.set(id, {
      version: Math.max(1, Number(row?.version || 1)),
      ts: payloadUpdatedAtMs(row || {}, String(row?.localUpdatedAt || '')),
    });
  });
  productMap.forEach((row, id) => {
    productVersionMeta.set(id, {
      version: Math.max(1, Number(row?.version || 1)),
      ts: payloadUpdatedAtMs(row || {}, String(row?.localUpdatedAt || '')),
    });
  });
  let applied = 0;
  let skippedSparseWithoutBase = 0;
  let rows = [];
  try {
    rows = getEffectiveAnchorRows(state)
      .filter((row) => /^(category|product)_/.test(String(row?.eventType || '')))
      .sort((a, b) => {
        const da = eventMomentMs(a);
        const db = eventMomentMs(b);
        if (da !== db) return da - db;
        const ta = Date.parse(String(a?.ts || '')) || 0;
        const tb = Date.parse(String(b?.ts || '')) || 0;
        if (ta !== tb) return ta - tb;
        return String(a?.txid || '').localeCompare(String(b?.txid || ''));
      });
  } catch (err) {
    appendMarketDebug('catalog_anchor_overlay_failed', { message: String(err?.message || err || '') });
    return state;
  }

  rows.forEach((row) => {
    const eventType = String(row?.eventType || '');
    const modifiedAt = Number.isFinite(eventMomentMs(row)) && eventMomentMs(row) > 0
      ? new Date(eventMomentMs(row)).toISOString()
      : String(row?.ts || '');
    const p = normalizeEventPayload(eventType, row?.payload || {}, modifiedAt);
    const eventTs = payloadUpdatedAtMs(p, modifiedAt);
    if (eventType === 'category_add' && p.id) {
      const id = String(p.id);
      if (!shouldApplyVersionedEntityEvent(categoryVersionMeta, id, p.version, eventTs)) return;
      const ownerMerchantId = resolveMerchantIdByOwnership(row, p.merchantId, currentMerchantId, walletTxidSet)
        || sanitizeMerchantId(p.merchantId || row?.merchantId || '');
      categoryMap.set(id, {
        id,
        name: String(p.name || id),
        merchantId: ownerMerchantId || 'm-local',
        version: Number(p.version || 1),
        deleted: false,
        ownedByCurrentWallet: Boolean(isAnchorOwnedByCurrentWallet(row, walletTxidSet) && isCurrentMerchantRow(ownerMerchantId)),
        localStatus: 'synced',
        localUpdatedAt: Number.isFinite(eventTs) && eventTs > 0 ? new Date(eventTs).toISOString() : modifiedAt,
      });
      applied += 1;
      return;
    }
    if (eventType === 'category_edit' && p.id) {
      const id = String(p.id);
      const existing = categoryMap.get(id);
      if (!existing) {
        skippedSparseWithoutBase += 1;
        return;
      }
      if (!shouldApplyVersionedEntityEvent(categoryVersionMeta, id, p.version, eventTs)) return;
      const ownerMerchantId = resolveMerchantIdByOwnership(row, p.merchantId, currentMerchantId, walletTxidSet)
        || sanitizeMerchantId(p.merchantId || existing.merchantId || row?.merchantId || '');
      if (ownerMerchantId) existing.merchantId = ownerMerchantId;
      if (hasPayloadField(p, 'name')) existing.name = String(p.name || existing.name || id);
      existing.version = Number(p.version || existing.version || 1);
      existing.deleted = false;
      existing.ownedByCurrentWallet = Boolean(isAnchorOwnedByCurrentWallet(row, walletTxidSet) && isCurrentMerchantRow(existing.merchantId));
      existing.localStatus = 'synced';
      existing.localUpdatedAt = Number.isFinite(eventTs) && eventTs > 0 ? new Date(eventTs).toISOString() : modifiedAt;
      applied += 1;
      return;
    }
    if (eventType === 'category_delete' && p.id) {
      const id = String(p.id);
      const existing = categoryMap.get(id);
      if (!existing) return;
      if (!shouldApplyVersionedEntityEvent(categoryVersionMeta, id, p.version, eventTs)) return;
      existing.version = Number(p.version || existing.version || 1);
      existing.deleted = true;
      existing.ownedByCurrentWallet = Boolean(isAnchorOwnedByCurrentWallet(row, walletTxidSet) && isCurrentMerchantRow(existing.merchantId));
      existing.localStatus = 'synced';
      existing.localUpdatedAt = Number.isFinite(eventTs) && eventTs > 0 ? new Date(eventTs).toISOString() : modifiedAt;
      applied += 1;
      return;
    }
    if (eventType === 'product_add' && p.id) {
      const id = String(p.id);
      if (!shouldApplyVersionedEntityEvent(productVersionMeta, id, p.version, eventTs)) return;
      const ownerMerchantId = resolveMerchantIdByOwnership(row, p.merchantId, currentMerchantId, walletTxidSet)
        || sanitizeMerchantId(p.merchantId || row?.merchantId || '');
      productMap.set(id, {
        id,
        merchantId: ownerMerchantId || 'm-local',
        ownedByCurrentWallet: Boolean(isAnchorOwnedByCurrentWallet(row, walletTxidSet) && isCurrentMerchantRow(ownerMerchantId)),
        categoryId: String(p.categoryId || ''),
        title: String(p.title || id),
        price: Number(p.price || 0),
        stock: Number(p.stock || 0),
        soldCount: Number(p.soldCount || 0),
        imageUrl: String(p.imageUrl || ''),
        description: String(p.description || ''),
        version: Number(p.version || 1),
        deleted: false,
        deleteSync: { acked: 1, total: 1 },
        localStatus: 'synced',
        localUpdatedAt: Number.isFinite(eventTs) && eventTs > 0 ? new Date(eventTs).toISOString() : modifiedAt,
      });
      applied += 1;
      return;
    }
    if ((eventType === 'product_edit' || eventType === 'product_bump') && p.id) {
      const id = String(p.id);
      const existing = productMap.get(id);
      if (!existing) {
        skippedSparseWithoutBase += 1;
        return;
      }
      if (!shouldApplyVersionedEntityEvent(productVersionMeta, id, p.version, eventTs)) return;
      const ownerMerchantId = resolveMerchantIdByOwnership(row, p.merchantId, currentMerchantId, walletTxidSet)
        || sanitizeMerchantId(p.merchantId || existing.merchantId || row?.merchantId || '');
      if (ownerMerchantId) existing.merchantId = ownerMerchantId;
      existing.ownedByCurrentWallet = Boolean(isAnchorOwnedByCurrentWallet(row, walletTxidSet) && isCurrentMerchantRow(existing.merchantId));
      if (hasPayloadField(p, 'categoryId')) existing.categoryId = String(p.categoryId || '');
      if (hasPayloadField(p, 'title')) existing.title = String(p.title ?? existing.title ?? id);
      if (hasPayloadField(p, 'price')) existing.price = Number(p.price ?? existing.price);
      if (hasPayloadField(p, 'stock')) existing.stock = Number(p.stock ?? existing.stock);
      if (hasPayloadField(p, 'soldCount')) existing.soldCount = Number(p.soldCount ?? existing.soldCount ?? 0);
      if (hasPayloadField(p, 'imageUrl')) existing.imageUrl = String(p.imageUrl || '');
      if (hasPayloadField(p, 'description')) existing.description = String(p.description || '');
      existing.version = Number(p.version || existing.version || 1);
      existing.deleted = false;
      existing.localStatus = 'synced';
      existing.localUpdatedAt = Number.isFinite(eventTs) && eventTs > 0 ? new Date(eventTs).toISOString() : modifiedAt;
      applied += 1;
      return;
    }
    if (eventType === 'product_delete' && p.id) {
      const id = String(p.id);
      const existing = productMap.get(id);
      if (!existing) return;
      if (!shouldApplyVersionedEntityEvent(productVersionMeta, id, p.version, eventTs)) return;
      if (row?.confirmed !== true) {
        const ageMs = Date.now() - Number(eventTs || 0);
        if (Number.isFinite(ageMs) && ageMs > UNCONFIRMED_DELETE_TTL_MS) return;
      }
      existing.version = Number(p.version || existing.version || 1);
      existing.deleted = true;
      existing.deleteSync = { acked: row?.confirmed === true ? 1 : 0, total: 1 };
      existing.ownedByCurrentWallet = Boolean(isAnchorOwnedByCurrentWallet(row, walletTxidSet) && isCurrentMerchantRow(existing.merchantId));
      existing.localStatus = 'synced';
      existing.localUpdatedAt = Number.isFinite(eventTs) && eventTs > 0 ? new Date(eventTs).toISOString() : modifiedAt;
      applied += 1;
    }
  });

  if (applied > 0 || skippedSparseWithoutBase > 0) {
    appendMarketDebug('catalog_anchor_overlay_on_snapshot', {
      rows: rows.length,
      applied,
      skippedSparseWithoutBase,
      products: productMap.size,
      categories: categoryMap.size,
    });
  }
  state.categories = Array.from(categoryMap.values());
  state.products = Array.from(productMap.values());
  return state;
}

function mapDbCategoryRow(row = null) {
  if (!row) return null;
  return {
    id: String(row.category_id || ''),
    merchantId: String(row.merchant_id || ''),
    name: String(row.name || ''),
    version: Math.max(1, Number(row.version || 1)),
    deleted: String(row.status || '') === 'deleted',
    ownedByCurrentWallet: Number(row.owned_by_current_wallet || 0) === 1,
    localStatus: String(row.local_status || 'synced'),
    localUpdatedAt: String(row.updated_at || ''),
  };
}

function mapDbProductRow(row = null) {
  if (!row) return null;
  return {
    id: String(row.product_id || ''),
    merchantId: String(row.merchant_id || ''),
    categoryId: String(row.category_id || ''),
    title: String(row.title || ''),
    description: String(row.description || ''),
    imageUrl: String(row.image_url || ''),
    price: Math.max(0, Number(row.price || 0)),
    stock: Math.max(0, Number(row.stock || 0)),
    soldCount: Math.max(0, Number(row.sold_count || 0)),
    version: Math.max(1, Number(row.version || 1)),
    deleted: String(row.status || '') === 'deleted',
    ownedByCurrentWallet: Number(row.owned_by_current_wallet || 0) === 1,
    localStatus: String(row.local_status || 'synced'),
    localUpdatedAt: String(row.updated_at || ''),
  };
}

function getCatalogProjectionRowById(entityType = '', id = '') {
  const safeId = String(id || '').trim();
  if (!safeId) return null;
  const db = marketDb.openReadDb();
  try {
    if (entityType === 'category') {
      return mapDbCategoryRow(db.prepare(`
        SELECT category_id, merchant_id, name, version, status, owned_by_current_wallet, local_status, updated_at
        FROM categories
        WHERE category_id = ?
        LIMIT 1
      `).get(safeId));
    }
    if (entityType === 'product') {
      return mapDbProductRow(db.prepare(`
        SELECT product_id, merchant_id, category_id, title, description, image_url, price, stock, sold_count,
               version, status, owned_by_current_wallet, local_status, updated_at
        FROM products
        WHERE product_id = ?
        LIMIT 1
      `).get(safeId));
    }
  } catch (_) {
    return null;
  } finally {
    try { db.close(); } catch (_) {}
  }
  return null;
}

function catalogEventIsNewerThanExisting(payload = {}, existing = null) {
  if (!existing) return true;
  const nextVersion = Math.max(1, Number(payload?.version || 1));
  const prevVersion = Math.max(1, Number(existing?.version || 1));
  if (nextVersion !== prevVersion) return nextVersion > prevVersion;
  const nextTs = payloadUpdatedAtMs(payload, String(payload?._updatedAt || ''));
  const prevTs = payloadUpdatedAtMs(existing, String(existing?.localUpdatedAt || ''));
  return nextTs >= prevTs;
}

async function applyCatalogAnchorRowsIncremental(rows = [], req = null) {
  const catalogRows = (Array.isArray(rows) ? rows : [])
    .filter((row) => /^(category|product)_/i.test(String(row?.eventType || '').trim()))
    .sort((a, b) => {
      const da = payloadUpdatedAtMs(a?.payload || {}, String(a?.ts || ''));
      const db = payloadUpdatedAtMs(b?.payload || {}, String(b?.ts || ''));
      if (da !== db) return da - db;
      return String(a?.txid || '').localeCompare(String(b?.txid || ''));
    });
  if (!catalogRows.length) return { applied: 0, categories: [], products: [] };
  const stateForIdentity = buildCoreStateFromSqlite(req || buildRuntimeAuthReq());
  const walletTxidSet = getWalletTxidSetSafe();
  const currentMerchantId = ensureCurrentMerchantId(stateForIdentity, req || buildRuntimeAuthReq());
  const sameMerchantId = (a = '', b = '') => String(a || '').trim().toLowerCase() === String(b || '').trim().toLowerCase();
  const isCurrentMerchantRow = (merchantId = '') => Boolean(currentMerchantId && merchantId && sameMerchantId(merchantId, currentMerchantId));
  const hasPayloadField = (payload, field) => Object.prototype.hasOwnProperty.call(payload || {}, field);
  const categoryCache = new Map();
  const productCache = new Map();
  const categoriesById = new Map();
  const productsById = new Map();
  const loadCategory = (id) => {
    const safeId = String(id || '').trim();
    if (!safeId) return null;
    if (!categoryCache.has(safeId)) categoryCache.set(safeId, getCatalogProjectionRowById('category', safeId));
    return categoryCache.get(safeId);
  };
  const loadProduct = (id) => {
    const safeId = String(id || '').trim();
    if (!safeId) return null;
    if (!productCache.has(safeId)) productCache.set(safeId, getCatalogProjectionRowById('product', safeId));
    return productCache.get(safeId);
  };

  for (const row of catalogRows) {
    const eventType = String(row?.eventType || '').trim();
    const modifiedAt = (() => {
      const ts = payloadUpdatedAtMs(row?.payload || {}, String(row?.ts || ''));
      return Number.isFinite(ts) && ts > 0 ? new Date(ts).toISOString() : String(row?.ts || new Date().toISOString());
    })();
    const p = normalizeEventPayload(eventType, row?.payload || {}, modifiedAt);
    const eventTs = payloadUpdatedAtMs(p, modifiedAt);
    const updatedAt = Number.isFinite(eventTs) && eventTs > 0 ? new Date(eventTs).toISOString() : modifiedAt;
    if (eventType === 'category_add' && p.id) {
      const id = String(p.id);
      const existing = categoriesById.get(id) || loadCategory(id);
      if (!catalogEventIsNewerThanExisting(p, existing)) continue;
      const ownerMerchantId = resolveMerchantIdByOwnership(row, p.merchantId, currentMerchantId, walletTxidSet)
        || sanitizeMerchantId(p.merchantId || row?.merchantId || existing?.merchantId || '');
      const next = {
        id,
        name: String(p.name || existing?.name || id),
        merchantId: ownerMerchantId || 'm-local',
        version: Number(p.version || existing?.version || 1),
        deleted: false,
        ownedByCurrentWallet: Boolean(isAnchorOwnedByCurrentWallet(row, walletTxidSet) && isCurrentMerchantRow(ownerMerchantId)),
        localStatus: 'synced',
        localUpdatedAt: updatedAt,
      };
      categoriesById.set(id, next);
      categoryCache.set(id, next);
      continue;
    }
    if (eventType === 'category_edit' && p.id) {
      const id = String(p.id);
      const existing = categoriesById.get(id) || loadCategory(id);
      if (!existing || !catalogEventIsNewerThanExisting(p, existing)) continue;
      const ownerMerchantId = resolveMerchantIdByOwnership(row, p.merchantId, currentMerchantId, walletTxidSet)
        || sanitizeMerchantId(p.merchantId || existing.merchantId || row?.merchantId || '');
      const next = {
        ...existing,
        merchantId: ownerMerchantId || existing.merchantId || 'm-local',
        name: hasPayloadField(p, 'name') ? String(p.name || existing.name || id) : String(existing.name || id),
        version: Number(p.version || existing.version || 1),
        deleted: false,
        ownedByCurrentWallet: Boolean(isAnchorOwnedByCurrentWallet(row, walletTxidSet) && isCurrentMerchantRow(ownerMerchantId || existing.merchantId)),
        localStatus: 'synced',
        localUpdatedAt: updatedAt,
      };
      categoriesById.set(id, next);
      categoryCache.set(id, next);
      continue;
    }
    if (eventType === 'category_delete' && p.id) {
      const id = String(p.id);
      const existing = categoriesById.get(id) || loadCategory(id);
      if (!existing || !catalogEventIsNewerThanExisting(p, existing)) continue;
      const next = {
        ...existing,
        version: Number(p.version || existing.version || 1),
        deleted: true,
        ownedByCurrentWallet: Boolean(isAnchorOwnedByCurrentWallet(row, walletTxidSet) && isCurrentMerchantRow(existing.merchantId)),
        localStatus: 'synced',
        localUpdatedAt: updatedAt,
      };
      categoriesById.set(id, next);
      categoryCache.set(id, next);
      continue;
    }
    if (eventType === 'product_add' && p.id) {
      const id = String(p.id);
      const existing = productsById.get(id) || loadProduct(id);
      if (!catalogEventIsNewerThanExisting(p, existing)) continue;
      const ownerMerchantId = resolveMerchantIdByOwnership(row, p.merchantId, currentMerchantId, walletTxidSet)
        || sanitizeMerchantId(p.merchantId || row?.merchantId || existing?.merchantId || '');
      const next = {
        id,
        merchantId: ownerMerchantId || 'm-local',
        ownedByCurrentWallet: Boolean(isAnchorOwnedByCurrentWallet(row, walletTxidSet) && isCurrentMerchantRow(ownerMerchantId)),
        categoryId: String(p.categoryId || existing?.categoryId || ''),
        title: String(p.title || existing?.title || id),
        price: Number(p.price || existing?.price || 0),
        stock: Number(p.stock || existing?.stock || 0),
        soldCount: Number(p.soldCount || existing?.soldCount || 0),
        imageUrl: String(p.imageUrl || existing?.imageUrl || ''),
        description: String(p.description || existing?.description || ''),
        version: Number(p.version || existing?.version || 1),
        deleted: false,
        deleteSync: { acked: 1, total: 1 },
        localStatus: 'synced',
        localUpdatedAt: updatedAt,
      };
      productsById.set(id, next);
      productCache.set(id, next);
      continue;
    }
    if ((eventType === 'product_edit' || eventType === 'product_bump') && p.id) {
      const id = String(p.id);
      const existing = productsById.get(id) || loadProduct(id);
      if (!existing) {
        appendMarketDebug('catalog_incremental_sparse_product_missing_base', {
          id,
          eventType,
          txid: String(row?.txid || ''),
        });
        continue;
      }
      if (!catalogEventIsNewerThanExisting(p, existing)) continue;
      const ownerMerchantId = resolveMerchantIdByOwnership(row, p.merchantId, currentMerchantId, walletTxidSet)
        || sanitizeMerchantId(p.merchantId || existing.merchantId || row?.merchantId || '');
      const next = {
        ...existing,
        merchantId: ownerMerchantId || existing.merchantId || 'm-local',
        ownedByCurrentWallet: Boolean(isAnchorOwnedByCurrentWallet(row, walletTxidSet) && isCurrentMerchantRow(ownerMerchantId || existing.merchantId)),
        categoryId: hasPayloadField(p, 'categoryId') ? String(p.categoryId || '') : String(existing.categoryId || ''),
        title: hasPayloadField(p, 'title') ? String(p.title ?? existing.title ?? id) : String(existing.title || id),
        price: hasPayloadField(p, 'price') ? Number(p.price ?? existing.price ?? 0) : Number(existing.price || 0),
        stock: hasPayloadField(p, 'stock') ? Number(p.stock ?? existing.stock ?? 0) : Number(existing.stock || 0),
        soldCount: hasPayloadField(p, 'soldCount') ? Number(p.soldCount ?? existing.soldCount ?? 0) : Number(existing.soldCount || 0),
        imageUrl: hasPayloadField(p, 'imageUrl') ? String(p.imageUrl || '') : String(existing.imageUrl || ''),
        description: hasPayloadField(p, 'description') ? String(p.description || '') : String(existing.description || ''),
        version: Number(p.version || existing.version || 1),
        deleted: false,
        localStatus: 'synced',
        localUpdatedAt: updatedAt,
      };
      productsById.set(id, next);
      productCache.set(id, next);
      continue;
    }
    if (eventType === 'product_delete' && p.id) {
      const id = String(p.id);
      const existing = productsById.get(id) || loadProduct(id);
      if (!existing || !catalogEventIsNewerThanExisting(p, existing)) continue;
      const next = {
        ...existing,
        version: Number(p.version || existing.version || 1),
        deleted: true,
        deleteSync: { acked: row?.confirmed === true ? 1 : 0, total: 1 },
        ownedByCurrentWallet: Boolean(isAnchorOwnedByCurrentWallet(row, walletTxidSet) && isCurrentMerchantRow(existing.merchantId)),
        localStatus: 'synced',
        localUpdatedAt: updatedAt,
      };
      productsById.set(id, next);
      productCache.set(id, next);
    }
  }

  const categories = Array.from(categoriesById.values());
  const products = Array.from(productsById.values());
  if (categories.length || products.length) {
    await marketDb.replaceCatalogSnapshot({ categories, products, resetAll: false });
    categories.forEach((category) => {
      frontendEventGateway?.publishInfo?.(
        category.deleted ? 'catalog.category.deleted' : (Number(category.version || 0) <= 1 ? 'catalog.category.added' : 'catalog.category.updated'),
        'catalog',
        { category },
      );
    });
    products.forEach((product) => {
      frontendEventGateway?.publishInfo?.(
        product.deleted ? 'catalog.product.deleted' : (Number(product.version || 0) <= 1 ? 'catalog.product.added' : 'catalog.product.updated'),
        'catalog',
        { product },
      );
    });
  }
  appendMarketDebug('catalog_incremental_anchor_applied', {
    inputRows: catalogRows.length,
    categories: categories.length,
    products: products.length,
  });
  return { applied: categories.length + products.length, categories, products };
}

function enrichCatalogMerchantsFromVisibleCatalog(state) {
  if (!state || typeof state !== 'object') return state;
  const currentMerchantId = sanitizeMerchantId(state.currentMerchantId || '');
  const namesByMerchant = new Map();
  const metaByMerchant = new Map();
  const touchMerchant = (merchantIdRaw, tsRaw = '') => {
    const merchantId = sanitizeMerchantId(merchantIdRaw || '');
    if (!merchantId) return;
    const prev = metaByMerchant.get(merchantId) || { id: merchantId, downloadedAt: 0 };
    const ts = Date.parse(String(tsRaw || '')) || Number(tsRaw || 0) || 0;
    metaByMerchant.set(merchantId, {
      id: merchantId,
      downloadedAt: Math.max(Number(prev.downloadedAt || 0), Number(ts || 0), Date.now()),
    });
  };
  (Array.isArray(state.merchants) ? state.merchants : []).forEach((m) => {
    const merchantId = sanitizeMerchantId(m?.id || '');
    if (!merchantId) return;
    const name = String(m?.name || '').trim();
    if (name) namesByMerchant.set(merchantId, name);
    touchMerchant(merchantId, m?.downloadedAt || '');
  });
  if (currentMerchantId && String(state.profile?.name || '').trim()) {
    namesByMerchant.set(currentMerchantId, String(state.profile.name || '').trim());
  }
  try {
    getEffectiveAnchorRows(state)
      .filter((row) => String(row?.eventType || '') === 'profile_set')
      .forEach((row) => {
        const payload = normalizeEventPayload('profile_set', row?.payload || {}, String(row?.ts || ''));
        const merchantId = sanitizeMerchantId(payload?.merchantId || '');
        const name = String(payload?.name || '').trim();
        if (!merchantId) return;
        if (name) namesByMerchant.set(merchantId, name);
        touchMerchant(merchantId, payload?._updatedAt || row?.ts || '');
      });
  } catch (err) {
    appendMarketDebug('catalog_merchant_name_enrich_failed', { message: String(err?.message || err || '') });
  }
  (Array.isArray(state.categories) ? state.categories : []).forEach((c) => {
    if (c?.deleted === true) return;
    touchMerchant(c?.merchantId, c?.localUpdatedAt);
  });
  (Array.isArray(state.products) ? state.products : []).forEach((p) => {
    if (p?.deleted && Number(p?.deleteSync?.acked || 0) >= Number(p?.deleteSync?.total || 0)) return;
    touchMerchant(p?.merchantId, p?.localUpdatedAt);
  });
  state.merchants = Array.from(metaByMerchant.values())
    .map((m) => {
      const name = merchantDisplayName(m.id, namesByMerchant.get(m.id) || '');
      getOrCreateSellerUser(state, m.id, name);
      return { id: m.id, name, downloadedAt: Number(m.downloadedAt || Date.now()) };
    })
    .sort((a, b) => {
      const aCurrent = a.id === currentMerchantId ? 1 : 0;
      const bCurrent = b.id === currentMerchantId ? 1 : 0;
      if (aCurrent !== bCurrent) return bCurrent - aCurrent;
      return Number(b.downloadedAt || 0) - Number(a.downloadedAt || 0);
    });
  return state;
}

function buildCoreStateFromSqlite(req = null) {
  const state = trimStateToCoreDomains(defaultState(), req);
  const rawState = loadParsedJsonFileCached(STATE_FILE) || {};
  if (rawState?.steward && typeof rawState.steward === 'object') {
    state.steward = {
      ...state.steward,
      ...rawState.steward,
    };
  }
  applySqliteSyncStateRow(state.sync, loadSyncStateRowFromSqlite());
  const sqliteProfile = loadProfileSnapshotFromSqlite();
  if (sqliteProfile) {
    state.profile = {
      ...state.profile,
      name: String(sqliteProfile.name || state.profile?.name || ''),
      localStatus: String(sqliteProfile.localStatus || state.profile?.localStatus || ''),
      localUpdatedAt: String(sqliteProfile.localUpdatedAt || state.profile?.localUpdatedAt || ''),
    };
  }
  const sessionMerchantId = req ? sanitizeMerchantId(deriveMerchantIdForSession(req)) : '';
  const profileMerchantId = sanitizeMerchantId(sqliteProfile?.merchantId || '');
  state.currentMerchantId = sessionMerchantId || profileMerchantId || state.currentMerchantId || 'm-local';
  state.users = [{ id: 'buyer', name: String(state.profile?.name || '买家A'), role: 'buyer' }];
  return state;
}

function buildFastProjectionLiteState(req = null) {
  const state = buildCoreStateFromSqlite(req);
  const sqliteCatalog = loadCatalogSnapshotFromSqlite();
  if (sqliteCatalog) {
    state.categories = Array.isArray(sqliteCatalog.categories) ? sqliteCatalog.categories : [];
    state.products = Array.isArray(sqliteCatalog.products) ? sqliteCatalog.products : [];
  }
  const sqliteLocalState = localStateDomain.getLocalStateSync('main');
  if (sqliteLocalState && typeof sqliteLocalState === 'object') {
    state.pendingAnchors = (Array.isArray(sqliteLocalState.pendingAnchors) ? sqliteLocalState.pendingAnchors : [])
      .filter((row) => row?.confirmed !== true)
      .map((row) => ({
        ...row,
        payload: row?.payload && typeof row.payload === 'object' ? row.payload : {},
      }));
    state.recentRawtxs = Array.isArray(sqliteLocalState.recentRawtxs)
      ? sqliteLocalState.recentRawtxs.map((row) => ({ ...row }))
      : [];
    state.localChanges = {
      seq: Math.max(1, Number(sqliteLocalState.seq || 1)),
      queue: Array.isArray(sqliteLocalState.localChanges)
        ? sqliteLocalState.localChanges.map((row) => ({ ...row }))
        : [],
    };
  }
  if (!Array.isArray(state.pendingAnchors)) state.pendingAnchors = [];
  if (!Array.isArray(state.recentRawtxs)) state.recentRawtxs = [];
  if (!state.localChanges || typeof state.localChanges !== 'object') state.localChanges = { seq: 1, queue: [] };
  if (!Array.isArray(state.localChanges.queue)) state.localChanges.queue = [];
  state.orders = listActiveProtocolOrdersSync();
  if (state.currentMerchantId && state.currentMerchantId !== 'm-local') {
    const merchantName = merchantDisplayName(state.currentMerchantId, String(state.profile?.name || ''));
    state.merchants = [{ id: state.currentMerchantId, name: merchantName, downloadedAt: Date.now() }];
  }
  enrichCatalogMerchantsFromVisibleCatalog(state);
  return state;
}

function getOrderPayloadValue(payload = {}, ...keys) {
  const safePayload = payload && typeof payload === 'object' ? payload : {};
  for (const key of keys) {
    if (Object.prototype.hasOwnProperty.call(safePayload, key) && safePayload[key] !== undefined && safePayload[key] !== null && String(safePayload[key]).trim() !== '') {
      return safePayload[key];
    }
  }
  return undefined;
}

function expandCompactOrderPlacePayload(payload = []) {
  const arr = Array.isArray(payload) ? payload : [];
  const v = Math.max(0, Number(arr[0] || 0));
  const pid = String(arr[1] || '').trim();
  const q = Math.max(1, Number(arr[2] || 1));
  const ps = Math.max(0, Number(arr[3] || 0));
  const bp = String(arr[4] || '').trim();
  const sp = String(arr[5] || '').trim();
  const br = String(arr[6] || '').trim();
  const on = String(arr[7] || '').trim();
  const sm = String(arr[8] || '').trim();
  const sw = String(arr[9] || '').trim();
  const bd = Math.floor(ps * 0.2);
  const sd = computeOrderSellerDepositSatsForProtocol(ps);
  const bs = ps + bd;
  const base = {
    v,
    pt: '',
    pid,
    q,
    ps,
    bd,
    sd,
    bp,
    sp,
    br,
    on,
    sm,
    sw,
    bv: 0,
    bs,
  };
  const buyerLockRedeemScriptHex = deriveOrderBuyerLockRedeemScriptHexFromPayload(base);
  const jointRedeemScriptHex = deriveOrderJointRedeemScriptHexFromPayload(base);
  return {
    ...base,
    bh: orderProtocolV3.scriptHashHex(buyerLockRedeemScriptHex),
    jh: orderProtocolV3.scriptHashHex(jointRedeemScriptHex),
  };
}

function compactOrderPlacePayload(payload = {}) {
  const safe = payload && typeof payload === 'object' ? payload : {};
  return [
    Math.max(0, Number(getOrderPayloadValue(safe, 'v', 'orderProtocolVersion') || 3)),
    String(getOrderPayloadValue(safe, 'pid', 'productId', 'product_id') || '').trim(),
    Math.max(1, Number(getOrderPayloadValue(safe, 'q', 'quantity') || 1)),
    Math.max(0, Number(getOrderPayloadValue(safe, 'ps', 'priceSats', 'priceSnapshot') || 0)),
    String(getOrderPayloadValue(safe, 'bp', 'buyerChatPubKey') || '').trim(),
    String(getOrderPayloadValue(safe, 'sp', 'sellerChatPubKey') || '').trim(),
    String(getOrderPayloadValue(safe, 'br', 'buyerRefundAddress') || '').trim(),
    String(getOrderPayloadValue(safe, 'on', 'orderNonce') || '').trim(),
    String(getOrderPayloadValue(safe, 'sm', 'sellerMerchantId', 'merchantId') || '').trim(),
    String(getOrderPayloadValue(safe, 'sw', 'sellerWalletId') || '').trim(),
  ];
}

function computeOrderSellerDepositSatsForProtocol(priceSats) {
  const safePrice = Math.max(0, Math.floor(Number(priceSats || 0)));
  if (safePrice <= 0) return 0;
  return Math.max(1000, Math.floor(safePrice * 0.10));
}

function deriveOrderJointRedeemScriptHexFromPayload(payload = {}) {
  const buyerPubKey = String(getOrderPayloadValue(payload, 'bp', 'buyerChatPubKey') || '').trim();
  const sellerPubKey = String(getOrderPayloadValue(payload, 'sp', 'sellerChatPubKey') || '').trim();
  if (!buyerPubKey || !sellerPubKey) return '';
  try {
    return String(wallet.buildOrderJointRedeemScript({
      buyerChatPubKey: buyerPubKey,
      sellerChatPubKey: sellerPubKey,
    }).toHex() || '').trim();
  } catch (_) {
    return '';
  }
}

function deriveOrderBuyerLockRedeemScriptHexFromPayload(payload = {}) {
  const buyerRefundAddress = String(getOrderPayloadValue(payload, 'br', 'buyerRefundAddress') || '').trim();
  if (buyerRefundAddress) {
    try {
      return bsv.Script.buildPublicKeyHashOut(buyerRefundAddress).toHex();
    } catch (_) {}
  }
  const buyerPubKey = String(getOrderPayloadValue(payload, 'bp', 'buyerChatPubKey') || '').trim();
  const sellerPubKey = String(getOrderPayloadValue(payload, 'sp', 'sellerChatPubKey') || '').trim();
  const timeoutAt = Math.max(0, Number(getOrderPayloadValue(payload, 'to', 'timeoutAt') || 0));
  if (!buyerPubKey || !sellerPubKey) return '';
  try {
    return String(wallet.buildOrderBuyerLockRedeemScript({
      buyerChatPubKey: buyerPubKey,
      sellerChatPubKey: sellerPubKey,
      timeoutAt,
    }).toHex() || '').trim();
  } catch (_) {
    return '';
  }
}

function buildOrderSnapshotFromAnchorPayload(payload = {}, state = null) {
  const sourcePayload = Array.isArray(payload) ? expandCompactOrderPlacePayload(payload) : payload;
  const productId = String(getOrderPayloadValue(sourcePayload, 'pid', 'productId', 'product_id') || '').trim();
  const product = Array.isArray(state?.products)
    ? state.products.find((row) => String(row?.id || '').trim() === productId)
    : null;
  return {
    product_id: productId,
    product_version: Math.max(0, Number(getOrderPayloadValue(sourcePayload, 'pv', 'productVersion', 'product_version') || product?.version || 0)),
    price_snapshot: Math.max(0, Number(getOrderPayloadValue(sourcePayload, 'ps', 'priceSnapshot', 'price_snapshot', 'price', 'priceSats') || bsvAmountToSat(product?.price || 0))),
    stock_snapshot: Math.max(0, Number(getOrderPayloadValue(sourcePayload, 'stockSnapshot', 'stock_snapshot') || product?.stock || 0)),
    quantity: Math.max(1, Number(getOrderPayloadValue(sourcePayload, 'q', 'quantity') || 1)),
    merchant_id: String(getOrderPayloadValue(sourcePayload, 'sm', 'sellerMerchantId', 'merchantId') || product?.merchantId || '').trim(),
    category_id: String(getOrderPayloadValue(sourcePayload, 'categoryId') || product?.categoryId || '').trim(),
    title: String(getOrderPayloadValue(sourcePayload, 'title') || product?.title || '').trim(),
  };
}

function enrichOrderSnapshotFromCatalog(orderLike, products = []) {
  const order = migrateOrderModel(orderLike || {});
  const productId = String(order?.snapshot?.product_id || '').trim();
  if (!productId) return order;
  const product = Array.isArray(products)
    ? products.find((row) => String(row?.id || '').trim() === productId)
    : null;
  if (!product) return order;
  order.snapshot = {
    ...(order.snapshot || {}),
    product_version: Math.max(0, Number(order?.snapshot?.product_version || product?.version || 0)),
    price_snapshot: Math.max(0, Number(order?.snapshot?.price_snapshot || bsvAmountToSat(product?.price || 0))),
    stock_snapshot: Math.max(0, Number(order?.snapshot?.stock_snapshot || product?.stock || 0)),
    merchant_id: String(order?.snapshot?.merchant_id || product?.merchantId || '').trim(),
    category_id: String(order?.snapshot?.category_id || product?.categoryId || '').trim(),
    title: String(order?.snapshot?.title || product?.title || '').trim(),
  };
  return order;
}

function bsvAmountToSat(value) {
  return Math.max(0, Math.round(Number(value || 0) * 100000000));
}

function satToBsv(value) {
  return Math.max(0, Number(value || 0)) / 100000000;
}

function buildOrderPlaceChainPayload(product, quantity, payloadContext, sellerChatPubKey, timeoutAt) {
  const safeProduct = product && typeof product === 'object' ? product : {};
  const safeCtx = payloadContext && typeof payloadContext === 'object' ? payloadContext : {};
  const sellerMerchantId = sanitizeMerchantId(safeProduct.merchantId || safeProduct.merchant_id || safeProduct.merchant);
  const sellerWalletId = String(safeCtx.sellerWalletId || walletIdByMerchant(sellerMerchantId) || '').trim();
  const priceSats = bsvAmountToSat(Number(safeProduct.price || 0) * Math.max(1, Number(quantity || 1)));
  const buyerDepositSats = Math.floor(priceSats * 0.2);
  const buyerLockRedeemScriptHex = String(safeCtx.buyerLockRedeemScriptHex || '').trim();
  const jointRedeemScriptHex = (() => {
    const buyerPubKey = String(safeCtx.buyerChatPubKey || '').trim();
    const sellerPubKey = String(sellerChatPubKey || '').trim();
    if (!buyerPubKey || !sellerPubKey) return '';
    try {
      return wallet.buildOrderJointRedeemScript({
        buyerChatPubKey: buyerPubKey,
        sellerChatPubKey: sellerPubKey,
      }).toHex();
    } catch (_) {
      return '';
    }
  })();
  return withSchemaMeta('order_place', {
    v: 3,
    pt: '',
    sm: sellerMerchantId,
    bw: String(safeCtx.buyerWalletId || '').trim(),
    sw: sellerWalletId,
    pid: String(safeProduct.id || safeProduct.product_id || '').trim(),
    pv: Math.max(0, Number(safeProduct.version || 0)),
    q: Math.max(1, Number(quantity || 1)),
    ps: priceSats,
    bd: buyerDepositSats,
    sd: computeOrderSellerDepositSatsForProtocol(priceSats),
    bp: String(safeCtx.buyerChatPubKey || '').trim(),
    sp: String(sellerChatPubKey || '').trim(),
    br: String(safeCtx.buyerRefundAddress || '').trim(),
    on: String(safeCtx.orderNonce || '').trim(),
    bv: 0,
    bs: priceSats + buyerDepositSats,
    bh: orderProtocolV3.scriptHashHex(buyerLockRedeemScriptHex),
    jh: orderProtocolV3.scriptHashHex(jointRedeemScriptHex),
    to: Math.max(0, Number(timeoutAt || 0)),
  });
}

function storeOrderTxContextFromRawtx(rawtx, {
  txid = '',
  source = 'order_anchor',
  kind = 'order_anchor',
  confirmed = false,
  height = 0,
  node = '',
} = {}) {
  const safeRawtx = typeof wallet.rawtxHexFromUnknown === 'function'
    ? String(wallet.rawtxHexFromUnknown(rawtx) || '').trim()
    : String(rawtx || '').trim();
  if (!safeRawtx || typeof wallet.upsertTxContext !== 'function') return null;
  try {
    const info = typeof wallet.inspectRawTx === 'function' ? wallet.inspectRawTx(safeRawtx) : null;
    const safeTxid = String(txid || info?.txid || '').trim().toLowerCase();
    if (!/^[0-9a-f]{64}$/i.test(safeTxid)) return null;
    const row = wallet.upsertTxContext(safeRawtx, {
      source: String(source || 'order_anchor'),
      kind: String(kind || 'order_anchor'),
      confirmed: confirmed === true,
      firstSeenHeight: Math.max(0, Number(height || 0)),
    });
    appendMarketDebug('order_tx_context_saved', {
      txid: safeTxid,
      source: String(source || ''),
      kind: String(kind || ''),
      confirmed: confirmed === true,
      height: Math.max(0, Number(height || 0)),
      node: String(node || ''),
      rawtxBytes: Math.floor(safeRawtx.length / 2),
    });
    return row;
  } catch (err) {
    appendMarketDebug('order_tx_context_save_failed', {
      txid: String(txid || ''),
      source: String(source || ''),
      kind: String(kind || ''),
      message: String(err?.message || err || ''),
    });
    return null;
  }
}

function getOrderPlacePrevoutFromTxContext(txid, vout = 0) {
  const safeTxid = String(txid || '').trim().toLowerCase();
  const safeVout = Math.max(0, Number(vout || 0));
  if (!/^[0-9a-f]{64}$/i.test(safeTxid) || typeof wallet.getTxContextByTxid !== 'function') return null;
  try {
    const ctx = wallet.getTxContextByTxid(safeTxid);
    const rawtx = String(ctx?.rawtx || '').trim();
    if (!rawtx || !bsv || typeof bsv.Transaction !== 'function') return null;
    const tx = new bsv.Transaction(rawtx);
    const output = Array.isArray(tx?.outputs) ? tx.outputs[safeVout] : null;
    if (!output) return null;
    return {
      txid: safeTxid,
      vout: safeVout,
      satoshis: Math.max(0, Number(output.satoshis || 0)),
      scriptHex: typeof output?.script?.toHex === 'function' ? String(output.script.toHex() || '') : '',
      rawtx,
    };
  } catch (_) {
    return null;
  }
}

async function ensureOrderActionTxContexts(order, action) {
  if (!order || typeof order !== 'object' || typeof wallet.ensureDirectParentTxContexts !== 'function') {
    return { requested: 0, inserted: 0, skipped: 0, missingTxids: [] };
  }
  const safeAction = String(action || '').trim();
  const chain = order.chain && typeof order.chain === 'object' ? order.chain : {};
  const txids = [];
  const needsBuyerLock = new Set([
    'accept',
    'cancel',
    'sellerCancel',
    'timeoutCancel',
    'confirmReceipt',
    'requestRefund',
    'confirmRefund',
  ]);
  const needsSellerLock = new Set([
    'confirmReceipt',
    'requestRefund',
    'confirmRefund',
  ]);
  if (needsBuyerLock.has(safeAction)) txids.push(String(chain.buyerLockTxid || chain.placeTxid || '').trim());
  if (needsSellerLock.has(safeAction)) txids.push(String(chain.sellerLockTxid || '').trim());
  const unique = Array.from(new Set(txids
    .map((txid) => String(txid || '').trim().toLowerCase())
    .filter((txid) => /^[0-9a-f]{64}$/i.test(txid))));
  if (!unique.length) return { requested: 0, inserted: 0, skipped: 0, missingTxids: [] };
  const result = await wallet.ensureDirectParentTxContexts(unique, {
    sourceLabel: 'order_action_prevout_backfill',
    kindLabel: `order_action_${safeAction || 'unknown'}_prevout`,
    confirmed: false,
  });
  appendMarketDebug('order_action_prevout_backfill', {
    orderId: String(order?.id || ''),
    action: safeAction,
    txids: unique,
    requested: Number(result?.requested || 0),
    inserted: Number(result?.inserted || 0),
    skipped: Number(result?.skipped || 0),
    missingTxids: Array.isArray(result?.missingTxids) ? result.missingTxids.slice(0, 8) : [],
  });
  return result;
}

function hydrateOrderSuppliedTxContexts(order, action) {
  if (!order || typeof order !== 'object' || typeof wallet.upsertTxContext !== 'function') return 0;
  const safeAction = String(action || '').trim();
  const chain = order.chain && typeof order.chain === 'object' ? order.chain : {};
  const rawtxs = [];
  if (safeAction === 'confirmRefund') {
    if (String(chain.refundRequestRawtx || '').trim()) rawtxs.push(chain.refundRequestRawtx);
    if (Array.isArray(chain.refundFeeContextRawtxs)) rawtxs.push(...chain.refundFeeContextRawtxs);
  }
  let inserted = 0;
  for (const rawtx of rawtxs) {
    const safeRawtx = wallet.rawtxHexFromUnknown(rawtx);
    if (!safeRawtx) continue;
    try {
      const row = wallet.upsertTxContext(safeRawtx, {
        source: `order_supplied_context:${safeAction || 'unknown'}`,
        kind: `order_supplied_context_${safeAction || 'unknown'}`,
        confirmed: false,
        height: 0,
        node: 'supplied_order',
      });
      if (row?.txid) inserted += 1;
    } catch (_) {}
  }
  if (inserted > 0) {
    appendMarketDebug('order_supplied_tx_context_hydrated', {
      orderId: String(order?.id || ''),
      action: safeAction,
      inserted,
    });
  }
  return inserted;
}

function isProtocolV1Order(row = {}) {
  const id = String(row?.id || row?.orderId || '').trim();
  const version = Number(row?.chain?.orderProtocolVersion || 0);
  return version >= 1 || id.startsWith('order:');
}

function filterProjectedOrdersForActiveProtocol(rows = []) {
  const list = hydrateOrderPlaceTimesForDisplay(Array.isArray(rows) ? rows.slice() : []);
  const hasProtocolV1 = list.some((row) => isProtocolV1Order(row));
  if (!hasProtocolV1) return sortOrdersForDisplay(list);
  return sortOrdersForDisplay(list.filter((row) => isProtocolV1Order(row)));
}

function orderUpdatedAtMs(row = {}) {
  const raw = row?.updatedAt ?? row?.updated_at ?? row?.updated ?? 0;
  const numeric = Number(raw);
  if (Number.isFinite(numeric) && numeric > 0) return numeric;
  return Date.parse(String(raw || '')) || 0;
}

function orderPlacedAtMs(row = {}) {
  const chain = row?.chain && typeof row.chain === 'object' ? row.chain : {};
  const candidates = [
    row?.createdAt,
    row?.created_at,
    row?.placedAt,
    row?.placed_at,
    row?.createdTs,
    row?.created_ts,
    chain?.placeTime,
    chain?.placedAt,
    chain?.createdAt,
    row?.timestamp,
    row?.time,
  ];
  for (const raw of candidates) {
    if (raw === undefined || raw === null || raw === '') continue;
    const numeric = Number(raw);
    if (Number.isFinite(numeric) && numeric > 0) {
      return numeric < 100000000000 ? numeric * 1000 : numeric;
    }
    const parsed = Date.parse(String(raw || ''));
    if (Number.isFinite(parsed) && parsed > 0) return parsed;
  }
  return 0;
}

function loadOrderPlaceTimesByIdFromSqlite() {
  const byId = new Map();
  try {
    const dbFile = marketDb.getDbFilePath();
    if (!dbFile || !fs.existsSync(dbFile)) return byId;
    const db = marketDb.openReadDb();
    try {
      const rows = db.prepare(`
        SELECT txid, payload_json, ts
        FROM anchor_events
        WHERE event_type IN ('order_place', 'order_open')
        ORDER BY ts ASC, event_id ASC
        LIMIT 5000
      `).all();
      for (const row of rows) {
        const txid = String(row?.txid || '').trim();
        let payload = {};
        try { payload = JSON.parse(String(row?.payload_json || '{}')); } catch (_) {}
        const orderId = deriveOrderIdFromAnchorRow({
          eventType: 'order_place',
          txid,
          payload,
        });
        const ts = String(row?.ts || '').trim();
        if (!orderId || !ts) continue;
        byId.set(orderId, ts);
      }
    } finally {
      db.close();
    }
  } catch (_) {}
  return byId;
}

function hydrateOrderPlaceTimesForDisplay(rows = []) {
  const list = Array.isArray(rows) ? rows : [];
  const needsHydration = list.some((row) => String(row?.id || row?.orderId || '').trim() && orderPlacedAtMs(row) <= 0);
  if (!needsHydration) return list.slice();
  const placeTimes = loadOrderPlaceTimesByIdFromSqlite();
  if (!placeTimes.size) return list.slice();
  return list.map((row) => {
    const orderId = String(row?.id || row?.orderId || '').trim();
    const placeTime = placeTimes.get(orderId);
    if (!placeTime || orderPlacedAtMs(row) > 0) return row;
    const chain = row?.chain && typeof row.chain === 'object' ? { ...row.chain } : {};
    chain.placeTime = chain.placeTime || placeTime;
    return {
      ...row,
      createdAt: row?.createdAt || placeTime,
      placedAt: row?.placedAt || placeTime,
      chain,
    };
  });
}

function sortOrdersForDisplay(rows = []) {
  return hydrateOrderPlaceTimesForDisplay(Array.isArray(rows) ? rows.slice() : []).sort((a, b) => {
    const pt = orderPlacedAtMs(b) - orderPlacedAtMs(a);
    if (pt !== 0) return pt;
    const dt = orderUpdatedAtMs(b) - orderUpdatedAtMs(a);
    if (dt !== 0) return dt;
    return String(a?.id || a?.orderId || '').localeCompare(String(b?.id || b?.orderId || ''));
  });
}

function persistOrderProjectionRowsSync(rows = [], producer = 'orders_anchor_rebuild_sync') {
  const list = Array.isArray(rows) ? rows.filter((row) => String(row?.id || row?.orderId || '').trim()) : [];
  if (!list.length || !DatabaseSync) return 0;
  const dbFile = marketDb.getDbFilePath();
  if (!dbFile) return 0;
  let db = null;
  try {
    db = new DatabaseSync(dbFile);
    db.exec(`
      CREATE TABLE IF NOT EXISTS order_projection (
        order_id TEXT PRIMARY KEY,
        status TEXT NOT NULL DEFAULT '',
        snapshot_json TEXT NOT NULL DEFAULT '{}',
        funds_json TEXT NOT NULL DEFAULT '{}',
        transition_ids_json TEXT NOT NULL DEFAULT '[]',
        tip TEXT NOT NULL DEFAULT '',
        updated_at TEXT NOT NULL,
        last_event_seq INTEGER NOT NULL DEFAULT 0,
        payload_json TEXT NOT NULL DEFAULT '{}'
      );
      CREATE INDEX IF NOT EXISTS idx_order_projection_status_updated
        ON order_projection(status, updated_at DESC, order_id ASC);
    `);
    const stmt = db.prepare(`
      INSERT INTO order_projection (
        order_id, status, snapshot_json, funds_json, transition_ids_json,
        tip, updated_at, last_event_seq, payload_json
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
      ON CONFLICT(order_id) DO UPDATE SET
        status = excluded.status,
        snapshot_json = excluded.snapshot_json,
        funds_json = excluded.funds_json,
        transition_ids_json = excluded.transition_ids_json,
        tip = excluded.tip,
        updated_at = excluded.updated_at,
        last_event_seq = excluded.last_event_seq,
        payload_json = excluded.payload_json
    `);
    db.exec('BEGIN IMMEDIATE');
    try {
      for (const row of list) {
        const orderId = String(row?.id || row?.orderId || '').trim();
        if (!orderId) continue;
        stmt.run(
          orderId,
          String(row?.status || '').trim(),
          JSON.stringify(row?.snapshot && typeof row.snapshot === 'object' ? row.snapshot : {}),
          JSON.stringify(row?.funds && typeof row.funds === 'object' ? row.funds : {}),
          JSON.stringify(Array.isArray(row?.transitionIds) ? row.transitionIds : []),
          String(row?.tip || '').trim(),
          String(row?.updatedAt || new Date().toISOString()),
          Math.max(0, Number(row?.lastEventSeq || 0)),
          JSON.stringify(row && typeof row === 'object' ? row : {}),
        );
      }
      db.exec('COMMIT');
    } catch (error) {
      try { db.exec('ROLLBACK'); } catch (_) {}
      throw error;
    }
    appendMarketDebug('order_projection_sync_persisted', {
      producer,
      orderCount: list.length,
      orderIds: list.map((row) => String(row?.id || row?.orderId || '')).slice(0, 20),
    });
    return list.length;
  } catch (error) {
    appendMarketDebug('order_projection_sync_persist_failed', {
      producer,
      orderCount: list.length,
      message: String(error?.message || error || 'sync order projection persist failed'),
    });
    return 0;
  } finally {
    try { db?.close?.(); } catch (_) {}
  }
}

function listActiveProtocolOrdersSync() {
  return filterProjectedOrdersForActiveProtocol(orderDomain.listOrdersSync());
}

function deriveOrderIdFromAnchorRow(row = {}) {
  const eventType = String(row?.eventType || '').trim();
  const payload = row?.payload && typeof row.payload === 'object' ? row.payload : {};
  const explicitOrderId = String(
    payload?.orderId
    || payload?.order_id
    || payload?.id
    || ''
  ).trim();
  if (explicitOrderId) {
    return explicitOrderId.startsWith('order:') ? explicitOrderId : `order:${explicitOrderId}`;
  }
  const placeTxid = String(
    payload?.pt
    || payload?.placeTxid
    || (eventType === 'order_place' ? String(row?.txid || '').trim() : '')
    || ''
  ).trim();
  return placeTxid ? `order:${placeTxid}` : '';
}

function getOrderAnchorReplayRank(row = {}) {
  const eventType = String(row?.eventType || '').trim();
  switch (eventType) {
    case 'order_open':
    case 'order_place':
      return 10;
    case 'order_accept':
      return 20;
    case 'order_ship':
      return 30;
    case 'order_confirm':
      return 40;
    case 'order_refund_request':
      return 50;
    case 'order_cancel_before_ship':
    case 'order_cancel_before_accept':
      return 60;
    case 'order_timeout_cancel':
      return 70;
    case 'order_refund':
      return 80;
    default:
      return 100;
  }
}

function rebuildOrdersFromAnchors(state, _req = null, options = {}) {
  if (!state || typeof state !== 'object') return [];
  const sourceRows = Array.isArray(options.anchorRows)
    ? options.anchorRows
    : getEffectiveAnchorRows(state, {
        req: _req,
        includePending: options.includePending !== false,
      });
  const partialReplay = Array.isArray(options.anchorRows);
  const rows = sourceRows
    .filter((row) => /^order_/i.test(String(row?.eventType || '').trim()))
    .filter((row) => {
      const eventType = String(row?.eventType || '').trim();
      if (row?.confirmed === true) return true;
      if (eventType === 'order_place' || eventType === 'order_open') return true;
      if (options.includeUnconfirmedActionAnchors === true) return true;
      appendMarketDebug('order_anchor_replay_skipped_unconfirmed_action', {
        eventType,
        txid: String(row?.txid || ''),
        node: String(row?.node || ''),
      });
      return false;
    })
    .sort((a, b) => {
      const orderIdA = deriveOrderIdFromAnchorRow(a);
      const orderIdB = deriveOrderIdFromAnchorRow(b);
      if (orderIdA && orderIdA === orderIdB) {
        const rankA = getOrderAnchorReplayRank(a);
        const rankB = getOrderAnchorReplayRank(b);
        if (rankA !== rankB) return rankA - rankB;
      }
      const ta = Date.parse(String(a?.ts || '')) || 0;
      const tb = Date.parse(String(b?.ts || '')) || 0;
      if (ta !== tb) return ta - tb;
      return String(a?.txid || '').localeCompare(String(b?.txid || ''));
    });
  const anchorDerivedOrderIds = new Set(rows
    .map((row) => deriveOrderIdFromAnchorRow(row))
    .filter(Boolean));
  const seedOrders = Array.isArray(state.orders)
    ? state.orders
      .map((row) => migrateOrderModel(row))
      .filter((row) => {
        const safeId = String(row?.id || '').trim();
        if (!safeId || !safeId.startsWith('order:')) return true;
        // Full repairs rebuild protocol orders from anchors only. Partial sync/listen
        // replays must preserve the existing projection and apply only incoming rows.
        return partialReplay || !anchorDerivedOrderIds.has(safeId);
      })
    : [];
  const seedById = new Map(seedOrders
    .filter((row) => String(row?.id || '').trim())
    .map((row) => [String(row.id || '').trim(), row]));
  const orderMap = new Map(seedOrders
    .filter((row) => String(row?.id || '').trim())
    .map((row) => [String(row.id || '').trim(), row]));
  if (rows.length === 0) {
    state.orders = Array.from(orderMap.values()).sort((a, b) => {
      const ta = Date.parse(String(a?.updatedAt || '')) || 0;
      const tb = Date.parse(String(b?.updatedAt || '')) || 0;
      return tb - ta;
    });
    return state.orders;
  }
  const actionByEvent = new Map(Object.values(ORDER_ACTION_META).map((meta) => [String(meta?.eventType || ''), meta]));
  const localReceiveAddress = (() => {
    try { return String(wallet.getReceiveAddress() || '').trim(); } catch (_) { return ''; }
  })();
  const localChatPubKey = (() => {
    try {
      const runtimePassword = getRuntimeWalletPassword();
      if (!runtimePassword) return '';
      const mnemonic = wallet.getMnemonicFromPassword(runtimePassword);
      return String(wallet.deriveChatPublicKeyFromMnemonic(mnemonic) || '').trim();
    } catch (_) {
      return '';
    }
  })();
  rows.forEach((row) => {
    const eventType = String(row?.eventType || '').trim();
    const payload = row?.payload && typeof row.payload === 'object' ? row.payload : {};
    const orderId = deriveOrderIdFromAnchorRow(row);
    if (!orderId) return;
    if (/^order_/i.test(eventType) && row?.rawtx) {
      storeOrderTxContextFromRawtx(row.rawtx, {
        txid: String(row?.txid || ''),
        source: String(row?.node || 'order_anchor_replay'),
        kind: eventType,
        confirmed: row?.confirmed === true,
        height: Number(row?.height || 0),
        node: String(row?.node || ''),
      });
    }
    if (eventType !== 'order_place' && eventType !== 'order_open') {
      scheduleOrderPlaceContextBackfillFromActionPayload(payload, `order_anchor_replay:${eventType}`);
    }
    const updatedAt = String(row?.ts || new Date().toISOString());
    const transitionId = `${eventType}:${String(row?.txid || updatedAt).trim()}`;
    if (eventType === 'order_open' || eventType === 'order_place') {
	      const snapshot = buildOrderSnapshotFromAnchorPayload(payload, state);
	      const buyerLockRedeemScriptHex = String(getOrderPayloadValue(payload, 'buyerLockRedeemScriptHex') || deriveOrderBuyerLockRedeemScriptHexFromPayload(payload) || '').trim();
	      const jointRedeemScriptHex = String(deriveOrderJointRedeemScriptHexFromPayload(payload) || '').trim();
	      try {
	        if (Number(getOrderPayloadValue(payload, 'v') || 0) >= 3) {
	          orderProtocolV3.validatePlacePayload(payload, {
	            expectedBuyerScriptHash: orderProtocolV3.scriptHashHex(buyerLockRedeemScriptHex),
	            expectedJointScriptHash: orderProtocolV3.scriptHashHex(jointRedeemScriptHex),
	            minSellerDepositSats: 1000,
	          });
	        }
	      } catch (err) {
	        appendMarketDebug('order_place_payload_invalid', {
	          orderId,
	          txid: String(row?.txid || ''),
	          error: String(err?.message || ''),
	        });
	        return;
	      }
	      const buyerLockTxid = String(getOrderPayloadValue(payload, 'bx') || row?.txid || '').trim();
      const buyerLockVout = Math.max(0, Number(getOrderPayloadValue(payload, 'bv', 'buyerLockVout') || 0));
      const prevout = getOrderPlacePrevoutFromTxContext(buyerLockTxid, buyerLockVout);
      const buyerLockSats = Math.max(0, Number(getOrderPayloadValue(payload, 'bs', 'buyerLockSats', 'buyerJointSats') || prevout?.satoshis || 0));
      const baseOrder = {
        id: orderId,
        buyerWalletId: String(getOrderPayloadValue(payload, 'bw', 'buyerWalletId') || '').trim()
          || ((String(getOrderPayloadValue(payload, 'br', 'buyerRefundAddress') || '').trim() && String(getOrderPayloadValue(payload, 'br', 'buyerRefundAddress') || '').trim() === localReceiveAddress)
            || (String(getOrderPayloadValue(payload, 'bp', 'buyerChatPubKey') || '').trim() && String(getOrderPayloadValue(payload, 'bp', 'buyerChatPubKey') || '').trim() === localChatPubKey)
            ? walletIdByMerchant(ensureCurrentMerchantId(state, _req || {}))
            : ''),
        sellerWalletId: String(getOrderPayloadValue(payload, 'sw', 'sellerWalletId') || '').trim()
          || walletIdByMerchant(String(getOrderPayloadValue(payload, 'sm', 'sellerMerchantId', 'merchantId') || snapshot.merchant_id || '').trim()),
        snapshot,
        status: ORDER_STATUS.NEW,
        funds: {
          priceSats: Math.max(0, Number(getOrderPayloadValue(payload, 'ps', 'priceSats') || snapshot.price_snapshot || 0)),
        },
        transitionIds: [],
        chain: {
          orderProtocolVersion: Number(getOrderPayloadValue(payload, 'v', 'orderProtocolVersion') || 3),
          placeTxid: String(row?.txid || '').trim(),
          buyerLockTxid,
          buyerLockVout,
	          buyerLockRedeemScriptHex,
          buyerLockScriptHex: String(prevout?.scriptHex || buyerLockRedeemScriptHex || '').trim(),
	          jointRedeemScriptHex,
          placeTime: updatedAt,
          placedAt: updatedAt,
          createdAt: updatedAt,
	          buyerRefundAddress: String(getOrderPayloadValue(payload, 'br', 'buyerRefundAddress') || '').trim(),
          buyerChatPubKey: String(getOrderPayloadValue(payload, 'bp', 'buyerChatPubKey') || '').trim(),
          sellerChatPubKey: String(getOrderPayloadValue(payload, 'sp', 'sellerChatPubKey') || '').trim(),
          sellerMerchantId: String(getOrderPayloadValue(payload, 'sm', 'sellerMerchantId', 'merchantId') || snapshot.merchant_id || '').trim(),
          buyerLockSats,
          sellerLockSats: Math.max(0, Number(getOrderPayloadValue(payload, 'sd', 'sellerDepositSats') || computeOrderSellerDepositSatsForProtocol(Number(getOrderPayloadValue(payload, 'ps', 'priceSats') || snapshot.price_snapshot || 0)))),
          timeoutAt: Math.max(0, Number(getOrderPayloadValue(payload, 'to', 'timeoutAt') || 0)),
          stateAnchorTxid: String(row?.txid || '').trim(),
          shipConfirmed: false,
          shipConfirmedHeight: 0,
        },
      };
      try {
        const opened = applyTransition(baseOrder, 'place', {
          transitionId,
          config: orderMachineConfig(),
          nowMs: Date.parse(updatedAt) || Date.now(),
        });
        opened.tip = 'order_tip_place';
        opened.createdAt = opened.createdAt || updatedAt;
        opened.placedAt = opened.placedAt || updatedAt;
        opened.updatedAt = updatedAt;
        orderMap.set(orderId, migrateOrderModel(opened));
      } catch (_) {
        orderMap.set(orderId, migrateOrderModel({
          ...baseOrder,
          status: ORDER_STATUS.PLACED,
          transitionIds: [transitionId],
          tip: 'order_tip_place',
          createdAt: updatedAt,
          placedAt: updatedAt,
          updatedAt,
        }));
      }
      return;
    }
	    if (eventType === 'order_accept') {
	      const existing = orderMap.get(orderId);
	      if (!existing) return;
	      try {
	        if (Number(getOrderPayloadValue(payload, 'v') || 0) >= 3) {
	          if (!orderProtocolV3.verifyPayload(payload, bsv)) throw new Error('Invalid order_accept actor signature');
	          if (String(payload.ar || '').trim() !== 'seller') throw new Error('Invalid order_accept actor role');
	          if (String(payload.ap || '').trim() !== String(existing?.chain?.sellerChatPubKey || '').trim()) throw new Error('order_accept actor does not match seller');
	        }
        assertOrderAnchorFundingRefsAvailable(eventType, payload, existing, row?.txid);
	        const next = applyTransition(existing, 'accept', {
          transitionId,
          config: orderMachineConfig(),
          nowMs: Date.parse(updatedAt) || Date.now(),
        });
        const sellerLockTxidForPayload = String(getOrderPayloadValue(payload, 'sx', 'sellerLockTxid') || String(row?.txid || '').trim()).trim();
        const sellerLockVoutForPayload = Math.max(0, Number(getOrderPayloadValue(payload, 'sv', 'sellerLockVout') || 0));
        const sellerLockPrevout = getOrderPlacePrevoutFromTxContext(sellerLockTxidForPayload, sellerLockVoutForPayload);
        const sellerLockScriptHex = String(
          sellerLockPrevout?.scriptHex
          || getOrderPayloadValue(payload, 'sellerLockRedeemScriptHex')
          || deriveOrderJointRedeemScriptHexFromPayload(existing.chain)
          || deriveOrderJointRedeemScriptHexFromPayload(payload)
          || ''
        ).trim();
        next.chain.sellerLockTxid = sellerLockTxidForPayload;
        next.chain.sellerLockVout = sellerLockVoutForPayload;
        next.chain.sellerLockSats = Math.max(0, Number(getOrderPayloadValue(payload, 'ss', 'sellerLockSats') || existing?.chain?.sellerLockSats || existing?.funds?.sellerDepositSats || 0));
        next.chain.sellerLockRedeemScriptHex = sellerLockScriptHex;
        next.chain.jointRedeemScriptHex = sellerLockScriptHex;
        next.chain.sellerReceiveAddress = String(getOrderPayloadValue(payload, 'sr', 'sellerReceiveAddress') || existing?.chain?.sellerReceiveAddress || '').trim();
        next.chain.sellerRefundAddress = String(getOrderPayloadValue(payload, 'sf', 'sellerRefundAddress') || existing?.chain?.sellerRefundAddress || '').trim();
        next.chain.sellerSettlementFeeTxid = String(getOrderPayloadValue(payload, 'sfx', 'sellerSettlementFeeTxid') || next.chain.sellerLockTxid || '').trim();
        next.chain.sellerSettlementFeeVout = Math.max(0, Number(getOrderPayloadValue(payload, 'sfv', 'sellerSettlementFeeVout') || 0));
        next.chain.sellerSettlementFeeSats = Math.max(0, Number(getOrderPayloadValue(payload, 'sfs', 'sellerSettlementFeeSats') || 0));
        next.chain.sellerShipAnchorFeeTxid = String(getOrderPayloadValue(payload, 'shfx', 'sellerShipAnchorFeeTxid') || '').trim();
        next.chain.sellerShipAnchorFeeVout = Math.max(0, Number(getOrderPayloadValue(payload, 'shfv', 'sellerShipAnchorFeeVout') || 0));
        next.chain.sellerShipAnchorFeeSats = Math.max(0, Number(getOrderPayloadValue(payload, 'shfs', 'sellerShipAnchorFeeSats') || 0));
        next.chain.sellerLockAcceptedAtHeight = Math.max(0, Number(getOrderPayloadValue(payload, 'sah', 'sellerLockAcceptedAtHeight') || row?.height || 0));
        next.tip = 'order_tip_accept';
        next.updatedAt = updatedAt;
        orderMap.set(orderId, migrateOrderModel(next));
      } catch (err) {
        appendMarketDebug('order_anchor_replay_skipped', {
          orderId,
          eventType,
          txid: String(row?.txid || ''),
          reason: String(err?.message || err || 'replay_failed'),
        });
      }
      return;
    }
    const existing = orderMap.get(orderId);
    if (!existing) {
      if (eventType === 'order_ship') {
        scheduleOrderPlaceContextBackfillFromActionPayload(payload, 'order_ship_missing_place');
      }
      return;
    }
	    const actionMeta = actionByEvent.get(eventType);
	    if (!actionMeta) return;
	    try {
	      if (Number(getOrderPayloadValue(payload, 'v') || 0) >= 3 && orderActionPayloadRequiresActorSignature(eventType, payload)) {
	        if (!orderProtocolV3.verifyPayload(payload, bsv)) throw new Error(`Invalid ${eventType} actor signature`);
      }
      assertOrderAnchorFundingRefsAvailable(eventType, payload, existing, row?.txid);
	      if (eventType === 'order_refund_request') {
	        const refreshed = refreshRefundRequestReplay(existing, payload, row, updatedAt, transitionId, actionMeta);
	        if (refreshed) {
	          orderMap.set(orderId, refreshed);
	          return;
	        }
	      }
	      if (eventType === 'order_ship' && String(existing?.status || '') === ORDER_STATUS.SHIPPED) {
        const shipConfirmed = existing?.chain?.shipConfirmed === true || row?.confirmed === true;
	        const refreshed = migrateOrderModel({
	          ...existing,
	          chain: {
	            ...(existing.chain || {}),
	            shipTxid: String(getOrderPayloadValue(payload, 'hx', 'txid') || existing?.chain?.shipTxid || row?.txid || '').trim(),
	            shipConfirmed,
	            shipConfirmedHeight: shipConfirmed
	              ? Math.max(0, Number(row?.height || existing?.chain?.shipConfirmedHeight || 0))
	              : 0,
	            shipmentInfo: String(getOrderPayloadValue(payload, 'si', 'shipmentInfo') || existing?.chain?.shipmentInfo || '').trim().slice(0, 100),
	            completedDraftRawtx: String(getOrderPayloadValue(payload, 'sg', 'completedDraftRawtx') || existing?.chain?.completedDraftRawtx || '').trim(),
	          },
	          updatedAt,
	          tip: String(actionMeta.tip || existing.tip || '').trim(),
	        });
	        orderMap.set(orderId, refreshed);
	        return;
	      }
      const transitionBase = eventType === 'order_ship'
        ? inferOrderAcceptFromShipPayload(existing, payload, updatedAt)
        : existing;
	      const next = applyTransition(transitionBase, actionMeta.machineAction, {
	        transitionId,
	        config: orderMachineConfig(),
        nowMs: Date.parse(updatedAt) || Date.now(),
      });
      if (eventType === 'order_ship') {
        next.chain.shipTxid = String(getOrderPayloadValue(payload, 'hx', 'txid') || row?.txid || '').trim();
        next.chain.shipConfirmed = row?.confirmed === true;
        next.chain.shipConfirmedHeight = row?.confirmed === true ? Math.max(0, Number(row?.height || 0)) : 0;
        next.chain.shipmentInfo = String(getOrderPayloadValue(payload, 'si', 'shipmentInfo') || existing?.chain?.shipmentInfo || '').trim().slice(0, 100);
        next.chain.completedDraftRawtx = String(getOrderPayloadValue(payload, 'sg', 'completedDraftRawtx') || existing?.chain?.completedDraftRawtx || '').trim();
      } else if (eventType === 'order_confirm') {
        next.chain.settleTxid = String(getOrderPayloadValue(payload, 'fx', 'txid') || row?.txid || '').trim();
        next.chain.completedSettlementTxid = next.chain.settleTxid;
      } else if (eventType === 'order_refund_request') {
        next.chain.refundRequestTxid = String(getOrderPayloadValue(payload, 'rx', 'txid') || row?.txid || '').trim();
        next.chain.refundDraftRawtx = String(getOrderPayloadValue(payload, 'rd', 'refundDraftRawtx') || existing?.chain?.refundDraftRawtx || '').trim();
      } else if (eventType === 'order_refund_confirm') {
        next.chain.settleTxid = String(getOrderPayloadValue(payload, 'fx', 'txid') || row?.txid || '').trim();
        next.chain.refundSettlementTxid = next.chain.settleTxid;
      } else if (eventType === 'order_cancel_before_ship' || eventType === 'order_cancel_before_accept' || eventType === 'order_timeout_cancel') {
        next.chain.cancelTxid = String(getOrderPayloadValue(payload, 'cx', 'txid') || row?.txid || '').trim();
      }
      next.tip = String(actionMeta.tip || existing.tip || '').trim();
      next.updatedAt = updatedAt;
      orderMap.set(orderId, migrateOrderModel(next));
    } catch (err) {
      appendMarketDebug('order_anchor_replay_skipped', {
        orderId,
        eventType,
        txid: String(row?.txid || ''),
        reason: String(err?.message || err || 'replay_failed'),
      });
    }
  });
  const replayActionRows = rows
    .filter((row) => {
      const eventType = String(row?.eventType || '').trim();
      return /^order_/i.test(eventType) && eventType !== 'order_place' && eventType !== 'order_open';
    })
    .sort((a, b) => {
      const orderIdA = deriveOrderIdFromAnchorRow(a);
      const orderIdB = deriveOrderIdFromAnchorRow(b);
      if (orderIdA && orderIdA === orderIdB) {
        const rankA = getOrderAnchorReplayRank(a);
        const rankB = getOrderAnchorReplayRank(b);
        if (rankA !== rankB) return rankA - rankB;
      }
      const ta = Date.parse(String(a?.ts || '')) || 0;
      const tb = Date.parse(String(b?.ts || '')) || 0;
      if (ta !== tb) return ta - tb;
      return String(a?.txid || '').localeCompare(String(b?.txid || ''));
    });
  replayActionRows.forEach((row) => {
    const eventType = String(row?.eventType || '').trim();
    const actionMeta = actionByEvent.get(eventType);
    if (!actionMeta) return;
    const orderId = deriveOrderIdFromAnchorRow(row);
    if (!orderId) return;
    const existing = orderMap.get(orderId);
    if (!existing) return;
    const updatedAt = String(row?.ts || new Date().toISOString());
    const transitionId = `${eventType}:${String(row?.txid || updatedAt).trim()}`;
    if (Array.isArray(existing.transitionIds) && existing.transitionIds.includes(transitionId)) return;
    const payload = row?.payload && typeof row.payload === 'object' ? row.payload : {};
    try {
      if (Number(getOrderPayloadValue(payload, 'v') || 0) >= 3 && orderActionPayloadRequiresActorSignature(eventType, payload)) {
        if (!orderProtocolV3.verifyPayload(payload, bsv)) throw new Error(`Invalid ${eventType} actor signature`);
      }
      assertOrderAnchorFundingRefsAvailable(eventType, payload, existing, row?.txid);
      if (eventType === 'order_refund_request') {
        const refreshed = refreshRefundRequestReplay(existing, payload, row, updatedAt, transitionId, actionMeta);
        if (refreshed) {
          orderMap.set(orderId, refreshed);
          appendMarketDebug('order_anchor_replay_repaired', {
            orderId,
            eventType,
            txid: String(row?.txid || ''),
            fromStatus: String(existing?.status || ''),
            toStatus: String(refreshed?.status || ''),
            refreshedRefundDraft: Boolean(String(refreshed?.chain?.refundDraftRawtx || '').trim()),
          });
          return;
        }
      }
      const transitionBase = eventType === 'order_ship'
        ? inferOrderAcceptFromShipPayload(existing, payload, updatedAt)
        : existing;
      const next = applyTransition(transitionBase, actionMeta.machineAction, {
        transitionId,
        config: orderMachineConfig(),
        nowMs: Date.parse(updatedAt) || Date.now(),
      });
      if (eventType === 'order_ship') {
        next.chain.shipTxid = String(getOrderPayloadValue(payload, 'hx', 'txid') || row?.txid || '').trim();
        next.chain.shipConfirmed = row?.confirmed === true;
        next.chain.shipConfirmedHeight = row?.confirmed === true ? Math.max(0, Number(row?.height || 0)) : 0;
        next.chain.shipmentInfo = String(getOrderPayloadValue(payload, 'si', 'shipmentInfo') || existing?.chain?.shipmentInfo || '').trim().slice(0, 100);
        next.chain.completedDraftRawtx = String(getOrderPayloadValue(payload, 'sg', 'completedDraftRawtx') || existing?.chain?.completedDraftRawtx || '').trim();
      } else if (eventType === 'order_confirm') {
        next.chain.settleTxid = String(getOrderPayloadValue(payload, 'fx', 'txid') || row?.txid || '').trim();
        next.chain.completedSettlementTxid = next.chain.settleTxid;
      } else if (eventType === 'order_refund_request') {
        next.chain.refundRequestTxid = String(getOrderPayloadValue(payload, 'rx', 'txid') || row?.txid || '').trim();
        next.chain.refundDraftRawtx = String(getOrderPayloadValue(payload, 'rd', 'refundDraftRawtx') || existing?.chain?.refundDraftRawtx || '').trim();
      } else if (eventType === 'order_refund_confirm') {
        next.chain.settleTxid = String(getOrderPayloadValue(payload, 'fx', 'txid') || row?.txid || '').trim();
        next.chain.refundSettlementTxid = next.chain.settleTxid;
      } else if (eventType === 'order_cancel_before_ship' || eventType === 'order_cancel_before_accept' || eventType === 'order_timeout_cancel') {
        next.chain.cancelTxid = String(getOrderPayloadValue(payload, 'cx', 'txid') || row?.txid || '').trim();
      }
      next.tip = String(actionMeta.tip || existing.tip || '').trim();
      next.updatedAt = updatedAt;
      orderMap.set(orderId, migrateOrderModel(next));
      appendMarketDebug('order_anchor_replay_repaired', {
        orderId,
        eventType,
        txid: String(row?.txid || ''),
        fromStatus: String(existing?.status || ''),
        toStatus: String(next?.status || ''),
      });
    } catch (err) {
      appendMarketDebug('order_anchor_repair_skipped', {
        orderId,
        eventType,
        txid: String(row?.txid || ''),
        status: String(existing?.status || ''),
        reason: String(err?.message || err || 'repair_failed'),
      });
    }
  });
  state.orders = Array.from(orderMap.values()).sort((a, b) => {
    const ta = Date.parse(String(a?.updatedAt || '')) || 0;
    const tb = Date.parse(String(b?.updatedAt || '')) || 0;
    return tb - ta;
  });
  const changedOrders = [];
  for (const order of state.orders) {
    const safeId = String(order?.id || '').trim();
    if (!safeId || !safeId.startsWith('order:')) continue;
    const prev = seedById.get(safeId) || null;
    const changed = !prev || JSON.stringify(prev) !== JSON.stringify(order);
    if (!changed) continue;
    changedOrders.push(order);
    void orderDomain.emitOrderUpsert(order, {
      producer: 'orders_anchor_rebuild',
      dedupeKey: `order.upsert:${safeId}:${String(order?.status || '')}:${String(order?.transitionIds?.slice(-1)[0] || 'anchor_rebuild')}`,
    }).catch(() => {});
  }
  if (changedOrders.length > 0) {
    persistOrderProjectionRowsSync(changedOrders, 'orders_anchor_rebuild');
  }
  return state.orders;
}

function scheduleOrderAnchorProjectionRebuild(reason = 'order_anchor_projection', meta = {}) {
  pendingOrderAnchorProjectionRebuild.reason = String(reason || pendingOrderAnchorProjectionRebuild.reason || 'order_anchor_projection');
  pendingOrderAnchorProjectionRebuild.eventCount += Math.max(0, Number(meta?.eventCount || 0));
  const txid = String(meta?.txid || '').trim().toLowerCase();
  if (/^[0-9a-f]{64}$/.test(txid)) pendingOrderAnchorProjectionRebuild.txids.add(txid);
  if (orderAnchorProjectionRebuildTimer) return;
  orderAnchorProjectionRebuildTimer = setTimeout(() => {
    orderAnchorProjectionRebuildTimer = null;
    const snapshot = {
      reason: pendingOrderAnchorProjectionRebuild.reason || 'order_anchor_projection',
      eventCount: pendingOrderAnchorProjectionRebuild.eventCount,
      txids: Array.from(pendingOrderAnchorProjectionRebuild.txids).slice(0, 25),
    };
    pendingOrderAnchorProjectionRebuild.reason = '';
    pendingOrderAnchorProjectionRebuild.eventCount = 0;
    pendingOrderAnchorProjectionRebuild.txids.clear();
    try {
      const req = buildRuntimeAuthReq();
      const state = buildProjectionBackedState(req);
      const beforeCount = Array.isArray(state?.orders) ? state.orders.length : 0;
      const allowPendingReplay = snapshot.reason === 'chain_rawtx_router';
      const orders = rebuildOrdersFromAnchors(state, req, {
        includePending: allowPendingReplay,
        includeUnconfirmedActionAnchors: allowPendingReplay,
      });
      scheduleMappedFrontendBroadcast('order.anchor.projection', 'order_anchor_projection_rebuilt', 50, true, snapshot.reason, {
        eventCount: snapshot.eventCount,
        txids: snapshot.txids,
        beforeCount,
        afterCount: Array.isArray(orders) ? orders.length : 0,
        includePending: allowPendingReplay,
      });
      appendMarketDebug('order_anchor_projection_rebuilt', {
        ...snapshot,
        beforeCount,
        afterCount: Array.isArray(orders) ? orders.length : 0,
        includePending: allowPendingReplay,
      });
    } catch (error) {
      appendMarketDebug('order_anchor_projection_rebuild_failed', {
        ...snapshot,
        error: String(error?.message || error || 'order anchor projection rebuild failed'),
      });
    }
  }, 350);
  orderAnchorProjectionRebuildTimer.unref?.();
}

function runtimeProjectionNeedsSqliteHydrate(runtimeState = null) {
  if (!runtimeState || typeof runtimeState !== 'object') return true;
  const hasCatalog = Array.isArray(runtimeState.categories) && runtimeState.categories.length > 0;
  const hasProducts = Array.isArray(runtimeState.products) && runtimeState.products.length > 0;
  const hasMerchants = Array.isArray(runtimeState.merchants) && runtimeState.merchants.length > 0;
  const hasNamedProfile = String(runtimeState?.profile?.name || '').trim().length > 0;
  const hasCurrentMerchant = String(runtimeState?.currentMerchantId || '').trim() !== ''
    && String(runtimeState?.currentMerchantId || '').trim() !== 'm-local';
  return !(hasCatalog || hasProducts || hasMerchants || hasNamedProfile || hasCurrentMerchant);
}

function stateHasLiteProjectionRows(state = null) {
  if (!state || typeof state !== 'object') return false;
  return (
    (Array.isArray(state.categories) && state.categories.length > 0)
    || (Array.isArray(state.products) && state.products.length > 0)
    || (Array.isArray(state.orders) && state.orders.length > 0)
  );
}

function buildProjectionBackedState(req = null) {
  const runtimeState = getRuntimeProjectionStateSnapshot(req);
  if (runtimeState && runtimeProjectionStateHydrated) {
    if (!req?.session?.walletPassword && !runtimeProjectionNeedsSqliteHydrate(runtimeState)) return runtimeState;
    const sqliteState = buildProjectionStateFromSqlite(req);
    const preferredState = chooseRicherStateSnapshot(runtimeState, sqliteState, 'projection_state_sqlite_rehydrate');
    commitCoreRuntimeProjectionState(preferredState, { reason: 'projection_state_sqlite_rehydrate', hydrated: true, req });
    return preferredState;
  }
  appendMarketDebug('projection_state_sqlite_fallback', {
    reason: runtimeState ? 'runtime_projection_state_not_hydrated' : 'runtime_projection_state_missing',
    hasWalletSession: Boolean(req?.session?.walletPassword),
    runtimeLocalHeight: Math.max(0, Number(runtimeState?.sync?.localHeight || 0)),
    runtimeCategories: Array.isArray(runtimeState?.categories) ? runtimeState.categories.length : 0,
    runtimeProducts: Array.isArray(runtimeState?.products) ? runtimeState.products.length : 0,
  });
  const state = buildProjectionStateFromSqlite(req);
  const preferredState = runtimeState
    ? chooseRicherStateSnapshot(runtimeState, state, 'projection_state_sqlite_hydrate')
    : state;
  commitCoreRuntimeProjectionState(preferredState, { reason: 'projection_state_sqlite_hydrate', hydrated: true, req });
  return preferredState;
}

function loadProjectionBackedRuntimeState(req = null) {
  return getStateWithRuntimeSync(buildProjectionBackedState(req));
}

function loadJsonStateRawFast() {
  ensureMarketDataDir();
  const candidates = [STATE_FILE, STATE_BACKUP_FILE];
  for (const file of candidates) {
    try {
      if (!file || !fs.existsSync(file)) continue;
      const parsed = JSON.parse(fs.readFileSync(file, 'utf8'));
      if (parsed && typeof parsed === 'object') return parsed;
    } catch (_) {}
  }
  return null;
}

