function buildPublicBhsSummary(snapshot = null) {
  const bhs = snapshot && typeof snapshot === 'object' ? snapshot : getBhsTipSnapshot();
  return {
    ok: bhs?.ok === true,
    checkpointHeight: Math.max(0, Number(bhs?.checkpointHeight || 0)),
    checkpointHash: String(bhs?.checkpointHash || '').trim().toLowerCase(),
    tipHeight: Math.max(0, Number(bhs?.tipHeight || 0)),
    tipHash: String(bhs?.tipHash || '').trim().toLowerCase(),
    headerCount: Math.max(0, Number(bhs?.headerCount || 0)),
    lastRound: bhs?.lastRound && typeof bhs.lastRound === 'object' ? bhs.lastRound : {},
  };
}

function getDisplayedHighestBlock(syncLike = {}, bhsSnapshot = null) {
  const bhs = (bhsSnapshot && typeof bhsSnapshot === 'object') ? bhsSnapshot : getBhsTipSnapshot();
  return Math.max(
    0,
    Number(syncLike?.localHeight || 0),
    Number(syncLike?.fixedSyncLastHeight || 0),
    Number(syncLike?.receiptCommittedHeight || 0),
    Number(bhs?.tipHeight || syncLike?.bhs?.tipHeight || 0),
  );
}

function getDisplayedLag(syncLike = {}, bhsSnapshot = null) {
  const localHeight = Math.max(0, Number(syncLike?.localHeight || 0));
  const highestBlock = getDisplayedHighestBlock(syncLike, bhsSnapshot);
  return Math.max(0, highestBlock - localHeight);
}

function loadLegacyStateSnapshot() {
  const startedAtMs = Date.now();
  ensureMarketDataDir();
  if (!fs.existsSync(STATE_FILE)) {
    const init = defaultState();
    const initJson = buildJsonStateSnapshot(init);
    atomicWriteTextFile(STATE_FILE, JSON.stringify(initJson, null, 2));
    persistSyncStateAsync(init.sync);
    return init;
  }
  const parseJsonFile = (file) => {
    if (!file || !fs.existsSync(file)) return null;
    return JSON.parse(fs.readFileSync(file, 'utf8'));
  };
  const findCandidateStateFiles = () => {
    const candidates = [STATE_FILE, STATE_BACKUP_FILE];
    try {
      const prefix = `${path.basename(STATE_FILE)}.tmp`;
      const extras = fs.readdirSync(DATA_DIR)
        .filter((name) => name === prefix || name.startsWith(`${prefix}.`))
        .map((name) => path.join(DATA_DIR, name))
        .sort((a, b) => {
          try {
            return fs.statSync(b).mtimeMs - fs.statSync(a).mtimeMs;
          } catch (_) {
            return 0;
          }
        });
      candidates.push(...extras);
    } catch (_) {}
    return Array.from(new Set(candidates));
  };
  let raw = null;
  let lastParseError = null;
  try {
    raw = parseJsonFile(STATE_FILE);
  } catch (err) {
    lastParseError = err;
  }
  for (let attempt = 0; attempt < 3 && !raw; attempt += 1) {
    const candidates = findCandidateStateFiles();
    for (const candidate of candidates) {
      if (candidate === STATE_FILE) continue;
      try {
        raw = parseJsonFile(candidate);
        lastParseError = null;
        if (candidate !== STATE_FILE && raw) {
          atomicWriteTextFile(STATE_FILE, JSON.stringify(raw, null, 2));
          if (candidate !== STATE_BACKUP_FILE) {
            try {
              atomicWriteTextFile(STATE_BACKUP_FILE, JSON.stringify(raw, null, 2));
            } catch (_) {}
          }
          appendMarketDebug('state_recovered_from_fallback', {
            sourceFile: candidate,
          });
        }
        break;
      } catch (err) {
        lastParseError = err;
      }
    }
    if (!raw) {
      Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, 25);
    }
  }
  if (!raw) {
    appendMarketDebug('state_load_parse_failed', {
      file: STATE_FILE,
      message: String(lastParseError?.message || lastParseError || 'unknown parse error'),
    });
    throw lastParseError || new Error('Failed to parse state file');
  }
  const init = defaultState();
  const sqliteSyncRow = loadSyncStateRowFromSqlite();
  const sqliteCatalog = loadCatalogSnapshotFromSqlite();
  const sqliteProfile = loadProfileSnapshotFromSqlite();
  const sqliteLocalState = localStateDomain.getLocalStateSync('main');
  const merged = {
    ...init,
    ...raw,
    profile: { ...init.profile, ...(raw.profile || {}) },
    steward: { ...init.steward, ...(raw.steward || {}) },
    walletShadow: { ...init.walletShadow, ...(raw.walletShadow || raw.wallet || {}) },
    sync: { ...init.sync, ...(raw.sync || {}) },
  };
  const legacyAnchorsForBackfill = Array.isArray(merged.pendingAnchors)
    ? merged.pendingAnchors.slice()
    : (Array.isArray(merged.anchors) ? merged.anchors.slice() : []);
  applySqliteSyncStateRow(merged.sync, sqliteSyncRow);
  if (sqliteCatalog) {
    merged.categories = sqliteCatalog.categories;
    merged.products = sqliteCatalog.products;
  }
  if (sqliteProfile) {
    merged.profile = {
      ...merged.profile,
      name: String(sqliteProfile.name || merged.profile?.name || ''),
      localStatus: String(sqliteProfile.localStatus || merged.profile?.localStatus || ''),
      localUpdatedAt: String(sqliteProfile.localUpdatedAt || merged.profile?.localUpdatedAt || ''),
    };
  }
  const needsLegacyQueueMigration = raw.localChanges === null;
  if (!Array.isArray(merged.pendingAnchors)) {
    merged.pendingAnchors = Array.isArray(merged.anchors) ? merged.anchors.slice() : [];
  }
  merged.pendingAnchors = merged.pendingAnchors.filter((row) => row?.confirmed !== true);
  delete merged.anchors;
  if (!Array.isArray(merged.recentRawtxs)) merged.recentRawtxs = [];
  if (!merged.localChanges || typeof merged.localChanges !== 'object') {
    merged.localChanges = { seq: 1, queue: [] };
  }
  if (!Number.isFinite(Number(merged.localChanges.seq))) merged.localChanges.seq = 1;
  if (!Array.isArray(merged.localChanges.queue)) merged.localChanges.queue = [];
  if (sqliteLocalState && typeof sqliteLocalState === 'object') {
    merged.pendingAnchors = (Array.isArray(sqliteLocalState.pendingAnchors) ? sqliteLocalState.pendingAnchors : [])
      .filter((row) => row?.confirmed !== true)
      .map((row) => ({
        ...row,
        payload: row?.payload && typeof row.payload === 'object' ? row.payload : {},
      }));
    merged.recentRawtxs = Array.isArray(sqliteLocalState.recentRawtxs)
      ? sqliteLocalState.recentRawtxs.map((row) => ({ ...row }))
      : [];
    merged.localChanges = {
      seq: Math.max(1, Number(sqliteLocalState.seq || merged.localChanges.seq || 1)),
      queue: Array.isArray(sqliteLocalState.localChanges)
        ? sqliteLocalState.localChanges.map((row) => ({ ...row }))
        : [],
    };
  }
  if (!Array.isArray(merged.orders)) merged.orders = [];
  if (!Array.isArray(merged.products)) merged.products = [];
  if (!Array.isArray(merged.categories)) merged.categories = [];
  if (!Array.isArray(merged.merchants)) merged.merchants = [];
  if (!Array.isArray(merged.users)) merged.users = [];
  if (typeof merged.currentMerchantId !== 'string') merged.currentMerchantId = 'm-local';
  delete merged.chats;
  delete merged.p2pChat;
  ensureChatState(merged);
  const sqliteChatProfiles = loadRegisteredChatProfilesFromSqlite();
  if (sqliteChatProfiles && typeof sqliteChatProfiles === 'object' && Object.keys(sqliteChatProfiles).length > 0) {
    merged.chatDiscovery.profiles = {
      ...(merged.chatDiscovery?.profiles && typeof merged.chatDiscovery.profiles === 'object' ? merged.chatDiscovery.profiles : {}),
      ...sqliteChatProfiles,
    };
  }
  rebuildWalletKeyBindingsFromAnchors(merged);
  rebuildRegisteredPeerProfilesFromAnchors(merged);
  const repairedKnownBuyerPlaceholder = repairKnownBuyerProfilePlaceholderQueue(merged, { log: false });
  if (repairedKnownBuyerPlaceholder > 0) {
    scheduleKnownBuyerProfilePlaceholderRepairPersist(merged);
  }
  merged.orders = merged.orders.map((o) => migrateOrderModel(o));
  if (needsLegacyQueueMigration) {
    const nowIso = new Date().toISOString();
    const defaultBuyerPlaceholderName = String(defaultState().profile?.name || '').trim();
    const profileName = String(merged.profile?.name || '').trim();
    const shouldMigrateProfileAsDirty = Boolean(profileName) && profileName !== defaultBuyerPlaceholderName;
    if (merged.profile && !merged.profile.localStatus && shouldMigrateProfileAsDirty) {
      merged.profile.localStatus = 'modified';
      merged.profile.localUpdatedAt = nowIso;
    }
    (merged.categories || []).forEach((c) => {
      if (!c || typeof c !== 'object') return;
      if (!c.localStatus) c.localStatus = 'modified';
      if (!c.localUpdatedAt) c.localUpdatedAt = nowIso;
    });
    (merged.products || []).forEach((p) => {
      if (!p || typeof p !== 'object') return;
      if (!p.localStatus) p.localStatus = 'modified';
      if (!p.localUpdatedAt) p.localUpdatedAt = nowIso;
      if (!Number.isFinite(Number(p.soldCount))) p.soldCount = 0;
      if (typeof p.imageUrl !== 'string') p.imageUrl = '';
      if (typeof p.description !== 'string') p.description = '';
    });
  }
  (merged.categories || []).forEach((c) => {
    if (!c || typeof c !== 'object') return;
    c.version = Math.max(1, Number(c.version || 1));
    c.deleted = c.deleted === true;
  });
  (merged.products || []).forEach((p) => {
    if (!p || typeof p !== 'object') return;
    p.version = Math.max(1, Number(p.version || 1));
    p.deleted = p.deleted === true;
  });
  if (!Number.isFinite(Number(merged.sync.bootstrapHeight)) || Number(merged.sync.bootstrapHeight) < FIXED_SYNC_BOOTSTRAP_HEIGHT) {
    merged.sync.bootstrapHeight = FIXED_SYNC_BOOTSTRAP_HEIGHT;
  }
  const bootstrapHeight = Number(merged.sync.bootstrapHeight || FIXED_SYNC_BOOTSTRAP_HEIGHT);
  if (!Number.isFinite(Number(merged.sync.fixedSyncLastHeight))) merged.sync.fixedSyncLastHeight = null;
  if (!Array.isArray(merged.sync.chainSources)) merged.sync.chainSources = [];
  if (!merged.sync.sourceStats || typeof merged.sync.sourceStats !== 'object') merged.sync.sourceStats = {};
  if (!Number.isFinite(Number(merged.sync.p2pHeaderCursorHeight))) merged.sync.p2pHeaderCursorHeight = -1;
  if (typeof merged.sync.p2pHeaderCursorHash !== 'string') merged.sync.p2pHeaderCursorHash = '';
  if (!Number.isFinite(Number(merged.sync.p2pTipHeight))) merged.sync.p2pTipHeight = 0;
  if (typeof merged.sync.p2pTipHash !== 'string') merged.sync.p2pTipHash = '';
  if (!merged.sync.p2pHeightHashCache || typeof merged.sync.p2pHeightHashCache !== 'object') merged.sync.p2pHeightHashCache = {};
  if (!Array.isArray(merged.sync.p2pGapHeights)) merged.sync.p2pGapHeights = [];
  if (!merged.sync.p2pNodeStats || typeof merged.sync.p2pNodeStats !== 'object') merged.sync.p2pNodeStats = {};
  merged.sync.p2pGapHeights = merged.sync.p2pGapHeights
    .map((x) => Number(x))
    .filter((x) => Number.isFinite(x) && x >= 0)
    .map((x) => Math.floor(x));
  const normalizedP2PNodeStats = {};
  Object.entries(merged.sync.p2pNodeStats || {}).forEach(([endpointRaw, row]) => {
    const endpoint = String(endpointRaw || '').trim();
    if (!endpoint || typeof row !== 'object' || !row) return;
    normalizedP2PNodeStats[endpoint] = {
      score: Math.max(-100, Math.min(100, Number(row.score || 0))),
      successCount: Math.max(0, Number(row.successCount || 0)),
      failCount: Math.max(0, Number(row.failCount || 0)),
      consecutiveFails: Math.max(0, Number(row.consecutiveFails || 0)),
      bannedUntil: Math.max(0, Number(row.bannedUntil || 0)),
      avgLatencyMs: Math.max(0, Number(row.avgLatencyMs || 0)),
      avgDownloadBytesPerSec: Math.max(0, Number(row.avgDownloadBytesPerSec || 0)),
      lastDownloadBytesPerSec: Math.max(0, Number(row.lastDownloadBytesPerSec || 0)),
      downloadSampleCount: Math.max(0, Number(row.downloadSampleCount || 0)),
      lastError: String(row.lastError || '').slice(0, 240),
      lastFailureAt: Math.max(0, Number(row.lastFailureAt || 0)),
      lastTimeoutAt: Math.max(0, Number(row.lastTimeoutAt || 0)),
      lastSuccessAt: Math.max(0, Number(row.lastSuccessAt || 0)),
      updatedAt: Math.max(0, Number(row.updatedAt || 0)),
    };
  });
  merged.sync.p2pNodeStats = normalizedP2PNodeStats;
  p2pNodeSelector.importStats(normalizedP2PNodeStats);
  const minBootstrapLocal = Math.max(0, Number(merged.sync.bootstrapHeight || FIXED_SYNC_BOOTSTRAP_HEIGHT) - 1);
  if (!Number.isFinite(Number(merged.sync.localHeight))) merged.sync.localHeight = minBootstrapLocal;
  delete merged.sync.networkHeight;
  if (typeof merged.sync.initialSyncCompleted !== 'boolean') merged.sync.initialSyncCompleted = false;
  // New machine / fresh wallet can have empty header cache, causing very slow
  // header walk from genesis. Seed a known checkpoint at bootstrap-1.
  if (
    BOOTSTRAP_PREV_HEIGHT > 0
    && /^[0-9a-f]{64}$/i.test(BOOTSTRAP_PREV_HASH)
    && Number(merged.sync.bootstrapHeight || 0) === FIXED_SYNC_BOOTSTRAP_HEIGHT
    && Object.keys(merged.sync.p2pHeightHashCache || {}).length === 0
    && Number(merged.sync.p2pHeaderCursorHeight || -1) < 0
  ) {
    merged.sync.p2pHeightHashCache[String(BOOTSTRAP_PREV_HEIGHT)] = BOOTSTRAP_PREV_HASH;
    merged.sync.p2pHeaderCursorHeight = BOOTSTRAP_PREV_HEIGHT;
    merged.sync.p2pHeaderCursorHash = BOOTSTRAP_PREV_HASH;
    appendMarketDebug('p2p_bootstrap_checkpoint_seeded', {
      bootstrapHeight: merged.sync.bootstrapHeight,
      checkpointHeight: BOOTSTRAP_PREV_HEIGHT,
      checkpointHash: BOOTSTRAP_PREV_HASH,
    });
  }
  if (Number(merged.sync.localHeight || 0) < minBootstrapLocal) {
    merged.sync.localHeight = minBootstrapLocal;
  }
  if (Number.isFinite(Number(merged.sync.fixedSyncLastHeight)) && Number(merged.sync.fixedSyncLastHeight) < minBootstrapLocal) {
    merged.sync.fixedSyncLastHeight = minBootstrapLocal;
  }
  if (!Number.isFinite(Number(merged.sync.scannedFrom)) || Number(merged.sync.scannedFrom) < Number(merged.sync.bootstrapHeight || FIXED_SYNC_BOOTSTRAP_HEIGHT)) {
    merged.sync.scannedFrom = Number(merged.sync.bootstrapHeight || FIXED_SYNC_BOOTSTRAP_HEIGHT);
  }
  const localBaseHeight = Math.max(
    Number(merged.sync.bootstrapHeight || 0),
    Number(merged.sync.localHeight || 0),
    Number(merged.sync.fixedSyncLastHeight || 0),
  );
  const maxReasonableHeaderHeight = Number(localBaseHeight + P2P_SYNC_MAX_HEADER_AHEAD);
  const tipHintOnLoad = Math.max(
    Number(merged.sync.p2pTipHeight || 0),
    Number(merged.sync.localHeight || 0),
    minBootstrapLocal,
  );
  const cacheCeilOnLoad = Math.min(maxReasonableHeaderHeight, Number(tipHintOnLoad + P2P_SYNC_TIP_DRIFT_BLOCKS));
  if (Number(merged.sync.p2pHeaderCursorHeight || -1) > cacheCeilOnLoad) {
    merged.sync.p2pHeaderCursorHeight = -1;
    merged.sync.p2pHeaderCursorHash = '';
    appendMarketDebug('p2p_header_cursor_sanitized_by_tip_on_load', {
      tipHintOnLoad,
      cacheCeilOnLoad,
    });
  }
  if (Number(merged.sync.p2pHeaderCursorHeight || -1) > maxReasonableHeaderHeight) {
    merged.sync.p2pHeaderCursorHeight = -1;
    merged.sync.p2pHeaderCursorHash = '';
    appendMarketDebug('p2p_header_cursor_sanitized_on_load', {
      localBaseHeight,
      maxReasonableHeaderHeight,
    });
  }
  if (Number(merged.sync.p2pTipHeight || 0) > maxReasonableHeaderHeight) {
    merged.sync.p2pTipHeight = 0;
    merged.sync.p2pTipHash = '';
    appendMarketDebug('p2p_tip_sanitized_on_load', {
      localBaseHeight,
      maxReasonableHeaderHeight,
    });
  }
  if (merged.sync.p2pHeightHashCache && typeof merged.sync.p2pHeightHashCache === 'object') {
    let dropped = 0;
    Object.keys(merged.sync.p2pHeightHashCache).forEach((k) => {
      const h = Number(k);
      const hash = String(merged.sync.p2pHeightHashCache[k] || '').trim().toLowerCase();
      const valid = Number.isFinite(h) && h >= 0 && h <= cacheCeilOnLoad && /^[0-9a-f]{64}$/i.test(hash);
      if (!valid) {
        delete merged.sync.p2pHeightHashCache[k];
        dropped += 1;
      }
    });
    if (dropped > 0) {
      appendMarketDebug('p2p_height_hash_cache_sanitized_on_load', {
        localBaseHeight,
        maxReasonableHeaderHeight,
        cacheCeilOnLoad,
        dropped,
      });
    }
    const stripped = stripTrustedBhsHeightsFromCache(merged.sync.p2pHeightHashCache);
    const strippedCount = Math.max(0, Object.keys(merged.sync.p2pHeightHashCache).length - Object.keys(stripped).length);
    merged.sync.p2pHeightHashCache = stripped;
    if (strippedCount > 0) {
      appendMarketDebug('p2p_height_hash_cache_bhs_mirror_stripped_on_load', {
        stripped: strippedCount,
      });
    }
  }
  const receipts = loadP2PSyncReceipts(Number(merged.sync.bootstrapHeight || FIXED_SYNC_BOOTSTRAP_HEIGHT));
  const hasReceiptCommittedHeight = fs.existsSync(P2P_SYNC_RECEIPTS_FILE)
    && Number.isFinite(Number(receipts?.committedHeight))
    && Number(receipts.committedHeight) > 0;
  const receiptCommittedHeight = Math.max(
    minBootstrapLocal,
    Number(receipts?.committedHeight || minBootstrapLocal),
  );
  if (
    hasReceiptCommittedHeight
    && (
    Number(merged.sync.localHeight || 0) > receiptCommittedHeight
    || Number(merged.sync.fixedSyncLastHeight || 0) > receiptCommittedHeight
    )
  ) {
    appendMarketDebug('sync_heights_clamped_by_receipts_on_load', {
      before: {
        localHeight: Number(merged.sync.localHeight || 0),
        fixedSyncLastHeight: Number(merged.sync.fixedSyncLastHeight || 0),
      },
      receiptCommittedHeight,
    });
    merged.sync.localHeight = Math.min(Number(merged.sync.localHeight || 0), receiptCommittedHeight);
    merged.sync.fixedSyncLastHeight = Math.min(Number(merged.sync.fixedSyncLastHeight || 0), receiptCommittedHeight);
  }
  applyDerivedSyncOnline(merged.sync);
  rebuildPendingQueueFromLocalState(merged);
  rebuildChatUiSummary(merged);
  if (legacyAnchorsForBackfill.length > 0) backfillLegacyAnchorsToSqliteAsync({ anchors: legacyAnchorsForBackfill });
  appendMarketDebug('state_loaded', {
    categories: Array.isArray(merged.categories) ? merged.categories.length : -1,
    products: Array.isArray(merged.products) ? merged.products.length : -1,
    queueSize: Array.isArray(merged.localChanges?.queue) ? merged.localChanges.queue.length : -1,
    pending: Array.isArray(merged.localChanges?.queue) ? merged.localChanges.queue.filter((q) => q?.status === 'pending').length : -1,
    migratedLegacyQueue: needsLegacyQueueMigration,
  });
  const elapsedMs = Date.now() - startedAtMs;
  if (elapsedMs >= 100) {
    appendMarketDebug('loadState_profile', {
      elapsedMs,
      categories: Array.isArray(merged.categories) ? merged.categories.length : 0,
      products: Array.isArray(merged.products) ? merged.products.length : 0,
      orders: Array.isArray(merged.orders) ? merged.orders.length : 0,
      pendingAnchors: Array.isArray(merged.pendingAnchors) ? merged.pendingAnchors.length : 0,
      recentRawtxs: Array.isArray(merged.recentRawtxs) ? merged.recentRawtxs.length : 0,
      localChangeQueue: Array.isArray(merged.localChanges?.queue) ? merged.localChanges.queue.length : 0,
      chatProfiles: Object.keys(merged.chatDiscovery?.profiles || {}).length,
    });
  }
  return merged;
}

function prepareStateForCommit(state) {
  ensureChatState(state);
  rebuildChatUiSummary(state);
  if (!state.sync || typeof state.sync !== 'object') state.sync = {};
  state.sync.sessionEpoch = Math.max(
    Number(state.sync.sessionEpoch || 0),
    Number(syncSessionEpoch || 0),
  );
  applyDerivedSyncOnline(state.sync);
  if (state.sync.online) state.sync.initialSyncCompleted = true;
  state.sync.p2pNodeStats = trimP2PSyncNodeStatsObject({
    ...(state.sync.p2pNodeStats || {}),
    ...exportP2PSyncNodeStats(),
  });
  return state;
}

async function flushPendingStateJsonSnapshot(options = {}) {
  if (pendingStateJsonTimer) {
    clearTimeout(pendingStateJsonTimer);
    pendingStateJsonTimer = null;
  }
  const pending = pendingStateJsonSnapshot;
  if (!pending || typeof pending !== 'object') return;
  pendingStateJsonSnapshot = null;
  const request = {
    stateFile: STATE_FILE,
    backupFile: STATE_BACKUP_FILE,
    serialized: String(pending.serialized || ''),
  };
  await queueCoalescedSnapshotWrite(coalescedSnapshotWrites.stateJson, request, (nextPayload) =>
    marketDb.writeStateJsonSnapshot(nextPayload));
  appendMarketDebug('state_saved', {
    file: STATE_FILE,
    categories: Array.isArray(pending.state?.categories) ? pending.state.categories.length : -1,
    products: Array.isArray(pending.state?.products) ? pending.state.products.length : -1,
    queueSize: Array.isArray(pending.state?.localChanges?.queue) ? pending.state.localChanges.queue.length : -1,
    pending: Array.isArray(pending.state?.localChanges?.queue) ? pending.state.localChanges.queue.filter((q) => q?.status === 'pending').length : -1,
    localHeight: Number(pending.state?.sync?.localHeight || 0),
    fixedSyncLastHeight: Number(pending.state?.sync?.fixedSyncLastHeight || 0),
    networkHeight: Number(pending.state?.sync?.networkHeight || 0),
    online: Boolean(pending.state?.sync?.online),
    reason: String(pending.reason || options.reason || 'state_saved'),
  });
}

function scheduleStateJsonSnapshotPersist(state, options = {}) {
  prepareStateForCommit(state);
  commitCoreRuntimeProjectionState(state, {
    reason: String(options.reason || 'state_saved'),
    req: options?.req || null,
  });
  const reason = String(options.reason || 'state_saved');
  appendMarketDebug('state_save_attempt', {
    file: STATE_FILE,
    reason,
    chatMessageCount: Object.keys(state?.chatMessages || {}).length,
    recentRawtxCount: Array.isArray(state?.recentRawtxs) ? state.recentRawtxs.length : -1,
    lastRecentRawtx: String((state?.recentRawtxs || []).slice(-1)[0]?.txid || ''),
  });
  const jsonState = buildJsonStateSnapshot(state);
  const serialized = JSON.stringify(jsonState, null, 2);
  const payloadHash = hashSnapshotPayload(serialized);
  if (!options.immediate && payloadHash && payloadHash === pendingStateJsonLastHash) {
    appendMarketDebug('state_save_skipped_unchanged', { reason });
    return Promise.resolve({ scheduled: false, skipped: true });
  }
  pendingStateJsonLastHash = payloadHash;
  pendingStateJsonSnapshot = {
    state,
    serialized,
    reason,
  };
  if (pendingStateJsonTimer) clearTimeout(pendingStateJsonTimer);
  if (options.immediate === true) {
    return flushPendingStateJsonSnapshot({ reason });
  }
  const delayMs = getLagAdjustedDelayMs(
    Math.max(0, Number(options.delayMs || STATE_JSON_PERSIST_DEBOUNCE_MS)),
    { minimumDelayMs: STATE_JSON_PERSIST_DEBOUNCE_MS },
  );
  pendingStateJsonTimer = setTimeout(() => {
    pendingStateJsonTimer = null;
    void flushPendingStateJsonSnapshot({ reason }).catch(() => {});
  }, delayMs);
  pendingStateJsonTimer.unref?.();
  return Promise.resolve({ scheduled: true, delayMs });
}

const STATE_JSON_ALLOWED_REASONS = new Set([
  'state_saved',
  'save_state_compat',
  'steward_saved',
  'manual_data_rebuild_saved',
  'wallet_switch_reset_saved',
  'wallet_switch_chain_sync_done',
  'wallet_switch_chain_sync_failed',
  'catalog_resync_reset_saved',
  'profile_saved_local',
  'discard_local_changes',
  'discard_local_changes_reset_only',
  'push_start_queue',
  'push_item_ok_queue',
  'push_item_failed_queue',
  'push_worker_done_queue',
]);

function isAllowedStateJsonPersistReason(reason = '') {
  const normalized = String(reason || 'state_saved').trim() || 'state_saved';
  if (/^auth_login(?:_|$)/.test(normalized)) return false;
  if (/^runtime_wallet_password_(?:updated|cleared)$/.test(normalized)) return false;
  if (/^public_state_cache(?::|$)/.test(normalized)) return false;
  if (/^bootstrap(?:_|-|$)/.test(normalized)) return false;
  if (/^view_state(?:_|-|$)/.test(normalized)) return false;
  if (/^session(?:_|-|$)/.test(normalized)) return false;
  if (STATE_JSON_ALLOWED_REASONS.has(normalized)) return true;
  if (normalized.endsWith('_saved')) return true;
  return false;
}

async function writeStateJsonSnapshot(state, options = {}) {
  const reason = String(options.reason || 'state_saved').trim() || 'state_saved';
  if (!isAllowedStateJsonPersistReason(reason)) {
    appendMarketDebug('state_save_blocked_reason', {
      file: STATE_FILE,
      reason,
    });
    return Promise.resolve({ scheduled: false, blocked: true, reason });
  }
  return scheduleStateJsonSnapshotPersist(state, {
    ...options,
    reason,
    immediate: options.immediate === true,
  });
}

function schedulePublicStateRefresh(reason = 'runtime', stateSnapshot = null) {
  const snapshot = stateSnapshot && typeof stateSnapshot === 'object' ? stateSnapshot : null;
  const hasFullCatalogShape = snapshot
    && Array.isArray(snapshot.merchants)
    && Array.isArray(snapshot.users)
    && Array.isArray(snapshot.categories)
    && Array.isArray(snapshot.products);
  let effectiveSnapshot = hasFullCatalogShape ? snapshot : null;
  if (effectiveSnapshot) {
    const projectionState = buildProjectionBackedState(buildRuntimeAuthReq());
    const snapshotCatalogTotal = Number(effectiveSnapshot.merchants.length || 0)
      + Number(effectiveSnapshot.users.length || 0)
      + Number(effectiveSnapshot.categories.length || 0)
      + Number(effectiveSnapshot.products.length || 0);
    const projectionCatalogTotal = Number(Array.isArray(projectionState?.merchants) ? projectionState.merchants.length : 0)
      + Number(Array.isArray(projectionState?.users) ? projectionState.users.length : 0)
      + Number(Array.isArray(projectionState?.categories) ? projectionState.categories.length : 0)
      + Number(Array.isArray(projectionState?.products) ? projectionState.products.length : 0);
    if (projectionCatalogTotal > snapshotCatalogTotal) {
      appendMarketDebug('public_state_refresh_stale_snapshot_skipped', {
        reason: String(reason || 'runtime'),
        snapshotCatalogTotal,
        projectionCatalogTotal,
        snapshotMerchants: Number(effectiveSnapshot.merchants.length || 0),
        snapshotUsers: Number(effectiveSnapshot.users.length || 0),
        snapshotCategories: Number(effectiveSnapshot.categories.length || 0),
        snapshotProducts: Number(effectiveSnapshot.products.length || 0),
      });
      effectiveSnapshot = null;
    }
  }
  if (snapshot && !hasFullCatalogShape) {
    appendMarketDebug('public_state_refresh_partial_snapshot_skipped', {
      reason: String(reason || 'runtime'),
      hasMerchants: Array.isArray(snapshot?.merchants),
      hasUsers: Array.isArray(snapshot?.users),
      hasCategories: Array.isArray(snapshot?.categories),
      hasProducts: Array.isArray(snapshot?.products),
    });
  }
  notifyViewStateWorkerRefresh(reason, effectiveSnapshot);
}

function buildSyncBusinessPipelineDeps() {
  return {
    appendMarketDebug,
    applyDerivedSyncOnline,
    buildCatalogSnapshotPayload,
    buildLocalStateSnapshotPayload,
    buildProfileSnapshotPayload,
    cancelSqliteSnapshotPersist,
    catalogDomain,
    hashSnapshotPayload,
    localStateDomain,
    maybeRefreshWalletForCommittedSyncState,
    mergeStatePreservingChat,
    mergeSyncStatePreservingProgress,
    persistCatalogSnapshotAsync,
    persistProfileSnapshotAsync,
    persistSyncStateAsync,
    persistSyncStateNow,
    prepareStateForCommit,
    profileDomain,
    scheduleLocalPublicStateCacheRebuild,
    schedulePublicStateRefresh,
    scheduleSqliteSnapshotPersist,
    shouldRefreshWalletIndexForSync,
    triggerWalletIndexRefreshInBackground,
    writeStateJsonSnapshot,
    flushP2PSyncReceiptsSnapshot: flushPendingP2PSyncReceiptsSnapshot,
    getTrustedSyncSnapshot,
    async refreshChatProjectionFromAnchors(finalState) {
      mergeChatArtifactsFromAnchors(finalState, null);
      await persistChatRuntimeProjectionFromState(finalState, null);
    },
    refreshBusinessSummaries(finalState, context = {}) {
      const phaseTimer = context.phaseTimer || null;
      if (phaseTimer && typeof phaseTimer.mark === 'function') phaseTimer.mark('final_state_saved');
      if (typeof context.updateSyncStage === 'function') context.updateSyncStage('final_state_saved');
      appendMarketDebug('catalog_sync_timing', phaseTimer?.snapshot?.({
        localHeight: Number(finalState?.sync?.localHeight || 0),
        networkHeight: Number(finalState?.sync?.networkHeight || 0),
        anchors: Array.isArray(finalState?.anchors) ? finalState.anchors.length : 0,
        products: Array.isArray(finalState?.products) ? finalState.products.length : 0,
        categories: Array.isArray(finalState?.categories) ? finalState.categories.length : 0,
      }) || {
        localHeight: Number(finalState?.sync?.localHeight || 0),
        networkHeight: Number(finalState?.sync?.networkHeight || 0),
        anchors: Array.isArray(finalState?.anchors) ? finalState.anchors.length : 0,
        products: Array.isArray(finalState?.products) ? finalState.products.length : 0,
        categories: Array.isArray(finalState?.categories) ? finalState.categories.length : 0,
      });
    },
  };
}

function buildSyncWorkerRuntimeDeps() {
  return {
    appendMarketDebug,
    createDebugPhaseTimer,
    getStateWithRuntimeSync,
    getTrustedSyncSnapshot,
    applyDerivedSyncOnline,
    loadProjectionState: buildProjectionBackedState,
    isSyncSessionEpochCurrent,
    getSyncSessionEpoch: () => syncSessionEpoch,
    summarizeJobStage,
    updateJobState,
    commitSyncState,
    mergeAnchorsFromChain,
    reconcileBroadcastedLocalChanges,
    reconcileBroadcastedChatMessages,
    rebuildCatalogFromAnchors,
    buildRuntimeAuthReq,
    mergeLatestPendingQueueIntoState,
    applyPendingChangesOnTop,
    syncBusinessPipeline,
    buildSyncBusinessPipelineDeps,
    getSyncFinalFollowupDelayMs,
    processLocalChangeQueueInBackground,
    getQueuedPushPassword: () => queuedPushPassword,
  };
}

const syncWorkerRuntime = createSyncWorkerRuntime(buildSyncWorkerRuntimeDeps());

function commitSyncState(state, options = {}) {
  syncBusinessPipeline.commitSyncProjectionState(state, options, buildSyncBusinessPipelineDeps());
}

async function commitSyncStateNow(state, options = {}) {
  await syncBusinessPipeline.commitSyncProjectionStateNow(state, options, buildSyncBusinessPipelineDeps());
}

function commitCatalogState(state, options = {}) {
  syncBusinessPipeline.commitCatalogProjectionState(state, options, buildSyncBusinessPipelineDeps());
}

function commitProfileState(state, options = {}) {
  syncBusinessPipeline.commitProfileProjectionState(state, options, buildSyncBusinessPipelineDeps());
}

function commitLocalState(state, options = {}) {
  syncBusinessPipeline.commitLocalProjectionState(state, options, buildSyncBusinessPipelineDeps());
}

async function persistLocalStateSnapshotDirect(state, reason = 'local_state_direct') {
  await marketDb.replaceCatalogSnapshot(buildCatalogSnapshotPayload(state));
  await marketDb.replaceProfileSnapshot(buildProfileSnapshotPayload(state));
  const payload = buildLocalStateSnapshotPayload(state);
  await localStateDomain.applyLocalStateSnapshot(payload, {
    source: String(reason || 'local_state_direct'),
    seq: 0,
  });
  await writeStateJsonSnapshot(state, { reason: String(reason || 'local_state_direct') });
  getPublicViewCacheService().invalidateStateLiteSnapshotCache(`persist_local_state:${String(reason || 'local_state_direct')}`);
}

function commitChatRuntimeState(state, options = {}) {
  prepareStateForCommit(state);
  getChatRuntimeOverlay().commit(state);
  appendMarketDebug('chat_runtime_overlay_committed', {
    reason: String(options.reason || 'chat_runtime_saved'),
    unreadTotal: Math.max(0, Number(state?.chatUi?.chatUnreadTotal || 0)),
    threadCount: Object.keys(state?.chatThreads || {}).length,
    sessionCount: Object.keys(state?.chatSessions || {}).length,
  });
}

function commitAllState(state, options = {}) {
  prepareStateForCommit(state);
  const syncImmediate = options.syncImmediate === true || options.immediate === true;
  const otherImmediate = options.immediate === true;
  if (syncImmediate) {
    cancelSqliteSnapshotPersist('sync');
    void persistSyncStateNow(state.sync, {
      reason: String(options.reason || 'state_saved'),
      source: 'commitAllState',
    }).catch(() => {});
  }
  else persistSyncStateAsync(state.sync);
  if (otherImmediate) {
    commitCatalogState(state, { immediate: true, writeJson: false, refresh: false });
    commitProfileState(state, { immediate: true, writeJson: false, refresh: false });
    commitLocalState(state, { immediate: true, writeJson: false, refresh: false });
  } else {
    persistCatalogSnapshotAsync(state);
    persistProfileSnapshotAsync(state);
    scheduleSqliteSnapshotPersist('localState', state);
  }
  void writeStateJsonSnapshot(state, {
    reason: String(options.reason || 'state_saved'),
    immediate: options.immediate === true,
  }).catch(() => {});
  if (options.refresh !== false) schedulePublicStateRefresh(String(options.refreshReason || options.reason || 'state_saved'), state);
}

function getSyncFinalFollowupDelayMs() {
  return Math.max(
    PUBLIC_STATE_REFRESH_DEFER_DURING_SYNC_MS,
    Number(process.env.BSV_MARKET_SYNC_FINAL_FOLLOWUP_DELAY_MS || 30000),
  );
}

function saveState(state) {
  commitAllState(state, { reason: 'save_state_compat', refresh: false, immediate: true });
}

function unlinkIfExists(file) {
  try {
    if (fs.existsSync(file)) fs.unlinkSync(file);
  } catch (_) {}
}

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, Math.max(0, Number(ms) || 0)));
}

function yieldToEventLoop() {
  return new Promise((resolve) => setImmediate(resolve));
}

function isTransientResetError(error) {
  const code = String(error?.code || '').trim().toUpperCase();
  const message = String(error?.message || error || '').toLowerCase();
  if (code === 'EPERM' || code === 'EACCES' || code === 'EBUSY' || code === 'SQLITE_BUSY' || code === 'SQLITE_LOCKED') {
    return true;
  }
  return message.includes('database is locked')
    || message.includes('resource busy')
    || message.includes('used by another process');
}

async function withTransientResetRetries(label, fn, options = {}) {
  const attempts = Math.max(1, Number(options.attempts || 3));
  const baseDelayMs = Math.max(25, Number(options.baseDelayMs || 150));
  let lastError = null;
  for (let attempt = 1; attempt <= attempts; attempt += 1) {
    try {
      return await fn(attempt);
    } catch (error) {
      lastError = error;
      const retryable = isTransientResetError(error);
      appendMarketDebug('catalog_resync_retryable_step_error', {
        label,
        attempt,
        attempts,
        retryable,
        code: String(error?.code || ''),
        message: String(error?.message || error || 'unknown_error'),
      });
      if (!retryable || attempt >= attempts) break;
      await sleep(baseDelayMs * attempt);
    }
  }
  throw lastError;
}

function readJsonFile(file, fallback) {
  try {
    if (!fs.existsSync(file)) return fallback;
    return JSON.parse(fs.readFileSync(file, 'utf8'));
  } catch (_) {
    return fallback;
  }
}

function fsyncDirectoryIfPossible(dir) {
  if (!dir) return;
  let fd = null;
  try {
    fd = fs.openSync(dir, 'r');
    fs.fsyncSync(fd);
  } catch (_) {
  } finally {
    if (fd !== null) {
      try { fs.closeSync(fd); } catch (_) {}
    }
  }
}

function atomicWriteTextFile(file, serialized) {
  ensureMarketDataDir();
  const dir = path.dirname(file);
  const tempFile = `${file}.tmp.${process.pid}.${Date.now()}`;
  let fd = null;
  try {
    fd = fs.openSync(tempFile, 'w');
    fs.writeFileSync(fd, serialized, 'utf8');
    fs.fsyncSync(fd);
  } finally {
    if (fd !== null) {
      try { fs.closeSync(fd); } catch (_) {}
    }
  }
  try {
    fs.renameSync(tempFile, file);
  } catch (err) {
    const code = String(err?.code || '').toUpperCase();
    const transient = code === 'EPERM' || code === 'EACCES' || code === 'EBUSY';
    if (!transient) {
      try { if (fs.existsSync(tempFile)) fs.unlinkSync(tempFile); } catch (_) {}
      throw err;
    }
    try {
      fs.copyFileSync(tempFile, file);
      fs.unlinkSync(tempFile);
      appendMarketDebug('atomic_write_fallback_copy', {
        file,
        code: code || 'UNKNOWN',
      });
    } catch (copyErr) {
      try { if (fs.existsSync(tempFile)) fs.unlinkSync(tempFile); } catch (_) {}
      throw copyErr;
    }
  }
  fsyncDirectoryIfPossible(dir);
}

function writeJsonFile(file, value) {
  const serialized = JSON.stringify(value, null, 2);
  atomicWriteTextFile(file, serialized);
}

