function trimStateToCoreDomains(source = null, req = null) {
  const init = defaultState();
  const state = source && typeof source === 'object' ? source : {};
  const profileName = String(state?.profile?.name || '').trim();
  const merchantId = sanitizeMerchantId(
    (req ? deriveMerchantIdForSession(req) : '')
      || state?.currentMerchantId
      || '',
  ) || init.currentMerchantId;
  const users = Array.isArray(state?.users) && state.users.length > 0
    ? state.users.map((row) => ({ ...row }))
    : [{ id: 'buyer', name: String(profileName || '买家A'), role: 'buyer' }];
  return {
    ...init,
    sync: {
      ...init.sync,
      ...(state?.sync && typeof state.sync === 'object' ? state.sync : {}),
    },
    profile: {
      ...init.profile,
      ...(state?.profile && typeof state.profile === 'object' ? state.profile : {}),
      name: profileName,
    },
    steward: {
      ...init.steward,
      ...(state?.steward && typeof state.steward === 'object' ? state.steward : {}),
    },
    walletShadow: state?.walletShadow && typeof state.walletShadow === 'object'
      ? { ...state.walletShadow }
      : { buyer: 0, seller: 0 },
    currentMerchantId: merchantId,
    users,
    merchants: [],
    categories: [],
    products: [],
    orders: [],
    pendingAnchors: [],
    recentRawtxs: [],
    localChanges: { seq: 1, queue: [] },
    runtime: state?.runtime && typeof state.runtime === 'object'
      ? { ...state.runtime }
      : {},
  };
}

function buildCoreRuntimeStateSnapshot(req = null, sourceState = null) {
  if (sourceState && typeof sourceState === 'object') {
    return trimStateToCoreDomains(sourceState, req);
  }
  const runtimeState = getRuntimeProjectionStateSnapshot(req);
  if (runtimeState && typeof runtimeState === 'object') {
    return trimStateToCoreDomains(runtimeState, req);
  }
  return buildCoreStateFromSqlite(req);
}

function hasProjectionDomains(state = null) {
  if (!state || typeof state !== 'object') return false;
  return (
    Array.isArray(state.merchants)
    || Array.isArray(state.categories)
    || Array.isArray(state.products)
    || Array.isArray(state.orders)
    || Array.isArray(state.pendingAnchors)
    || Array.isArray(state.recentRawtxs)
    || (state.localChanges && typeof state.localChanges === 'object')
  );
}

function shouldMergeCoreRuntimeProjectionState(state = null, meta = {}) {
  if (meta?.forceCoreMerge === true) return true;
  if (!state || typeof state !== 'object') return false;
  const reason = String(meta?.reason || '');
  const looksCoreOnlyReason = (
    reason.startsWith('public_state_cache:')
    || reason === 'sync_state_saved'
    || reason === 'sync_final_state_saved'
    || reason === 'independent_sync_start_saved'
    || reason === 'independent_sync_commit_window_saved'
    || reason === 'independent_sync_commit_block_saved'
  );
  if (!looksCoreOnlyReason) return false;
  const projectionLists = [
    state.merchants,
    state.categories,
    state.products,
    state.orders,
    state.pendingAnchors,
    state.recentRawtxs,
    state?.localChanges?.queue,
  ];
  return projectionLists.every((list) => !Array.isArray(list) || list.length <= 0);
}

function mergeCoreSnapshotIntoRuntime(req = null, sourceState = null) {
  const runtimeState = getRuntimeProjectionStateSnapshot(req);
  const base = runtimeState && typeof runtimeState === 'object'
    ? runtimeState
    : defaultState();
  const core = buildCoreRuntimeStateSnapshot(req, sourceState);
  return {
    ...base,
    ...core,
    sync: {
      ...(base?.sync && typeof base.sync === 'object' ? base.sync : {}),
      ...(core?.sync && typeof core.sync === 'object' ? core.sync : {}),
    },
    profile: {
      ...(base?.profile && typeof base.profile === 'object' ? base.profile : {}),
      ...(core?.profile && typeof core.profile === 'object' ? core.profile : {}),
    },
    steward: {
      ...(base?.steward && typeof base.steward === 'object' ? base.steward : {}),
      ...(core?.steward && typeof core.steward === 'object' ? core.steward : {}),
    },
    walletShadow: core?.walletShadow && typeof core.walletShadow === 'object'
      ? { ...core.walletShadow }
      : (base?.walletShadow && typeof base.walletShadow === 'object' ? { ...base.walletShadow } : { buyer: 0, seller: 0 }),
    runtime: {
      ...(base?.runtime && typeof base.runtime === 'object' ? base.runtime : {}),
      ...(core?.runtime && typeof core.runtime === 'object' ? core.runtime : {}),
    },
    merchants: Array.isArray(base?.merchants) ? base.merchants.map((row) => ({ ...row })) : [],
    categories: Array.isArray(base?.categories) ? base.categories.map((row) => ({ ...row })) : [],
    products: Array.isArray(base?.products) ? base.products.map((row) => ({ ...row })) : [],
    orders: Array.isArray(base?.orders) ? base.orders.map((row) => ({ ...row })) : [],
    pendingAnchors: Array.isArray(base?.pendingAnchors) ? base.pendingAnchors.map((row) => ({ ...row })) : [],
    recentRawtxs: Array.isArray(base?.recentRawtxs) ? base.recentRawtxs.map((row) => ({ ...row })) : [],
    localChanges: base?.localChanges && typeof base.localChanges === 'object'
      ? {
          ...base.localChanges,
          queue: Array.isArray(base.localChanges.queue) ? base.localChanges.queue.map((row) => ({ ...row })) : [],
        }
      : { seq: 1, queue: [] },
  };
}

function commitCoreRuntimeProjectionState(state = null, meta = {}) {
  const effectiveState = shouldMergeCoreRuntimeProjectionState(state, meta)
    ? mergeCoreSnapshotIntoRuntime(meta?.req || null, state)
    : hasProjectionDomains(state)
    ? cloneRuntimeProjectionState(state)
    : mergeCoreSnapshotIntoRuntime(meta?.req || null, state);
  if (!effectiveState) return null;
  stripRuntimeChatArtifacts(effectiveState);
  return commitRuntimeProjectionState(effectiveState, meta);
}

