function enforceCoreMemoryOnly(req = null, sourceState = null, reason = 'core_memory_enforced') {
  const committed = commitCoreRuntimeProjectionState(sourceState, {
    reason: String(reason || 'core_memory_enforced'),
    hydrated: true,
    req,
  });
  getPublicViewCacheService().setEnvelope(getPublicViewCacheService().getEnvelope());
  invalidateStateLiteSnapshotCache(String(reason || 'core_memory_enforced'));
  return committed;
}

