function shouldRefreshWalletIndexForSync(state) {
  if (!wallet.walletExists()) return false;
  const currentLocalHeight = Number(state?.sync?.localHeight || 0);
  const currentTargetHeight = Number(state?.sync?.targetHeight || 0);
  const walletIndexState = loadWalletIndexState();
  const previousHeight = Number(walletIndexState?.walletScanCursorHeight || 0);
  const recentRawtxs = Array.isArray(state?.recentRawtxs) ? state.recentRawtxs : [];
  const latestRecentRawtx = recentRawtxs.length ? recentRawtxs[recentRawtxs.length - 1] : null;
  const currentRecentRawtxLatestTxid = String(latestRecentRawtx?.txid || '');
  const currentRecentRawtxLatestTs = String(latestRecentRawtx?.ts || '');
  const previousRecentRawtxCount = Number(walletIndexState?.recentRawtxCount || 0);
  const previousRecentRawtxLatestTxid = String(walletIndexState?.recentRawtxLatestTxid || '');
  const previousRecentRawtxLatestTs = String(walletIndexState?.recentRawtxLatestTs || '');
  const recentRawtxChanged = recentRawtxs.length > 0 && (
    recentRawtxs.length !== previousRecentRawtxCount
    || currentRecentRawtxLatestTxid !== previousRecentRawtxLatestTxid
    || currentRecentRawtxLatestTs !== previousRecentRawtxLatestTs
  );
  if (!walletIndexState?.walletKey) return true;
  if (recentRawtxChanged) return true;
  if (currentTargetHeight > 0 && currentLocalHeight >= currentTargetHeight) return currentLocalHeight > previousHeight;
  return (currentLocalHeight - previousHeight) >= WALLET_INDEX_REFRESH_BLOCK_INTERVAL;
}

function triggerWalletIndexRefreshInBackground(state) {
  if (!shouldRefreshWalletIndexForSync(state)) return false;
  if (walletIndexRefreshPromise) return false;
  const timeoutMs = WALLET_INDEX_REFRESH_TIMEOUT_MS;
  walletIndexRefreshPromise = (async () => {
    let timer = null;
    try {
      let confirmedChainReconcile = null;
      let stalePendingReconcile = null;
      await Promise.race([
        (async () => {
          if (typeof wallet.reconcileUnconfirmedUtxosWithConfirmedChain === 'function') {
            confirmedChainReconcile = await wallet.reconcileUnconfirmedUtxosWithConfirmedChain({
              source: 'wallet_index_refresh_background',
              localHeight: Number(state?.sync?.localHeight || 0),
              allowDisabled: true,
            });
          }
          if (typeof wallet.reconcileStalePendingWalletTxs === 'function') {
            stalePendingReconcile = await wallet.reconcileStalePendingWalletTxs({
              source: 'wallet_index_refresh_background',
              localHeight: Number(state?.sync?.localHeight || 0),
              minBlocks: 6,
              minAgeMs: 10 * 60 * 1000,
              nodeLimit: 3,
              maxChecks: 8,
            });
          }
        })(),
        new Promise((_, reject) => {
          timer = setTimeout(() => reject(new Error(`wallet index refresh timeout after ${timeoutMs}ms`)), timeoutMs);
        }),
      ]);
      appendMarketDebug('wallet_index_refresh_background_done', {
        localHeight: Number(state?.sync?.localHeight || 0),
        targetHeight: Number(state?.sync?.targetHeight || 0),
        recentRawtxCount: Array.isArray(state?.recentRawtxs) ? state.recentRawtxs.length : 0,
        confirmedChainReconcile,
        stalePendingReconcile,
        timeoutMs,
      });
    } catch (err) {
      appendMarketDebug('wallet_index_refresh_soft_fail', {
        localHeight: Number(state?.sync?.localHeight || 0),
        targetHeight: Number(state?.sync?.targetHeight || 0),
        timeoutMs,
        message: String(err?.message || 'wallet index refresh failed'),
      });
    } finally {
      if (timer) clearTimeout(timer);
      try {
        await bridgeWalletFactsToDomainSafe(null, 'background_wallet_index_refresh');
        scheduleFrontendDomainBroadcast('wallet', 'background_wallet_index_refresh', 60);
      } catch (_) {}
      walletIndexRefreshPromise = null;
    }
  })();
  return true;
}

