function findActiveWalletRefreshCommand(criteria = {}) {
  const wantRescan = criteria?.rescan === true;
  const wantForceBootstrap = criteria?.forceBootstrap === true;
  const wantClearLocalFirst = criteria?.clearLocalFirst === true;
  const wantCount = Math.max(1, Math.min(500, Number(criteria?.count || wallet.DEFAULT_RESCAN_COUNT) || wallet.DEFAULT_RESCAN_COUNT));
  const queueState = loadCommandQueueState({ fresh: true });
  const commands = Array.isArray(queueState?.commands) ? queueState.commands : [];
  return commands.find((row) => {
    if (String(row?.commandType || '') !== 'wallet_refresh_cache') return false;
    if (!['pending', 'claimed'].includes(String(row?.status || ''))) return false;
    const payload = row?.payload && typeof row.payload === 'object' ? row.payload : {};
    return (
      payload.rescan === wantRescan
      && payload.forceBootstrap === wantForceBootstrap
      && payload.clearLocalFirst === wantClearLocalFirst
      && Math.max(1, Math.min(500, Number(payload.count || wallet.DEFAULT_RESCAN_COUNT) || wallet.DEFAULT_RESCAN_COUNT)) === wantCount
    );
  }) || null;
}

async function waitForCommandResult(commandId, timeoutMs = 30000, pollMs = 150) {
  const deadline = Date.now() + Math.max(1000, Number(timeoutMs || 0));
  while (Date.now() <= deadline) {
    const row = getCommandByIdFresh(commandId);
    if (row && ['done', 'failed', 'interrupted'].includes(String(row.status || ''))) {
      return row;
    }
    await new Promise((resolve) => setTimeout(resolve, Math.max(25, Number(pollMs || 0))));
  }
  throw new Error(`command wait timeout: ${commandId}`);
}

async function waitForResyncCommandsToDrain(options = {}) {
  const timeoutMs = Math.max(1000, Number(options?.timeoutMs || 0) || 15000);
  const pollMs = Math.max(25, Number(options?.pollMs || 0) || 150);
  const resetEpoch = Math.max(0, Number(options?.resetEpoch || 0));
  const reason = String(options?.reason || 'waiting for resync commands to drain');
  const deadline = Date.now() + timeoutMs;
  let lastSnapshot = {
    pendingCount: 0,
    claimedCount: 0,
    currentJobId: '',
    currentJobType: '',
    currentJobStatus: '',
  };

  while (Date.now() <= deadline) {
    const queueState = loadCommandQueueState({ fresh: true });
    const commands = Array.isArray(queueState?.commands) ? queueState.commands : [];
    const pendingOrClaimed = commands.filter((row) => {
      if (!isResyncManagedCommandType(row?.commandType)) return false;
      return ['pending', 'claimed'].includes(String(row?.status || ''));
    });
    const jobState = loadJobState({ fresh: true });
    const currentJob = jobState?.currentJob && typeof jobState.currentJob === 'object'
      ? jobState.currentJob
      : null;
    const currentJobType = String(currentJob?.jobType || '');
    const currentJobActive = isResyncManagedCommandType(currentJobType)
      && ['running', 'claimed', 'pending'].includes(String(currentJob?.status || 'running'));
    let serviceActive = false;
    let runtimeActive = false;
    try {
      serviceActive = getIndependentSyncService().getServiceSnapshot()?.active === true;
    } catch (_) {}
    try {
      runtimeActive = getIndependentSyncRuntime().loadStatus()?.active === true;
    } catch (_) {}

    lastSnapshot = {
      pendingCount: pendingOrClaimed.filter((row) => String(row?.status || '') === 'pending').length,
      claimedCount: pendingOrClaimed.filter((row) => String(row?.status || '') === 'claimed').length,
      currentJobId: String(currentJob?.jobId || currentJob?.id || ''),
      currentJobType,
      currentJobStatus: String(currentJob?.status || ''),
      serviceActive,
      runtimeActive,
    };

    if (pendingOrClaimed.length === 0 && !currentJobActive && !serviceActive && !runtimeActive) {
      return {
        drained: true,
        elapsedMs: Math.max(0, timeoutMs - Math.max(0, deadline - Date.now())),
        ...lastSnapshot,
      };
    }

    notifyStewardSyncEpoch(resetEpoch);
    if (lastSnapshot.claimedCount > 0) {
      await interruptStaleClaimedCommands(
        (row) => isResyncManagedCommandType(row?.commandType),
        {
          reason,
          minClaimAgeMs: 1000,
        },
      );
    }
    await new Promise((resolve) => setTimeout(resolve, pollMs));
  }

  throw new Error(
    `Timed out waiting for active sync to stop (job ${lastSnapshot.currentJobType || '-'} ${lastSnapshot.currentJobStatus || '-'}, pending ${lastSnapshot.pendingCount}, claimed ${lastSnapshot.claimedCount}, serviceActive ${lastSnapshot.serviceActive === true}, runtimeActive ${lastSnapshot.runtimeActive === true})`,
  );
}

async function stopActiveSyncServices(reason = 'manual catalog resync') {
  const message = String(reason || 'manual catalog resync');
  let serviceCancelled = false;
  let runtimeCancelled = false;
  try {
    serviceCancelled = getIndependentSyncService().cancelActiveRun(message)?.cancelled === true;
  } catch (_) {}
  try {
    getIndependentSyncRuntime().cancelActiveRun(message);
    runtimeCancelled = true;
  } catch (_) {}
  clearRuntimeSyncProgress();
  appendMarketDebug('active_sync_services_stopped', {
    reason: message,
    serviceCancelled,
    runtimeCancelled,
  });
  await new Promise((resolve) => setTimeout(resolve, 150));
  return { serviceCancelled, runtimeCancelled };
}

async function stopSyncAndWait(options = {}) {
  const reason = String(options?.reason || 'manual sync stop');
  const timeoutMs = Math.max(1000, Number(options?.timeoutMs || 0) || 20000);
  const pollMs = Math.max(25, Number(options?.pollMs || 0) || 200);
  const pause = options?.pause !== false;
  let pauseResult = null;
  if (pause) {
    pauseResult = await syncDomain.pauseSync(`${reason}:pause`);
  }
  const stopEpoch = bumpSyncSessionEpoch('manual_sync_stop', {
    reason,
    pause,
  });
  notifyStewardSyncEpoch(stopEpoch);
  const stoppedServices = await stopActiveSyncServices(`${reason} epoch ${stopEpoch}`);
  const interruptedCount = await interruptQueuedCommands((row) => isResyncManagedCommandType(row?.commandType), {
    reason: `${reason} epoch ${stopEpoch}`,
  });
  const drainStartedAtMs = Date.now();
  const drainResult = await waitForResyncCommandsToDrain({
    resetEpoch: stopEpoch,
    timeoutMs,
    pollMs,
    reason: `${reason} epoch ${stopEpoch}`,
  });
  const stoppedSync = await mutateSyncProjection((sync) => {
    sync.independentPhase = 'idle';
    sync.activeSyncNodes = 0;
    sync.connectedNodes = 0;
    sync.syncWorkerNodes = 0;
    sync.activeSyncNodeList = [];
    sync.syncWorkerNodeList = [];
    sync.onlineNodeList = Array.isArray(sync.onlineNodeList) ? sync.onlineNodeList : [];
  });
  return {
    success: true,
    pauseApplied: pause,
    pauseResult,
    stopEpoch,
    interruptedCount,
    stoppedServices,
    drainWaitMs: Math.max(0, Date.now() - drainStartedAtMs),
    drainResult,
    status: syncDomain.getSyncStatus({ confirm: true }),
    stoppedSync,
  };
}

async function waitForManualSyncStartup(options = {}) {
  const commandId = String(options?.commandId || '').trim();
  const timeoutMs = Math.max(1000, Number(options?.timeoutMs || 0) || 30000);
  const pollMs = Math.max(25, Number(options?.pollMs || 0) || 200);
  const deadline = Date.now() + timeoutMs;
  let lastStatus = syncDomain.getSyncStatus({ confirm: true }) || {};
  while (Date.now() <= deadline) {
    const status = syncDomain.getSyncStatus({ confirm: true }) || {};
    lastStatus = status;
    const sync = status?.sync && typeof status.sync === 'object' ? status.sync : {};
    const jobState = status?.jobState && typeof status.jobState === 'object' ? status.jobState : {};
    const commandQueue = status?.commandQueue && typeof status.commandQueue === 'object' ? status.commandQueue : {};
    const currentJob = jobState?.currentJob && typeof jobState.currentJob === 'object' ? jobState.currentJob : null;
    const lastCommand = commandQueue?.lastCommand && typeof commandQueue.lastCommand === 'object' ? commandQueue.lastCommand : null;
    const activeJobType = String(currentJob?.jobType || '');
    const activeJobStatus = String(currentJob?.status || '');
    const activeStage = String(currentJob?.stage || '');
    const currentJobId = String(currentJob?.jobId || currentJob?.id || '');
    const queueCommandId = String(lastCommand?.id || '');
    const syncWorkerNodes = Math.max(
      0,
      Number(sync?.syncWorkerNodes || 0),
      Number(sync?.activeSyncNodes || 0),
      Number(sync?.connectedNodes || 0),
    );
    const independentPhase = String(sync?.independentPhase || '');
    const takeoverDone = activeJobType === 'run_chain_sync'
      && activeJobStatus === 'running'
      && (!commandId || currentJobId === commandId || queueCommandId === commandId);
    const prepareDone = takeoverDone && activeStage !== 'prepare_saved';
    const nodeReadyDone = prepareDone && (
      syncWorkerNodes > 0
      || ['p2p_header_sync', 'p2p_forward_probe', 'p2p_task_queue_ready', 'p2p_block_workers_done', 'p2p_service_window'].includes(activeStage)
      || ['round_running', 'round_committing', 'running'].includes(independentPhase)
    );
    const syncEnteredDone = takeoverDone && (
      syncWorkerNodes > 0
      || activeStage === 'p2p_service_window'
      || ['round_running', 'round_committing', 'running'].includes(independentPhase)
    );
    if (takeoverDone && prepareDone && nodeReadyDone && syncEnteredDone) {
      return {
        ready: true,
        steps: {
          queue: true,
          prepare: true,
          node: true,
          enterSync: true,
        },
        status,
      };
    }
    await new Promise((resolve) => setTimeout(resolve, pollMs));
  }
  throw new Error(
    `manual sync start timeout (job ${String(lastStatus?.jobState?.currentJob?.jobType || '-')}/${String(lastStatus?.jobState?.currentJob?.status || '-')}, stage ${String(lastStatus?.jobState?.currentJob?.stage || '-')}, phase ${String(lastStatus?.sync?.independentPhase || '-')})`,
  );
}

async function releaseClaimedCommand(commandId) {
  const row = await syncDomain.releaseClaimedCommand(commandId);
  if (!row) return null;
  appendMarketDebug('command_released', {
    commandId: row.id,
    commandType: row.commandType,
  });
  return { ...row };
}

async function recoverStewardQueue() {
  const { recoveredCommands, recoveredJob } = await syncDomain.recoverStewardQueue();
  if (recoveredCommands > 0 || recoveredJob) {
    appendMarketDebug('steward_queue_recovered', {
      recoveredCommands,
      recoveredJob,
    });
  }
  return {
    recoveredCommands,
    recoveredJob,
  };
}

async function recoverStartupChainSyncState() {
  let recoveredCommands = 0;
  let recoveredJob = false;
  let interruptedChainCommands = 0;
  try {
    const recovered = await recoverStewardQueue();
    recoveredCommands = Math.max(0, Number(recovered?.recoveredCommands || 0));
    recoveredJob = recovered?.recoveredJob === true;
  } catch (error) {
    appendMarketDebug('startup_chain_sync_recovery_failed', {
      step: 'recoverStewardQueue',
      message: String(error?.message || error || 'recoverStewardQueue failed'),
    });
  }
  try {
    interruptedChainCommands = await interruptQueuedCommands((row) => {
      const type = String(row?.commandType || '');
      return type === 'run_chain_sync' || type === 'rebuild_chain_indexes';
    }, {
      reason: 'startup stale chain sync interrupted',
    });
  } catch (error) {
    appendMarketDebug('startup_chain_sync_recovery_failed', {
      step: 'interruptQueuedCommands',
      message: String(error?.message || error || 'interruptQueuedCommands failed'),
    });
  }
  appendMarketDebug('startup_chain_sync_recovery', {
    recoveredCommands,
    recoveredJob,
    interruptedChainCommands,
  });
  return {
    recoveredCommands,
    recoveredJob,
    interruptedChainCommands,
  };
}

function scheduleStartupChainSyncEnqueue(delayMs = 1500) {
  const waitMs = Math.max(250, Number(delayMs || 0) || 1500);
  setTimeout(() => {
    const started = enqueueLagDrivenChainSync('startup_chain_sync_recovery');
    appendMarketDebug('startup_chain_sync_enqueue', {
      started,
      delayMs: waitMs,
      alreadyActive: hasQueuedOrActiveChainSync(),
    });
  }, waitMs).unref?.();
}

async function updateJobState(patch = {}, options = {}) {
  return syncDomain.updateJobState(patch, options);
}

async function finalizeInterruptedJob(jobId, jobType, reason, startedAt, workerId) {
  return updateJobState({
    jobId,
    jobType,
    status: 'interrupted',
    stage: 'interrupted',
    progressCurrent: 0,
    progressTotal: 1,
    lastError: String(reason || 'interrupted'),
    startedAt,
    workerId,
  }, { finalize: true });
}

function getStewardRuntimeSnapshot(options = {}) {
  const freshProjection = process.env.BSV_MARKET_HEADLESS_RUNTIME === '1' || options?.confirm === true;
  const state = loadProjectionBackedRuntimeState();
  const syncStatus = syncDomain.getSyncStatus(freshProjection ? { confirm: true } : {}) || {};
  const liveSync = (syncStatus.sync && typeof syncStatus.sync === 'object') ? syncStatus.sync : buildLiveSyncPublicSnapshot();
  const trusted = getTrustedSyncSnapshot(liveSync || {});
  const projectionCommandQueue = loadCommandQueueState(freshProjection ? { fresh: true } : {});
  const syncStatusCommandQueue = (syncStatus.commandQueue && typeof syncStatus.commandQueue === 'object')
    ? syncStatus.commandQueue
    : null;
  const commandQueue = Array.isArray(syncStatusCommandQueue?.commands)
    ? syncStatusCommandQueue
    : projectionCommandQueue;
  return {
    state,
    sync: {
      mode: String(liveSync.mode || ''),
      online: liveSync.online === true,
      localHeight: Number(liveSync.localHeight || 0),
      networkHeight: Number(liveSync.networkHeight || 0),
      lag: Number(liveSync.lag || 0),
      bootstrapHeight: Number(trusted.bootstrapHeight || FIXED_SYNC_BOOTSTRAP_HEIGHT),
      nodePool: Array.isArray(liveSync.nodePool) ? liveSync.nodePool : [],
    },
    jobState: (syncStatus.jobState && typeof syncStatus.jobState === 'object')
      ? syncStatus.jobState
      : loadJobState(freshProjection ? { fresh: true } : {}),
    walletState: (() => {
      try {
        return summarizeWalletIndexState(state, { source: 'state_lite_live_index' });
      } catch (_) {
        const walletKey = wallet.walletExists()
          ? (() => {
              try { return String(wallet.getReceiveAddress() || '').trim(); } catch (_) { return ''; }
            })()
          : '';
        return (walletKey ? walletReadDomain.getWalletIndexStatusSync(walletKey) : null) || defaultWalletIndexState();
      }
    })(),
    commandQueue,
  };
}

async function runWalletImportBootstrap(secretPayload = {}) {
  const mnemonic = String(secretPayload?.mnemonic || '').trim().replace(/\s+/g, ' ');
  const password = String(secretPayload?.password || '');
  const bootstrapMode = String(secretPayload?.bootstrapMode || 'lightweight').trim();
  const addressCount = Math.max(1, Math.min(Number(secretPayload?.addressCount || 50) || 50, 500));
  if (!mnemonic) throw new Error('Mnemonic is required');
  if (!password) throw new Error('Password is required');
  if (wallet.walletExists()) wallet.resetWalletData();

  let result;
  if (bootstrapMode === 'woc_once' || bootstrapMode === 'recover') {
    result = await wallet.recoverWallet(mnemonic, password);
  } else {
    result = await wallet.importWalletFromMnemonic(mnemonic, password, addressCount);
  }
  setRuntimeWalletPassword(password);
  const state = buildProjectionBackedState();
  const fresh = await resetAndSyncMarketStateForWallet(
    buildRuntimeAuthReq(),
    state.steward,
    getPendingAnchorOverlay(state),
    state.sync,
    { refreshWallet: true, deferChainSync: true, preserveSyncHints: false },
  );
  const chainSyncCommand = await enqueueCommand('run_chain_sync', {
    source: 'wallet_import_bootstrap',
    options: {},
  }, { dedupePending: true });
  refreshWalletIndexState(fresh, {
    source: 'import_wallet_bootstrap',
    lastIndexedAt: new Date().toISOString(),
  });
  return {
    result,
    state: fresh,
    chainSyncCommandId: String(chainSyncCommand?.id || ''),
  };
}

async function runWalletRefreshCacheCommand(payload = {}) {
  const shouldRescan = payload?.rescan === true;
  const shouldForceBootstrap = payload?.forceBootstrap === true;
  const shouldClearLocalFirst = payload?.clearLocalFirst === true;
  const shouldAbort = typeof payload?.shouldAbort === 'function'
    ? payload.shouldAbort
    : (() => hasPendingOrClaimedCommand('wallet_send'));
  let result;
  if (shouldRescan) {
    const countRaw = Number(payload?.count || wallet.DEFAULT_RESCAN_COUNT);
    const count = Number.isFinite(countRaw) ? Math.max(1, Math.min(500, Math.floor(countRaw))) : wallet.DEFAULT_RESCAN_COUNT;
    const mnemonic = wallet.getMnemonicFromPassword(getActiveWalletPassword(buildRuntimeAuthReq()));
    result = await wallet.rescanWalletAddresses(mnemonic, count);
  } else {
    const refreshSource = String(payload?.source || '').trim() || 'wallet_refresh_cache';
    result = await wallet.refreshBalancesAndHistory({
      source: shouldRescan ? 'wallet_rescan_command' : refreshSource,
      forceBootstrap: shouldForceBootstrap,
      clearLocalFirst: shouldClearLocalFirst,
      allowWocReconcile: payload?.allowWocReconcile === true
        || payload?.forceWocRebuild === true
        || refreshSource === 'wallet_sync_api'
        || refreshSource === 'wallet_sync_button'
        || refreshSource === 'wallet_switch_manual',
      shouldAbort,
    });
  }
  try {
    await bridgeWalletFactsToDomainSafe(null, shouldRescan ? 'wallet_rescan_command' : 'wallet_refresh_cache');
  } catch (_) {}
  scheduleFrontendDomainBroadcast('wallet', shouldRescan ? 'wallet_rescan_command' : 'wallet_refresh_cache', 60);
  return result && typeof result === 'object' ? result : {};
}

async function runWalletSendCommand(payload = {}) {
  const state = buildProjectionBackedState();
  const to = String(payload?.to || '').trim();
  const amountBsv = Number(payload?.amountBsv || 0);
  const sendAll = payload?.sendAll === true;
  const note = String(payload?.note || '');
  const sendTrace = String(payload?.sendTrace || '').trim();
  const commandId = String(payload?.commandId || '').trim();
  appendMarketDebug('wallet_send_request', {
    sendTrace,
    to,
    amountBsv: sendAll ? 'ALL' : amountBsv,
    sendAll,
    note,
    hasSession: false,
    hasWalletPassword: Boolean(getRuntimeWalletPassword()),
    runtimeWalletPasswordLoaded: Boolean(getRuntimeWalletPassword()),
    source: 'steward_worker',
  });
  const mnemonic = wallet.getMnemonicFromPassword(getActiveWalletPassword(buildRuntimeAuthReq()));
  if (commandId) {
    await updateJobState({
      jobId: commandId,
      jobType: 'wallet_send',
      status: 'running',
      ...summarizeJobStage('wallet_send', 'wallet_send_start'),
      lastError: '',
    });
  }
  const finalizeWalletSendFailure = async (error) => {
    const safeTxid = String(error?.txid || '').trim().toLowerCase();
    const failureStage = String(error?.failureStage || 'unknown').trim() || 'unknown';
    if (safeTxid) {
      dropRecentRawtxsByTxids(state, new Set([safeTxid]), {
        persist: false,
        reason: 'wallet_send_failed_recent_rawtx_cleanup',
      });
    }
    if (commandId) {
      try {
        await walletTxDomain.releaseReservation(commandId, {
          reason: 'wallet_send_failed',
          producer: 'wallet_send_command',
          dedupeKey: `wallet_tx.release:${commandId}:wallet_send_failed`,
        });
      } catch (_) {}
    }
    appendMarketDebug('wallet_send_failure_finalized', {
      sendTrace,
      commandId,
      txid: safeTxid,
      failureStage,
      message: String(error?.message || 'wallet send failed'),
    });
  };
  let result = null;
  try {
    result = await wallet.sendBsv({
      mnemonic,
      to,
      amountBsv,
      sendAll,
      note,
      excludeOutpoints: collectReservedOutpointsFromQueue(state),
      localHeight: Number(state?.sync?.localHeight || 0),
      onStage: (stage, extra = {}) => {
        if (!commandId) return;
        return updateJobState({
          jobId: commandId,
          jobType: 'wallet_send',
          status: 'running',
          ...summarizeJobStage('wallet_send', stage),
          stageMeta: extra && typeof extra === 'object' ? extra : {},
          lastError: '',
        }).catch(() => {});
      },
    });
  } catch (err) {
    await finalizeWalletSendFailure(err);
    throw err;
  }
  appendMarketDebug('wallet_send_result', {
    sendTrace,
    txid: String(result?.txid || ''),
    node: String(result?.node || ''),
    successCount: Number(result?.successCount || 0),
    attemptedCount: Number(result?.attemptedCount || 0),
    beefComplete: result?.beefComplete === true,
    feeSat: Number(result?.feeSat || 0),
    source: 'steward_worker',
  });
  rememberRecentRawtx(state, {
    ts: new Date().toISOString(),
    txid: String(result.txid || ''),
    eventType: 'wallet_send',
    note: String(note || '').trim() || 'wallet-send',
    rawtx: String(result.rawtx || ''),
  });
  await reserveWalletTxInputs(
    String(commandId || result.txid || '').trim(),
    'wallet_send',
    String(result.rawtx || ''),
    {
      ownerId: String(commandId || '').trim(),
      txid: String(result.txid || '').trim().toLowerCase(),
      producer: 'wallet_send_command',
      dedupeKey: `wallet_send:${String(commandId || result.txid || '').trim()}:${String(result.txid || '').trim().toLowerCase()}`,
    },
  );
  commitLocalState(state, {
    writeJson: true,
    refresh: false,
    refreshReason: 'wallet_send',
  });
  propagateWalletEventToViews('wallet_send', state, 100);
  return result && typeof result === 'object' ? result : {};
}

async function runStewardCommand(command, options = {}) {
  const workerId = String(options?.workerId || `worker-${process.pid}`);
  const commandTimeoutMs = Math.max(30000, Number(options?.timeoutMs || 0) || 0);
  const row = command && typeof command === 'object' ? command : null;
  const secretPayload = options?.secretPayload && typeof options.secretPayload === 'object'
    ? options.secretPayload
    : null;
  if (!row?.id || !row?.commandType) return null;
  const startedAt = new Date().toISOString();
  const initialSummary = summarizeJobStage(row.commandType, row.commandType === 'import_wallet_bootstrap' ? 'wallet_import_start' : 'starting');
  await updateJobState({
    jobId: row.id,
    jobType: row.commandType,
    status: 'running',
    stage: initialSummary.stage,
    progressCurrent: initialSummary.progressCurrent,
    progressTotal: initialSummary.progressTotal,
    lastError: '',
    startedAt,
    workerId,
  });
  const finalizeCommandAndJob = async (status, extra = {}, jobPatch = {}) => {
    let firstError = null;
    try {
      await markCommandFinished(row.id, status, extra);
    } catch (error) {
      if (!firstError) firstError = error;
      appendMarketDebug('command_finalize_failed', {
        commandId: row.id,
        commandType: row.commandType,
        status,
        step: 'markCommandFinished',
        message: String(error?.message || error || 'command finalize failed'),
      });
    }
    try {
      await updateJobState({
        jobId: row.id,
        jobType: row.commandType,
        status,
        startedAt,
        workerId,
        ...jobPatch,
      }, { finalize: true });
    } catch (error) {
      if (!firstError) firstError = error;
      appendMarketDebug('command_finalize_failed', {
        commandId: row.id,
        commandType: row.commandType,
        status,
        step: 'updateJobState',
        message: String(error?.message || error || 'job finalize failed'),
      });
    }
    if (firstError) throw firstError;
  };
  try {
    let interruptedReason = '';
    const nextState = await withActivityTimeout(async (noteActivity) => {
      let nextState;
      if (row.commandType === 'run_chain_sync' || row.commandType === 'rebuild_chain_indexes') {
        await updateJobState({
          jobId: row.id,
          jobType: row.commandType,
          status: 'running',
          stage: 'chain_sync',
          progressCurrent: 0,
          progressTotal: 1,
          lastError: '',
          startedAt,
          workerId,
        });
        nextState = await syncWorkerRuntime.runCatalogSyncSerial(buildRuntimeAuthReq(), {
          ...(row.payload?.options || {}),
          shouldAbort: () => hasPendingOrClaimedWalletSendCommand(),
          onStage: (stage, extra = {}) => {
            const stageName = String(stage || '').trim() || 'unknown';
            if (stageName === 'p2p_service_window' && Number(extra?.completedCount || 0) > 0) {
              noteActivity(`p2p_service_window:${Number(extra?.endHeight || 0)}`);
              return;
            }
            noteActivity(stageName);
          },
        });
        if (nextState?.interrupted === true) {
          interruptedReason = String(nextState.reason || 'sync interrupted');
          return nextState?.state || buildProjectionBackedState();
        }
      } else if (row.commandType === 'import_wallet_bootstrap') {
        if (!secretPayload) throw new Error('missing sensitive payload for import_wallet_bootstrap');
        await updateJobState({
          ...summarizeJobStage(row.commandType, 'wallet_import_start'),
          jobId: row.id,
          jobType: row.commandType,
          status: 'running',
          lastError: '',
          startedAt,
          workerId,
        });
        const imported = await runWalletImportBootstrap(secretPayload);
        await updateJobState({
          ...summarizeJobStage(row.commandType, 'wallet_materialized'),
          jobId: row.id,
          jobType: row.commandType,
          status: 'running',
          lastError: '',
          startedAt,
          workerId,
        });
        nextState = imported.state;
        await updateJobState({
          ...summarizeJobStage(row.commandType, 'market_state_reset'),
          jobId: row.id,
          jobType: row.commandType,
          status: 'running',
          lastError: '',
          startedAt,
          workerId,
        });
        await updateJobState({
          ...summarizeJobStage(row.commandType, 'chain_sync_queued'),
          jobId: row.id,
          jobType: row.commandType,
          status: 'running',
          lastError: '',
          startedAt,
          workerId,
        });
      } else if (row.commandType === 'wallet_refresh_cache') {
        nextState = buildProjectionBackedState();
        const refreshResult = await runWalletRefreshCacheCommand({
          ...(row.payload || {}),
          shouldAbort: () => {
            const latest = getCommandById(row.id);
            if (String(latest?.status || '') === 'interrupted') return true;
            return hasPendingOrClaimedCommand('wallet_send');
          },
        });
        row.result = refreshResult;
      } else if (row.commandType === 'wallet_send') {
        nextState = buildProjectionBackedState();
        const sendResult = await runWalletSendCommand({
          ...(row.payload || {}),
          commandId: row.id,
        });
        row.result = sendResult;
      } else {
        throw new Error(`unsupported command type: ${row.commandType}`);
      }
      return nextState;
    }, commandTimeoutMs, ({ lastActivityLabel, timeoutMs }) => `steward command timeout: ${row.commandType} ${row.id} (last_activity=${lastActivityLabel}, timeoutMs=${timeoutMs})`);
    if (row.commandType !== 'run_chain_sync' && row.commandType !== 'rebuild_chain_indexes') {
      refreshWalletIndexState(nextState, {
        source: row.commandType,
        lastIndexedAt: new Date().toISOString(),
      });
    }
    if (interruptedReason) {
      try {
        await finalizeCommandAndJob('interrupted', { error: interruptedReason }, {
          stage: 'interrupted',
          progressCurrent: 0,
          progressTotal: 1,
          lastError: interruptedReason,
        });
      } catch (_) {}
      await finalizeInterruptedJob(row.id, row.commandType, interruptedReason, startedAt, workerId);
      return getStewardRuntimeSnapshot();
    }
    await finalizeCommandAndJob('done', {
      result: row.result && typeof row.result === 'object' ? row.result : null,
    }, {
      ...summarizeJobStage(row.commandType, 'done'),
      lastError: '',
    });
    return getStewardRuntimeSnapshot();
  } catch (err) {
    const message = String(err?.message || 'steward command failed');
    if (String(err?.code || '') === 'COMMAND_PREEMPTED' && row.commandType === 'wallet_refresh_cache') {
      try {
        await finalizeCommandAndJob('interrupted', { error: message }, {
        stage: 'interrupted',
        progressCurrent: 0,
        progressTotal: 1,
        lastError: message,
        });
      } catch (_) {}
      return getStewardRuntimeSnapshot();
    }
    try {
      await finalizeCommandAndJob('failed', { error: message }, {
        stage: 'failed',
        progressCurrent: 0,
        progressTotal: 1,
        lastError: message,
      });
    } catch (_) {}
    throw err;
  }
}

function clearLocalCatalogArtifacts() {
  unlinkIfExists(path.join(DATA_DIR, 'anchors_global.json'));
  unlinkIfExists(CHAIN_SPOOL_FILE);
  unlinkIfExists(CHAIN_SPOOL_STATE_FILE);
  unlinkIfExists(P2P_SYNC_RECEIPTS_FILE);
  unlinkIfExists(INDEPENDENT_SYNC_STATUS_FILE);
}

async function clearLocalCatalogArtifactsWithRetry() {
  return withTransientResetRetries('clear_local_catalog_artifacts', async () => {
    clearLocalCatalogArtifacts();
    return true;
  }, {
    attempts: 4,
    baseDelayMs: 200,
  });
}

function loadP2PSyncReceipts(bootstrapHeight = FIXED_SYNC_BOOTSTRAP_HEIGHT) {
  const minHeight = Math.max(0, Number(bootstrapHeight || FIXED_SYNC_BOOTSTRAP_HEIGHT) - 1);
  const init = { version: 1, committedHeight: minHeight, entries: {} };
  try {
    const stat = fs.existsSync(P2P_SYNC_RECEIPTS_FILE) ? fs.statSync(P2P_SYNC_RECEIPTS_FILE) : null;
    const fileMtimeMs = Number(stat?.mtimeMs || 0);
    if (
      p2pSyncReceiptsCache
      && typeof p2pSyncReceiptsCache === 'object'
      && fileMtimeMs > 0
      && fileMtimeMs <= Number(p2pSyncReceiptsCacheMtimeMs || 0)
    ) {
      return {
        version: 1,
        committedHeight: Math.max(minHeight, Math.floor(Number(p2pSyncReceiptsCache.committedHeight || minHeight))),
        entries: { ...(p2pSyncReceiptsCache.entries || {}) },
      };
    }
    if (
      p2pSyncReceiptsCache
      && typeof p2pSyncReceiptsCache === 'object'
      && fileMtimeMs <= 0
    ) {
      p2pSyncReceiptsCache = null;
      p2pSyncReceiptsCacheMtimeMs = 0;
    }
    if (!fs.existsSync(P2P_SYNC_RECEIPTS_FILE)) return init;
    const raw = JSON.parse(fs.readFileSync(P2P_SYNC_RECEIPTS_FILE, 'utf8'));
    const entries = {};
    Object.entries(raw?.entries || {}).forEach(([k, v]) => {
      const h = Number(k);
      const hash = String(v?.hash || '').trim().toLowerCase();
      if (!Number.isFinite(h) || h < minHeight || !/^[0-9a-f]{64}$/i.test(hash)) return;
      entries[String(Math.floor(h))] = {
        hash,
        persistedAt: String(v?.persistedAt || ''),
        rowsFound: Math.max(0, Number(v?.rowsFound || 0)),
        txCount: Math.max(0, Number(v?.txCount || 0)),
      };
    });
    const committedHeight = Math.max(
      minHeight,
      Math.floor(Number(raw?.committedHeight || minHeight)),
    );
    const normalized = { version: 1, committedHeight, entries };
    p2pSyncReceiptsCache = normalized;
    p2pSyncReceiptsCacheMtimeMs = fileMtimeMs;
    return normalized;
  } catch (_) {
    return init;
  }
}

function saveP2PSyncReceipts(receipts) {
  const next = {
    version: 1,
    committedHeight: Math.max(0, Math.floor(Number(receipts?.committedHeight || 0))),
    entries: {},
  };
  const sorted = Object.entries(receipts?.entries || {})
    .map(([k, v]) => [Math.floor(Number(k)), v])
    .filter(([h, v]) => Number.isFinite(h) && h >= 0 && /^[0-9a-f]{64}$/i.test(String(v?.hash || '')))
    .sort((a, b) => a[0] - b[0]);
  const kept = sorted.slice(Math.max(0, sorted.length - P2P_SYNC_RECEIPTS_MAX_ENTRIES));
  kept.forEach(([h, v]) => {
    next.entries[String(h)] = {
      hash: String(v.hash || '').trim().toLowerCase(),
      persistedAt: String(v.persistedAt || ''),
      rowsFound: Math.max(0, Number(v.rowsFound || 0)),
      txCount: Math.max(0, Number(v.txCount || 0)),
    };
  });
  p2pSyncReceiptsCache = {
    version: 1,
    committedHeight: next.committedHeight,
    entries: { ...next.entries },
  };
  p2pSyncReceiptsCacheMtimeMs = Date.now();
  pendingP2PSyncReceiptsSnapshot = next;
  scheduleP2PSyncReceiptsPersist();
  return next;
}

function flushPendingP2PSyncReceiptsSnapshot(options = {}) {
  if (pendingP2PSyncReceiptsTimer) {
    clearTimeout(pendingP2PSyncReceiptsTimer);
    pendingP2PSyncReceiptsTimer = null;
  }
  const snapshot = pendingP2PSyncReceiptsSnapshot;
  if (!snapshot || typeof snapshot !== 'object') return Promise.resolve(null);
  const request = {
    file: P2P_SYNC_RECEIPTS_FILE,
    serialized: JSON.stringify(snapshot, null, 2),
  };
  return queueCoalescedSnapshotWrite(coalescedSnapshotWrites.p2pSyncReceipts, request, (nextPayload) =>
    marketDb.writeP2PSyncReceiptsSnapshot(nextPayload)).catch((error) => {
    appendMarketDebug('p2p_sync_receipts_persist_failed', {
      message: String(error?.message || error || 'p2p_sync_receipts_persist_failed'),
      reason: String(options.reason || 'p2p_sync_receipts_flush'),
    });
    throw error;
  });
}

function scheduleP2PSyncReceiptsPersist(options = {}) {
  if (pendingP2PSyncReceiptsTimer) clearTimeout(pendingP2PSyncReceiptsTimer);
  const force = options.force === true;
  const activeSync = !force && hasQueuedOrActiveChainSync();
  const baseDelayMs = activeSync
    ? P2P_SYNC_RECEIPTS_ACTIVE_SYNC_DEBOUNCE_MS
    : P2P_SYNC_RECEIPTS_PERSIST_DEBOUNCE_MS;
  const delayMs = getLagAdjustedDelayMs(baseDelayMs, { minimumDelayMs: baseDelayMs });
  pendingP2PSyncReceiptsTimer = setTimeout(() => {
    pendingP2PSyncReceiptsTimer = null;
    void flushPendingP2PSyncReceiptsSnapshot({
      reason: String(options.reason || (activeSync ? 'sync_active_checkpoint' : 'idle_checkpoint')),
    }).catch(() => {});
  }, delayMs);
  pendingP2PSyncReceiptsTimer.unref?.();
}

function recordPersistedP2PSyncRound({ bootstrapHeight, committedHeight, perHeight }) {
  const base = loadP2PSyncReceipts(bootstrapHeight);
  const next = {
    version: 1,
    committedHeight: Math.max(Number(base.committedHeight || 0), Math.floor(Number(committedHeight || 0))),
    entries: { ...(base.entries || {}) },
  };
  Object.entries(perHeight || {}).forEach(([k, v]) => {
    const h = Math.floor(Number(k));
    const hash = String(v?.hash || '').trim().toLowerCase();
    if (!Number.isFinite(h) || h < 0 || !/^[0-9a-f]{64}$/i.test(hash)) return;
    next.entries[String(h)] = {
      hash,
      persistedAt: String(v?.persistedAt || new Date().toISOString()),
      rowsFound: Math.max(0, Number(v?.rowsFound || 0)),
      txCount: Math.max(0, Number(v?.txCount || 0)),
    };
  });
  return saveP2PSyncReceipts(next);
}

function resetP2PSyncReceiptsState({
  bootstrapHeight = FIXED_SYNC_BOOTSTRAP_HEIGHT,
  committedHeight,
} = {}) {
  const normalizedBootstrapHeight = Math.max(0, Number(bootstrapHeight || FIXED_SYNC_BOOTSTRAP_HEIGHT || 0));
  const normalizedCommittedHeight = Math.max(
    0,
    Number(committedHeight ?? (normalizedBootstrapHeight > 0 ? (normalizedBootstrapHeight - 1) : 0)),
  );
  if (pendingP2PSyncReceiptsTimer) {
    clearTimeout(pendingP2PSyncReceiptsTimer);
    pendingP2PSyncReceiptsTimer = null;
  }
  pendingP2PSyncReceiptsSnapshot = null;
  p2pSyncReceiptsCache = null;
  p2pSyncReceiptsCacheMtimeMs = 0;
  return saveP2PSyncReceipts({
    version: 1,
    committedHeight: normalizedCommittedHeight,
    entries: {},
  });
}

async function resetSyncArtifactsForBootstrap(options = {}) {
  const bootstrapHeight = Math.max(0, Number(options?.bootstrapHeight || FIXED_SYNC_BOOTSTRAP_HEIGHT));
  const resetEpoch = Math.max(0, Number(options?.resetEpoch || 0));
  const reason = String(options?.reason || 'sync_reset_artifacts');
  const localHeight = Math.max(0, bootstrapHeight - 1);
  const syncState = options?.syncState && typeof options.syncState === 'object'
    ? options.syncState
    : {};
  const targetHeight = syncState.manualQuickstartPending === true
    ? Math.max(0, Number(syncState.independentTargetHeight || syncState.p2pTipHeight || 0))
    : 0;
  resetP2PSyncReceiptsState({
    bootstrapHeight,
    committedHeight: localHeight,
  });
  await flushPendingP2PSyncReceiptsSnapshot({ reason: `${reason}:receipts_reset` });
  try {
    getIndependentSyncRuntime().resetStatus({
      bootstrapHeight,
      localHeight,
      targetHeight,
    });
  } catch (_) {}
  try {
    getIndependentSyncService().resetServiceState();
  } catch (_) {}
  notifyStewardResetSyncArtifacts({
    bootstrapHeight,
    localHeight,
    targetHeight,
    resetEpoch,
    manualQuickstartPending: syncState.manualQuickstartPending === true,
  });
  const heartbeatSnapshot = readJsonFile(STEWARD_HEARTBEAT_FILE, null);
  const nextHeartbeat = {
    ...(heartbeatSnapshot && typeof heartbeatSnapshot === 'object' ? heartbeatSnapshot : {}),
    ts: new Date().toISOString(),
    inFlight: false,
    phase: 'idle',
    lastPhase: 'sync_reset',
    elapsedMs: 0,
    lag: 0,
    nextDelaySec: Number(heartbeatSnapshot?.nextDelaySec || 15),
  };
  await marketDb.writeTextFileSnapshot({
    file: STEWARD_HEARTBEAT_FILE,
    serialized: JSON.stringify(nextHeartbeat, null, 2),
  });
  await syncDomain.resetProjectionState({
    ...syncState,
    bootstrapHeight,
    localHeight,
    fixedSyncLastHeight: 0,
    receiptCommittedHeight: localHeight,
    independentPhase: 'idle',
    independentLocalHeight: localHeight,
    independentTargetHeight: Number(syncState.manualQuickstartPending === true
      ? Math.max(0, Number(syncState.independentTargetHeight || syncState.p2pTipHeight || 0))
      : 0),
    p2pTipHeight: Math.max(0, Number(syncState.p2pTipHeight || 0)),
    p2pHeaderCursorHeight: Number.isFinite(Number(syncState.p2pHeaderCursorHeight))
      ? Number(syncState.p2pHeaderCursorHeight)
      : -1,
    sessionEpoch: resetEpoch,
    updatedAt: new Date().toISOString(),
  }, {
    reason: `${reason}:projection_reset`,
    paused: syncState.manualQuickstartPending !== true,
    autoSyncEnabled: false,
    pauseReason: syncState.manualQuickstartPending === true ? '' : 'manual_sync_state_reset',
  });
  reinitializeRuntimeProjectionStateForSyncReset({
    req: buildRuntimeAuthReq(),
    syncState: {
      ...syncState,
      bootstrapHeight,
      localHeight,
      fixedSyncLastHeight: 0,
      targetHeight,
      sessionEpoch: resetEpoch,
    },
    reason: `${reason}:runtime_reset`,
  });
  appendMarketDebug('sync_reset_artifacts_completed', {
    bootstrapHeight,
    resetEpoch,
    reason,
    localHeight,
  });
}

function buildFreshMarketStateForBootstrap(req, stewardLike = {}, bootstrapHeight = FIXED_SYNC_BOOTSTRAP_HEIGHT) {
  const fresh = defaultState();
  fresh.steward = { ...fresh.steward, ...(stewardLike || {}) };
  fresh.currentMerchantId = ensureCurrentMerchantId(fresh, req);
  fresh.sync.bootstrapHeight = bootstrapHeight;
  fresh.sync.fixedSyncLastHeight = null;
  fresh.sync.emptyBackfillTried = false;
  fresh.sync.localHeight = Math.max(0, bootstrapHeight - 1);
  fresh.sync.scannedFrom = bootstrapHeight;
  fresh.sync.p2pTipHeight = 0;
  fresh.sync.p2pTipHash = '';
  fresh.sync.p2pGapHeights = [];
  if (Number(bootstrapHeight) !== Number(FIXED_SYNC_BOOTSTRAP_HEIGHT)) {
    fresh.sync.p2pHeaderCursorHeight = -1;
    fresh.sync.p2pHeaderCursorHash = '';
    fresh.sync.p2pHeightHashCache = {};
  }
  applyDerivedSyncOnline(fresh.sync);
  return fresh;
}

function buildRuntimeProjectionBaseForSyncReset(options = {}) {
  const req = options?.req || null;
  const bootstrapHeight = Math.max(
    0,
    Number(options?.bootstrapHeight || options?.syncState?.bootstrapHeight || FIXED_SYNC_BOOTSTRAP_HEIGHT),
  );
  const stewardLike = options?.stewardLike || runtimeProjectionState?.steward || {};
  const runtimeState = getRuntimeProjectionStateSnapshot(req);
  if (runtimeState && !runtimeProjectionNeedsSqliteHydrate(runtimeState)) {
    return runtimeState;
  }
  const sqliteState = buildProjectionStateFromSqlite(req);
  if (sqliteState && !runtimeProjectionNeedsSqliteHydrate(sqliteState)) {
    sqliteState.steward = { ...(sqliteState.steward || {}), ...stewardLike };
    sqliteState.currentMerchantId = ensureCurrentMerchantId(sqliteState, req);
    return sqliteState;
  }
  return buildFreshMarketStateForBootstrap(req, stewardLike, bootstrapHeight);
}

function reinitializeRuntimeProjectionStateForSyncReset(options = {}) {
  const syncState = options?.syncState && typeof options.syncState === 'object' ? options.syncState : {};
  const bootstrapHeight = Math.max(
    0,
    Number(syncState.bootstrapHeight || options?.bootstrapHeight || FIXED_SYNC_BOOTSTRAP_HEIGHT),
  );
  const localHeight = Math.max(
    0,
    Number(syncState.localHeight ?? options?.localHeight ?? (bootstrapHeight > 0 ? (bootstrapHeight - 1) : 0)),
  );
  const fixedSyncLastHeight = Math.max(
    Math.max(0, bootstrapHeight - 1),
    Number(syncState.fixedSyncLastHeight ?? options?.fixedSyncLastHeight ?? 0),
  );
  const targetHeight = Math.max(
    0,
    Number(syncState.targetHeight || syncState.independentTargetHeight || syncState.p2pTipHeight || options?.targetHeight || 0),
  );
  const next = buildRuntimeProjectionBaseForSyncReset({
    ...options,
    bootstrapHeight,
    syncState,
  });
  if (!next.sync || typeof next.sync !== 'object') next.sync = { ...defaultState().sync };
  next.steward = {
    ...(next.steward || {}),
    ...(options?.stewardLike || runtimeProjectionState?.steward || {}),
  };
  next.currentMerchantId = ensureCurrentMerchantId(next, options?.req || null);
  next.sync.bootstrapHeight = bootstrapHeight;
  next.sync.emptyBackfillTried = false;
  next.sync.scannedFrom = bootstrapHeight;
  next.sync.localHeight = Math.max(localHeight, fixedSyncLastHeight);
  next.sync.fixedSyncLastHeight = fixedSyncLastHeight;
  next.sync.p2pTipHeight = Math.max(0, Number(syncState.p2pTipHeight || targetHeight || 0));
  next.sync.p2pTipHash = String(syncState.p2pTipHash || '');
  next.sync.p2pHeaderCursorHeight = Number.isFinite(Number(syncState.p2pHeaderCursorHeight))
    ? Number(syncState.p2pHeaderCursorHeight)
    : Number(next.sync.p2pHeaderCursorHeight || -1);
  next.sync.p2pHeaderCursorHash = String(syncState.p2pHeaderCursorHash || next.sync.p2pHeaderCursorHash || '');
  next.sync.p2pHeightHashCache = syncState.p2pHeightHashCache && typeof syncState.p2pHeightHashCache === 'object'
    ? { ...syncState.p2pHeightHashCache }
    : (next.sync.p2pHeightHashCache || {});
  next.sync.p2pGapHeights = Array.isArray(syncState.p2pGapHeights) ? syncState.p2pGapHeights.slice() : [];
  next.sync.p2pNodeStats = syncState.p2pNodeStats && typeof syncState.p2pNodeStats === 'object'
    ? { ...syncState.p2pNodeStats }
    : {};
  next.sync.manualQuickstartPending = syncState.manualQuickstartPending === true;
  next.sync.sessionEpoch = Math.max(0, Number(syncState.sessionEpoch || options?.resetEpoch || syncSessionEpoch || 0));
  next.sync.skipHeaderSyncEpoch = Math.max(0, Number(syncState.skipHeaderSyncEpoch || 0));
  next.sync.skipForwardProbeEpoch = Math.max(0, Number(syncState.skipForwardProbeEpoch || 0));
  next.sync.targetHeight = targetHeight;
  next.sync.networkHeight = targetHeight;
  applyDerivedSyncOnline(next.sync);
  clearRuntimeSyncProgress();
  commitCoreRuntimeProjectionState(next, {
    reason: String(options?.reason || 'sync_reset_runtime_projection'),
    hydrated: true,
    req: options?.req || null,
  });
  appendMarketDebug('runtime_projection_state_reinitialized_for_sync_reset', {
    reason: String(options?.reason || 'sync_reset_runtime_projection'),
    bootstrapHeight,
    localHeight: Number(next.sync.localHeight || 0),
    fixedSyncLastHeight: Number(next.sync.fixedSyncLastHeight || 0),
    targetHeight,
    sessionEpoch: Number(next.sync.sessionEpoch || 0),
    manualQuickstartPending: next.sync.manualQuickstartPending === true,
    categories: Array.isArray(next?.categories) ? next.categories.length : 0,
    products: Array.isArray(next?.products) ? next.products.length : 0,
    merchants: Array.isArray(next?.merchants) ? next.merchants.length : 0,
    profileName: String(next?.profile?.name || ''),
  });
  return next;
}

function syncMode(state) {
  if (!state.sync.online) return 'OUT_OF_SYNC';
  const lag = Math.max(0, Number(getBhsTipSnapshot()?.tipHeight || 0) - Number(state.sync.localHeight || 0));
  if (lag === 0) return 'FULL_SYNC';
  if (lag <= 3) return 'NEAR_SYNC';
  return 'OUT_OF_SYNC';
}

function setRuntimeSyncProgress(patch) {
  const now = Date.now();
  const current = (runtimeSyncProgress && typeof runtimeSyncProgress === 'object') ? runtimeSyncProgress : {};
  runtimeSyncProgress = {
    ...current,
    ...(patch || {}),
    active: true,
    updatedAt: now,
  };
}

function getTrustedSyncSnapshot(syncLike = {}) {
  const bootstrapHeight = Math.max(0, FIXED_SYNC_BOOTSTRAP_HEIGHT, Number(syncLike?.bootstrapHeight || 0));
  const minLocalHeight = Math.max(0, bootstrapHeight - 1);
  const bhsTip = getBhsTipSnapshot();
  const bhsCap = bhsTip.ok ? Math.max(minLocalHeight, Number(bhsTip.tipHeight || 0)) : Number.MAX_SAFE_INTEGER;
  const localHeight = Math.min(bhsCap, Math.max(minLocalHeight, Number(syncLike?.localHeight || 0)));
  const rawP2PTipHeight = Math.min(bhsCap, Math.max(0, Number(syncLike?.p2pTipHeight || 0)));
  const rawHeaderCursorHeight = Math.min(bhsCap, Math.max(0, Number(syncLike?.p2pHeaderCursorHeight || 0)));
  const bhsObservedTip = bhsTip.ok ? Math.max(localHeight, Math.min(bhsCap, Number(bhsTip.tipHeight || 0))) : 0;
  const p2pTipHeight = Math.max(localHeight, rawP2PTipHeight, bhsObservedTip);
  const effectiveObservedTip = Math.max(p2pTipHeight, rawHeaderCursorHeight, bhsObservedTip);
  const unresolvedGapCount = Array.isArray(syncLike?.p2pGapHeights)
    ? syncLike.p2pGapHeights
      .map((x) => Number(x))
      .filter((x) => Number.isFinite(x) && x > localHeight).length
    : 0;
  const hasRealAheadTip = Number(syncLike?.p2pTipHeight || 0) > localHeight;
  const cursorRaw = Number(syncLike?.p2pHeaderCursorHeight);
  const driftCeil = Math.max(localHeight, Number(p2pTipHeight + P2P_SYNC_TIP_DRIFT_BLOCKS));
  const p2pHeaderCursorHeight = Number.isFinite(cursorRaw) && cursorRaw <= driftCeil
    ? Math.min(cursorRaw, bhsCap)
    : -1;
  const highestBlock = Number(bhsTip.ok ? Math.max(localHeight, Number(bhsTip.tipHeight || 0)) : 0);
  const lag = highestBlock > 0 ? Math.max(0, highestBlock - localHeight) : 0;
  return {
    bootstrapHeight,
    localHeight,
    p2pTipHeight,
    p2pHeaderCursorHeight,
    highestBlock,
    lag,
    observedTipHeight: effectiveObservedTip,
    hasRealAheadTip,
    unresolvedGapCount,
  };
}

function normalizeSyncForDisplay(trustedLike = {}) {
  const trusted = { ...(trustedLike || {}) };
  const localHeight = Number(trusted.localHeight || 0);
  const highestBlock = Math.max(0, Number(trusted.highestBlock || 0));
  const lag = highestBlock > 0 ? Math.max(0, highestBlock - localHeight) : 0;
  return {
    ...trusted,
    localHeight,
    highestBlock,
    lag,
  };
}

function clearRuntimeSyncProgress() {
  runtimeSyncProgress = null;
}

function invalidateRuntimeProjectionState(reason = 'manual_invalidate') {
  runtimeProjectionState = null;
  runtimeProjectionStateHydrated = false;
  clearRuntimeSyncProgress();
  appendMarketDebug('runtime_projection_state_invalidated', {
    reason: String(reason || 'manual_invalidate'),
  });
}

function bumpSyncSessionEpoch(reason = 'unknown', extra = {}) {
  syncSessionEpoch += 1;
  appendMarketDebug('sync_session_epoch_bump', {
    epoch: syncSessionEpoch,
    reason,
    ...(extra || {}),
  });
  return syncSessionEpoch;
}

function forceSyncSessionEpoch(epoch = 0, reason = 'external') {
  const nextEpoch = Math.max(0, Number(epoch || 0));
  if (nextEpoch <= syncSessionEpoch) return syncSessionEpoch;
  syncSessionEpoch = nextEpoch;
  invalidateRuntimeProjectionState(`sync_epoch_forced:${String(reason || 'external')}`);
  appendMarketDebug('sync_session_epoch_forced', {
    epoch: syncSessionEpoch,
    reason: String(reason || 'external'),
  });
  return syncSessionEpoch;
}

function isSyncSessionEpochCurrent(epoch) {
  return Number(epoch) === Number(syncSessionEpoch);
}

function isSyncEpochTokenCurrent(epochToken) {
  if (!Number.isFinite(Number(epochToken))) return true;
  return isSyncSessionEpochCurrent(Number(epochToken));
}

function getStateWithRuntimeSync(state) {
  const base = (state && typeof state === 'object') ? state : defaultState();
  const live = runtimeSyncProgress;
  if (!live || !live.active) return base;
  if (Date.now() - Number(live.updatedAt || 0) > 120000) return base;
  const mergedSync = { ...(base.sync || {}) };
  const syncNumberFields = ['bootstrapHeight', 'p2pHeaderCursorHeight', 'p2pTipHeight'];
  syncNumberFields.forEach((k) => {
    if (Number.isFinite(Number(live[k]))) mergedSync[k] = Number(live[k]);
  });
  applyDerivedSyncOnline(mergedSync);
  return { ...base, sync: mergedSync };
}

function productVisibleForBuyer(product) {
  if (!product.deleted) return true;
  return Number(product.deleteSync?.acked || 0) < Number(product.deleteSync?.total || 0);
}

function sanitizeMerchantId(raw) {
  const s = String(raw || '').trim().toLowerCase().replace(/[^a-z0-9_-]/g, '');
  return s ? `m-${s.replace(/^m-/, '')}` : '';
}

function merchantIdFromReceiveAddress(address) {
  const a = String(address || '').trim();
  if (!a) return '';
  const hex = crypto.createHash('sha256').update(a).digest('hex').slice(0, 10);
  return `m-${hex}`;
}

function deriveMerchantIdForSession(req) {
  try {
    const pwd = req.session?.walletPassword;
    if (!pwd) return '';
    wallet.getMnemonicFromPassword(pwd);
    const receive = wallet.getReceiveAddress();
    return merchantIdFromReceiveAddress(receive);
  } catch (_) {
    return '';
  }
}

function ensureCurrentMerchantId(state, req) {
  const sessionMerchant = sanitizeMerchantId(deriveMerchantIdForSession(req));
  const fromState = sanitizeMerchantId(state.currentMerchantId);
  const fallback = sessionMerchant || fromState || 'm-local';
  const walletTxidSet = getWalletTxidSetSafe();
  let resolved = fallback;
  if (sessionMerchant) {
    // The logged-in wallet address is the authority for the local identity.
    // Historical local anchors may contain older/incorrect merchant ids and must
    // not move the current wallet to a different self identity.
    resolved = sessionMerchant;
  } else if (fromState && !isLegacyMerchantId(fromState)) {
    // Keep a stable wallet-derived merchant id once we have one; remote legacy catalog
    // rows must not steal current identity during background rebuilds.
    resolved = fromState;
  } else {
    const ownedResolved = inferOwnedMerchantIdFromAnchors(state, walletTxidSet, fallback) || fallback;
    resolved = inferLegacyCurrentMerchantIdFromCatalog(state, ownedResolved) || ownedResolved;
  }
  state.currentMerchantId = resolved;
  return resolved;
}

function getWalletTxidSetSafe() {
  try {
    const cache = wallet.getCachedBalanceAndHistory();
    const txids = Array.isArray(cache?.txids) ? cache.txids : [];
    return new Set(txids.map((x) => String(x || '').trim()).filter(Boolean));
  } catch (_) {
    return new Set();
  }
}

