function rememberRecentRawtx(state, entry = {}) {
  if (!state || typeof state !== 'object') return;
  if (!Array.isArray(state.recentRawtxs)) state.recentRawtxs = [];
  const rawtx = String(entry?.rawtx || '').trim();
  const txid = String(entry?.txid || '').trim();
  if (!rawtx || !txid) return;
  const next = {
    ts: String(entry?.ts || new Date().toISOString()),
    txid,
    eventType: String(entry?.eventType || '').trim(),
    note: String(entry?.note || '').trim(),
    rawtx,
  };
  state.recentRawtxs = state.recentRawtxs
    .filter((item) => String(item?.txid || '').trim() !== txid)
    .concat([next])
    .slice(-10);
}

function finalizeAnchorFailure(state, options = {}) {
  if (!state || typeof state !== 'object') return { keptRecentRawtx: false, failureStage: 'unknown', txid: '' };
  const safeTxid = String(options.txid || '').trim().toLowerCase();
  const safeRawtx = String(options.rawtx || '').trim();
  const eventType = String(options.eventType || '').trim();
  const failureStage = String(options.failureStage || '').trim() || 'unknown';
  const keepRecentRawtx = failureStage === 'post_broadcast_failed';
  if (/^[0-9a-f]{64}$/i.test(safeTxid)) {
    try {
      if (typeof wallet?.revertPendingWalletTx === 'function') {
        wallet.revertPendingWalletTx(safeTxid, {
          reason: `anchor_failure:${failureStage}`,
        });
      }
    } catch (err) {
      appendMarketDebug('anchor_failure_revert_failed', {
        txid: safeTxid,
        failureStage,
        message: String(err?.message || err || 'revert failed'),
      });
    }
    if (keepRecentRawtx && safeRawtx) {
      rememberRecentRawtx(state, {
        ts: new Date().toISOString(),
        txid: safeTxid,
        eventType,
        note: `market:${eventType}:needs_reconcile`,
        rawtx: safeRawtx,
      });
    } else {
      dropRecentRawtxsByTxids(state, new Set([safeTxid]), {
        persist: false,
        reason: 'anchor_failure_cleanup',
      });
    }
  }
  appendMarketDebug('anchor_failure_finalized', {
    eventType,
    txid: safeTxid,
    failureStage,
    keepRecentRawtx,
    rawtxLength: safeRawtx.length,
    message: String(options.message || ''),
  });
  return { keptRecentRawtx: keepRecentRawtx, failureStage, txid: safeTxid };
}

