let knownBuyerProfilePlaceholderRepairInFlight = false;
let knownBuyerProfilePlaceholderRepairQueued = false;

function repairKnownBuyerProfilePlaceholderQueue(state, options = {}) {
  if (!state || typeof state !== 'object') return 0;
  const queue = Array.isArray(state?.localChanges?.queue) ? state.localChanges.queue : null;
  if (!queue || !queue.length) return 0;
  const currentMerchantId = sanitizeMerchantId(state.currentMerchantId);
  if (!currentMerchantId || currentMerchantId === 'm-local') return 0;

  const merchant = Array.isArray(state.merchants)
    ? state.merchants.find((m) => sanitizeMerchantId(m?.id) === currentMerchantId)
    : null;
  const merchantName = String(merchant?.name || '').trim();
  if (!merchantName || merchantName === merchantDisplayName(currentMerchantId, '')) return 0;

  const before = queue.length;
  state.localChanges.queue = queue.filter((item) => {
    if (String(item?.targetType || '') !== 'profile') return true;
    if (String(item?.targetId || '') !== 'buyer') return true;
    if (String(item?.eventType || '') !== 'profile_set') return true;
    const pendingName = String(item?.payload?.name || '').trim();
    const pendingMerchantId = sanitizeMerchantId(item?.payload?.merchantId || '');
    return !(pendingName === '匿名买家A' && !pendingMerchantId);
  });
  const removed = before - state.localChanges.queue.length;
  if (removed <= 0) return 0;

  state.profile.name = merchantName;
  state.profile.localStatus = 'synced';
  state.profile.localUpdatedAt = new Date().toISOString();
  const buyer = Array.isArray(state.users) ? state.users.find((u) => String(u?.id || '') === 'buyer') : null;
  if (buyer) {
    buyer.name = merchantName;
    buyer.localStatus = 'synced';
    buyer.localUpdatedAt = state.profile.localUpdatedAt;
  }
  if (options.log !== false) {
    appendMarketDebug('repair_known_buyer_profile_placeholder_queue', {
      currentMerchantId,
      merchantName,
      removed,
    });
  }
  return removed;
}

function scheduleKnownBuyerProfilePlaceholderRepairPersist(state) {
  if (!state || typeof state !== 'object') return;
  if (knownBuyerProfilePlaceholderRepairInFlight) {
    knownBuyerProfilePlaceholderRepairQueued = true;
    return;
  }
  knownBuyerProfilePlaceholderRepairInFlight = true;
  const snapshotState = JSON.parse(JSON.stringify({
    profile: state.profile || {},
    currentMerchantId: state.currentMerchantId || '',
    localChanges: state.localChanges || { seq: 1, queue: [] },
    recentRawtxs: state.recentRawtxs || [],
    pendingAnchors: state.pendingAnchors || [],
  }));
  setImmediate(async () => {
    try {
      prepareStateForCommit(snapshotState);
      const profilePayload = buildProfileSnapshotPayload(snapshotState);
      const localPayload = buildLocalStateSnapshotPayload(snapshotState);
      await Promise.all([
        profileDomain.emitProfileUpsert(profilePayload, {
          producer: 'repair_known_buyer_profile_placeholder_queue',
          dedupeKey: `profile.upsert:${profilePayload.profileKey}:${hashSnapshotPayload(profilePayload)}`,
        }),
        localStateDomain.emitLocalStateSnapshot(localPayload, {
          producer: 'repair_known_buyer_profile_placeholder_queue',
          dedupeKey: `local_state.snapshot:${hashSnapshotPayload(localPayload)}`,
        }),
      ]);
      appendMarketDebug('repair_known_buyer_profile_placeholder_persisted', {
        currentMerchantId: String(snapshotState.currentMerchantId || ''),
        queueSize: Array.isArray(snapshotState.localChanges?.queue) ? snapshotState.localChanges.queue.length : -1,
        profileName: String(snapshotState.profile?.name || ''),
      });
    } catch (error) {
      appendMarketDebug('repair_known_buyer_profile_placeholder_persist_failed', {
        message: String(error?.message || error || 'repair_known_buyer_profile_placeholder_persist_failed'),
      });
    } finally {
      knownBuyerProfilePlaceholderRepairInFlight = false;
      if (knownBuyerProfilePlaceholderRepairQueued) {
        knownBuyerProfilePlaceholderRepairQueued = false;
        const latest = buildProjectionBackedState();
        if (Array.isArray(latest?.localChanges?.queue) && latest.localChanges.queue.some((item) =>
          String(item?.targetType || '') === 'profile'
          && String(item?.targetId || '') === 'buyer'
          && String(item?.eventType || '') === 'profile_set'
          && String(item?.payload?.name || '').trim() === '匿名买家A'
          && !sanitizeMerchantId(item?.payload?.merchantId || '')
        )) {
          const removed = repairKnownBuyerProfilePlaceholderQueue(latest, { log: false });
          if (removed > 0) scheduleKnownBuyerProfilePlaceholderRepairPersist(latest);
        }
      }
    }
  });
}

function findOrder(state, orderId) {
  const wanted = String(orderId || '').trim();
  if (!wanted) return null;
  const inState = Array.isArray(state?.orders) ? state.orders.find((row) => String(row?.id || '').trim() === wanted) : null;
  return inState || orderDomain.getOrderByIdSync(wanted);
}

function isOrderPlaceConfirmed(order) {
  const placeTxid = String(order?.chain?.placeTxid || '').trim();
  if (!placeTxid) return false;
  try {
    if (typeof wallet.isTxConfirmedInSpvIndex === 'function' && wallet.isTxConfirmedInSpvIndex(placeTxid)) {
      return true;
    }
  } catch (_) {}
  try {
    const anchorRows = loadAnchorEventsFromSqlite({ txid: placeTxid });
    if (Array.isArray(anchorRows) && anchorRows.some((row) => row?.confirmed === true)) return true;
  } catch (_) {}
  return false;
}

function isOrderShipConfirmed(order) {
  const shipTxid = String(order?.chain?.shipTxid || '').trim();
  if (!shipTxid) return false;
  if (order?.chain?.shipConfirmed === true || Number(order?.chain?.shipConfirmedHeight || 0) > 0) return true;
  try {
    if (typeof wallet.isTxConfirmedInSpvIndex === 'function' && wallet.isTxConfirmedInSpvIndex(shipTxid)) {
      return true;
    }
  } catch (_) {}
  try {
    const anchorRows = loadAnchorEventsFromSqlite({ txid: shipTxid });
    if (Array.isArray(anchorRows) && anchorRows.some((row) =>
      String(row?.eventType || '').trim() === 'order_ship' && row?.confirmed === true
    )) return true;
  } catch (_) {}
  return false;
}

function hasOrderPlaceTxContext(order) {
  const placeTxid = String(order?.chain?.placeTxid || order?.chain?.buyerLockTxid || '').trim();
  if (!/^[0-9a-f]{64}$/i.test(placeTxid)) return false;
  try {
    const ctx = typeof wallet.getTxContextByTxid === 'function' ? wallet.getTxContextByTxid(placeTxid) : null;
    const rawtx = wallet.rawtxHexFromUnknown(ctx?.rawtx || '');
    return Boolean(rawtx);
  } catch (_) {
    return false;
  }
}

function findExistingSellerLockForOrder(order) {
  const orderId = String(order?.id || '').trim();
  if (!orderId || typeof wallet.getHistorySnapshot !== 'function' || typeof wallet.getTxContextByTxid !== 'function') return null;
  try {
    const history = wallet.getHistorySnapshot();
    const items = Array.isArray(history?.items) ? history.items : [];
    const notes = new Set([
      `order_accept:${orderId}`,
      `order_accept_seller_lock:${orderId}`,
    ]);
    const candidates = items
      .filter((item) => notes.has(String(item?.note || '').trim()))
      .map((item) => String(item?.txid || '').trim().toLowerCase())
      .filter((txid) => /^[0-9a-f]{64}$/i.test(txid));
    for (const txid of candidates) {
      const ctx = wallet.getTxContextByTxid(txid);
      const rawtx = wallet.rawtxHexFromUnknown(ctx?.rawtx || '');
      if (!rawtx || !bsv || typeof bsv.Transaction !== 'function') continue;
      const tx = new bsv.Transaction(rawtx);
      const output = Array.isArray(tx?.outputs) ? tx.outputs[0] : null;
      if (!output) continue;
      const scriptHex = typeof output?.script?.toHex === 'function' ? String(output.script.toHex() || '').trim() : '';
      const sellerLockSats = Math.max(0, Number(output?.satoshis || 0));
      if (!scriptHex || sellerLockSats <= 0) continue;
      return {
        txid,
        rawtx,
        sellerLockVout: 0,
        sellerLockSats,
        sellerLockRedeemScriptHex: scriptHex,
      };
    }
  } catch (err) {
    appendMarketDebug('order_accept_existing_seller_lock_lookup_failed', {
      orderId,
      error: String(err?.message || err || ''),
    });
  }
  return null;
}

function orderMissingBuyerActionTemplates(order) {
  return {
    accept: false,
    sellerCancel: false,
  };
}

function orderMachineConfig() {
  return {
    buyerDepositRateBps: ORDER_BUYER_DEPOSIT_BPS,
    sellerDepositRateBps: ORDER_SELLER_DEPOSIT_BPS,
    timeoutHours: 24,
  };
}

function migrateOrderModel(orderLike) {
  const order = orderLike && typeof orderLike === 'object' ? orderLike : {};
  const normalizedStatus = coerceLegacyStatus(order.status);
  order.status = normalizedStatus;
  if (!order.snapshot || typeof order.snapshot !== 'object') order.snapshot = {};
  order.funds = ensureOrderShape(
    {
      snapshot: order.snapshot,
      status: normalizedStatus,
      funds: order.funds || {},
      transitionIds: order.transitionIds || [],
    },
    orderMachineConfig(),
  ).funds;
  if (order.funds?.settlement && typeof order.funds.settlement === 'object') {
    if (!Number.isFinite(Number(order.funds.buyerRefundSats))) order.funds.buyerRefundSats = Number(order.funds.settlement.buyerRefundSats || 0);
    if (!Number.isFinite(Number(order.funds.sellerRefundSats))) order.funds.sellerRefundSats = Number(order.funds.settlement.sellerRefundSats || 0);
    if (!Number.isFinite(Number(order.funds.sellerCreditSats))) order.funds.sellerCreditSats = Number(order.funds.settlement.sellerCreditSats || 0);
  }
  if (!Array.isArray(order.transitionIds)) order.transitionIds = [];
  if (!order.chain || typeof order.chain !== 'object') order.chain = {};
  if (!String(order.chain.completedSettlementTxid || '').trim() && normalizedStatus === ORDER_STATUS.COMPLETED) {
    order.chain.completedSettlementTxid = String(order.chain.settleTxid || '').trim();
  }
  if (!String(order.chain.refundSettlementTxid || '').trim() && normalizedStatus === ORDER_STATUS.REFUNDED) {
    order.chain.refundSettlementTxid = String(order.chain.settleTxid || '').trim();
  }
  if (!Number.isFinite(Number(order.updatedAt))) order.updatedAt = Date.now();
  return order;
}

const ORDER_ACTION_META = Object.freeze({
  sellerCancel: {
    machineAction: 'cancel_by_seller',
    tip: 'order_tip_seller_cancel',
    eventType: 'order_cancel_before_ship',
  },
  accept: {
    machineAction: 'accept',
    tip: 'order_tip_accept',
    eventType: 'order_accept',
  },
  ship: {
    machineAction: 'ship',
    tip: 'order_tip_ship',
    eventType: 'order_ship',
  },
  confirmReceipt: {
    machineAction: 'confirm_receipt',
    tip: 'order_tip_confirm_receipt',
    eventType: 'order_confirm',
  },
  requestRefund: {
    machineAction: 'request_refund',
    tip: 'order_tip_request_refund',
    eventType: 'order_refund_request',
  },
  confirmRefund: {
    machineAction: 'confirm_refund',
    tip: 'order_tip_confirm_refund',
    eventType: 'order_refund_confirm',
  },
  timeoutCancel: {
    machineAction: 'timeout_cancel',
    tip: 'order_tip_timeout_cancel',
    eventType: 'order_timeout_cancel',
  },
});

function parseActionConfirmations(reqBody = {}, actionMeta = {}) {
  return 0;
}

function getOrderWalletIdentity(state, req) {
  const merchantId = ensureCurrentMerchantId(state, req);
  return {
    merchantId,
    walletId: walletIdByMerchant(merchantId),
  };
}

function assertOrderActorAllowed(order, action, actorIdentity = {}) {
  const safeAction = String(action || '').trim();
  const safeActorWalletId = String(actorIdentity?.walletId || '').trim();
  const safeActorMerchantId = String(actorIdentity?.merchantId || '').trim();
  const safeActorReceiveAddress = String(actorIdentity?.receiveAddress || '').trim();
  const safeActorChatPubKey = String(actorIdentity?.chatPubKey || '').trim();
  const buyerWalletId = String(order?.buyerWalletId || '').trim();
  const sellerWalletId = String(order?.sellerWalletId || '').trim();
  const orderBuyerRefundAddress = String(order?.chain?.buyerRefundAddress || '').trim();
  const orderBuyerChatPubKey = String(order?.chain?.buyerChatPubKey || '').trim();
  const orderSellerMerchantId = String(order?.chain?.sellerMerchantId || order?.snapshot?.merchant_id || '').trim();
  const orderSellerChatPubKey = String(order?.chain?.sellerChatPubKey || '').trim();
  const buyerActions = new Set([
    'cancel',
    'confirmReceipt',
    'requestRefund',
    'timeoutCancel',
  ]);
  const sellerActions = new Set([
    'accept',
    'ship',
    'confirmRefund',
    'sellerCancel',
  ]);
  const isBuyerActor = Boolean(
    (buyerWalletId && safeActorWalletId && safeActorWalletId === buyerWalletId)
    || (orderBuyerRefundAddress && safeActorReceiveAddress && safeActorReceiveAddress === orderBuyerRefundAddress)
    || (orderBuyerChatPubKey && safeActorChatPubKey && safeActorChatPubKey === orderBuyerChatPubKey)
  );
  const isSellerActor = Boolean(
    (sellerWalletId && safeActorWalletId && safeActorWalletId === sellerWalletId)
    || (orderSellerMerchantId && safeActorMerchantId && safeActorMerchantId === orderSellerMerchantId)
    || (orderSellerChatPubKey && safeActorChatPubKey && safeActorChatPubKey === orderSellerChatPubKey)
  );
  if (buyerActions.has(safeAction) && !isBuyerActor) {
    const err = new Error('Only the buyer wallet can perform this order action');
    err.code = 'ORDER_ACTOR_FORBIDDEN';
    throw err;
  }
  if (sellerActions.has(safeAction) && !isSellerActor) {
    const err = new Error('Only the seller wallet can perform this order action');
    err.code = 'ORDER_ACTOR_FORBIDDEN';
    throw err;
  }
}

function assertOrderChainValue(order, path, message) {
  const parts = String(path || '').split('.').filter(Boolean);
  let cursor = order;
  for (const part of parts) {
    cursor = cursor && typeof cursor === 'object' ? cursor[part] : undefined;
  }
  if (cursor === undefined || cursor === null || String(cursor).trim() === '') {
    const err = new Error(String(message || `Missing order chain field: ${path}`));
    err.code = 'ORDER_CHAIN_INCOMPLETE';
    throw err;
  }
}

function collectOrderRebroadcastTxids(orderLike) {
  const order = migrateOrderModel(orderLike || {});
  const chain = order.chain && typeof order.chain === 'object' ? order.chain : {};
  const txids = new Set();
  const add = (value) => {
    const safe = String(value || '').trim().toLowerCase();
    if (/^[0-9a-f]{64}$/.test(safe)) txids.add(safe);
  };
  for (const key of [
    'placeTxid',
    'buyerLockTxid',
    'stateAnchorTxid',
    'sellerLockTxid',
    'shipTxid',
    'refundRequestTxid',
    'settleTxid',
    'completedSettlementTxid',
    'refundSettlementTxid',
    'cancelTxid',
  ]) {
    add(chain[key]);
  }
  for (const transitionId of (Array.isArray(order.transitionIds) ? order.transitionIds : [])) {
    const matches = String(transitionId || '').match(/[0-9a-f]{64}/ig) || [];
    for (const match of matches) add(match);
  }
  return Array.from(txids);
}

function getPeerChatPubKeyForMerchant(state, merchantId) {
  const safeMerchantId = String(merchantId || '').trim();
  if (!safeMerchantId) return '';
  const walletId = walletIdByMerchant(safeMerchantId);
  return String(getPreferredPeerChatPubKey(state, walletId) || '').trim();
}

function normalizeOrderQuantity(raw) {
  const qty = Math.max(1, Math.floor(Number(raw || 1)));
  return qty;
}

function buildOrderActionAnchorPayload(order, actionMeta, txid = '', actorSignatureContext = null) {
  const safeOrder = migrateOrderModel(order || {});
  const snapshot = safeOrder?.snapshot && typeof safeOrder.snapshot === 'object' ? safeOrder.snapshot : {};
  const chain = safeOrder?.chain && typeof safeOrder.chain === 'object' ? safeOrder.chain : {};
  const payload = {
    v: 3,
    pt: String(chain?.placeTxid || '').trim(),
    bw: String(safeOrder?.buyerWalletId || '').trim(),
    sw: String(safeOrder?.sellerWalletId || '').trim(),
    sm: String(chain?.sellerMerchantId || snapshot?.merchant_id || snapshot?.merchantId || '').trim(),
    bp: String(chain?.buyerChatPubKey || '').trim(),
    sp: String(chain?.sellerChatPubKey || '').trim(),
    br: String(chain?.buyerRefundAddress || '').trim(),
  };
  const eventType = String(actionMeta?.eventType || '').trim();
  if (eventType === 'order_accept') {
    payload.sx = String(chain?.sellerLockTxid || '').trim();
    payload.sv = Math.max(0, Number(chain?.sellerLockVout || 0));
    payload.ss = Math.max(0, Number(chain?.sellerLockSats || safeOrder?.funds?.sellerDepositSats || 0));
    payload.sh = orderProtocolV3.scriptHashHex(String(chain?.sellerLockRedeemScriptHex || '').trim());
    payload.sr = String(chain?.sellerReceiveAddress || '').trim();
    payload.sf = String(chain?.sellerRefundAddress || '').trim();
    payload.sfx = String(chain?.sellerSettlementFeeTxid || '').trim();
    payload.sfv = Math.max(0, Number(chain?.sellerSettlementFeeVout || 0));
    payload.sfs = Math.max(0, Number(chain?.sellerSettlementFeeSats || 0));
    payload.shfx = String(chain?.sellerShipAnchorFeeTxid || '').trim();
    payload.shfv = Math.max(0, Number(chain?.sellerShipAnchorFeeVout || 0));
    payload.shfs = Math.max(0, Number(chain?.sellerShipAnchorFeeSats || 0));
    payload.sah = Math.max(0, Number(chain?.sellerLockAcceptedAtHeight || 0));
  } else if (eventType === 'order_ship') {
    payload.hx = String(txid || chain?.shipTxid || '').trim();
    payload.sg = String(chain?.completedDraftRawtx || '').trim();
    const shipmentInfo = String(chain?.shipmentInfo || '').trim();
    if (shipmentInfo) payload.si = shipmentInfo.slice(0, 100);
  } else if (eventType === 'order_confirm') {
    payload.fx = String(txid || chain?.settleTxid || '').trim();
  } else if (eventType === 'order_refund_request') {
    payload.rx = String(txid || chain?.refundRequestTxid || '').trim();
    payload.rd = String(chain?.refundDraftRawtx || '').trim();
  } else if (eventType === 'order_refund_confirm') {
    payload.fx = String(txid || chain?.settleTxid || '').trim();
	  } else if (eventType === 'order_cancel_before_ship' || eventType === 'order_cancel_before_accept' || eventType === 'order_timeout_cancel') {
    payload.cx = String(txid || chain?.cancelTxid || '').trim();
  }
	  const withMeta = withSchemaMeta(String(actionMeta?.eventType || '').trim(), payload);
	  if (actorSignatureContext && typeof actorSignatureContext === 'object') {
	    const role = String(actorSignatureContext.role || '').trim();
	    const pubKey = String(actorSignatureContext.pubKey || '').trim();
	    const privateKey = actorSignatureContext.privateKey || null;
	    if (role && pubKey && privateKey) {
	      return orderProtocolV3.attachActorSignature(withMeta, { role, pubKey, privateKey, bsv });
	    }
	  }
	  return withMeta;
	}

function refreshRefundRequestReplay(existing, payload, row, updatedAt, transitionId, actionMeta = {}) {
  if (String(existing?.status || '') !== ORDER_STATUS.REFUND_REQUESTED) return null;
  const safeTransitionId = String(transitionId || '').trim();
  const transitionIds = Array.isArray(existing?.transitionIds) ? existing.transitionIds.slice(0, 200) : [];
  if (safeTransitionId && !transitionIds.includes(safeTransitionId)) transitionIds.push(safeTransitionId);
  return migrateOrderModel({
    ...existing,
    transitionIds,
    chain: {
      ...(existing?.chain || {}),
      refundRequestTxid: String(getOrderPayloadValue(payload, 'rx', 'txid') || row?.txid || existing?.chain?.refundRequestTxid || '').trim(),
      refundDraftRawtx: String(getOrderPayloadValue(payload, 'rd', 'refundDraftRawtx') || existing?.chain?.refundDraftRawtx || '').trim(),
    },
    tip: String(actionMeta?.tip || existing?.tip || '').trim(),
    updatedAt,
  });
}

function getOrderShipDraftRefs(payload = {}) {
  const rawtx = String(getOrderPayloadValue(payload, 'sg', 'completedDraftRawtx') || '').trim();
  if (!rawtx || !bsv || typeof bsv.Transaction !== 'function') return null;
  try {
    const tx = new bsv.Transaction(rawtx);
    const inputs = Array.isArray(tx.inputs) ? tx.inputs : [];
    const txidAt = (index) => {
      const input = inputs[index];
      if (!input?.prevTxId) return '';
      return String(input.prevTxId.toString('hex') || '').trim().toLowerCase();
    };
    return {
      buyerLockTxid: txidAt(0),
      sellerLockTxid: txidAt(1),
      feeTxid: txidAt(2),
      inputCount: inputs.length,
    };
  } catch (_) {
    return null;
  }
}

function hasUsableOrderReferencedTx(txid) {
  const safeTxid = String(txid || '').trim().toLowerCase();
  if (!/^[0-9a-f]{64}$/i.test(safeTxid)) return false;
  try {
    if (typeof wallet.isTxConfirmedInSpvIndex === 'function' && wallet.isTxConfirmedInSpvIndex(safeTxid)) return true;
  } catch (_) {}
  try {
    const ctx = typeof wallet.getTxContextByTxid === 'function'
      ? wallet.getTxContextByTxid(safeTxid, { includeRawtx: true })
      : null;
    const rawtx = typeof wallet.rawtxHexFromUnknown === 'function'
      ? wallet.rawtxHexFromUnknown(ctx?.rawtx || ctx?.rawtx_hex || '')
      : String(ctx?.rawtx || ctx?.rawtx_hex || '').trim();
    return Boolean(rawtx);
  } catch (_) {
    return false;
  }
}

function assertOrderAnchorFundingRefsAvailable(eventType, payload = {}, existingOrder = {}, fallbackTxid = '') {
  const safeEventType = String(eventType || '').trim();
  if (safeEventType === 'order_accept') {
    const sellerLockTxid = String(getOrderPayloadValue(payload, 'sx', 'sellerLockTxid') || fallbackTxid || '').trim().toLowerCase();
    if (!hasUsableOrderReferencedTx(sellerLockTxid)) {
      const err = new Error(`Referenced seller lock tx is unavailable: ${sellerLockTxid || '(missing)'}`);
      err.code = 'ORDER_REFERENCED_TX_UNAVAILABLE';
      throw err;
    }
  }
  if (safeEventType === 'order_ship') {
    const refs = getOrderShipDraftRefs(payload);
    const sellerLockTxid = String(
      refs?.sellerLockTxid
      || existingOrder?.chain?.sellerLockTxid
      || '',
    ).trim().toLowerCase();
    if (!hasUsableOrderReferencedTx(sellerLockTxid)) {
      const err = new Error(`Referenced seller lock tx is unavailable: ${sellerLockTxid || '(missing)'}`);
      err.code = 'ORDER_REFERENCED_TX_UNAVAILABLE';
      throw err;
    }
  }
  if (safeEventType === 'order_confirm' || safeEventType === 'order_refund_confirm') {
    const settlementTxid = String(getOrderPayloadValue(payload, 'fx', 'txid') || fallbackTxid || '').trim().toLowerCase();
    if (!hasUsableOrderReferencedTx(settlementTxid)) {
      const err = new Error(`Referenced settlement tx is unavailable: ${settlementTxid || '(missing)'}`);
      err.code = 'ORDER_REFERENCED_TX_UNAVAILABLE';
      throw err;
    }
  }
}

function orderActionPayloadRequiresActorSignature(eventType = '', payload = {}) {
  const safeEventType = String(eventType || '').trim();
  if (safeEventType === 'order_confirm' || safeEventType === 'order_refund_confirm') {
    return Boolean(String(payload?.es || '').trim() || String(payload?.ap || '').trim());
  }
  return true;
}

function scheduleOrderPlaceContextBackfillFromActionPayload(payload = {}, source = 'order_action_payload') {
  const placeTxid = String(getOrderPayloadValue(payload, 'pt', 'placeTxid') || '').trim().toLowerCase();
  if (!/^[0-9a-f]{64}$/i.test(placeTxid)) return;
  try {
    if (typeof wallet.getTxContextByTxid === 'function' && wallet.getTxContextByTxid(placeTxid)?.rawtx) return;
    if (typeof wallet.scheduleDirectParentTxContextBackfill === 'function') {
      wallet.scheduleDirectParentTxContextBackfill([placeTxid], {
        sourceLabel: String(source || 'order_action_payload'),
        kindLabel: 'order_missing_place_backfill',
        confirmed: true,
      })
        .then((result) => {
          if (Number(result?.inserted || 0) > 0 || Number(result?.skipped || 0) > 0) {
            scheduleOrderAnchorProjectionRebuild('order_missing_place_backfilled', { placeTxid, source });
          }
        })
        .catch((err) => appendMarketDebug('order_missing_place_backfill_failed', {
          placeTxid,
          source,
          error: String(err?.message || err || ''),
        }));
    }
  } catch (err) {
    appendMarketDebug('order_missing_place_backfill_failed', {
      placeTxid,
      source,
      error: String(err?.message || err || ''),
    });
  }
}

function inferOrderAcceptFromShipPayload(existingOrder, payload = {}, updatedAt = '') {
  const existing = migrateOrderModel(existingOrder || {});
  if (String(existing?.status || '') !== ORDER_STATUS.PLACED) return existing;
  const refs = getOrderShipDraftRefs(payload);
  const buyerLockTxid = String(existing?.chain?.buyerLockTxid || existing?.chain?.placeTxid || '').trim().toLowerCase();
  if (!refs?.sellerLockTxid || !refs?.buyerLockTxid || (buyerLockTxid && refs.buyerLockTxid !== buyerLockTxid)) {
    return existing;
  }
  const transitionId = `order_accept:inferred:${refs.sellerLockTxid}`;
  if (Array.isArray(existing.transitionIds) && existing.transitionIds.includes(transitionId)) return existing;
  const next = applyTransition(existing, 'accept', {
    transitionId,
    config: orderMachineConfig(),
    nowMs: Date.parse(updatedAt) || Date.now(),
  });
  next.chain.sellerLockTxid = refs.sellerLockTxid;
  next.chain.sellerLockVout = 0;
  next.chain.sellerLockSats = Math.max(0, Number(existing?.chain?.sellerLockSats || existing?.funds?.sellerDepositSats || 0));
  next.chain.sellerLockRedeemScriptHex = String(existing?.chain?.sellerLockRedeemScriptHex || existing?.chain?.jointRedeemScriptHex || '').trim();
  next.chain.jointRedeemScriptHex = String(next.chain.sellerLockRedeemScriptHex || existing?.chain?.jointRedeemScriptHex || '').trim();
  next.tip = 'order_tip_accept';
  next.updatedAt = updatedAt || Date.now();
  return migrateOrderModel(next);
}

async function broadcastAndTrackOrderRawtx(req, state, {
  rawtx,
  source = 'order_tx',
  reservationId = '',
  reservationType = 'order_tx',
  note = '',
  trackOutputs = true,
  requireVisibility = false,
  allowMissingExternalInputs = false,
  allowPendingVisibilityCommit = false,
  rootOnlyBroadcast = false,
} = {}) {
  const safeRawtx = String(rawtx || '').trim();
  if (!safeRawtx) throw new Error('Missing rawtx');
  appendMarketDebug('order_rawtx_broadcast_start', {
    source: String(source || ''),
    reservationId: String(reservationId || ''),
    reservationType: String(reservationType || ''),
    note: String(note || ''),
    rawtxBytes: Math.floor(safeRawtx.length / 2),
    allowMissingExternalInputs: allowMissingExternalInputs === true,
    allowPendingVisibilityCommit: allowPendingVisibilityCommit === true,
    rootOnlyBroadcast: rootOnlyBroadcast === true,
  });
  let broadcast;
  try {
    broadcast = await wallet.broadcastRawTx(safeRawtx, {
      requireVisibility: requireVisibility === true,
      minDataOutputSat: 0,
      allowedP2shVouts: [0],
      allowMissingExternalInputs: allowMissingExternalInputs === true,
      allowPendingVisibilityCommit: allowPendingVisibilityCommit === true,
      rootOnlyBroadcast: rootOnlyBroadcast === true,
      rootOnlyReason: String(source || ''),
    });
  } catch (err) {
    const inspected = typeof wallet.inspectRawTx === 'function' ? wallet.inspectRawTx(safeRawtx) : null;
    const failedTxid = String(inspected?.txid || '').trim().toLowerCase();
    appendMarketDebug('order_rawtx_broadcast_failed', {
      source: String(source || ''),
      reservationId: String(reservationId || ''),
      reservationType: String(reservationType || ''),
      note: String(note || ''),
      txid: failedTxid,
      rawtxBytes: Math.floor(safeRawtx.length / 2),
      rawtx: safeRawtx,
      requireVisibility: requireVisibility === true,
      allowMissingExternalInputs: allowMissingExternalInputs === true,
      allowPendingVisibilityCommit: allowPendingVisibilityCommit === true,
      rootOnlyBroadcast: rootOnlyBroadcast === true,
      error: String(err?.message || err || 'broadcast failed'),
    });
    if (failedTxid && !err.txid) err.txid = failedTxid;
    if (!err.rawtx) err.rawtx = safeRawtx;
    if (!err.failureStage) err.failureStage = 'broadcast_failed';
    throw err;
  }
  const txid = String(broadcast?.txid || '').trim().toLowerCase();
  const mempoolProofHitCount = Math.max(0, Number(broadcast?.mempoolProofHitCount || 0));
  const observedNode = String(broadcast?.observedNode || '').trim();
  const externalObserved = Boolean(
    broadcast?.observed
    && observedNode
    && observedNode !== 'spv_index'
  );
  const realVisibility = Boolean(
    externalObserved
    || broadcast?.observedConfirmed
    || mempoolProofHitCount >= 1
  );
  const optimisticSendAccepted = Boolean(
    broadcast?.broadcastAcceptedByMempool
    || broadcast?.acceptedWithoutVisibility
  );
  const pendingBroadcastAccepted = Boolean(
    broadcast?.broadcastPendingConfirm
    || (
      optimisticSendAccepted
      && Math.max(0, Number(broadcast?.successCount || 0)) >= 3
    )
  );
  const visible = requireVisibility === true
    ? Boolean(realVisibility || (allowPendingVisibilityCommit === true && pendingBroadcastAccepted))
    : Boolean(realVisibility || optimisticSendAccepted);
  if (requireVisibility && !visible) {
    const err = new Error('Broadcast has no external visibility proof; refusing to commit local order state');
    err.code = 'ORDER_BROADCAST_NOT_VISIBLE';
    err.txid = txid;
    appendMarketDebug('order_rawtx_visibility_failed', {
      source: String(source || ''),
      reservationId: String(reservationId || ''),
      reservationType: String(reservationType || ''),
      note: String(note || ''),
      txid,
      observed: Boolean(broadcast?.observed),
      observedRelevant: Boolean(broadcast?.observedRelevant),
      observedConfirmed: Boolean(broadcast?.observedConfirmed),
      observedNode,
      externalObserved,
      mempoolProofHitCount,
      mempoolProofNodes: Array.isArray(broadcast?.mempoolProofNodes) ? broadcast.mempoolProofNodes.slice(0, 16) : [],
      broadcastAcceptedByMempool: Boolean(broadcast?.broadcastAcceptedByMempool),
      acceptedWithoutVisibility: Boolean(broadcast?.acceptedWithoutVisibility),
      optimisticSendAccepted,
      pendingBroadcastAccepted,
      realVisibility,
      allowMissingExternalInputs: allowMissingExternalInputs === true,
      allowPendingVisibilityCommit: allowPendingVisibilityCommit === true,
      rootOnlyBroadcast: rootOnlyBroadcast === true,
    });
    throw err;
  }
  appendMarketDebug('order_rawtx_broadcast_done', {
    source: String(source || ''),
    reservationId: String(reservationId || ''),
    reservationType: String(reservationType || ''),
    note: String(note || ''),
    txid,
    observedRelevant: Boolean(broadcast?.observedRelevant),
    observedConfirmed: Boolean(broadcast?.observedConfirmed),
    observedNode,
    externalObserved,
    mempoolProofHitCount,
    mempoolProofNodes: Array.isArray(broadcast?.mempoolProofNodes) ? broadcast.mempoolProofNodes.slice(0, 16) : [],
    broadcastAcceptedByMempool: Boolean(broadcast?.broadcastAcceptedByMempool),
    acceptedWithoutVisibility: Boolean(broadcast?.acceptedWithoutVisibility),
    optimisticSendAccepted,
    pendingBroadcastAccepted,
    realVisibility,
    allowMissingExternalInputs: allowMissingExternalInputs === true,
    allowPendingVisibilityCommit: allowPendingVisibilityCommit === true,
    rootOnlyBroadcast: rootOnlyBroadcast === true,
  });
  const localCommit = wallet.commitWalletLocalMutation(safeRawtx, {
    source,
    txid,
    confirmed: false,
    trackOutputs,
    requireApplied: false,
    localHeight: Math.max(0, Number(state?.sync?.localHeight || 0)),
  });
  appendMarketDebug('order_rawtx_local_commit_done', {
    source: String(source || ''),
    txid,
    applied: localCommit?.applied === true,
  });
  rememberRecentRawtx(state, {
    ts: new Date().toISOString(),
    txid,
    eventType: source,
    note: String(note || source),
    rawtx: safeRawtx,
  });
  await reserveWalletTxInputs(
    String(reservationId || `${reservationType}:${txid}`),
    reservationType,
    safeRawtx,
    {
      ownerId: String(reservationId || txid),
      txid,
      producer: source,
      dedupeKey: `${source}:${txid}`,
    },
  );
  appendMarketDebug('order_rawtx_reservation_done', {
    source: String(source || ''),
    txid,
    reservationId: String(reservationId || `${reservationType}:${txid}`),
    reservationType: String(reservationType || ''),
  });
  return {
    txid,
    rawtx: safeRawtx,
    broadcast,
  };
}

function parseAnchorPayloadText(text) {
  const raw = String(text || '').trim();
  if (!raw.startsWith(CHAIN_MARKER_PREFIX)) return null;
  const secondBar = raw.indexOf('|', CHAIN_MARKER_PREFIX.length);
  if (secondBar < 0) return null;
  const marker = CHAIN_MARKER;
  const eventType = raw.slice(CHAIN_MARKER_PREFIX.length, secondBar).trim();
  const payloadRaw = raw.slice(secondBar + 1).trim();
  if (!eventType || !payloadRaw) return null;
  let payload = {};
  try {
    payload = JSON.parse(payloadRaw);
  } catch (_) {
    payload = { raw: payloadRaw };
  }
  if ((eventType === 'order_place' || eventType === 'order_open') && Array.isArray(payload)) {
    payload = expandCompactOrderPlacePayload(payload);
  }
  return { marker, eventType, payload };
}

function buildAnchorWireText(eventType, payloadForChain) {
  const safeEventType = String(eventType || '').trim();
  if (safeEventType === 'order_place' || safeEventType === 'order_open') {
    return `${CHAIN_MARKER}|${safeEventType}|${JSON.stringify(compactOrderPlacePayload(payloadForChain))}`;
  }
  return `${CHAIN_MARKER}|${safeEventType}|${JSON.stringify(payloadForChain)}`;
}

function clonePayload(payloadLike) {
  if (!payloadLike || typeof payloadLike !== 'object') return {};
  try {
    return JSON.parse(JSON.stringify(payloadLike));
  } catch (_) {
    return { ...payloadLike };
  }
}

function clampNonNegativeNumber(v, fallback = 0) {
  const n = Number(v);
  if (!Number.isFinite(n)) return Number(fallback || 0);
  return Math.max(0, n);
}

function detectPayloadSchemaVersion(payloadLike) {
  const raw = payloadLike && typeof payloadLike === 'object' ? payloadLike : {};
  const n = Number(raw._v);
  if (!Number.isFinite(n) || n <= 0) return CHAIN_SCHEMA_V1;
  return Math.floor(n);
}

function eventSchemaFamily(eventType) {
  const e = String(eventType || '');
  if (e === 'profile_set') return 'profile';
  if (e.startsWith('category_')) return 'category';
  if (e.startsWith('product_')) return 'product';
  if (e === 'wallet_key_bind' || e === 'chat_message' || e === 'chat_invite' || e === 'chat_connect_ack') return 'other';
  return 'other';
}

// Unified policy for all on-chain event families.
const CHAIN_EVENT_POLICY = Object.freeze({
  profile_set: { family: 'profile', entity: 'profile' },
  category_add: { family: 'category', entity: 'category' },
  category_edit: { family: 'category', entity: 'category' },
  category_delete: { family: 'category', entity: 'category' },
  product_add: { family: 'product', entity: 'product' },
  product_edit: { family: 'product', entity: 'product' },
  product_bump: { family: 'product', entity: 'product' },
  product_delete: { family: 'product', entity: 'product' },
  order_place: { family: 'other', entity: 'order' },
  order_open: { family: 'other', entity: 'order' },
  order_cancel: { family: 'other', entity: 'order' },
  order_cancel_before_ship: { family: 'other', entity: 'order' },
  order_confirm: { family: 'other', entity: 'order' },
  order_return: { family: 'other', entity: 'order' },
  order_return_request: { family: 'other', entity: 'order' },
  order_ship: { family: 'other', entity: 'order' },
  order_acceptReturn: { family: 'other', entity: 'order' },
  order_return_accept: { family: 'other', entity: 'order' },
  order_dispute_lock: { family: 'other', entity: 'order' },
  wallet_key_bind: { family: 'other', entity: 'chat' },
  chat_message: { family: 'other', entity: 'chat' },
  chat_invite: { family: 'other', entity: 'chat' },
  chat_connect_ack: { family: 'other', entity: 'chat' },
  chat_send: { family: 'other', entity: 'chat' },
  manual: { family: 'other', entity: 'manual' },
});

function chainEventPolicy(eventType) {
  const e = String(eventType || '');
  if (CHAIN_EVENT_POLICY[e]) return CHAIN_EVENT_POLICY[e];
  return { family: eventSchemaFamily(e), entity: 'other' };
}

function payloadUpdatedAtMs(payloadLike, fallback = '') {
  const payloadTs = Date.parse(String(payloadLike?._updatedAt || payloadLike?.updatedAt || ''));
  if (Number.isFinite(payloadTs)) return payloadTs;
  const fb = Date.parse(String(fallback || ''));
  if (Number.isFinite(fb)) return fb;
  return 0;
}

function shouldApplyEntityEvent(stampMap, key, eventTs) {
  const prevTs = Number(stampMap.get(String(key)) || 0);
  if (eventTs < prevTs) return false;
  stampMap.set(String(key), eventTs);
  return true;
}

function shouldApplyVersionedEntityEvent(metaMap, key, version, eventTs) {
  const safeKey = String(key || '');
  const prev = metaMap.get(safeKey) || { version: 0, ts: 0 };
  const nextVersion = Math.max(1, Number(version || 1));
  const nextTs = Math.max(0, Number(eventTs || 0));
  if (nextVersion < Number(prev.version || 0)) return false;
  if (nextVersion === Number(prev.version || 0) && nextTs < Number(prev.ts || 0)) return false;
  metaMap.set(safeKey, { version: nextVersion, ts: nextTs });
  return true;
}

function migrateProfileV1ToV2(payload) {
  const p = clonePayload(payload);
  if (typeof p.merchantId !== 'string') p.merchantId = '';
  p._v = CHAIN_SCHEMA_V2;
  return p;
}

function migrateProfileV2ToV3(payload) {
  const p = clonePayload(payload);
  p.name = String(p.name || '');
  p.merchantId = String(p.merchantId || '');
  p._v = CHAIN_SCHEMA_V3;
  return p;
}

function migrateCategoryV1ToV2(payload) {
  const p = clonePayload(payload);
  if (typeof p.merchantId !== 'string') p.merchantId = '';
  p._v = CHAIN_SCHEMA_V2;
  return p;
}

function migrateCategoryV2ToV3(payload) {
  const p = clonePayload(payload);
  p.id = String(p.id || '');
  p.name = String(p.name || p.id || '');
  p.merchantId = String(p.merchantId || '');
  p.version = Math.max(1, Math.floor(clampNonNegativeNumber(p.version, 1)));
  p._v = CHAIN_SCHEMA_V3;
  return p;
}

function migrateProductV1ToV2(payload) {
  const p = clonePayload(payload);
  if (typeof p.merchantId !== 'string') p.merchantId = '';
  p._v = CHAIN_SCHEMA_V2;
  return p;
}

function migrateProductV2ToV3(payload) {
  const p = clonePayload(payload);
  p.id = String(p.id || '');
  p.merchantId = String(p.merchantId || '');
  p.categoryId = String(p.categoryId || '');
  p.title = String(p.title || p.id || '');
  p.price = clampNonNegativeNumber(p.price, 0);
  p.stock = clampNonNegativeNumber(p.stock, 0);
  p.soldCount = clampNonNegativeNumber(p.soldCount, 0);
  p.imageUrl = String(p.imageUrl || '');
  p.description = String(p.description || '');
  p.version = Math.max(1, Math.floor(clampNonNegativeNumber(p.version, 1)));
  p._v = CHAIN_SCHEMA_V3;
  return p;
}

const CHAIN_MIGRATION_STEPS = {
  profile: {
    1: migrateProfileV1ToV2,
    2: migrateProfileV2ToV3,
  },
  category: {
    1: migrateCategoryV1ToV2,
    2: migrateCategoryV2ToV3,
  },
  product: {
    1: migrateProductV1ToV2,
    2: migrateProductV2ToV3,
  },
  other: {},
};

function migratePayloadToCurrent(eventType, payloadLike) {
  const family = eventSchemaFamily(eventType);
  const steps = CHAIN_MIGRATION_STEPS[family] || {};
  let payload = clonePayload(payloadLike);
  const sourceVersion = detectPayloadSchemaVersion(payloadLike);
  let v = sourceVersion;
  while (v < CHAIN_SCHEMA_VERSION) {
    const step = steps[v];
    payload = typeof step === 'function'
      ? step(payload)
      : { ...clonePayload(payload), _v: v + 1 };
    v += 1;
  }
  if (!Number.isFinite(Number(payload._v)) || Number(payload._v) !== CHAIN_SCHEMA_VERSION) {
    payload._v = CHAIN_SCHEMA_VERSION;
  }
  return {
    payload,
    sourceVersion,
    targetVersion: CHAIN_SCHEMA_VERSION,
  };
}

function normalizeEventPayload(eventType, payloadLike, fallbackUpdatedAt = '') {
  const originalPayload = payloadLike && typeof payloadLike === 'object' ? payloadLike : {};
  const migrated = migratePayloadToCurrent(eventType, payloadLike);
  const raw = migrated.payload;
  const updatedAt = String(raw._updatedAt || fallbackUpdatedAt || new Date().toISOString());
  const policy = chainEventPolicy(eventType);
  const hasOwn = (key) => Object.prototype.hasOwnProperty.call(originalPayload, key);

  if (policy.family === 'profile') {
    return {
      _v: CHAIN_SCHEMA_VERSION,
      _sourceV: migrated.sourceVersion,
      _updatedAt: updatedAt,
      name: String(raw.name || ''),
      merchantId: String(raw.merchantId || ''),
    };
  }
  if (policy.family === 'category') {
    return {
      _v: CHAIN_SCHEMA_VERSION,
      _sourceV: migrated.sourceVersion,
      _updatedAt: updatedAt,
      id: String(raw.id || ''),
      name: String(raw.name || raw.id || ''),
      merchantId: String(raw.merchantId || ''),
      version: Number(raw.version || 1),
    };
  }
  if (policy.family === 'product') {
    const normalized = {
      _v: CHAIN_SCHEMA_VERSION,
      _sourceV: migrated.sourceVersion,
      _updatedAt: updatedAt,
      id: String(raw.id || ''),
      merchantId: String(raw.merchantId || ''),
      version: Number(raw.version || 1),
    };
    if (eventType === 'product_edit' || eventType === 'product_bump') {
      if (hasOwn('categoryId')) normalized.categoryId = String(raw.categoryId || '');
      if (hasOwn('title')) normalized.title = String(raw.title ?? raw.id ?? '');
      if (hasOwn('price')) normalized.price = Number(raw.price || 0);
      if (hasOwn('stock')) normalized.stock = Number(raw.stock || 0);
      if (hasOwn('soldCount')) normalized.soldCount = Number(raw.soldCount || 0);
      if (hasOwn('imageUrl')) normalized.imageUrl = String(raw.imageUrl || '');
      if (hasOwn('description')) normalized.description = String(raw.description || '');
      return normalized;
    }
    return {
      ...normalized,
      categoryId: String(raw.categoryId || ''),
      title: String(raw.title || raw.id || ''),
      price: Number(raw.price || 0),
      stock: Number(raw.stock || 0),
      soldCount: Number(raw.soldCount || 0),
      imageUrl: String(raw.imageUrl || ''),
      description: String(raw.description || ''),
    };
  }
  return {
    _v: CHAIN_SCHEMA_VERSION,
    _sourceV: migrated.sourceVersion,
    _updatedAt: updatedAt,
    ...raw,
  };
}

function withSchemaMeta(eventType, payloadObj, updatedAt = '') {
  const normalized = normalizeEventPayload(eventType, payloadObj || {}, updatedAt || new Date().toISOString());
  const { _sourceV, ...clean } = normalized;
  return {
    ...clean,
    _v: CHAIN_SCHEMA_VERSION,
    _updatedAt: String(updatedAt || normalized._updatedAt || new Date().toISOString()),
  };
}

function estimateAnchorFeeSat(payloadBytes) {
  const feeRate = Math.max(0.25, Number(wallet.DEFAULT_FEE_RATE || 1));
  const sizeBytes = 220 + Math.max(0, Number(payloadBytes || 0));
  return Math.max(1, Math.ceil(sizeBytes * feeRate));
}

function getPendingQueueSorted(state, desc = true) {
  const queue = Array.isArray(state?.localChanges?.queue) ? state.localChanges.queue : [];
  return queue
    .filter((q) => q.status === 'pending')
    .slice()
    .sort((a, b) => {
      const ta = Date.parse(String(a?.ts || ''));
      const tb = Date.parse(String(b?.ts || ''));
      if (Number.isFinite(ta) && Number.isFinite(tb) && ta !== tb) return desc ? (tb - ta) : (ta - tb);
      return desc ? (Number(b?.seq || 0) - Number(a?.seq || 0)) : (Number(a?.seq || 0) - Number(b?.seq || 0));
    });
}

function getQueuedWorkQueueSorted(state, desc = false) {
  const queue = Array.isArray(state?.localChanges?.queue) ? state.localChanges.queue : [];
  return queue
    .filter((q) => q.status === 'queued' || q.status === 'pending')
    .slice()
    .sort((a, b) => {
      const ta = Date.parse(String(a?.ts || ''));
      const tb = Date.parse(String(b?.ts || ''));
      if (Number.isFinite(ta) && Number.isFinite(tb) && ta !== tb) return desc ? (tb - ta) : (ta - tb);
      return desc ? (Number(b?.seq || 0) - Number(a?.seq || 0)) : (Number(a?.seq || 0) - Number(b?.seq || 0));
    });
}

function getBroadcastTrackingQueue(state) {
  const queue = Array.isArray(state?.localChanges?.queue) ? state.localChanges.queue : [];
  return queue.filter((q) => q?.status === 'broadcasted' || q?.status === 'anchored');
}

function currentLocalSyncHeight(state) {
  const sync = state?.sync && typeof state.sync === 'object' ? state.sync : {};
  return Math.max(
    0,
    Number(sync.localHeight || 0),
    Number(sync.fixedSyncLastHeight || 0),
  );
}

function localChangeHasNetworkEvidence(state, item, txid) {
  if (String(item?.status || '').trim().toLowerCase() === 'anchored') return true;
  if (String(item?.publicVisibleAt || '').trim()) return true;
  const safeTxid = String(txid || item?.txid || '').trim().toLowerCase();
  if (!/^[0-9a-f]{64}$/i.test(safeTxid)) return false;
  if (wallet.isTxConfirmedInSpvIndex(safeTxid)) return true;
  const anchor = getEffectiveAnchorRows(state, { sqlite: { txid: safeTxid } })
    .find((a) => String(a?.txid || '').trim().toLowerCase() === safeTxid);
  return Boolean(anchor);
}

function isRecoverableLocalBroadcast(state, item) {
  const status = String(item?.status || '').trim().toLowerCase();
  if (!['broadcasted', 'anchored'].includes(status)) return false;
  const txid = String(item?.txid || '').trim().toLowerCase();
  if (!/^[0-9a-f]{64}$/i.test(txid)) return false;
  if (localChangeHasNetworkEvidence(state, item, txid)) return false;
  const broadcastHeight = Math.max(
    0,
    Number(item?.lastBroadcastHeight || 0),
    Number(item?.broadcastHeight || 0),
  );
  if (broadcastHeight <= 0) return false;
  return currentLocalSyncHeight(state) > broadcastHeight;
}

function collectReservedOutpointsFromQueue(state, options = {}) {
  const skipChangeId = String(options.skipChangeId || '').trim();
  const reserved = new Set();
  for (const outpoint of walletTxDomain.listReservedOutpointsSync()) {
    const safe = String(outpoint || '').trim().toLowerCase();
    if (safe) reserved.add(safe);
  }
  const queue = Array.isArray(state?.localChanges?.queue) ? state.localChanges.queue : [];
  for (const item of queue) {
    const id = String(item?.id || '').trim();
    if (skipChangeId && id === skipChangeId) continue;
    const status = String(item?.status || '').trim().toLowerCase();
    if (!['broadcasted', 'anchored'].includes(status)) continue;
    const rawtx = String(item?.rawtx || '').trim();
    if (!rawtx || typeof wallet.inspectRawTx !== 'function') continue;
    const info = wallet.inspectRawTx(rawtx);
    for (const outpoint of (Array.isArray(info?.inputOutpoints) ? info.inputOutpoints : [])) {
      const safe = String(outpoint || '').trim().toLowerCase();
      if (safe) reserved.add(safe);
    }
  }
  return reserved;
}

function collectOrderLinkedOutpointsForAnchorExclusion(state, options = {}) {
  const allowed = new Set((Array.isArray(options.allowOutpoints) ? options.allowOutpoints : [])
    .map((value) => String(value || '').trim().toLowerCase())
    .filter(Boolean));
  const currentOrderId = String(options.currentOrderId || '').trim();
  const reserved = new Set();
  const currentOrderTxids = new Set();
  const addOutpoint = (txid, vout) => {
    const safeTxid = String(txid || '').trim().toLowerCase();
    const safeVout = Number(vout || 0);
    if (!/^[0-9a-f]{64}$/.test(safeTxid) || !Number.isFinite(safeVout) || safeVout < 0) return;
    const outpoint = `${safeTxid}:${safeVout}`;
    if (!allowed.has(outpoint)) reserved.add(outpoint);
  };
  const addTxOutputs = (txid, limit = 12) => {
    const safeTxid = String(txid || '').trim().toLowerCase();
    if (!/^[0-9a-f]{64}$/.test(safeTxid)) return;
    const ctx = typeof wallet.getTxContextByTxid === 'function' ? wallet.getTxContextByTxid(safeTxid) : null;
    const rawtx = String(ctx?.rawtx || ctx?.rawtx_hex || '').trim();
    if (!rawtx || !bsv || typeof bsv.Transaction !== 'function') return;
    try {
      const tx = new bsv.Transaction(rawtx);
      const outputs = Array.isArray(tx.outputs) ? tx.outputs : [];
      const count = Math.min(outputs.length, Math.max(0, Number(limit || outputs.length)));
      for (let vout = 0; vout < count; vout += 1) {
        const outpoint = `${safeTxid}:${vout}`;
        if (!allowed.has(outpoint)) reserved.add(outpoint);
      }
    } catch (_) {}
  };
  for (const order of (Array.isArray(state?.orders) ? state.orders : [])) {
    const chain = order?.chain && typeof order.chain === 'object' ? order.chain : {};
    const orderTxids = [
      chain.placeTxid,
      chain.buyerLockTxid,
      chain.sellerLockTxid,
      chain.sellerSettlementFeeTxid,
      chain.shipTxid,
      chain.settleTxid,
      chain.completedSettlementTxid,
      chain.refundSettlementTxid,
      chain.refundRequestTxid,
      chain.cancelTxid,
    ];
    const orderId = String(order?.id || '').trim();
    if (currentOrderId && orderId === currentOrderId) {
      for (const txid of orderTxids) {
        const safeTxid = String(txid || '').trim().toLowerCase();
        if (/^[0-9a-f]{64}$/.test(safeTxid)) currentOrderTxids.add(safeTxid);
      }
      addTxOutputs(chain.placeTxid || chain.buyerLockTxid);
      addTxOutputs(chain.sellerLockTxid);
      addOutpoint(chain.placeTxid || chain.buyerLockTxid, Number(chain.buyerLockVout || 0));
      addOutpoint(chain.sellerLockTxid, Number(chain.sellerLockVout || 0));
      addOutpoint(chain.sellerSettlementFeeTxid || chain.sellerLockTxid, Number(chain.sellerSettlementFeeVout || 0));
      continue;
    }
    for (const txid of orderTxids) {
      addTxOutputs(txid);
    }
  }
  if (typeof wallet.listTxContexts === 'function') {
    for (const row of wallet.listTxContexts({ order: 'recent', limit: 3000 })) {
      const kind = String(row?.kind || '').trim();
      const source = String(row?.source || '').trim();
      if (!/^order_/i.test(kind) && !/^order_/i.test(source)) continue;
      const txid = String(row?.txid || '').trim().toLowerCase();
      if (currentOrderTxids.has(txid)) continue;
      addTxOutputs(row?.txid);
    }
  }
  return Array.from(reserved);
}

function deriveSellerShipAnchorFeeOutpoints(orderLike, mnemonic = '', options = {}) {
  const order = migrateOrderModel(orderLike || {});
  const chain = order?.chain && typeof order.chain === 'object' ? order.chain : {};
  const excluded = new Set((Array.isArray(options.excludeOutpoints) ? options.excludeOutpoints : [])
    .map((value) => String(value || '').trim().toLowerCase())
    .filter(Boolean));
  const lockOutpoint = `${String(chain.sellerLockTxid || '').trim().toLowerCase()}:${Number(chain.sellerLockVout || 0)}`;
  const settlementOutpoint = `${String(chain.sellerSettlementFeeTxid || chain.sellerLockTxid || '').trim().toLowerCase()}:${Number(chain.sellerSettlementFeeVout || 0)}`;
  const directTxid = String(chain.sellerShipAnchorFeeTxid || '').trim().toLowerCase();
  const directVout = Number(chain.sellerShipAnchorFeeVout || 0);
  const directOutpoint = `${directTxid}:${directVout}`;
  if (
    /^[0-9a-f]{64}$/.test(directTxid)
    && Number.isInteger(directVout)
    && directVout >= 0
    && Number(chain.sellerShipAnchorFeeSats || 0) > 0
    && directOutpoint !== lockOutpoint
    && directOutpoint !== settlementOutpoint
    && !excluded.has(directOutpoint)
  ) {
    return [directOutpoint];
  }
  const sellerLockTxid = String(chain.sellerLockTxid || '').trim().toLowerCase();
  if (!/^[0-9a-f]{64}$/.test(sellerLockTxid)) return [];
  const ctx = typeof wallet.getTxContextByTxid === 'function' ? wallet.getTxContextByTxid(sellerLockTxid) : null;
  const rawtx = String(ctx?.rawtx || ctx?.rawtx_hex || '').trim();
  if (!rawtx || !bsv || typeof bsv.Transaction !== 'function') return [];
  let receiveAddress = String(chain.sellerReceiveAddress || chain.sellerRefundAddress || '').trim();
  if (!receiveAddress && mnemonic && typeof wallet.getReceiveAddress === 'function') {
    try { receiveAddress = String(wallet.getReceiveAddress() || '').trim(); } catch (_) {}
  }
  const excludedVouts = new Set([
    Number(chain.sellerLockVout || 0),
    Number(chain.sellerSettlementFeeVout || 0),
  ]);
  try {
    const tx = new bsv.Transaction(rawtx);
    const candidates = [];
    const outputs = Array.isArray(tx.outputs) ? tx.outputs : [];
    for (let vout = 0; vout < outputs.length; vout += 1) {
      if (excludedVouts.has(vout)) continue;
      const output = outputs[vout];
      const satoshis = Number(output?.satoshis || 0);
      if (!(satoshis >= 1000)) continue;
      const outpoint = `${sellerLockTxid}:${vout}`;
      if (excluded.has(outpoint)) continue;
      let address = '';
      try { address = String(output?.script?.toAddress?.(wallet.NETWORK) || '').trim(); } catch (_) {}
      if (receiveAddress && address !== receiveAddress) continue;
      const scriptHex = String(output?.script?.toHex?.() || '').trim().toLowerCase();
      let p2pkhHex = '';
      try { p2pkhHex = String(bsv.Script.buildPublicKeyHashOut(address).toHex() || '').trim().toLowerCase(); } catch (_) {}
      if (!p2pkhHex || scriptHex !== p2pkhHex) continue;
      candidates.push({ outpoint, satoshis });
    }
    candidates.sort((a, b) => Number(b.satoshis || 0) - Number(a.satoshis || 0));
    return candidates.map((row) => row.outpoint);
  } catch (_) {
    return [];
  }
}

async function reserveWalletTxInputs(reservationId, reservationType, rawtx, options = {}) {
  const safeRawtx = String(rawtx || '').trim();
  if (!safeRawtx || typeof wallet.inspectRawTx !== 'function') return false;
  const info = wallet.inspectRawTx(safeRawtx);
  const outpoints = Array.isArray(info?.inputOutpoints)
    ? info.inputOutpoints.map((item) => String(item || '').trim().toLowerCase()).filter(Boolean)
    : [];
  if (outpoints.length <= 0) return false;
  await walletTxDomain.reserveOutpoints(reservationId, reservationType, outpoints, {
    ownerId: String(options.ownerId || '').trim(),
    txid: String(options.txid || info?.txid || '').trim().toLowerCase(),
    producer: String(options.producer || 'server_market.wallet_tx_reserve'),
    dedupeKey: String(options.dedupeKey || '').trim(),
  });
  return true;
}

function rebuildWalletIndexFromLiveQueue(state) {
  const queue = Array.isArray(state?.localChanges?.queue) ? state.localChanges.queue : [];
  const keepRawTxs = queue
    .filter((q) => ['broadcasted', 'anchored'].includes(String(q?.status || '').trim().toLowerCase()))
    .sort((a, b) => Number(a?.seq || 0) - Number(b?.seq || 0))
    .map((q) => String(q?.rawtx || '').trim())
    .filter(Boolean);
  appendMarketDebug('wallet_queue_rebuild_skipped_policy', {
    source: 'rebuild_wallet_index_from_live_queue',
    keepRawTxCount: keepRawTxs.length,
    policy: 'manual_recovery_only',
  });
}

function dropRecentRawtxByTxid(state, txid) {
  const safeTxid = String(txid || '').trim().toLowerCase();
  if (!safeTxid || !Array.isArray(state?.recentRawtxs)) return 0;
  const before = state.recentRawtxs.length;
  state.recentRawtxs = state.recentRawtxs.filter((row) => String(row?.txid || '').trim().toLowerCase() !== safeTxid);
  return Math.max(0, before - state.recentRawtxs.length);
}

function dropConfirmedRecentRawtxs(state, txidSet) {
  const txids = txidSet instanceof Set ? txidSet : new Set();
  if (!txids.size || !Array.isArray(state?.recentRawtxs)) return 0;
  let dropped = 0;
  for (const txid of txids) {
    dropped += dropRecentRawtxByTxid(state, txid);
  }
  return dropped;
}

function dropRecentRawtxsByTxids(state, txidSet, options = {}) {
  const txids = txidSet instanceof Set ? txidSet : new Set();
  if (!txids.size || !Array.isArray(state?.recentRawtxs)) return 0;
  const dropped = dropConfirmedRecentRawtxs(state, txids);
  if (dropped > 0 && options.persist !== false) {
    commitLocalState(state, {
      immediate: true,
      writeJson: true,
      refresh: true,
      reason: String(options.reason || 'recent_rawtx_drop_by_txids'),
    });
  }
  return dropped;
}

function normalizeTxidSet(txids) {
  const values = txids instanceof Set
    ? Array.from(txids)
    : Array.isArray(txids)
    ? txids
    : [txids];
  return new Set(values
    .map((txid) => String(txid || '').trim().toLowerCase())
    .filter((txid) => /^[0-9a-f]{64}$/i.test(txid)));
}

function handleConfirmedTxidsForLocalState(state, txids, options = {}) {
  const confirmedTxids = normalizeTxidSet(txids);
  if (!confirmedTxids.size) {
    return {
      txids: [],
      markedAnchors: 0,
      markedQueue: 0,
      walletConfirmed: 0,
      droppedRecentRawtxs: 0,
    };
  }
  const source = String(options.source || 'confirmed_txids_local_event').trim() || 'confirmed_txids_local_event';
  const markedAnchors = options.markAnchors === false ? 0 : markAnchorsConfirmedByTxid(state, confirmedTxids);
  const markedQueue = options.markQueue === false ? 0 : markLocalQueueConfirmedByTxid(state, confirmedTxids);
  let walletConfirmed = 0;
  if (options.confirmWallet !== false && typeof wallet.confirmWalletTransaction === 'function') {
    for (const txid of confirmedTxids) {
      try {
        const changed = wallet.confirmWalletTransaction(txid, {
          source,
          allowCreateFromRawtx: false,
        });
        if (changed) walletConfirmed += 1;
      } catch (err) {
        appendMarketDebug('confirmed_txid_wallet_confirm_failed', {
          source,
          txid,
          message: String(err?.message || 'wallet confirm failed'),
        });
      }
    }
  }
  const droppedRecentRawtxs = dropConfirmedRecentRawtxs(state, confirmedTxids);
  if ((markedAnchors > 0 || markedQueue > 0 || droppedRecentRawtxs > 0) && options.persist === true) {
    commitLocalState(state, {
      immediate: options.immediate !== false,
      writeJson: true,
      refresh: options.refresh === true,
      reason: String(options.reason || `${source}_confirmed_txids_cleanup`),
    });
  }
  if (markedAnchors > 0 || markedQueue > 0 || walletConfirmed > 0 || droppedRecentRawtxs > 0) {
    appendMarketDebug('confirmed_txids_local_event', {
      source,
      txids: Array.from(confirmedTxids),
      markedAnchors,
      markedQueue,
      walletConfirmed,
      droppedRecentRawtxs,
    });
  }
  return {
    txids: Array.from(confirmedTxids),
    markedAnchors,
    markedQueue,
    walletConfirmed,
    droppedRecentRawtxs,
  };
}

function reconcileRecentRawtxConfirmationState(state, options = {}) {
  const recentRawtxs = Array.isArray(state?.recentRawtxs) ? state.recentRawtxs : [];
  if (!recentRawtxs.length) return { dropped: 0, confirmedTxids: [] };
  const confirmedTxids = new Set();
  const staleTxids = new Set();
  const queue = Array.isArray(state?.localChanges?.queue) ? state.localChanges.queue : [];
  const pendingAnchorTxids = new Set(
    getPendingAnchorOverlay(state)
      .map((row) => String(row?.txid || '').trim().toLowerCase())
      .filter((txid) => /^[0-9a-f]{64}$/i.test(txid)),
  );
  const staleRetentionMs = Math.max(60 * 60 * 1000, Number(process.env.BSV_MARKET_STALE_RECENT_RAWTX_MS || (6 * 60 * 60 * 1000)));
  for (const row of recentRawtxs) {
    const txid = String(row?.txid || '').trim().toLowerCase();
    if (!/^[0-9a-f]{64}$/i.test(txid)) continue;
    if (wallet.isTxConfirmedInSpvIndex?.(txid)) {
      confirmedTxids.add(txid);
      continue;
    }
    const anchorRows = loadAnchorEventsFromSqlite({
      txid,
      limit: 1,
    });
    const confirmedAnchor = anchorRows.some((anchor) => anchor?.confirmed === true);
    if (confirmedAnchor) confirmedTxids.add(txid);
    if (confirmedAnchor) continue;
    const queueTracked = queue.some((item) => {
      const itemTxid = String(item?.txid || '').trim().toLowerCase();
      const status = String(item?.status || '').trim().toLowerCase();
      return itemTxid === txid && ['pending', 'queued', 'broadcasted', 'anchored'].includes(status);
    });
    const hasAnchorTrace = anchorRows.length > 0 || pendingAnchorTxids.has(txid);
    const ageMs = Math.max(0, Date.now() - (Date.parse(String(row?.ts || row?.updatedAt || '')) || 0));
    if (!queueTracked && !hasAnchorTrace && ageMs >= staleRetentionMs) {
      staleTxids.add(txid);
    }
  }
  if (!confirmedTxids.size && !staleTxids.size) return { dropped: 0, confirmedTxids: [] };
  const confirmedCleanup = handleConfirmedTxidsForLocalState(state, confirmedTxids, {
    source: String(options.source || 'reconcile_recent_rawtx_confirmation_state'),
    markAnchors: false,
    markQueue: false,
    persist: false,
  });
  const staleDropped = dropConfirmedRecentRawtxs(state, staleTxids);
  const dropped = Number(confirmedCleanup.droppedRecentRawtxs || 0) + staleDropped;
  if (dropped > 0 && options.persist !== false) {
    commitLocalState(state, {
      immediate: true,
      writeJson: true,
      refresh: true,
      reason: String(options.reason || 'recent_rawtx_confirmed_cleanup'),
    });
  }
  if (dropped > 0) {
    appendMarketDebug('recent_rawtx_confirmed_cleanup', {
      source: String(options.source || 'reconcile_recent_rawtx_confirmation_state'),
      dropped,
      confirmedTxids: Array.from(confirmedTxids),
      staleTxids: Array.from(staleTxids),
    });
  }
  return {
    dropped,
    confirmedTxids: Array.from(confirmedTxids),
  };
}

function isMissingInputsBroadcastError(message = '') {
  const text = String(message || '').trim().toLowerCase();
  if (!text) return false;
  return text.includes('missing inputs')
    || text.includes('missing-inputs')
    || text.includes('bad-txns-inputs-missingorspent')
    || text.includes('txn-mempool-conflict');
}

let localChangePushWorkerPromise = null;
let queuedPushPassword = '';

function isLocalChangeQueueBlockedError(message) {
  const text = String(message || '').trim().toLowerCase();
  if (!text) return false;
  return text.includes('no local spv utxos found');
}

function markSyncedForSettledQueue(state) {
  const stillPending = (state.localChanges?.queue || []).filter((q) => q.status === 'pending' || q.status === 'queued' || q.status === 'broadcasted');
  const pendingKeys = new Set(stillPending.map((q) => `${q.targetType}|${q.targetId}`));
  state.products.forEach((p) => {
    if (!p.localStatus) return;
    if (!pendingKeys.has(`product|${p.id}`)) p.localStatus = 'synced';
  });
  state.categories.forEach((c) => {
    if (!c.localStatus) return;
    if (!pendingKeys.has(`category|${c.id}`)) c.localStatus = 'synced';
  });
  if (!pendingKeys.has('profile|buyer')) {
    state.profile.localStatus = 'synced';
    const buyer = state.users.find((u) => u.id === 'buyer');
    if (buyer) buyer.localStatus = 'synced';
  }
}

async function processLocalChangeQueueInBackground(reqLike = null, password = '') {
  const pwd = String(password || queuedPushPassword || '').trim();
  if (!pwd) return { started: false, reason: 'password_missing' };
  if (localChangePushWorkerPromise) return { started: false, reason: 'already_running' };
  queuedPushPassword = pwd;
  const loadQueueProjectionState = () => buildProjectionStateFromSqlite(reqLike);
  localChangePushWorkerPromise = withHotPathDebugAsync('processLocalChangeQueueInBackground', async () => {
    let processed = 0;
    let blocked = false;
    let lastError = '';
    const initialState = loadQueueProjectionState();
    rebuildPendingQueueFromLocalState(initialState);
    const initialTotal = getQueuedWorkQueueSorted(initialState, false).length;
    setLocalChangePushProgress({
      active: true,
      status: 'running',
      stage: 'push_queue_ready',
      currentLabel: 'queue',
      currentDetail: '',
      processed: 0,
      total: initialTotal,
      remaining: initialTotal,
      currentItem: null,
      lastError: '',
      startedAt: new Date().toISOString(),
      finishedAt: '',
    });
    appendMarketDebug('push_worker_start', {});
    while (true) {
      const state = loadQueueProjectionState();
      rebuildPendingQueueFromLocalState(state);
      const next = getQueuedWorkQueueSorted(state, false)[0];
      if (!next) {
        await reconcileBroadcastedLocalChanges(state);
        markSyncedForSettledQueue(state);
        await persistLocalStateSnapshotDirect(state, 'push_worker_done_queue');
        setLocalChangePushProgress({
          active: false,
          status: blocked ? 'failed' : 'done',
          stage: blocked ? 'push_failed' : 'push_done',
          currentLabel: blocked ? 'failed' : 'done',
          currentDetail: blocked ? lastError : '',
          processed,
          total: Math.max(processed, Number(getLocalChangePushProgress().total || 0)),
          remaining: 0,
          currentItem: null,
          lastError,
          finishedAt: new Date().toISOString(),
        });
        break;
      }

      const total = Math.max(processed + 1, Number(getLocalChangePushProgress().total || 0));
      setLocalChangePushProgress({
        active: true,
        status: 'running',
        stage: 'push_item_start',
        currentLabel: 'compose',
        currentDetail: `${String(next.eventType || '')} ${String(next.targetId || '')}`.trim(),
        processed,
        total,
        remaining: Math.max(1, total - processed),
        currentItem: {
          id: String(next.id || ''),
          eventType: String(next.eventType || ''),
          targetType: String(next.targetType || ''),
          targetId: String(next.targetId || ''),
        },
        lastError: '',
      });

      const anchor = await tryAnchorEvent(reqLike, state, next.eventType, next.payload || {}, {
        password: pwd,
        changeId: String(next.id || ''),
        updatedAt: String(next?.payload?._updatedAt || next.ts || ''),
        includeUnconfirmed: true,
        trackOutputs: true,
        onStage: (stage, extra = {}) => {
          const stageName = String(stage || '').trim();
          let currentLabel = 'compose';
          if (stageName === 'wallet_anchor_signed') currentLabel = 'sign';
          else if (stageName === 'wallet_anchor_broadcasted') currentLabel = 'broadcast';
          setLocalChangePushProgress({
            active: true,
            status: 'running',
            stage: stageName,
            currentLabel,
            currentDetail: String(extra?.txid || `${String(next.eventType || '')} ${String(next.targetId || '')}`.trim()),
            processed,
            total: Math.max(processed + 1, Number(getLocalChangePushProgress().total || 0)),
            remaining: Math.max(1, Number(getLocalChangePushProgress().remaining || 1)),
            currentItem: {
              id: String(next.id || ''),
              eventType: String(next.eventType || ''),
              targetType: String(next.targetType || ''),
              targetId: String(next.targetId || ''),
            },
            lastError: '',
          });
        },
      });

      if (anchor?.txid) {
        const broadcastHeight = currentLocalSyncHeight(state);
        next.status = 'broadcasted';
        next.txid = anchor.txid;
        next.broadcastedAt = new Date().toISOString();
        next.lastBroadcastAt = next.broadcastedAt;
        next.broadcastHeight = broadcastHeight;
        next.lastBroadcastHeight = broadcastHeight;
        next.feeSat = Number(anchor.feeSat || 0);
        next.rawtx = String(anchor.rawtx || '');
        next.broadcastNodes = Array.isArray(anchor.broadcastNodes) ? anchor.broadcastNodes.slice(0, 8) : [];
        next.broadcastSuccessCount = Number(anchor.broadcastSuccessCount || 0);
        next.broadcastAttemptedCount = Number(anchor.broadcastAttemptedCount || 0);
        next.rebroadcastCount = 0;
        delete next.lastError;
        delete next.failedAt;
        await reserveWalletTxInputs(
          String(next.id || '').trim(),
          'local_change',
          String(anchor.rawtx || ''),
          {
            ownerId: String(next.targetId || next.id || '').trim(),
            txid: String(anchor.txid || '').trim().toLowerCase(),
            producer: 'local_change_push',
            dedupeKey: `local_change:${String(next.id || '').trim()}:${String(anchor.txid || '').trim().toLowerCase()}`,
          },
        );
        appendMarketDebug('push_item_ok', {
          changeId: next.id,
          eventType: next.eventType,
          targetType: next.targetType,
          targetId: next.targetId,
          txid: next.txid,
          feeSat: next.feeSat,
          broadcastSuccessCount: next.broadcastSuccessCount,
          broadcastAttemptedCount: next.broadcastAttemptedCount,
        });
        await reconcileBroadcastedLocalChanges(state);
        markSyncedForSettledQueue(state);
        await persistLocalStateSnapshotDirect(state, 'push_item_ok_queue');
        processed += 1;
        setLocalChangePushProgress({
          active: true,
          status: 'running',
          stage: 'push_item_ok',
          currentLabel: 'broadcast',
          currentDetail: String(anchor.txid || ''),
          processed,
          total: Math.max(processed, Number(getLocalChangePushProgress().total || 0)),
          remaining: Math.max(0, Number(getLocalChangePushProgress().total || 0) - processed),
          currentItem: {
            id: String(next.id || ''),
            eventType: String(next.eventType || ''),
            targetType: String(next.targetType || ''),
            targetId: String(next.targetId || ''),
            txid: String(anchor.txid || ''),
          },
          lastError: '',
        });
        continue;
      }

      const errorMessage = String(anchor?.error || 'Anchor failed');
      next.status = 'queued';
      next.failedAt = new Date().toISOString();
      next.lastError = errorMessage;
      if (!isLocalChangeQueueBlockedError(errorMessage)) {
        next.attempts = Number(next.attempts || 0) + 1;
      }
      appendMarketDebug(isLocalChangeQueueBlockedError(errorMessage) ? 'push_item_waiting' : 'push_item_failed', {
        changeId: next.id,
        eventType: next.eventType,
        targetType: next.targetType,
        targetId: next.targetId,
        attempts: Number(next.attempts || 0),
        reason: errorMessage,
      });
      await reconcileBroadcastedLocalChanges(state);
      markSyncedForSettledQueue(state);
      await persistLocalStateSnapshotDirect(state, 'push_item_failed_queue');
      blocked = true;
      lastError = errorMessage;
      setLocalChangePushProgress({
        active: false,
        status: 'failed',
        stage: 'push_item_failed',
        currentLabel: 'failed',
        currentDetail: errorMessage,
        processed,
        total: Math.max(processed + 1, Number(getLocalChangePushProgress().total || 0)),
        remaining: Math.max(1, Number(getLocalChangePushProgress().total || 0) - processed),
        currentItem: {
          id: String(next.id || ''),
          eventType: String(next.eventType || ''),
          targetType: String(next.targetType || ''),
          targetId: String(next.targetId || ''),
        },
        lastError,
        finishedAt: new Date().toISOString(),
      });
      break;
    }
    const finalProgress = getLocalChangePushProgress();
    appendMarketDebug('push_worker_done', {
      processed,
      blocked,
      lastError: lastError || null,
      remaining: Number(finalProgress.remaining || 0),
    });
  });

  try {
    await localChangePushWorkerPromise;
  } finally {
    localChangePushWorkerPromise = null;
  }
  return { started: true };
}

function buildPendingPreview(state) {
  rebuildPendingQueueFromLocalState(state);
  const maxPayloadBytes = Number(wallet.MAX_ANCHOR_PAYLOAD_BYTES || 10000);
  const pendingQueue = (Array.isArray(state?.localChanges?.queue) ? state.localChanges.queue : [])
    .filter((q) => ['pending', 'queued'].includes(String(q?.status || '').trim().toLowerCase()))
    .slice()
    .sort((a, b) => {
      const ta = Date.parse(String(a?.ts || ''));
      const tb = Date.parse(String(b?.ts || ''));
      if (Number.isFinite(ta) && Number.isFinite(tb) && ta !== tb) return tb - ta;
      return Number(b?.seq || 0) - Number(a?.seq || 0);
    });
  const recoverableQueue = getBroadcastTrackingQueue(state)
    .filter((q) => isRecoverableLocalBroadcast(state, q))
    .sort((a, b) => {
      const ta = Date.parse(String(a?.broadcastedAt || a?.ts || ''));
      const tb = Date.parse(String(b?.broadcastedAt || b?.ts || ''));
      if (Number.isFinite(ta) && Number.isFinite(tb) && ta !== tb) return tb - ta;
      return Number(b?.seq || 0) - Number(a?.seq || 0);
    });
  let estimatedTotalFeeSat = 0;
  let oversizeCount = 0;
  const pendingDetails = pendingQueue
    .slice(0, 100)
    .map((q) => {
      const payloadForChain = withSchemaMeta(q.eventType, q.payload || {}, String(q?.payload?._updatedAt || q.ts || ''));
      const compact = buildAnchorWireText(q.eventType, payloadForChain);
      const payloadBytes = Buffer.byteLength(compact, 'utf8');
      const estimatedFeeSat = estimateAnchorFeeSat(payloadBytes);
      estimatedTotalFeeSat += estimatedFeeSat;
      const tooLarge = payloadBytes > maxPayloadBytes;
      if (tooLarge) oversizeCount += 1;
      return {
        id: q.id,
        seq: Number(q.seq || 0),
        eventType: String(q.eventType || ''),
        targetType: String(q.targetType || ''),
        targetId: String(q.targetId || ''),
        status: String(q.status || ''),
        ts: String(q.ts || ''),
        updatedAt: String(q?.payload?._updatedAt || q.ts || ''),
        schemaVersion: Number(q?.payload?._v || 0),
        attempts: Number(q.attempts || 0),
        estimatedFeeSat,
        payloadBytes,
        tooLarge,
        payload: q.payload || {},
      };
    });
  const recoverableDetails = recoverableQueue
    .slice(0, 100)
    .map((q) => ({
      id: q.id,
      seq: Number(q.seq || 0),
      eventType: String(q.eventType || ''),
      targetType: String(q.targetType || ''),
      targetId: String(q.targetId || ''),
      txid: String(q.txid || ''),
      status: String(q.status || ''),
      ts: String(q.ts || ''),
      broadcastedAt: String(q.broadcastedAt || q.lastBroadcastAt || q.ts || ''),
      broadcastHeight: Number(q.broadcastHeight || 0),
      lastBroadcastHeight: Number(q.lastBroadcastHeight || q.broadcastHeight || 0),
      currentHeight: currentLocalSyncHeight(state),
      attempts: Number(q.attempts || 0),
      rebroadcastCount: Number(q.rebroadcastCount || 0),
      lastError: String(q.lastError || ''),
      payload: q.payload || {},
    }));
  return {
    pendingUploads: pendingQueue.length,
    pendingDetails,
    recoverableDetails,
    estimatedTotalFeeSat,
    estimatedTotalFeeBsv: estimatedTotalFeeSat / 100000000,
    oversizeCount,
    maxPayloadBytes,
  };
}

function parseOpReturnDataFromAsm(asmLike) {
  const tokens = String(asmLike || '').trim().split(/\s+/).filter(Boolean);
  if (!tokens.length) return null;
  const opReturnIdx = tokens.findIndex((t) => String(t || '').toUpperCase() === 'OP_RETURN');
  if (opReturnIdx < 0) return null;
  const hexTokens = tokens
    .slice(opReturnIdx + 1)
    .filter((t) => /^[0-9a-fA-F]+$/.test(t) && t.length % 2 === 0);
  if (!hexTokens.length) return Buffer.alloc(0);
  try {
    return Buffer.from(hexTokens.join(''), 'hex');
  } catch (_) {
    return null;
  }
}

function parseOpReturnDataFromScriptBuffer(scriptBuf) {
  if (!Buffer.isBuffer(scriptBuf) || scriptBuf.length <= 0) return null;
  let i = 0;
  if (scriptBuf.length >= 2 && scriptBuf[0] === 0x00 && scriptBuf[1] === 0x6a) i = 1; // OP_FALSE OP_RETURN
  if (scriptBuf[i] !== 0x6a) return null; // OP_RETURN
  i += 1;
  const parts = [];
  while (i < scriptBuf.length) {
    const opcode = scriptBuf[i];
    i += 1;
    let pushLen = null;
    if (opcode >= 0x01 && opcode <= 0x4b) {
      pushLen = opcode;
    } else if (opcode === 0x00) {
      // OP_0: empty push, keep scanning subsequent pushes.
      pushLen = 0;
    } else if (opcode >= 0x51 && opcode <= 0x60) {
      // OP_1..OP_16: minimal integer push (single-byte value).
      parts.push(Buffer.from([opcode - 0x50]));
      continue;
    } else if (opcode === 0x4f) {
      // OP_1NEGATE
      parts.push(Buffer.from([0x81]));
      continue;
    } else if (opcode === 0x4c) {
      if (i + 1 > scriptBuf.length) break;
      pushLen = scriptBuf[i];
      i += 1;
    } else if (opcode === 0x4d) {
      if (i + 2 > scriptBuf.length) break;
      pushLen = scriptBuf.readUInt16LE(i);
      i += 2;
    } else if (opcode === 0x4e) {
      if (i + 4 > scriptBuf.length) break;
      pushLen = scriptBuf.readUInt32LE(i);
      i += 4;
    } else {
      // Non-push opcode after OP_RETURN, ignore remaining.
      break;
    }
    if (!Number.isFinite(pushLen) || pushLen < 0) break;
    if ((i + pushLen) > scriptBuf.length) break;
    if (pushLen > 0) parts.push(scriptBuf.slice(i, i + pushLen));
    i += pushLen;
  }
  return parts.length ? Buffer.concat(parts) : Buffer.alloc(0);
}

function parseOpReturnPushBuffersFromScriptBuffer(scriptBuf) {
  if (!Buffer.isBuffer(scriptBuf) || scriptBuf.length <= 0) return null;
  let i = 0;
  if (scriptBuf.length >= 2 && scriptBuf[0] === 0x00 && scriptBuf[1] === 0x6a) i = 1; // OP_FALSE OP_RETURN
  if (scriptBuf[i] !== 0x6a) return null; // OP_RETURN
  i += 1;
  const parts = [];
  while (i < scriptBuf.length) {
    const opcode = scriptBuf[i];
    i += 1;
    let pushLen = null;
    if (opcode >= 0x01 && opcode <= 0x4b) {
      pushLen = opcode;
    } else if (opcode === 0x00) {
      // OP_0: empty push, keep scanning subsequent pushes.
      pushLen = 0;
    } else if (opcode >= 0x51 && opcode <= 0x60) {
      // OP_1..OP_16: minimal integer push (single-byte value).
      parts.push(Buffer.from([opcode - 0x50]));
      continue;
    } else if (opcode === 0x4f) {
      // OP_1NEGATE
      parts.push(Buffer.from([0x81]));
      continue;
    } else if (opcode === 0x4c) {
      if (i + 1 > scriptBuf.length) break;
      pushLen = scriptBuf[i];
      i += 1;
    } else if (opcode === 0x4d) {
      if (i + 2 > scriptBuf.length) break;
      pushLen = scriptBuf.readUInt16LE(i);
      i += 2;
    } else if (opcode === 0x4e) {
      if (i + 4 > scriptBuf.length) break;
      pushLen = scriptBuf.readUInt32LE(i);
      i += 4;
    } else {
      break;
    }
    if (!Number.isFinite(pushLen) || pushLen < 0) break;
    if ((i + pushLen) > scriptBuf.length) break;
    parts.push(scriptBuf.slice(i, i + pushLen));
    i += pushLen;
  }
  return parts;
}

function normalizeP2POutput(outputLike) {
  if (!outputLike) return null;
  if (Array.isArray(outputLike)) {
    // bsv-p2p can expose outputs as [index, output] tuples in some builds.
    for (const item of outputLike) {
      if (item && typeof item === 'object' && (item.script || item.scriptPubKey || item._script || item._scriptBuffer)) {
        return item;
      }
    }
    return outputLike[1] || outputLike[0] || null;
  }
  if (typeof outputLike === 'object') {
    if (outputLike.output && typeof outputLike.output === 'object') return outputLike.output;
    return outputLike;
  }
  return null;
}

function toBufferLike(input) {
  if (!input) return null;
  if (Buffer.isBuffer(input)) return input;
  if (input instanceof Uint8Array) return Buffer.from(input);
  if (Array.isArray(input) && input.every((x) => Number.isInteger(x) && x >= 0 && x <= 255)) {
    return Buffer.from(input);
  }
  if (typeof input === 'string') {
    const s = String(input || '').trim();
    if (/^[0-9a-fA-F]+$/.test(s) && s.length % 2 === 0) {
      try {
        return Buffer.from(s, 'hex');
      } catch (_) {}
    }
  }
  return null;
}

function getScriptCandidatesFromOutput(outputLike) {
  const out = normalizeP2POutput(outputLike);
  if (!out) return [];
  const directCandidates = [
    out?.script,
    out?.scriptPubKey,
    out?._script,
    out?._scriptBuffer,
    out?.scriptBuffer,
    out?.lockingScript,
    out?.pkScript,
  ].filter((x) => x !== undefined && x !== null);
  const nestedCandidates = [];
  directCandidates.forEach((c) => {
    if (!c || typeof c !== 'object') return;
    nestedCandidates.push(
      c?.buffer,
      c?._buffer,
      c?.buf,
      c?.raw,
      c?.script,
      c?.scriptBuffer,
      c?._script,
      c?._scriptBuffer,
      c?.hex,
    );
  });
  return [...directCandidates, ...nestedCandidates].filter((x) => x !== undefined && x !== null);
}

function hasDefinitelyNoOpReturnInScriptCandidate(scriptLike) {
  try {
    const buf = toBufferLike(scriptLike);
    if (Buffer.isBuffer(buf) && buf.length > 0) {
      if (buf[0] === 0x6a) return false;
      if (buf.length >= 2 && buf[0] === 0x00 && buf[1] === 0x6a) return false;
      return true;
    }
  } catch (_) {}
  try {
    if (typeof scriptLike?.toBuffer === 'function') {
      const buf = toBufferLike(scriptLike.toBuffer());
      if (Buffer.isBuffer(buf) && buf.length > 0) {
        if (buf[0] === 0x6a) return false;
        if (buf.length >= 2 && buf[0] === 0x00 && buf[1] === 0x6a) return false;
        return true;
      }
    }
  } catch (_) {}
  try {
    if (typeof scriptLike?.toASM === 'function') {
      const asm = String(scriptLike.toASM() || '').trim();
      if (!asm) return null;
      return !/^OP_FALSE\s+OP_RETURN\b|^OP_RETURN\b/i.test(asm);
    }
  } catch (_) {}
  try {
    const asm = String(scriptLike?.asm || '').trim();
    if (asm) return !/^OP_FALSE\s+OP_RETURN\b|^OP_RETURN\b/i.test(asm);
  } catch (_) {}
  try {
    const chunks = Array.isArray(scriptLike?.chunks) ? scriptLike.chunks : [];
    if (chunks.length > 0) {
      const first = Number(chunks?.[0]?.opcodenum);
      const second = Number(chunks?.[1]?.opcodenum);
      if (first === 106 || (first === 0 && second === 106)) return false;
      return true;
    }
  } catch (_) {}
  return null;
}

function outputMayContainOpReturn(outputLike) {
  const out = normalizeP2POutput(outputLike);
  if (!out) return false;
  const candidates = getScriptCandidatesFromOutput(out);
  if (candidates.length <= 0) return true;
  let sawUnknown = false;
  for (const candidate of candidates) {
    const definitelyNoOpReturn = hasDefinitelyNoOpReturnInScriptCandidate(candidate);
    if (definitelyNoOpReturn === false) return true;
    if (definitelyNoOpReturn === null) sawUnknown = true;
  }
  return sawUnknown;
}

function getOpReturnPushBuffersFromOutput(outputLike) {
  const out = normalizeP2POutput(outputLike);
  if (!out) return null;
  const candidates = getScriptCandidatesFromOutput(out);
  for (const script of candidates) {
    try {
      const directBuf = toBufferLike(script);
      if (Buffer.isBuffer(directBuf)) {
        const parsed = parseOpReturnPushBuffersFromScriptBuffer(directBuf);
        if (Array.isArray(parsed)) return parsed;
      }
    } catch (_) {}
    try {
      if (typeof script?.toBuffer === 'function') {
        const sb = toBufferLike(script.toBuffer());
        if (Buffer.isBuffer(sb)) {
          const parsed = parseOpReturnPushBuffersFromScriptBuffer(sb);
          if (Array.isArray(parsed)) return parsed;
        }
      }
    } catch (_) {}
    try {
      if (typeof script?.toHex === 'function') {
        const sh = String(script.toHex() || '');
        if (/^[0-9a-fA-F]+$/.test(sh) && sh.length % 2 === 0) {
          const parsed = parseOpReturnPushBuffersFromScriptBuffer(Buffer.from(sh, 'hex'));
          if (Array.isArray(parsed)) return parsed;
        }
      }
    } catch (_) {}
    try {
      const chunks = Array.isArray(script?.chunks) ? script.chunks : [];
      if (chunks.length > 0) {
        const opReturnIdx = chunks.findIndex((c) => Number(c?.opcodenum) === 106);
        if (opReturnIdx >= 0) {
          const buffers = [];
          for (const c of chunks.slice(opReturnIdx + 1)) {
            const b = toBufferLike(c?.buf || c?.buffer || c?.data || null);
            if (Buffer.isBuffer(b)) buffers.push(b);
          }
          return buffers;
        }
      }
    } catch (_) {}
  }
  return null;
}

function getOpReturnDataBufferFromOutput(outputLike) {
  const out = normalizeP2POutput(outputLike);
  if (!out) return null;
  const candidates = getScriptCandidatesFromOutput(out);
  for (const script of candidates) {
    try {
      const directBuf = toBufferLike(script);
      if (Buffer.isBuffer(directBuf)) {
        const parsed = parseOpReturnDataFromScriptBuffer(directBuf);
        if (Buffer.isBuffer(parsed)) return parsed;
      }
    } catch (_) {}
    try {
      if (typeof script?.toBuffer === 'function') {
        const sb = toBufferLike(script.toBuffer());
        if (Buffer.isBuffer(sb)) {
          const parsed = parseOpReturnDataFromScriptBuffer(sb);
          if (Buffer.isBuffer(parsed)) return parsed;
        }
      }
    } catch (_) {}
    try {
      if (typeof script?.toHex === 'function') {
        const sh = String(script.toHex() || '');
        if (/^[0-9a-fA-F]+$/.test(sh) && sh.length % 2 === 0) {
          const parsed = parseOpReturnDataFromScriptBuffer(Buffer.from(sh, 'hex'));
          if (Buffer.isBuffer(parsed)) return parsed;
        }
      }
    } catch (_) {}
    try {
      const chunks = Array.isArray(script?.chunks) ? script.chunks : [];
      if (chunks.length > 0) {
        const opReturnIdx = chunks.findIndex((c) => Number(c?.opcodenum) === 106);
        if (opReturnIdx >= 0) {
          const buffers = [];
          for (const c of chunks.slice(opReturnIdx + 1)) {
            const b = toBufferLike(c?.buf || c?.buffer || c?.data || null);
            if (Buffer.isBuffer(b) && b.length > 0) buffers.push(b);
          }
          return buffers.length ? Buffer.concat(buffers) : Buffer.alloc(0);
        }
      }
    } catch (_) {}
    try {
      const asm = String(script?.toASM?.() || script?.asm || '');
      const parsed = parseOpReturnDataFromAsm(asm);
      if (Buffer.isBuffer(parsed)) return parsed;
    } catch (_) {}
  }
  try {
    const asmFallback = String(out?.scriptPubKey?.asm || out?.asm || '');
    return parseOpReturnDataFromAsm(asmFallback);
  } catch (_) {}
  return null;
}

function decodeUtf8Safe(bufLike) {
  if (!Buffer.isBuffer(bufLike) || bufLike.length <= 0) return '';
  try {
    return bufLike.toString('utf8');
  } catch (_) {
    return '';
  }
}

function firstAcceptedChainMarkerInText(textLike) {
  const text = String(textLike || '');
  return text.includes(CHAIN_MARKER_PREFIX) ? CHAIN_MARKER : '';
}

function tryParseAnchorTextLoose(textLike) {
  const text = String(textLike || '');
  if (!text) return null;
  const compact = text.replace(/\u0000+/g, '').trim();
  const idx = compact.indexOf(CHAIN_MARKER_PREFIX);
  const candidate = idx >= 0 ? compact.slice(idx) : '';
  if (!candidate) return null;
  const direct = parseAnchorPayloadText(candidate);
  if (direct) return { parsed: direct, usedText: candidate };

  const firstBar = candidate.indexOf('|');
  const secondBar = firstBar >= 0 ? candidate.indexOf('|', firstBar + 1) : -1;
  const jsonStart = secondBar >= 0 ? candidate.indexOf('{', secondBar + 1) : -1;
  if (jsonStart < 0) return null;

  let depth = 0;
  let inStr = false;
  let esc = false;
  for (let i = jsonStart; i < candidate.length; i += 1) {
    const ch = candidate[i];
    if (inStr) {
      if (esc) {
        esc = false;
      } else if (ch === '\\') {
        esc = true;
      } else if (ch === '"') {
        inStr = false;
      }
      continue;
    }
    if (ch === '"') {
      inStr = true;
      continue;
    }
    if (ch === '{') depth += 1;
    else if (ch === '}') {
      depth -= 1;
      if (depth === 0) {
        const rebuilt = `${candidate.slice(0, jsonStart)}${candidate.slice(jsonStart, i + 1)}`;
        const parsed = parseAnchorPayloadText(rebuilt);
        if (parsed) return { parsed, usedText: rebuilt };
        break;
      }
    }
  }
  return null;
}

function tryParseAnchorPushBuffersFast(pushBuffers) {
  const bufs = Array.isArray(pushBuffers) ? pushBuffers.filter((buf) => Buffer.isBuffer(buf) && buf.length > 0) : [];
  if (!bufs.length) return null;
  for (const buf of bufs) {
    if (!buf.includes(CHAIN_MARKER_PREFIX_BUF)) continue;
    const text = decodeUtf8Safe(buf);
    const matched = tryParseAnchorTextLoose(text);
    if (matched?.parsed) return matched;
  }
  if (bufs.length === 1) return null;
  try {
    const joined = Buffer.concat(bufs);
    if (!joined.includes(CHAIN_MARKER_PREFIX_BUF)) return null;
    return tryParseAnchorTextLoose(decodeUtf8Safe(joined));
  } catch (_) {
    return null;
  }
}

function parseAnchorFromPushBuffers(pushBuffers, opReturnBuf = null) {
  const pushHexPrefixes = Array.isArray(pushBuffers)
    ? pushBuffers
      .slice(0, 4)
      .map((b) => (Buffer.isBuffer(b) ? b.toString('hex').slice(0, 80) : ''))
      .filter(Boolean)
    : [];
  const effectiveOpReturnBuf = Buffer.isBuffer(opReturnBuf)
    ? opReturnBuf
    : (() => {
      try {
        return Array.isArray(pushBuffers) ? Buffer.concat(pushBuffers.filter((b) => Buffer.isBuffer(b))) : null;
      } catch (_) {
        return null;
      }
    })();
  const opReturnHexPrefix = Buffer.isBuffer(effectiveOpReturnBuf)
    ? effectiveOpReturnBuf.toString('hex').slice(0, 160)
    : '';
  const fastMatched = tryParseAnchorPushBuffersFast(pushBuffers);
  if (fastMatched?.parsed) {
    return {
      parsed: fastMatched.parsed,
      usedText: String(fastMatched.usedText || ''),
      pushCount: Array.isArray(pushBuffers) ? pushBuffers.length : 0,
      fastPath: true,
    };
  }
  const candidateTexts = [];
  if (Array.isArray(pushBuffers)) {
    pushBuffers.forEach((b) => {
      const t = decodeUtf8Safe(b);
      if (t) candidateTexts.push(t);
    });
    if (pushBuffers.length > 0) {
      const joined = decodeUtf8Safe(Buffer.concat(pushBuffers));
      if (joined) candidateTexts.push(joined);
      const withPipe = pushBuffers.map((b) => decodeUtf8Safe(b)).filter(Boolean).join('|');
      if (withPipe) candidateTexts.push(withPipe);
    }
  } else {
    const text = Buffer.isBuffer(effectiveOpReturnBuf)
      ? decodeUtf8Safe(effectiveOpReturnBuf)
      : '';
    if (text) candidateTexts.push(text);
  }
  const seen = new Set();
  for (const c of candidateTexts) {
    const key = String(c || '').slice(0, 512);
    if (!key || seen.has(key)) continue;
    seen.add(key);
    const matched = tryParseAnchorTextLoose(c);
    if (matched?.parsed) {
      return {
        parsed: matched.parsed,
        usedText: String(matched.usedText || ''),
        pushCount: Array.isArray(pushBuffers) ? pushBuffers.length : 0,
      };
    }
  }
  return {
    parsed: null,
    pushCount: Array.isArray(pushBuffers) ? pushBuffers.length : 0,
    candidateCount: candidateTexts.length,
    sampleCandidate: candidateTexts.length ? String(candidateTexts[0]).slice(0, 220) : '',
    pushHexPrefixes,
    opReturnHexPrefix,
  };
}

function parseAnchorFromOutput(outputLike) {
  const pushBuffers = getOpReturnPushBuffersFromOutput(outputLike);
  return parseAnchorFromPushBuffers(pushBuffers, getOpReturnDataBufferFromOutput(outputLike));
}

function decodeOpReturnOutputToText(outputLike) {
  const buf = getOpReturnDataBufferFromOutput(outputLike);
  if (!Buffer.isBuffer(buf) || buf.length <= 0) return '';
  try {
    return buf.toString('utf8');
  } catch (_) {
    return '';
  }
}

function describeOutputShape(outputLike) {
  const out = normalizeP2POutput(outputLike);
  if (!out || typeof out !== 'object') return { type: typeof out, keys: [] };
  const keys = Object.keys(out).slice(0, 16);
  const scriptKeys = ['script', 'scriptPubKey', '_script', '_scriptBuffer', 'scriptBuffer', 'lockingScript', 'pkScript']
    .filter((k) => out[k] !== undefined);
  const scriptTypes = scriptKeys.map((k) => {
    const v = out[k];
    if (Buffer.isBuffer(v) || (v instanceof Uint8Array)) return `${k}:buffer`;
    if (v && typeof v === 'object') return `${k}:object`;
    return `${k}:${typeof v}`;
  });
  return { type: typeof out, keys, scriptTypes };
}

function getOutputScriptHex(outputLike) {
  const out = normalizeP2POutput(outputLike);
  if (!out) return '';
  const candidates = getScriptCandidatesFromOutput(out);
  for (const script of candidates) {
    try {
      const b = toBufferLike(script);
      if (Buffer.isBuffer(b) && b.length > 0) return b.toString('hex');
    } catch (_) {}
    try {
      if (typeof script?.toBuffer === 'function') {
        const b = toBufferLike(script.toBuffer());
        if (Buffer.isBuffer(b) && b.length > 0) return b.toString('hex');
      }
    } catch (_) {}
    try {
      if (typeof script?.toHex === 'function') {
        const h = String(script.toHex() || '').trim();
        if (/^[0-9a-fA-F]+$/.test(h) && h.length > 0) return h.toLowerCase();
      }
    } catch (_) {}
  }
  return '';
}

function isSystemDefinedOpReturn({ text = '', opReturnBuf = null, asm = '' } = {}) {
  const t = String(text || '');
  if (firstAcceptedChainMarkerInText(t)) return true;
  if (Buffer.isBuffer(opReturnBuf) && opReturnBuf.length > 0) {
    if (opReturnBuf.includes(CHAIN_MARKER_PREFIX_BUF)) return true;
    if (CHAIN_MARKER_BUFS.some((buf) => opReturnBuf.includes(buf))) return true;
    const hex = opReturnBuf.toString('hex').toLowerCase();
    if (hex.includes(CHAIN_MARKER_PREFIX_HEX)) return true;
    if (CHAIN_MARKER_HEXES.some((markerHex) => hex.includes(markerHex))) return true;
  }
  const rawAsm = String(asm || '');
  if (rawAsm.includes(CHAIN_MARKER_PREFIX) || rawAsm.includes(CHAIN_MARKER)) return true;
  return false;
}

function loadChainSpoolState() {
  ensureMarketDataDir();
  if (chainSpoolStateCache && typeof chainSpoolStateCache === 'object') {
    return { ...chainSpoolStateCache };
  }
  if (!fs.existsSync(CHAIN_SPOOL_STATE_FILE)) {
    return {
      version: 1,
      records: 0,
      bytes: 0,
      lastWriteAt: '',
      lastHeight: 0,
    };
  }
  try {
    const parsed = JSON.parse(fs.readFileSync(CHAIN_SPOOL_STATE_FILE, 'utf8'));
    const normalized = {
      version: 1,
      records: Math.max(0, Number(parsed?.records || 0)),
      bytes: Math.max(0, Number(parsed?.bytes || 0)),
      lastWriteAt: String(parsed?.lastWriteAt || ''),
      lastHeight: Math.max(0, Number(parsed?.lastHeight || 0)),
    };
    chainSpoolStateCache = normalized;
    return normalized;
  } catch (_) {
    return {
      version: 1,
      records: 0,
      bytes: 0,
      lastWriteAt: '',
      lastHeight: 0,
    };
  }
}

function saveChainSpoolState(nextLike) {
  ensureMarketDataDir();
  const next = {
    version: 1,
    records: Math.max(0, Number(nextLike?.records || 0)),
    bytes: Math.max(0, Number(nextLike?.bytes || 0)),
    lastWriteAt: String(nextLike?.lastWriteAt || ''),
    lastHeight: Math.max(0, Number(nextLike?.lastHeight || 0)),
  };
  chainSpoolStateCache = { ...next };
  const serialized = JSON.stringify(next, null, 2);
  void marketDb.writeChainSpoolStateSnapshot({
    file: CHAIN_SPOOL_STATE_FILE,
    serialized,
  }).catch((error) => {
    appendMarketDebug('chain_spool_state_persist_failed', {
      message: String(error?.message || error || 'chain_spool_state_persist_failed'),
    });
  });
}

function appendChainSpoolRecords(recordsLike) {
  const records = Array.isArray(recordsLike) ? recordsLike.filter((x) => x && typeof x === 'object') : [];
  if (!records.length) return { appended: 0 };
  ensureMarketDataDir();
  const lines = records.map((r) => JSON.stringify(r)).join('\n') + '\n';
  void marketDb.appendChainSpoolRecords({
    file: CHAIN_SPOOL_FILE,
    text: lines,
  }).catch((error) => {
    appendMarketDebug('chain_spool_append_persist_failed', {
      message: String(error?.message || error || 'chain_spool_append_persist_failed'),
    });
  });
  const curr = loadChainSpoolState();
  const next = {
    ...curr,
    records: Number(curr.records || 0) + records.length,
    bytes: Number(curr.bytes || 0) + Buffer.byteLength(lines, 'utf8'),
    lastWriteAt: new Date().toISOString(),
    lastHeight: Math.max(Number(curr.lastHeight || 0), ...records.map((x) => Number(x?.height || 0))),
  };
  saveChainSpoolState(next);
  appendMarketDebug('chain_spool_append', {
    appended: records.length,
    lastHeight: next.lastHeight,
    bytes: next.bytes,
    records: next.records,
  });
  return { appended: records.length };
}

function parseAnchorRowsFromSpoolRecord(recLike) {
  const rec = recLike && typeof recLike === 'object' ? recLike : {};
  const txid = String(rec.txid || '').trim().toLowerCase();
  if (!/^[0-9a-f]{64}$/i.test(txid)) return [];
  const ts = String(rec.ts || new Date().toISOString());
  const node = String(rec.node || 'spool');
  const height = Number(rec.height || 0);
  const textCandidates = [];
  const opHex = String(rec.opReturnHex || '').trim();
  if (/^[0-9a-fA-F]+$/.test(opHex) && opHex.length % 2 === 0) {
    try {
      const d = Buffer.from(opHex, 'hex').toString('utf8');
      if (d) textCandidates.push(d);
    } catch (_) {}
  }
  const t = String(rec.text || '');
  if (t) textCandidates.push(t);
  const outRows = [];
  const seen = new Set();
  textCandidates.forEach((candidate) => {
    const key = String(candidate || '').slice(0, 1024);
    if (!key || seen.has(key)) return;
    seen.add(key);
    let matched = null;
    const rawCandidate = String(candidate || '');
    if (rawCandidate.includes(CHAIN_MARKER_PREFIX)) {
      const idx = rawCandidate.indexOf(CHAIN_MARKER_PREFIX);
      const directText = idx >= 0 ? rawCandidate.slice(idx) : rawCandidate;
      const parsed = parseAnchorPayloadText(directText);
      if (parsed) matched = { parsed, usedText: directText };
    }
    if (!matched) matched = tryParseAnchorTextLoose(candidate);
    if (matched?.parsed) {
      if (!isSupportedOrderAnchorPayload(matched.parsed.eventType, matched.parsed.payload)) return;
      outRows.push({
        ts,
        eventType: matched.parsed.eventType,
        payload: matched.parsed.payload,
        txid,
        node,
        height,
        confirmed: true,
      });
      return;
    }
  });
  return outRows;
}

function replayAnchorsFromChainSpool(state, options = {}) {
  ensureMarketDataDir();
  if (!fs.existsSync(CHAIN_SPOOL_FILE)) return { records: 0, rows: 0, addedAnchors: 0, maxHeight: 0 };
  const resetAnchors = options.resetAnchors !== false;
  let records = 0;
  let rows = 0;
  let maxHeight = 0;
  const mergedRows = [];
  const lines = String(fs.readFileSync(CHAIN_SPOOL_FILE, 'utf8') || '').split(/\r?\n/);
  lines.forEach((line) => {
    const raw = String(line || '').trim();
    if (!raw) return;
    let rec = null;
    try {
      rec = JSON.parse(raw);
    } catch (_) {
      return;
    }
    records += 1;
    maxHeight = Math.max(maxHeight, Number(rec?.height || 0));
    const parsedRows = parseAnchorRowsFromSpoolRecord(rec);
    if (parsedRows.length > 0) {
      rows += parsedRows.length;
      mergedRows.push(...parsedRows);
    }
  });
  const dedupedRows = dedupeAnchorRows(mergedRows, ANCHOR_CACHE_MAX_ROWS);
  let addedAnchors = 0;
  persistAnchorEventsAsync(dedupedRows, 'chain_spool_replay');
  if (resetAnchors) {
    addedAnchors = replaceStateAnchors(state, dedupedRows, ANCHOR_STATE_MAX_ROWS);
  } else {
    addedAnchors = mergeRowsIntoStateAnchors(state, dedupedRows);
  }
  const eventCounts = dedupedRows.reduce((acc, row) => {
    const key = String(row?.eventType || 'unknown');
    acc[key] = Number(acc[key] || 0) + 1;
    return acc;
  }, {});
  appendMarketDebug('chain_spool_replay_done', {
    records,
    rows,
    dedupedRows: dedupedRows.length,
    addedAnchors,
    resetAnchors,
    maxHeight,
    eventCounts,
  });
  return { records, rows, addedAnchors, maxHeight };
}

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

async function withTimeout(promise, timeoutMs, message) {
  let timer = null;
  try {
    return await Promise.race([
      promise,
      new Promise((_, reject) => {
        timer = setTimeout(() => reject(new Error(message || 'timeout')), timeoutMs);
      }),
    ]);
  } finally {
    if (timer) clearTimeout(timer);
  }
}

async function withSoftTimeoutFallback(promise, timeoutMs, fallbackValue, debugEvent, meta = {}) {
  try {
    return await withTimeout(promise, timeoutMs, `${debugEvent} timeout after ${timeoutMs}ms`);
  } catch (err) {
    appendMarketDebug(debugEvent, {
      timeoutMs,
      message: String(err?.message || `${debugEvent} failed`),
      ...(meta || {}),
    });
    return fallbackValue;
  }
}

async function runParallelWorkers(workerCount, worker) {
  const n = Math.max(1, Number(workerCount || 1));
  await Promise.all(Array.from({ length: n }, () => worker()));
}

