app.use((req, res, next) => {
  const activity = beginRuntimeActivity('http_request', buildRequestActivityPayload(req));
  let finalized = false;
  const finalize = () => {
    if (finalized) return;
    finalized = true;
    endRuntimeActivity(activity, {
      statusCode: Math.max(0, Number(res?.statusCode || 0)),
      headersSent: res?.headersSent === true,
    });
  };
  res.once('finish', finalize);
  res.once('close', finalize);
  next();
});
