const UI_ASSET_FILES = new Set([
  'index.html',
  'app.js',
  'demo.css',
  'trade_client.js',
  'catalog_default_categories.js',
]);
const UI_ASSET_CONTENT_TYPE = {
  'index.html': 'text/html; charset=utf-8',
  'app.js': 'application/javascript; charset=utf-8',
  'demo.css': 'text/css; charset=utf-8',
  'trade_client.js': 'application/javascript; charset=utf-8',
  'catalog_default_categories.js': 'application/javascript; charset=utf-8',
};

app.get(/^\/([a-zA-Z0-9._-]+)$/, (req, res, next) => {
  const file = req.params[0];
  if (!UI_ASSET_FILES.has(file)) return next();
  const abs = path.resolve(__dirname, file);
  const buffer = readCachedFileBuffer(uiAssetCache, abs);
  if (!buffer) {
    appendMarketDebug('asset_read_error', {
      file,
      abs,
      url: req.originalUrl,
      message: 'asset cache read failed',
    });
    return res.status(404).type('text/plain').send('Not Found');
  }
  res.type(UI_ASSET_CONTENT_TYPE[file] || 'application/octet-stream');
  return res.send(buffer);
});

app.get(/^\/locales\/([a-zA-Z0-9._-]+\.json)$/, (req, res) => {
  const file = req.params[0];
  const abs = path.resolve(__dirname, 'locales', file);
  const buffer = readCachedFileBuffer(localeAssetCache, abs);
  if (!buffer) {
    return res.status(404).type('text/plain').send('Not Found');
  }
  res.type('application/json; charset=utf-8');
  return res.send(buffer);
});

