app.post('/api/wallet/create', async (req, res) => {
  try {
    const state = buildCoreRuntimeStateSnapshot(req);
    const password = String(req.body?.password || '');
    if (!password) return fail(res, 'Password is required');
    if (wallet.walletExists()) wallet.resetWalletData();
    const result = await wallet.createWallet(password);
    req.session.walletPassword = password;
    await saveSessionAsync(req);
    setRuntimeWalletPassword(password);
    // New wallet should start from zero cache; avoid immediate balance refresh.
    const fresh = await resetAndSyncMarketStateForWallet(
      req,
      state.steward,
      getPendingAnchorOverlay(state),
      state.sync,
      { refreshWallet: false, deferChainSync: true, preserveSyncHints: false },
    );
    scheduleWalletProjectionRefresh('wallet_create_login', fresh);
    scheduleChatProjectionBackfillAfterLogin(req, 'wallet_create_login');
    notifyStewardSyncNow();
    appendMarketDebug('wallet_create_session_saved', {
      hasSession: Boolean(req?.session),
      hasWalletPassword: Boolean(req?.session?.walletPassword),
    });
    return ok(res, fresh, req, { mnemonic: result.mnemonic, firstAddress: result.firstAddress });
  } catch (err) {
    return fail(res, err.message || 'Create wallet failed');
  }
});

app.post('/api/wallet/switch', async (req, res) => {
  try {
    const state = buildCoreRuntimeStateSnapshot(req);
    const password = String(req.body?.password || '');
    const mnemonic = String(req.body?.mnemonic || '').trim().replace(/\s+/g, ' ');
    const mode = String(req.body?.mode || '').trim();
    const exists = wallet.walletExists();
    if (!password) return fail(res, 'Password is required');

    let result;
    if (mnemonic) {
      if (mode === 'create' && !exists) {
        result = await wallet.createWalletFromMnemonic(mnemonic, password);
      } else if (mode === 'import') {
        if (exists) wallet.resetWalletData();
        result = await wallet.recoverWallet(mnemonic, password);
      } else {
        result = await wallet.recoverWallet(mnemonic, password);
      }
    } else {
      if (exists) wallet.resetWalletData();
      result = await wallet.createWallet(password);
    }
    req.session.walletPassword = password;
    await saveSessionAsync(req);
    setRuntimeWalletPassword(password);

    const isFreshCreate = !mnemonic || mode === 'create';
    const fresh = await resetAndSyncMarketStateForWallet(
      req,
      state.steward,
      getPendingAnchorOverlay(state),
      state.sync,
      {
        refreshWallet: !isFreshCreate,
        deferChainSync: true,
        preserveSyncHints: false,
      },
    );
    scheduleWalletProjectionRefresh('wallet_switch_login', fresh);
    scheduleChatProjectionBackfillAfterLogin(req, 'wallet_switch_login');
    notifyStewardSyncNow();
    appendMarketDebug('wallet_switch_session_saved', {
      hasSession: Boolean(req?.session),
      hasWalletPassword: Boolean(req?.session?.walletPassword),
      mode,
    });
    return ok(res, fresh, req, { ...result });
  } catch (err) {
    return fail(res, err.message || 'Switch wallet failed');
  }
});

