app.post('/api/wallet/import-bootstrap', async (req, res) => {
  try {
    const mnemonic = String(req.body?.mnemonic || '').trim().replace(/\s+/g, ' ');
    const password = String(req.body?.password || '');
    const bootstrapMode = String(req.body?.bootstrapMode || 'woc_once').trim() || 'woc_once';
    const addressCount = Math.max(1, Math.min(Number(req.body?.addressCount || 50) || 50, 500));
    if (!mnemonic) return fail(res, 'Mnemonic is required');
    if (!password) return fail(res, 'Password is required');
    if (!stewardWorker || stewardWorker.killed) {
      return fail(res, 'Steward worker unavailable', 503);
    }
    req.session.walletPassword = password;
    await saveSessionAsync(req);
    setRuntimeWalletPassword(password);
    scheduleWalletProjectionRefresh('wallet_import_bootstrap_login');
    scheduleChatProjectionBackfillAfterLogin(req, 'wallet_import_bootstrap_login');
    appendMarketDebug('wallet_import_bootstrap_session_saved', {
      hasSession: Boolean(req?.session),
      hasWalletPassword: Boolean(req?.session?.walletPassword),
      bootstrapMode,
      addressCount,
    });
    const command = await enqueueCommand('import_wallet_bootstrap', {
      source: 'api_wallet_import_bootstrap',
      bootstrapMode,
      addressCount,
    }, { dedupePending: false });
    const delivered = notifyStewardImportBootstrap(command.id, {
      mnemonic,
      password,
      bootstrapMode,
      addressCount,
    });
    if (!delivered) {
      await markCommandFinished(command.id, 'failed', { error: 'steward worker unavailable' });
      return fail(res, 'Steward worker unavailable', 503);
    }
    return res.json({
      success: true,
      queued: true,
      commandId: command.id,
      bootstrapMode,
      addressCount,
      jobState: loadJobState(),
    });
  } catch (err) {
    return fail(res, err.message || 'Wallet import bootstrap failed');
  }
});

