app.get('/api/wallet/balance', walletAuthRequired, async (req, res) => {
  try {
    let unconfirmedProbe = null;
    const balanceProbeEnabled = String(process.env.BSV_MARKET_BALANCE_UNCONFIRMED_PROBE || '0') === '1'
      || String(req.query?.probeUnconfirmed || '') === '1';
    try {
      if (balanceProbeEnabled && typeof wallet.refreshUnconfirmedWalletSnapshot === 'function') {
        unconfirmedProbe = await wallet.refreshUnconfirmedWalletSnapshot({
          source: 'wallet_balance_probe',
          cooldownMs: 4000,
          nodeLimit: 3,
          snapshotMs: 1200,
          connectTimeoutMs: 1800,
          stopOnHit: true,
        });
        if (Number(unconfirmedProbe?.changed || 0) > 0) {
          const freshState = buildProjectionBackedState();
          refreshWalletIndexState(freshState, {
            source: 'wallet_balance_unconfirmed_probe',
            lastIndexedAt: new Date().toISOString(),
          });
          propagateWalletEventToViews('wallet_balance_unconfirmed_probe', freshState, 250);
        }
      }
    } catch (probeErr) {
      appendMarketDebug('wallet_balance_unconfirmed_probe_failed', {
        message: String(probeErr?.message || 'unconfirmed probe failed'),
      });
    }
    const walletUi = buildWalletUiBundle(req, { page: 1, pageSize: 10 });
    appendMarketDebug('wallet_balance_served', {
      walletKey: String(walletUi?.walletKey || ''),
      confirmed: Number(walletUi?.walletBalance?.confirmed || 0),
      unconfirmed: Number(walletUi?.walletBalance?.unconfirmed || 0),
      total: Number(walletUi?.walletBalance?.total || 0),
      updatedAt: String(walletUi?.walletBalance?.updatedAt || ''),
      loggedIn: Boolean(req?.session?.walletPassword),
      unconfirmedProbeEnabled: Boolean(balanceProbeEnabled),
      unconfirmedProbeChanged: Number(unconfirmedProbe?.changed || 0),
      unconfirmedProbeSkipped: Boolean(unconfirmedProbe?.skipped),
    });
    return res.json(walletUi.walletBalance);
  } catch (err) {
    return fail(res, err.message || 'Balance failed');
  }
});

