app.post('/api/wallet/send', walletAuthRequired, async (req, res) => {
  try {
    const runtimePolicy = typeof wallet.getWalletRuntimePolicy === 'function'
      ? wallet.getWalletRuntimePolicy()
      : { sendEnabled: true, reason: '' };
    if (runtimePolicy.sendEnabled === false) {
      return fail(res, runtimePolicy.reason || 'Wallet sending is temporarily disabled', 400);
    }
    const to = String(req.body?.to || '').trim();
    const amountBsv = Number(req.body?.amountBsv || 0);
    const sendAll = req.body?.sendAll === true;
    const note = String(req.body?.note || '');
    const sendTrace = String(req.body?.sendTrace || '').trim();
    await interruptPendingCommands((row) => String(row?.commandType || '') === 'wallet_refresh_cache', {
      reason: 'preempted by wallet_send',
    });
    await interruptStaleClaimedCommands((row) => String(row?.commandType || '') === 'wallet_refresh_cache', {
      reason: 'preempted by wallet_send',
      minClaimAgeMs: 15000,
    });
    const command = await enqueueCommand('wallet_send', {
      to,
      amountBsv,
      sendAll,
      note,
      sendTrace,
    }, { dedupePending: false });
    notifyStewardSyncNow();
    if (req.body?.asyncProgress === true) {
      return res.json({
        success: true,
        queued: true,
        commandId: command.id,
        requestId: sendTrace || undefined,
      });
    }
    const finished = await waitForCommandResult(command.id, 120000, 150);
    if (String(finished?.status || '') !== 'done') {
      return fail(res, String(finished?.error || 'Send failed'));
    }
    return res.json({
      success: true,
      requestId: sendTrace || undefined,
      ...(finished?.result && typeof finished.result === 'object' ? finished.result : {}),
    });
  } catch (err) {
    appendMarketDebug('wallet_send_error', {
      sendTrace: String(req.body?.sendTrace || '').trim(),
      to: String(req.body?.to || '').trim(),
      amountBsv: Number(req.body?.amountBsv || 0),
      message: String(err?.message || 'Send failed'),
      code: String(err?.code || ''),
      txid: String(err?.txid || ''),
      rawtxLength: String(err?.rawtx || '').length,
    });
    return fail(res, err.message || 'Send failed');
  }
});

