app.post('/api/wallet/sync', walletAuthRequired, async (req, res) => {
  try {
    const shouldRescan = String(req.query?.rescan || '') === '1';
    const shouldForceBootstrap = String(req.query?.forceBootstrap || req.body?.forceBootstrap || '') === '1'
      || req.body?.forceBootstrap === true;
    const shouldClearLocalFirst = String(req.query?.clearLocalFirst || req.body?.clearLocalFirst || '') === '1'
      || req.body?.clearLocalFirst === true;
    const shouldTrackAsync = req.body?.asyncProgress === true || String(req.query?.asyncProgress || '') === '1';
    appendMarketDebug('wallet_sync_request', {
      method: String(req?.method || ''),
      path: String(req?.originalUrl || req?.url || ''),
      source: String(req.body?.source || req.query?.source || '').trim(),
      sendTrace: String(req.body?.sendTrace || req.query?.sendTrace || '').trim(),
      rescan: shouldRescan,
      forceBootstrap: shouldForceBootstrap,
      clearLocalFirst: shouldClearLocalFirst,
      hasSession: Boolean(req?.session),
      hasWalletPassword: Boolean(req?.session?.walletPassword),
    });
    const countRaw = Number(req.query?.count || wallet.DEFAULT_RESCAN_COUNT);
    const count = Number.isFinite(countRaw) ? Math.max(1, Math.min(500, Math.floor(countRaw))) : wallet.DEFAULT_RESCAN_COUNT;
    const requestSource = String(req.body?.source || req.query?.source || '').trim();
    const commandPayload = {
      source: 'wallet_sync_api',
      requestSource,
      sendTrace: String(req.body?.sendTrace || req.query?.sendTrace || '').trim(),
      rescan: shouldRescan,
      forceBootstrap: shouldForceBootstrap,
      clearLocalFirst: shouldClearLocalFirst,
      count,
    };
    const existing = findActiveWalletRefreshCommand(commandPayload);
    const command = existing || await enqueueCommand('wallet_refresh_cache', commandPayload, {
      dedupePending: !(shouldRescan || shouldForceBootstrap || shouldClearLocalFirst),
    });
    notifyStewardSyncNow();
    if (shouldTrackAsync) {
      return res.json(buildWalletSyncCommandResponse(command.id, {
        queued: true,
        inProgress: true,
        rescanned: shouldRescan,
        forceBootstrap: shouldForceBootstrap,
        clearLocalFirst: shouldClearLocalFirst,
      }));
    }
    const waitTimeoutMs = shouldRescan
      ? 180000
      : ((shouldForceBootstrap || shouldClearLocalFirst) ? 15000 : 60000);
    let finished = null;
    try {
      finished = await waitForCommandResult(command.id, waitTimeoutMs, 150);
    } catch (err) {
      if (!isCommandWaitTimeoutError(err)) throw err;
      const latest = getCommandByIdFresh(command.id) || getCommandById(command.id);
      const latestStatus = String(latest?.status || '');
      if (latest && ['pending', 'claimed'].includes(latestStatus)) {
        appendMarketDebug('wallet_sync_queued_response', {
          source: String(req.body?.source || req.query?.source || '').trim(),
          sendTrace: String(req.body?.sendTrace || req.query?.sendTrace || '').trim(),
          rescan: shouldRescan,
          forceBootstrap: shouldForceBootstrap,
          clearLocalFirst: shouldClearLocalFirst,
          commandId: String(latest.id || command.id),
          status: latestStatus,
          waitedMs: waitTimeoutMs,
        });
        return res.json(buildWalletSyncCommandResponse(latest.id || command.id, {
          queued: true,
          inProgress: true,
          rescanned: shouldRescan,
          forceBootstrap: shouldForceBootstrap,
          clearLocalFirst: shouldClearLocalFirst,
        }));
      }
      throw err;
    }
    if (String(finished?.status || '') !== 'done') {
      return fail(res, String(finished?.error || 'Sync failed'));
    }
    const data = (finished?.result && typeof finished.result === 'object') ? finished.result : {};
    appendMarketDebug('wallet_sync_result', {
      source: String(req.body?.source || req.query?.source || '').trim(),
      sendTrace: String(req.body?.sendTrace || req.query?.sendTrace || '').trim(),
      rescan: shouldRescan,
      forceBootstrap: shouldForceBootstrap,
      clearLocalFirst: shouldClearLocalFirst,
      total: Number(data?.total || 0),
      confirmed: Number(data?.confirmed || 0),
      unconfirmed: Number(data?.unconfirmed || 0),
      txidCount: Array.isArray(data?.txids) ? data.txids.length : undefined,
    });
    try {
      const stateForOrderReplay = buildProjectionBackedState(req);
      const baseRows = getEffectiveAnchorRows(stateForOrderReplay);
      const orderRows = getRemotePendingOrderAnchorRows(stateForOrderReplay, {
        baseRows,
        txLimit: 500,
      });
      if (orderRows.length > 0) {
        await marketDb.upsertAnchorEvents(normalizeAnchorRowsForSqlite(orderRows));
        replaceStateAnchors(stateForOrderReplay, dedupeAnchorRows([...baseRows, ...orderRows], ANCHOR_STATE_MAX_ROWS), ANCHOR_STATE_MAX_ROWS);
        rebuildOrdersFromAnchors(stateForOrderReplay, req, {
          anchorRows: orderRows,
          includeUnconfirmedActionAnchors: true,
        });
        appendMarketDebug('wallet_sync_order_tx_context_replayed', {
          rowCount: orderRows.length,
          txids: orderRows.map((row) => String(row?.txid || '')).slice(0, 20),
        });
      }
    } catch (orderReplayError) {
      appendMarketDebug('wallet_sync_order_tx_context_replay_failed', {
        message: String(orderReplayError?.message || orderReplayError || 'order tx context replay failed'),
      });
    }
    return res.json({
      success: true,
      rescanned: shouldRescan,
      forceBootstrap: shouldForceBootstrap,
      clearLocalFirst: shouldClearLocalFirst,
      ...data,
    });
  } catch (err) {
    appendMarketDebug('wallet_sync_error', {
      source: String(req.body?.source || req.query?.source || '').trim(),
      sendTrace: String(req.body?.sendTrace || req.query?.sendTrace || '').trim(),
      forceBootstrap: String(req.query?.forceBootstrap || req.body?.forceBootstrap || '').trim(),
      clearLocalFirst: String(req.query?.clearLocalFirst || req.body?.clearLocalFirst || '').trim(),
      message: String(err?.message || 'Sync failed'),
    });
    return fail(res, err.message || 'Sync failed');
  }
});

