app.post('/api/steward', async (req, res) => {
  const state = buildProjectionBackedState(req);
  state.steward.regionPriority = String(req.body?.regionPriority || state.steward.regionPriority);
  state.steward.pollSec = Math.max(5, Number(req.body?.pollSec || state.steward.pollSec));
  state.steward.replayWindow = Math.max(10, Number(req.body?.replayWindow || state.steward.replayWindow));
  if (Object.prototype.hasOwnProperty.call(req.body || {}, 'catalogSyncEnabled')) {
    state.steward.catalogSyncEnabled = req.body?.catalogSyncEnabled !== false
      && String(req.body?.catalogSyncEnabled || '1') !== '0';
  } else if (typeof state.steward.catalogSyncEnabled !== 'boolean') {
    state.steward.catalogSyncEnabled = true;
  }
  if (Array.isArray(req.body?.chainSources)) {
    const nextChainSources = req.body.chainSources
      .map((x) => normalizeChainHttpBase(x))
      .filter(Boolean)
      .slice(0, 12);
    await mutateSyncProjection((sync) => {
      sync.chainSources = nextChainSources;
    });
    state.sync.chainSources = nextChainSources;
  }
  delete state.steward.notifyThreshold;
  notifyStewardPollSec(state.steward.pollSec);
  await writeStateJsonSnapshot(state, { reason: 'steward_saved', immediate: true });
  invalidateStateLiteSnapshotCache('steward_saved');
  schedulePublicStateRefresh('steward_saved', state);
  return ok(res, state, req);
});

app.post('/api/sync/recover', async (req, res) => {
  const state = buildProjectionBackedState(req);
  const replayWindow = Math.max(10, Number(req.body?.replayWindow || state.steward.replayWindow));
  await mutateSyncProjection((sync) => {
    sync.retries = Math.max(0, Number(sync.retries || 0)) + 1;
    sync.scannedFrom = Math.max(0, Number(sync.localHeight || 0) - replayWindow);
  });
  return ok(res, buildProjectionBackedState(req), req);
});

