app.post('/api/sync/start-manual', walletAuthRequired, async (req, res) => {
  try {
    const reason = String(req.body?.reason || 'api_sync_start_manual');
    const timeoutMs = Number(req.body?.timeoutMs || 30000);
    const pollMs = Number(req.body?.pollMs || 200);
    notifyStewardSyncEpoch(syncSessionEpoch);
    const runtime = await syncDomain.startManualSyncMode(reason);
    const started = await syncDomain.requestSyncNow(reason, {
      allowWhilePaused: true,
      allowWhenAutoSyncDisabled: true,
    });
    if (started?.ok !== true) {
      return fail(res, String(started?.reason || 'manual sync start failed'));
    }
    const commandId = String(started?.command?.id || started?.runtime?.status?.commandQueue?.lastCommand?.id || '');
    const startup = await waitForManualSyncStartup({
      commandId,
      timeoutMs,
      pollMs,
    });
    return res.json({
      success: true,
      manualSyncStarted: true,
      commandId,
      runtime,
      started,
      startup,
    });
  } catch (err) {
    return fail(res, String(err?.message || err || 'manual sync start failed'));
  }
});

app.post('/api/sync/reset-local', walletAuthRequired, async (req, res) => {
  try {
    const requestedBootstrap = Math.floor(Number(req.body?.bootstrapHeight));
    const bootstrapHeight = Number.isFinite(requestedBootstrap)
      ? requestedBootstrap
      : FIXED_SYNC_BOOTSTRAP_HEIGHT;
    if (bootstrapHeight < FIXED_SYNC_BOOTSTRAP_HEIGHT) {
      return fail(res, `bootstrapHeight must be >= ${FIXED_SYNC_BOOTSTRAP_HEIGHT}`);
    }
    if (req.body?.confirmReset !== true) {
      return fail(res, 'confirmReset is required');
    }
    const previous = buildProjectionBackedState(req);
    const stopResult = await stopSyncAndWait({
      reason: 'manual_sync_state_reset',
      timeoutMs: Number(req.body?.timeoutMs || 20000),
      pollMs: Number(req.body?.pollMs || 200),
      pause: true,
    });
    const resetEpoch = Math.max(0, Number(stopResult?.stopEpoch || 0));
    const getWalletKey = () => {
      try {
        return wallet.walletExists() ? String(wallet.getReceiveAddress() || '').trim() : '';
      } catch (_) {
        return '';
      }
    };
    const { fresh } = await performLocalSyncStateReset({
      req,
      bootstrapHeight,
      resetEpoch,
      previousState: previous,
      clearRuntimeSyncProgress,
      clearLocalCatalogArtifactsWithRetry,
      buildFreshMarketStateForBootstrap,
      withTransientResetRetries,
      writeStateJsonSnapshot,
      persistSyncStateNow,
      resetSyncArtifacts: resetSyncArtifactsForBootstrap,
      rebuildPublicStateCache,
      appendMarketDebug,
      notifyStewardSyncEpoch,
      resetAnchorEvents: () => marketDb.clearAnchorEvents(),
      resetCatalogSnapshot: () => catalogDomain.resetCatalogSnapshot(),
      resetProfileSnapshot: (profileKey) => profileDomain.resetProfileSnapshot(profileKey),
      resetLocalState: (scope) => localStateDomain.resetLocalState(scope),
      resetOrdersProjection: () => orderDomain.resetOrdersProjection(),
      resetWalletState: (walletKey) => walletReadDomain.resetWalletState(walletKey),
      resetWalletTxProjection: () => walletTxDomain.resetWalletTxProjection(),
      getWalletKey,
    });
    return ok(res, fresh, req, {
      resetLocalSyncState: true,
      bootstrapHeight,
      resetEpoch,
      stopResult,
      warning: 'local sync state reset to initialized state',
    });
  } catch (err) {
    return fail(res, String(err?.message || err || 'local sync state reset failed'));
  }
});

app.post('/api/sync/progress', async (req, res) => {
  const state = buildProjectionBackedState(req);
  const step = Math.max(1, Number(req.body?.step || 2));
  await mutateSyncProjection((sync) => {
    sync.localHeight = Math.min(
      Math.max(0, Number(sync.targetHeight || sync.p2pTipHeight || 0)),
      Math.max(0, Number(sync.localHeight || 0)) + step,
    );
  });
  const refreshedState = buildProjectionBackedState(req);
  state.sync = refreshedState.sync;
  state.products.forEach((p) => {
    if (p.deleted && p.deleteSync?.acked < p.deleteSync?.total) p.deleteSync.acked += 1;
  });
  commitSyncState(state, { writeJson: false });
  commitCatalogState(state, { writeJson: true, refresh: false });
  return ok(res, refreshedState, req);
});

app.post('/api/merchants/refresh', async (req, res) => {
  const state = buildProjectionBackedState(req);
  rebuildCatalogFromAnchors(state, req);
  commitCatalogState(state, { writeJson: true, refresh: false });
  return ok(res, state, req);
});

app.post('/api/data/rebuild', async (req, res) => {
  try {
    const rebuilt = await rebuildDataFromLocalAnchors(buildProjectionBackedState(req), req, {
      reason: 'api_data_rebuild',
      source: 'api_data_rebuild',
    });
    if (Array.isArray(rebuilt?.orders)) {
      await marketDb.applyOrderProjectionBatch({ orders: rebuilt.orders });
    }
    return ok(res, rebuilt, req, {
      rebuilt: true,
      categories: Array.isArray(rebuilt?.categories) ? rebuilt.categories.length : 0,
      products: Array.isArray(rebuilt?.products) ? rebuilt.products.length : 0,
      chatProfiles: rebuilt?.chatDiscovery?.profiles && typeof rebuilt.chatDiscovery.profiles === 'object'
        ? Object.keys(rebuilt.chatDiscovery.profiles).length
        : 0,
    });
  } catch (err) {
    return fail(res, err.message || 'Data rebuild failed');
  }
});

