app.post('/api/orders/place/preview', async (req, res) => {
  const state = buildProjectionStateFromSqlite(req);
  const productId = String(req.body?.productId || '');
  const fallbackPublicState = await getPublicStateFromCache(req, { allowFallback: true }).catch(() => null);
  const publicProducts = Array.isArray(fallbackPublicState?.products) ? fallbackPublicState.products : [];
  const product = (Array.isArray(state.products) ? state.products : []).find((p) => p.id === productId)
    || publicProducts.find((p) => p.id === productId);
  if (!product) return fail(res, 'Product not found', 404);
  if (!productVisibleForBuyer(product) || product.deleted) return fail(res, 'Product unavailable');
  const quantity = normalizeOrderQuantity(req.body?.quantity, product.stock);
  const sellerChatPubKey = getPeerChatPubKeyForMerchant(state, product.merchantId);
  if (!sellerChatPubKey) return fail(res, 'Seller chat key not found');
  let mnemonic = '';
  try {
    mnemonic = wallet.getMnemonicFromPassword(getSessionPassword(req));
  } catch (err) {
    if (/not logged in/i.test(String(err?.message || ''))) return fail(res, 'Not logged in', 401);
    return fail(res, err?.message || 'Build order preview failed');
  }
  const timeoutAt = Math.floor(Date.now() / 1000) + (Number(orderMachineConfig().timeoutHours || 24) * 60 * 60);
	  try {
	    const totalPriceBsv = Number(product.price || 0) * quantity;
	    const orderWalletIdentity = getOrderWalletIdentity(state, req);
      const placeContext = wallet.getOrderPlaceContext(mnemonic);
	    const payloadContext = {
	      ...placeContext,
	      buyerWalletId: orderWalletIdentity.walletId,
	      sellerWalletId: walletIdByMerchant(product.merchantId),
	      buyerLockRedeemScriptHex: bsv.Script.buildPublicKeyHashOut(placeContext.buyerRefundAddress).toHex(),
    };
    const payloadForChain = buildOrderPlaceChainPayload(product, quantity, payloadContext, sellerChatPubKey, timeoutAt);
    const buyerLockTx = wallet.buildOrderPlaceLockTx({
      mnemonic,
      orderId: '',
      priceBsv: totalPriceBsv,
      sellerChatPubKey,
      timeoutAt,
      anchorText: buildAnchorWireText('order_place', payloadForChain),
      note: `order_place_preview:${product.id}`,
    });
    return ok(res, state, req, {
      quantity,
      priceSats: Number(buyerLockTx.priceSats || 0),
      priceBsv: satToBsv(Number(buyerLockTx.priceSats || 0)),
      depositSats: Number(buyerLockTx.buyerDepositSats || 0),
      depositBsv: satToBsv(Number(buyerLockTx.buyerDepositSats || 0)),
      lockTotalSats: Number(buyerLockTx.buyerLockSats || 0),
      lockTotalBsv: satToBsv(Number(buyerLockTx.buyerLockSats || 0)),
      feeSat: Number(buyerLockTx.feeSat || 0),
      feeBsv: satToBsv(Number(buyerLockTx.feeSat || 0)),
    });
  } catch (err) {
    return fail(res, err?.message || 'Build order preview failed');
  }
});

app.post('/api/orders/place', async (req, res) => {
  const state = buildProjectionStateFromSqlite(req);

  const productId = String(req.body?.productId || '');
  const fallbackPublicState = await getPublicStateFromCache(req, { allowFallback: true }).catch(() => null);
  const publicProducts = Array.isArray(fallbackPublicState?.products) ? fallbackPublicState.products : [];
  const product = (Array.isArray(state.products) ? state.products : []).find((p) => p.id === productId)
    || publicProducts.find((p) => p.id === productId);
  if (!product) return fail(res, 'Product not found', 404);
  if (!productVisibleForBuyer(product) || product.deleted) return fail(res, 'Product unavailable');
  const quantity = normalizeOrderQuantity(req.body?.quantity, product.stock);
  const sellerChatPubKey = getPeerChatPubKeyForMerchant(state, product.merchantId);
  if (!sellerChatPubKey) return fail(res, 'Seller chat key not found');
  const mnemonic = wallet.getMnemonicFromPassword(getSessionPassword(req));
  const timeoutAt = Math.floor(Date.now() / 1000) + (Number(orderMachineConfig().timeoutHours || 24) * 60 * 60);
  let buyerLockTx = null;
  let payloadForChain = null;
	  try {
      const placeContext = wallet.getOrderPlaceContext(mnemonic);
	    const buyerLockRedeemScriptHex = bsv.Script.buildPublicKeyHashOut(placeContext.buyerRefundAddress).toHex();
	    const orderWalletIdentity = getOrderWalletIdentity(state, req);
	    const payloadContext = {
	      ...placeContext,
	      buyerWalletId: orderWalletIdentity.walletId,
	      sellerWalletId: walletIdByMerchant(product.merchantId),
	      orderNonce: crypto.randomBytes(8).toString('hex'),
	      buyerLockRedeemScriptHex,
	    };
    payloadForChain = buildOrderPlaceChainPayload(product, quantity, payloadContext, sellerChatPubKey, timeoutAt);
    buyerLockTx = wallet.buildOrderPlaceLockTx({
      mnemonic,
      orderId: '',
      priceBsv: Number(product.price || 0) * quantity,
      sellerChatPubKey,
      timeoutAt,
      anchorText: buildAnchorWireText('order_place', payloadForChain),
      note: `order_place:${product.id}`,
    });
  } catch (err) {
    return fail(res, err?.message || 'Build order lock failed');
  }

  let placeBroadcast;
  try {
    placeBroadcast = await broadcastAndTrackOrderRawtx(req, state, {
      rawtx: buyerLockTx.rawtx,
      source: 'order_place_lock',
      reservationId: `order_place:${buyerLockTx.txid}`,
      reservationType: 'order_place_lock',
      note: `order_place:${product.id}`,
      trackOutputs: true,
      requireVisibility: true,
    });
  } catch (err) {
    return fail(res, err?.message || 'Order place broadcast failed');
  }

  if (payloadForChain && typeof payloadForChain === 'object') {
    const anchorRow = {
      ts: new Date().toISOString(),
      eventType: 'order_place',
      payload: payloadForChain,
      txid: String(placeBroadcast?.txid || buyerLockTx?.txid || '').trim(),
      node: String(placeBroadcast?.broadcast?.node || placeBroadcast?.broadcast?.observedNode || '').trim(),
      confirmed: false,
      publicVisible: false,
    };
    setPendingAnchorOverlay(state, [...getPendingAnchorOverlay(state), anchorRow].slice(-500));
    persistAnchorEventsAsync([anchorRow], 'order_place_local');
  }

  const orderId = `order:${buyerLockTx.txid}`;
  const productStockSnapshot = Math.max(0, Number(product.stock || 0));

  const baseOrder = {
    id: orderId,
    buyerWalletId: getOrderWalletIdentity(state, req).walletId,
    sellerWalletId: walletIdByMerchant(product.merchantId),
    snapshot: {
      product_id: product.id,
      product_version: product.version,
      price_snapshot: Number(product.price || 0) * quantity,
      stock_snapshot: productStockSnapshot,
      quantity,
      merchant_id: product.merchantId,
      category_id: product.categoryId,
      title: product.title,
    },
    status: ORDER_STATUS.NEW,
    funds: {
      priceSats: Number(buyerLockTx.priceSats || 0),
    },
    transitionIds: [],
    chain: {
      orderProtocolVersion: 3,
      placeTxid: buyerLockTx.txid,
      buyerLockTxid: buyerLockTx.txid,
      buyerLockVout: Number(buyerLockTx.buyerLockVout || 0),
      buyerLockRedeemScriptHex: buyerLockTx.buyerLockRedeemScriptHex,
      buyerLockScriptHash: String(payloadForChain?.bh || '').trim(),
      buyerLockAddress: buyerLockTx.buyerLockAddress,
      buyerLockSats: Number(buyerLockTx.buyerLockSats || 0),
      buyerRefundAddress: buyerLockTx.buyerRefundAddress,
      buyerChatPubKey: buyerLockTx.buyerChatPubKey,
      sellerChatPubKey,
      jointRedeemScriptHex: deriveOrderJointRedeemScriptHexFromPayload(payloadForChain),
      jointScriptHash: String(payloadForChain?.jh || '').trim(),
      sellerMerchantId: String(product.merchantId || '').trim(),
      sellerLockSats: computeOrderSellerDepositSatsForProtocol(Number(buyerLockTx.priceSats || 0)),
      timeoutAt,
      stateAnchorTxid: placeBroadcast.txid,
    },
  };
  let order = applyTransition(baseOrder, 'place', {
    transitionId: String(req.body?.transitionId || req.body?.clientActionId || `place:${orderId}`).trim(),
    config: orderMachineConfig(),
  });
  order.tip = 'order_tip_place';
  order.updatedAt = Date.now();
  await orderDomain.emitOrderUpsert(order, {
    producer: 'orders_api.place',
    dedupeKey: `order.upsert:${order.id}:${order.status}:${String(order.transitionIds?.slice(-1)[0] || 'place')}`,
  });

  commitLocalState(state, { writeJson: true, refresh: false });
  const nextState = buildProjectionBackedState(req);
  const nextOrders = Array.isArray(nextState?.orders) ? nextState.orders.slice() : [];
  const orderIndex = nextOrders.findIndex((row) => String(row?.id || '').trim() === String(order.id || '').trim());
  if (orderIndex >= 0) nextOrders.splice(orderIndex, 1);
  nextOrders.unshift(migrateOrderModel(order));
  nextState.orders = nextOrders;
  commitCoreRuntimeProjectionState(nextState, {
    reason: 'orders_api_place_immediate_order_visible',
    hydrated: true,
    req,
  });
  return ok(res, nextState, req, { orderId: order.id, anchorTxid: placeBroadcast?.txid || null });
});

app.post('/api/orders/:id/action', async (req, res) => {
  const suppliedOrder = req.body?.order && typeof req.body.order === 'object'
    ? { ...req.body.order, id: String(req.params.id || req.body.order.id || '').trim() }
    : null;
  const useSuppliedOrderFastPath = suppliedOrder && suppliedOrder.id && req.body?.useSuppliedOrder === true;
  const state = useSuppliedOrderFastPath ? defaultState() : buildProjectionStateFromSqlite(req);
  if (useSuppliedOrderFastPath) {
    ensureCurrentMerchantId(state, req);
    state.orders = [migrateOrderModel(suppliedOrder)];
  }
  let order = useSuppliedOrderFastPath ? state.orders[0] : findOrder(state, req.params.id);
  if (!order && req.body?.order && typeof req.body.order === 'object') {
    const supplied = suppliedOrder || { ...req.body.order, id: String(req.params.id || req.body.order.id || '').trim() };
    if (supplied.id) {
      order = migrateOrderModel(supplied);
    }
  }
  if (!order) return fail(res, 'Order not found', 404);
  migrateOrderModel(order);

  const action = String(req.body?.action || '');
  if (action === 'cancel') return fail(res, 'Buyer cancellation is disabled in this release');
  const actionMeta = ORDER_ACTION_META[action];
  if (!actionMeta) return fail(res, 'Unsupported action');
  const actionSuccessMessage = {
    accept: 'order_action_accept_success',
    ship: 'order_action_ship_success',
    confirmReceipt: 'order_action_confirm_receipt_success',
    requestRefund: 'order_action_refund_request_success',
    confirmRefund: 'order_action_refund_confirm_success',
    sellerCancel: 'order_action_cancel_success',
    timeoutCancel: 'order_action_timeout_cancel_success',
  }[action] || 'order_action_success';
  const mnemonic = wallet.getMnemonicFromPassword(getSessionPassword(req));
  const actorIdentity = {
    ...getCurrentWalletIdentity(state, req),
    receiveAddress: (() => {
      try { return String(wallet.getReceiveAddress() || '').trim(); } catch (_) { return ''; }
    })(),
    chatPubKey: (() => {
      try { return String(wallet.deriveChatPublicKeyFromMnemonic(mnemonic) || '').trim(); } catch (_) { return ''; }
    })(),
  };
  const buildSignedActionPayload = (txid = '', roleOverride = '') => {
    const actorRole = String(roleOverride || ((new Set(['accept', 'ship', 'confirmRefund', 'sellerCancel'])).has(action) ? 'seller' : 'buyer')).trim();
    const actorKeypair = (() => {
      try { return wallet.deriveChatKeypairFromMnemonic(mnemonic); } catch (_) { return null; }
    })();
    return buildOrderActionAnchorPayload(order, actionMeta, txid, actorKeypair ? {
      role: actorRole,
      pubKey: String(actorKeypair.chatPubKey || '').trim(),
      privateKey: actorKeypair.privateKey,
    } : null);
  };
  const broadcastSignedActionAnchor = async (txid = '', roleOverride = '', anchorOptions = {}) => {
	    const notifyAddresses = [];
	    for (const address of (Array.isArray(anchorOptions.notifyAddresses) ? anchorOptions.notifyAddresses : [])) {
	      const safeAddress = String(address || '').trim();
	      if (safeAddress) notifyAddresses.push(safeAddress);
	    }
	    if ((action === 'accept' || action === 'ship') && String(order?.chain?.buyerRefundAddress || '').trim()) {
	      notifyAddresses.push(String(order.chain.buyerRefundAddress).trim());
	    }
	    if (action === 'confirmRefund') {
	      for (const address of [order?.chain?.buyerRefundAddress, order?.chain?.sellerRefundAddress]) {
	        const safeAddress = String(address || '').trim();
	        if (safeAddress) notifyAddresses.push(safeAddress);
	      }
	    }
    if (action === 'confirmReceipt') {
      for (const address of [order?.chain?.sellerReceiveAddress, order?.chain?.sellerRefundAddress]) {
        const safeAddress = String(address || '').trim();
        if (safeAddress) notifyAddresses.push(safeAddress);
      }
    }
    const explicitExcludeOutpoints = Array.isArray(anchorOptions.excludeOutpoints) ? anchorOptions.excludeOutpoints : [];
    const preferredFeeOutpoints = Array.isArray(anchorOptions.preferredFeeOutpoints) ? anchorOptions.preferredFeeOutpoints : [];
    const orderLinkedExcludes = collectOrderLinkedOutpointsForAnchorExclusion(state, {
      allowOutpoints: preferredFeeOutpoints,
      currentOrderId: String(order?.id || '').trim(),
    });
    const result = await tryAnchorEvent(req, state, String(actionMeta.eventType || '').trim(), buildSignedActionPayload(txid, roleOverride), {
        includeUnconfirmed: anchorOptions.includeUnconfirmed !== false,
        requireVisibility: anchorOptions.requireVisibility !== false,
        trackOutputs: true,
      preferredFeeOutpoints,
      requirePreferredFee: anchorOptions.requirePreferredFee === true,
      notifyAddresses,
      excludeOutpoints: [
        ...explicitExcludeOutpoints,
        ...orderLinkedExcludes,
      ],
    });
    if (result?.error) {
      const err = new Error(String(result.error || 'Order action anchor broadcast failed'));
      err.code = 'ORDER_ACTION_ANCHOR_FAILED';
      throw err;
    }
    return result;
  };

  if (action === 'ship' && !useSuppliedOrderFastPath) {
    order = enrichOrderSnapshotFromCatalog(order, state.products);
    const current = state.products.find((p) => p.id === order.snapshot.product_id);
    if (!current || current.deleted) return fail(res, 'Product unavailable');
    if (current.version !== order.snapshot.product_version) return fail(
      res,
      `版本不一致: 下单v${order.snapshot.product_version}, 当前v${current.version}`,
    );
  }

  const transitionId = String(req.body?.transitionId || req.body?.clientActionId || `${action}:${order.id}`).trim();
  let anchor = null;
  let localTxid = '';
  try {
    appendMarketDebug('order_action_start', {
      orderId: String(order?.id || ''),
      action: String(action || ''),
      actorWalletId: String(actorIdentity?.walletId || ''),
      actorMerchantId: String(actorIdentity?.merchantId || ''),
      currentStatus: String(order?.status || ''),
      transitionId,
    });
    assertOrderActorAllowed(order, action, actorIdentity);
    hydrateOrderSuppliedTxContexts(order, action);
    await ensureOrderActionTxContexts(order, action);
    if ((action === 'confirmReceipt' || action === 'requestRefund') && !isOrderShipConfirmed(order)) {
      const err = new Error('order_ship_not_confirmed');
      err.code = 'ORDER_SHIP_NOT_CONFIRMED';
      throw err;
    }
    const refreshRefundRequestDraft = action === 'requestRefund'
      && String(order?.status || '') === ORDER_STATUS.REFUND_REQUESTED
      && (
        !String(order?.chain?.refundDraftRawtx || '').trim()
        || req.body?.refreshRefundDraft === true
        || req.body?.refreshDraft === true
      );
    if (!refreshRefundRequestDraft) {
      applyTransition(order, actionMeta.machineAction, {
        transitionId,
        config: orderMachineConfig(),
      });
    } else {
      appendMarketDebug('order_refund_request_refresh_draft', {
        orderId: String(order?.id || ''),
        status: String(order?.status || ''),
        transitionId,
      });
    }
    if (action === 'accept') {
      if (!isOrderPlaceConfirmed(order) && !hasOrderPlaceTxContext(order)) {
        const err = new Error('Order place transaction context is unavailable; wait for listener or sync before accepting');
        err.code = 'ORDER_PLACE_CONTEXT_UNAVAILABLE';
        throw err;
      }
      appendMarketDebug('order_action_stage', { orderId: String(order?.id || ''), action, stage: 'build_seller_lock' });
      assertOrderChainValue(order, 'chain.buyerLockRedeemScriptHex', 'Missing buyer lock redeem script');
      const sellerChatPubKey = wallet.deriveChatPublicKeyFromMnemonic(mnemonic);
      const existingSellerLock = null;
      let sellerLockTx = null;
      let sellerLockBroadcast = null;
      if (existingSellerLock) {
        appendMarketDebug('order_accept_existing_seller_lock_reused', {
          orderId: String(order?.id || ''),
          txid: String(existingSellerLock.txid || ''),
          sellerLockSats: Number(existingSellerLock.sellerLockSats || 0),
        });
        sellerLockBroadcast = {
          txid: existingSellerLock.txid,
          rawtx: existingSellerLock.rawtx,
          broadcast: { reusedLocal: true },
        };
        sellerLockTx = {
          txid: existingSellerLock.txid,
          rawtx: existingSellerLock.rawtx,
          sellerLockSats: existingSellerLock.sellerLockSats,
          sellerLockVout: 0,
          settlementFeeVout: Number(existingSellerLock.settlementFeeVout || 0),
          settlementFeeReserveSats: Number(existingSellerLock.settlementFeeReserveSats || 0),
          shipAnchorFeeVout: Number(existingSellerLock.shipAnchorFeeVout || 0),
          shipAnchorFeeReserveSats: Number(existingSellerLock.shipAnchorFeeReserveSats || 0),
          jointRedeemScriptHex: existingSellerLock.sellerLockRedeemScriptHex,
          jointAddress: '',
        };
      } else {
        order.chain.sellerLockTxid = '';
        order.chain.sellerLockVout = 0;
        order.chain.sellerRefundAddress = wallet.getReceiveAddress();
        order.chain.sellerReceiveAddress = wallet.getReceiveAddress();
        order.chain.sellerChatPubKey = sellerChatPubKey;
        order.chain.sellerLockRedeemScriptHex = String(order?.chain?.jointRedeemScriptHex || deriveOrderJointRedeemScriptHexFromPayload(order.chain) || '').trim();
        order.chain.sellerSettlementFeeTxid = '';
        order.chain.sellerSettlementFeeVout = 2;
        order.chain.sellerShipAnchorFeeTxid = '';
        order.chain.sellerShipAnchorFeeVout = 3;
        order.chain.sellerLockAcceptedAtHeight = Math.max(0, Number(state?.sync?.localHeight || 0));
        const confirmPayloadForReserve = buildOrderActionAnchorPayload(order, { eventType: 'order_confirm' }, '', null);
        const confirmAnchorTextForReserve = buildAnchorWireText('order_confirm', confirmPayloadForReserve);
        const settlementFeeReserveSats = typeof wallet.estimateOrderSettlementFeeReserveSat === 'function'
          ? wallet.estimateOrderSettlementFeeReserveSat({
            mode: 'completed',
            includeSellerSource: true,
            anchorText: confirmAnchorTextForReserve,
          })
          : Number(wallet.ORDER_SETTLEMENT_FEE_RESERVE_SAT || 0);
        const estimatedDraftHexChars = typeof wallet.estimateOrderSettlementDraftRawtxHexChars === 'function'
          ? wallet.estimateOrderSettlementDraftRawtxHexChars({
            mode: 'completed',
            includeSellerSource: true,
            anchorText: confirmAnchorTextForReserve,
          })
          : 0;
        const actorKeypairForReserve = (() => {
          try { return wallet.deriveChatKeypairFromMnemonic(mnemonic); } catch (_) { return null; }
        })();
        const shipReserveOrder = migrateOrderModel({
          ...order,
          chain: {
            ...(order.chain || {}),
            completedDraftRawtx: estimatedDraftHexChars > 0 ? '0'.repeat(estimatedDraftHexChars) : '',
          },
        });
        const shipPayloadForReserve = buildOrderActionAnchorPayload(shipReserveOrder, { eventType: 'order_ship' }, '', actorKeypairForReserve ? {
          role: 'seller',
          pubKey: String(actorKeypairForReserve.chatPubKey || '').trim(),
          privateKey: actorKeypairForReserve.privateKey,
        } : null);
        const shipAnchorTextForReserve = buildAnchorWireText('order_ship', shipPayloadForReserve);
        const shipAnchorFeeReserveSats = typeof wallet.estimateAnchorDataFeeReserveSat === 'function'
          ? wallet.estimateAnchorDataFeeReserveSat({
            payloadBytes: Buffer.byteLength(shipAnchorTextForReserve, 'utf8'),
            notifyOutputCount: String(order?.chain?.buyerRefundAddress || '').trim() ? 1 : 0,
          })
          : Number(wallet.ORDER_SHIP_ANCHOR_FEE_RESERVE_SAT || 0);
        order.chain.sellerSettlementFeeSats = settlementFeeReserveSats;
        order.chain.sellerShipAnchorFeeSats = shipAnchorFeeReserveSats;
        appendMarketDebug('order_accept_dynamic_fee_reserves', {
          orderId: String(order?.id || ''),
          settlementFeeReserveSats,
          shipAnchorFeeReserveSats,
          confirmPayloadBytes: Buffer.byteLength(confirmAnchorTextForReserve, 'utf8'),
          estimatedDraftHexChars,
          shipPayloadBytes: Buffer.byteLength(shipAnchorTextForReserve, 'utf8'),
        });
        sellerLockTx = wallet.buildOrderSellerLockTx({
          mnemonic,
          orderId: order.id,
          priceSats: Number(order?.funds?.priceSats || 0),
          buyerChatPubKey: String(order?.chain?.buyerChatPubKey || '').trim(),
          sellerChatPubKey,
          anchorText: buildAnchorWireText('order_accept', buildSignedActionPayload('', 'seller')),
          notifyAddresses: [String(order?.chain?.buyerRefundAddress || '').trim()].filter(Boolean),
          settlementFeeReserveSats,
          shipAnchorFeeReserveSats,
          note: `order_accept:${order.id}`,
        });
        appendMarketDebug('order_action_stage', {
          orderId: String(order?.id || ''),
          action,
          stage: 'broadcast_seller_lock',
          txid: String(sellerLockTx?.txid || ''),
        });
        sellerLockBroadcast = await broadcastAndTrackOrderRawtx(req, state, {
          rawtx: sellerLockTx.rawtx,
          source: 'order_accept_seller_lock',
          reservationId: `order_accept_seller_lock:${sellerLockTx.txid}`,
          reservationType: 'order_accept_seller_lock',
          note: `order_accept_seller_lock:${order.id}`,
          requireVisibility: true,
        });
      }
      order.chain.sellerLockTxid = sellerLockBroadcast.txid;
      order.chain.sellerLockVout = 0;
      order.chain.sellerLockSats = Number(sellerLockTx.sellerLockSats || 0);
      order.chain.sellerRefundAddress = wallet.getReceiveAddress();
      order.chain.sellerReceiveAddress = wallet.getReceiveAddress();
      order.chain.sellerChatPubKey = sellerChatPubKey;
      order.chain.sellerLockRedeemScriptHex = sellerLockTx.jointRedeemScriptHex;
      order.chain.jointRedeemScriptHex = sellerLockTx.jointRedeemScriptHex;
      order.chain.jointAddress = sellerLockTx.jointAddress;
      order.chain.sellerSettlementFeeTxid = sellerLockBroadcast.txid;
      order.chain.sellerSettlementFeeVout = Number(sellerLockTx.settlementFeeVout || 0);
      order.chain.sellerSettlementFeeSats = Number(sellerLockTx.settlementFeeReserveSats || 0);
      order.chain.sellerShipAnchorFeeTxid = sellerLockBroadcast.txid;
      order.chain.sellerShipAnchorFeeVout = Number(sellerLockTx.shipAnchorFeeVout || 0);
      order.chain.sellerShipAnchorFeeSats = Number(sellerLockTx.shipAnchorFeeReserveSats || 0);
      order.chain.sellerLockAcceptedAtHeight = Math.max(0, Number(state?.sync?.localHeight || 0));
      await handleObservedChainRawtx({
        txid: sellerLockBroadcast.txid,
        rawtx: sellerLockBroadcast.rawtx,
        confirmed: false,
        node: 'orders_api.accept_combined_tx',
        firstSeenAt: new Date().toISOString(),
      }, { source: 'orders_api.accept_combined_tx' });
      anchor = { txid: sellerLockBroadcast.txid, rawtx: sellerLockBroadcast.rawtx };
      localTxid = String(sellerLockBroadcast.txid || '').trim();
    } else if (action === 'ship') {
      appendMarketDebug('order_action_stage', { orderId: String(order?.id || ''), action, stage: 'broadcast_ship_anchor' });
      const shipmentInfo = String(req.body?.shipmentInfo || '').trim();
      if (shipmentInfo.length > 100) return fail(res, 'Shipment info must be 100 characters or less');
      order.chain.shipmentInfo = shipmentInfo;
      assertOrderChainValue(order, 'chain.buyerLockTxid', 'Missing buyer lock tx');
      assertOrderChainValue(order, 'chain.sellerLockTxid', 'Missing seller lock tx');
      assertOrderChainValue(order, 'chain.buyerLockRedeemScriptHex', 'Missing buyer lock redeem script');
      assertOrderChainValue(order, 'chain.sellerLockRedeemScriptHex', 'Missing seller lock redeem script');
      const acceptedAtHeight = Math.max(0, Number(order?.chain?.sellerLockAcceptedAtHeight || 0));
      const currentLocalHeight = Math.max(0, Number(state?.sync?.localHeight || 0));
      if (acceptedAtHeight > 0 && currentLocalHeight <= acceptedAtHeight) {
        return fail(res, `order_ship_wait_next_block:${currentLocalHeight}:${acceptedAtHeight}`);
      }
      const confirmPayloadForSettlement = buildOrderActionAnchorPayload(order, { eventType: 'order_confirm' }, '', null);
      const completedDraft = await wallet.buildOrderSettlementDraft({
        mnemonic,
        mode: 'completed',
        priceSats: Number(order?.funds?.priceSats || 0),
        buyerSourceTxid: String(order?.chain?.buyerLockTxid || '').trim(),
        buyerSourceVout: Number(order?.chain?.buyerLockVout || 0),
        buyerSourceSats: Number(order?.chain?.buyerLockSats || order?.funds?.buyerLockedSats || 0),
        buyerSourceRedeemScriptHex: String(order?.chain?.buyerLockRedeemScriptHex || '').trim(),
        sellerSourceTxid: String(order?.chain?.sellerLockTxid || '').trim(),
        sellerSourceVout: Number(order?.chain?.sellerLockVout || 0),
        sellerSourceSats: Number(order?.chain?.sellerLockSats || order?.funds?.sellerDepositSats || 0),
        sellerSourceRedeemScriptHex: String(order?.chain?.sellerLockRedeemScriptHex || '').trim(),
        buyerChatPubKey: String(order?.chain?.buyerChatPubKey || '').trim(),
        sellerChatPubKey: String(order?.chain?.sellerChatPubKey || '').trim(),
        buyerRefundAddress: String(order?.chain?.buyerRefundAddress || '').trim(),
        sellerReceiveAddress: String(order?.chain?.sellerReceiveAddress || '').trim(),
        sellerRefundAddress: String(order?.chain?.sellerRefundAddress || '').trim(),
        spendSellerSource: true,
        anchorText: buildAnchorWireText('order_confirm', confirmPayloadForSettlement),
        preferredFeeOutpoints: [`${String(order?.chain?.sellerSettlementFeeTxid || '').trim()}:${Number(order?.chain?.sellerSettlementFeeVout || 0)}`],
      });
      order.chain.completedDraftRawtx = wallet.signOrderSettlementDraft({
        mnemonic,
        draftRawtx: String(completedDraft.rawtx || '').trim(),
        buyerSourceRedeemScriptHex: String(order?.chain?.buyerLockRedeemScriptHex || '').trim(),
        sellerSourceRedeemScriptHex: String(order?.chain?.sellerLockRedeemScriptHex || '').trim(),
        buyerSourceSats: Number(order?.chain?.buyerLockSats || order?.funds?.buyerLockedSats || 0),
        sellerSourceSats: Number(order?.chain?.sellerLockSats || order?.funds?.sellerDepositSats || 0),
        spendSellerSource: true,
        signerRole: 'seller',
      }).rawtx;
      const settlementFeeInputOutpoints = Array.isArray(completedDraft.feeInputOutpoints) ? completedDraft.feeInputOutpoints : [];
      const shipAnchorFeeOutpoints = deriveSellerShipAnchorFeeOutpoints(order, mnemonic, {
        excludeOutpoints: settlementFeeInputOutpoints,
      });
      const hasDedicatedShipFee = Number(order?.chain?.sellerShipAnchorFeeSats || 0) > 0;
      appendMarketDebug('order_ship_anchor_fee_outpoints', {
        orderId: String(order?.id || ''),
        outpoints: shipAnchorFeeOutpoints,
        hasDedicatedShipFee,
        settlementFeeInputOutpoints,
      });
      const shipAnchor = await broadcastSignedActionAnchor('', 'seller', {
        excludeOutpoints: settlementFeeInputOutpoints,
        preferredFeeOutpoints: shipAnchorFeeOutpoints,
        requirePreferredFee: false,
      });
      anchor = shipAnchor;
      order.chain.shipTxid = String(shipAnchor?.txid || '').trim();
      order.chain.shipConfirmed = false;
      order.chain.shipConfirmedHeight = 0;
      localTxid = order.chain.shipTxid;
    } else if (action === 'confirmReceipt') {
      appendMarketDebug('order_action_stage', { orderId: String(order?.id || ''), action, stage: 'build_completed_settlement' });
      assertOrderChainValue(order, 'chain.buyerLockTxid', 'Missing buyer lock tx');
      assertOrderChainValue(order, 'chain.sellerLockTxid', 'Missing seller lock tx');
      assertOrderChainValue(order, 'chain.buyerLockRedeemScriptHex', 'Missing buyer lock redeem script');
      assertOrderChainValue(order, 'chain.sellerLockRedeemScriptHex', 'Missing seller lock redeem script');
      const existingSettlementTxid = String(req.body?.settlementTxid || req.body?.completedSettlementTxid || '').trim();
      if (existingSettlementTxid && req.body?.settlementAlreadyBroadcast === true) {
        appendMarketDebug('order_action_stage', {
          orderId: String(order?.id || ''),
          action,
          stage: 'broadcast_confirm_anchor_for_existing_settlement',
          settlementTxid: existingSettlementTxid,
        });
        order.chain.settleTxid = existingSettlementTxid;
        order.chain.completedSettlementTxid = existingSettlementTxid;
        order.funds.sellerCreditSats = Number(order?.funds?.priceSats || 0);
        order.funds.buyerRefundSats = Number(order?.funds?.buyerDepositSats || 0);
        order.funds.sellerRefundSats = Number(order?.funds?.sellerDepositSats || 0);
        const confirmAnchor = await broadcastSignedActionAnchor(existingSettlementTxid, 'buyer');
        anchor = confirmAnchor;
        localTxid = String(confirmAnchor?.txid || existingSettlementTxid || '').trim();
      } else {
      assertOrderChainValue(order, 'chain.completedDraftRawtx', 'Missing seller completion settlement signature from ship event');
      const completedBroadcast = await broadcastAndTrackOrderRawtx(req, state, {
        rawtx: wallet.signOrderSettlementDraft({
          mnemonic,
          draftRawtx: String(order?.chain?.completedDraftRawtx || '').trim(),
          buyerSourceRedeemScriptHex: String(order?.chain?.buyerLockRedeemScriptHex || '').trim(),
          sellerSourceRedeemScriptHex: String(order?.chain?.sellerLockRedeemScriptHex || '').trim(),
          buyerSourceSats: Number(order?.chain?.buyerLockSats || order?.funds?.buyerLockedSats || 0),
          sellerSourceSats: Number(order?.chain?.sellerLockSats || order?.funds?.sellerDepositSats || 0),
          spendSellerSource: true,
          signerRole: 'buyer',
        }).rawtx,
        source: 'order_complete_settlement',
        reservationId: `order_complete_settlement:${order.id}`,
        reservationType: 'order_complete_settlement',
        note: `order_complete:${order.id}`,
        trackOutputs: true,
        requireVisibility: true,
        allowMissingExternalInputs: true,
        allowPendingVisibilityCommit: true,
        rootOnlyBroadcast: true,
      });
      order.chain.settleTxid = completedBroadcast.txid;
      order.chain.completedSettlementTxid = completedBroadcast.txid;
      order.funds.sellerCreditSats = Number(order?.funds?.priceSats || 0);
      order.funds.buyerRefundSats = Number(order?.funds?.buyerDepositSats || 0);
      order.funds.sellerRefundSats = Number(order?.funds?.sellerDepositSats || 0);
      await handleObservedChainRawtx({
        txid: completedBroadcast.txid,
        rawtx: completedBroadcast.rawtx,
        confirmed: false,
        node: 'orders_api.confirm_receipt_settlement_tx',
        firstSeenAt: new Date().toISOString(),
      }, { source: 'orders_api.confirm_receipt_settlement_tx' });
      anchor = { txid: completedBroadcast.txid, rawtx: completedBroadcast.rawtx };
      localTxid = String(completedBroadcast.txid || '').trim();
      }
    } else if (action === 'requestRefund') {
      appendMarketDebug('order_action_stage', { orderId: String(order?.id || ''), action, stage: 'build_refund_request' });
      assertOrderChainValue(order, 'chain.buyerLockTxid', 'Missing buyer lock tx');
      assertOrderChainValue(order, 'chain.sellerLockTxid', 'Missing seller lock tx');
      assertOrderChainValue(order, 'chain.buyerLockRedeemScriptHex', 'Missing buyer lock redeem script');
      assertOrderChainValue(order, 'chain.sellerLockRedeemScriptHex', 'Missing seller lock redeem script');
      const refundConfirmPayloadForSettlement = buildOrderActionAnchorPayload(order, { eventType: 'order_refund_confirm' }, '', null);
      const refundDraft = await wallet.buildOrderSettlementDraft({
        mnemonic,
        mode: 'refunded',
        priceSats: Number(order?.funds?.priceSats || 0),
        buyerSourceTxid: String(order?.chain?.buyerLockTxid || '').trim(),
        buyerSourceVout: Number(order?.chain?.buyerLockVout || 0),
        buyerSourceSats: Number(order?.chain?.buyerLockSats || order?.funds?.buyerLockedSats || 0),
        buyerSourceRedeemScriptHex: String(order?.chain?.buyerLockRedeemScriptHex || '').trim(),
        sellerSourceTxid: String(order?.chain?.sellerLockTxid || '').trim(),
        sellerSourceVout: Number(order?.chain?.sellerLockVout || 0),
        sellerSourceSats: Number(order?.chain?.sellerLockSats || order?.funds?.sellerDepositSats || 0),
        sellerSourceRedeemScriptHex: String(order?.chain?.sellerLockRedeemScriptHex || '').trim(),
        buyerChatPubKey: String(order?.chain?.buyerChatPubKey || '').trim(),
        sellerChatPubKey: String(order?.chain?.sellerChatPubKey || '').trim(),
        buyerRefundAddress: String(order?.chain?.buyerRefundAddress || '').trim(),
        sellerReceiveAddress: String(order?.chain?.sellerReceiveAddress || '').trim(),
        sellerRefundAddress: String(order?.chain?.sellerRefundAddress || '').trim(),
        anchorText: buildAnchorWireText('order_refund_confirm', refundConfirmPayloadForSettlement),
      });
      const refundSettlementFeeInputOutpoints = Array.isArray(refundDraft.feeInputOutpoints)
        ? refundDraft.feeInputOutpoints
        : [];
      order.chain.refundDraftRawtx = wallet.signOrderSettlementDraft({
        mnemonic,
        draftRawtx: refundDraft.rawtx,
        buyerSourceRedeemScriptHex: String(order?.chain?.buyerLockRedeemScriptHex || '').trim(),
        sellerSourceRedeemScriptHex: String(order?.chain?.sellerLockRedeemScriptHex || '').trim(),
        buyerSourceSats: Number(order?.chain?.buyerLockSats || order?.funds?.buyerLockedSats || 0),
        sellerSourceSats: Number(order?.chain?.sellerLockSats || order?.funds?.sellerDepositSats || 0),
        spendSellerSource: true,
        signerRole: 'buyer',
      }).rawtx;
      if (refreshRefundRequestDraft) {
        const existingRefundRequestTxid = String(order?.chain?.refundRequestTxid || '').trim();
        appendMarketDebug('order_refund_request_draft_refreshed_without_rebroadcast', {
          orderId: String(order?.id || ''),
          refundRequestTxid: existingRefundRequestTxid,
          refundDraftRawtxLen: String(order.chain.refundDraftRawtx || '').length,
          feeInputOutpoints: refundSettlementFeeInputOutpoints,
        });
        anchor = {
          txid: existingRefundRequestTxid,
          rawtx: String(order?.chain?.refundRequestRawtx || '').trim(),
          draftRefreshOnly: true,
        };
        localTxid = existingRefundRequestTxid;
      } else {
      const refundRequestNotifyAddresses = [
        String(order?.chain?.sellerReceiveAddress || '').trim(),
        String(order?.chain?.sellerRefundAddress || '').trim(),
      ].filter(Boolean);
      const refundRequestAnchor = await broadcastSignedActionAnchor('', 'buyer', {
        notifyAddresses: refundRequestNotifyAddresses,
        excludeOutpoints: refundSettlementFeeInputOutpoints,
      });
      anchor = refundRequestAnchor;
      order.chain.refundRequestTxid = String(refundRequestAnchor?.txid || '').trim();
      order.chain.refundRequestRawtx = String(refundRequestAnchor?.rawtx || '').trim();
      order.chain.refundFeeContextRawtxs = order.chain.refundRequestRawtx
        ? [order.chain.refundRequestRawtx]
        : [];
      localTxid = order.chain.refundRequestTxid;
      }
    } else if (action === 'confirmRefund') {
      appendMarketDebug('order_action_stage', { orderId: String(order?.id || ''), action, stage: 'broadcast_refund_settlement' });
      assertOrderChainValue(order, 'chain.refundDraftRawtx', 'Missing refund settlement draft');
      const existingSettlementTxid = String(req.body?.settlementTxid || req.body?.refundSettlementTxid || '').trim();
      if (existingSettlementTxid && req.body?.settlementAlreadyBroadcast === true) {
        appendMarketDebug('order_action_stage', {
          orderId: String(order?.id || ''),
          action,
          stage: 'broadcast_refund_anchor_for_existing_settlement',
          settlementTxid: existingSettlementTxid,
        });
        order.chain.settleTxid = existingSettlementTxid;
        order.chain.refundSettlementTxid = existingSettlementTxid;
        order.funds.buyerRefundSats = Number(order?.funds?.priceSats || 0) + Number(order?.funds?.buyerDepositSats || 0);
        order.funds.sellerRefundSats = Number(order?.funds?.sellerDepositSats || 0);
        order.funds.sellerCreditSats = 0;
        const refundConfirmAnchor = await broadcastSignedActionAnchor(existingSettlementTxid, 'seller');
        anchor = refundConfirmAnchor;
        localTxid = String(refundConfirmAnchor?.txid || existingSettlementTxid || '').trim();
      } else {
      const refundBroadcast = await broadcastAndTrackOrderRawtx(req, state, {
        rawtx: wallet.signOrderSettlementDraft({
          mnemonic,
          draftRawtx: String(order?.chain?.refundDraftRawtx || '').trim(),
          buyerSourceRedeemScriptHex: String(order?.chain?.buyerLockRedeemScriptHex || '').trim(),
          sellerSourceRedeemScriptHex: String(order?.chain?.sellerLockRedeemScriptHex || '').trim(),
          buyerSourceSats: Number(order?.chain?.buyerLockSats || order?.funds?.buyerLockedSats || 0),
          sellerSourceSats: Number(order?.chain?.sellerLockSats || order?.funds?.sellerDepositSats || 0),
          spendSellerSource: true,
          signerRole: 'seller',
        }).rawtx,
        source: 'order_refund_settlement',
        reservationId: `order_refund_settlement:${order.id}`,
        reservationType: 'order_refund_settlement',
        note: `order_refund:${order.id}`,
        requireVisibility: true,
      });
      order.chain.settleTxid = refundBroadcast.txid;
      order.chain.refundSettlementTxid = refundBroadcast.txid;
      order.funds.buyerRefundSats = Number(order?.funds?.priceSats || 0) + Number(order?.funds?.buyerDepositSats || 0);
      order.funds.sellerRefundSats = Number(order?.funds?.sellerDepositSats || 0);
      order.funds.sellerCreditSats = 0;
      await handleObservedChainRawtx({
        txid: refundBroadcast.txid,
        rawtx: refundBroadcast.rawtx,
        confirmed: false,
        node: 'orders_api.refund_settlement_tx',
        firstSeenAt: new Date().toISOString(),
      }, { source: 'orders_api.refund_settlement_tx' });
      anchor = { txid: refundBroadcast.txid, rawtx: refundBroadcast.rawtx };
      localTxid = String(refundBroadcast.txid || '').trim();
      }
    } else if (action === 'cancel') {
      appendMarketDebug('order_action_stage', { orderId: String(order?.id || ''), action, stage: 'broadcast_buyer_cancel' });
      assertOrderChainValue(order, 'chain.buyerLockTxid', 'Missing buyer lock tx');
      assertOrderChainValue(order, 'chain.buyerLockRedeemScriptHex', 'Missing buyer lock redeem script');
      const cancelBroadcast = await broadcastAndTrackOrderRawtx(req, state, {
        rawtx: wallet.buildOrderTimeoutCancelTx({
          mnemonic,
          buyerLockTxid: String(order?.chain?.buyerLockTxid || '').trim(),
          buyerLockVout: Number(order?.chain?.buyerLockVout || 0),
          buyerLockSats: Number(order?.funds?.buyerLockedSats || 0),
          buyerLockRedeemScriptHex: String(order?.chain?.buyerLockRedeemScriptHex || '').trim(),
          buyerRefundAddress: String(order?.chain?.buyerRefundAddress || '').trim(),
          timeoutAt: 0,
        }).rawtx,
        source: 'order_cancel_buyer',
        reservationId: `order_cancel_buyer:${order.id}`,
        reservationType: 'order_cancel_buyer',
        note: `order_cancel_buyer:${order.id}`,
        requireVisibility: true,
      });
      order.chain.cancelTxid = cancelBroadcast.txid;
      localTxid = cancelBroadcast.txid;
    } else if (action === 'sellerCancel') {
      appendMarketDebug('order_action_stage', {
        orderId: String(order?.id || ''),
        action,
        stage: 'broadcast_seller_cancel',
        placeTxid: String(order?.chain?.placeTxid || ''),
      });
      assertOrderChainValue(order, 'chain.buyerLockRedeemScriptHex', 'Missing buyer lock redeem script');
      const sellerCancelBroadcast = await broadcastAndTrackOrderRawtx(req, state, {
        rawtx: wallet.buildOrderSellerCancelTx({
          mnemonic,
          buyerLockTxid: String(order?.chain?.buyerLockTxid || '').trim(),
          buyerLockVout: Number(order?.chain?.buyerLockVout || 0),
          buyerLockSats: Number(order?.funds?.buyerLockedSats || 0),
          buyerLockRedeemScriptHex: String(order?.chain?.buyerLockRedeemScriptHex || '').trim(),
          buyerRefundAddress: String(order?.chain?.buyerRefundAddress || '').trim(),
        }).rawtx,
        source: 'order_cancel_seller',
        reservationId: `order_cancel_seller:${order.id}`,
        reservationType: 'order_cancel_seller',
        note: `order_cancel_seller:${order.id}`,
        requireVisibility: true,
      });
      order.chain.cancelTxid = sellerCancelBroadcast.txid;
      localTxid = sellerCancelBroadcast.txid;
    } else if (action === 'timeoutCancel') {
      appendMarketDebug('order_action_stage', { orderId: String(order?.id || ''), action, stage: 'broadcast_timeout_cancel' });
      assertOrderChainValue(order, 'chain.buyerLockTxid', 'Missing buyer lock tx');
      assertOrderChainValue(order, 'chain.buyerLockRedeemScriptHex', 'Missing buyer lock redeem script');
      const timeoutBroadcast = await broadcastAndTrackOrderRawtx(req, state, {
        rawtx: wallet.buildOrderTimeoutCancelTx({
          mnemonic,
          buyerLockTxid: String(order?.chain?.buyerLockTxid || '').trim(),
          buyerLockVout: Number(order?.chain?.buyerLockVout || 0),
          buyerLockSats: Number(order?.funds?.buyerLockedSats || 0),
          buyerLockRedeemScriptHex: String(order?.chain?.buyerLockRedeemScriptHex || '').trim(),
          buyerRefundAddress: String(order?.chain?.buyerRefundAddress || '').trim(),
          timeoutAt: Number(order?.chain?.timeoutAt || 0),
        }).rawtx,
        source: 'order_timeout_cancel',
        reservationId: `order_timeout_cancel:${order.id}`,
        reservationType: 'order_timeout_cancel',
        note: `order_timeout_cancel:${order.id}`,
        requireVisibility: true,
      });
      order.chain.cancelTxid = timeoutBroadcast.txid;
      localTxid = timeoutBroadcast.txid;
    }

    if (!refreshRefundRequestDraft) {
      const next = applyTransition(order, actionMeta.machineAction, {
        transitionId,
        config: orderMachineConfig(),
      });
      Object.assign(order, next);
    }
    order.tip = actionMeta.tip;
    if (localTxid && (action === 'ship' || action === 'requestRefund' || action === 'cancel' || action === 'sellerCancel' || action === 'timeoutCancel')) {
      order.chain.stateAnchorTxid = localTxid;
    }
	    if (localTxid && actionMeta?.eventType) {
	      const actorRole = (new Set(['accept', 'ship', 'confirmRefund', 'sellerCancel'])).has(action) ? 'seller' : 'buyer';
	      const actorKeypair = (() => {
	        try { return wallet.deriveChatKeypairFromMnemonic(mnemonic); } catch (_) { return null; }
	      })();
	      const anchorRow = {
	        ts: new Date().toISOString(),
	        eventType: String(actionMeta.eventType || '').trim(),
	        payload: buildOrderActionAnchorPayload(order, actionMeta, (() => {
	          if (action === 'confirmReceipt') {
	            return String(order?.chain?.completedSettlementTxid || order?.chain?.settleTxid || '').trim();
	          }
	          if (action === 'confirmRefund') {
	            return String(order?.chain?.refundSettlementTxid || order?.chain?.settleTxid || '').trim();
	          }
	          return localTxid;
	        })(), actorKeypair ? {
	          role: actorRole,
	          pubKey: String(actorKeypair.chatPubKey || '').trim(),
	          privateKey: actorKeypair.privateKey,
	        } : null),
	        txid: String(localTxid || '').trim(),
        node: 'local_order_action',
        confirmed: false,
        publicVisible: false,
        merchantId: String(order?.chain?.sellerMerchantId || order?.snapshot?.merchant_id || '').trim(),
        walletId: String(order?.buyerWalletId || '').trim(),
      };
      setPendingAnchorOverlay(state, [...getPendingAnchorOverlay(state), anchorRow].slice(-500));
      persistAnchorEventsAsync([anchorRow], `order_action_${String(actionMeta.eventType || '').trim()}`);
    }
    await orderDomain.emitOrderUpsert(order, {
      producer: 'orders_api.action',
      dedupeKey: `order.upsert:${order.id}:${order.status}:${String(order.transitionIds?.slice(-1)[0] || actionMeta.machineAction)}`,
    });
    appendMarketDebug('order_action_committed', {
      orderId: String(order?.id || ''),
      action: String(action || ''),
      localTxid: String(localTxid || ''),
      nextStatus: String(order?.status || ''),
    });
  } catch (err) {
    const msg = err?.message || 'Order transition rejected';
    appendMarketDebug('order_action_failed', {
      orderId: String(order?.id || ''),
      action: String(action || ''),
      localTxid: String(localTxid || ''),
      error: String(msg || ''),
      code: String(err?.code || ''),
      inputs: Array.isArray(err?.inputs) ? err.inputs.slice(0, 8) : [],
      missingAncestors: Array.isArray(err?.missingAncestors) ? err.missingAncestors.slice(0, 8) : [],
    });
    if (
      err?.code === 'ILLEGAL_ORDER_TRANSITION'
      || err?.code === 'ORDER_ALREADY_TERMINAL'
      || err?.code === 'DUPLICATE_TRANSITION'
      || err?.code === 'CONFIRMATION_GUARD_FAILED'
      || err?.code === 'ORDER_PLACE_UNCONFIRMED'
      || err?.code === 'ORDER_ACTOR_FORBIDDEN'
      || err?.code === 'ORDER_CHAIN_INCOMPLETE'
    ) return fail(res, msg);
    if (err?.code === 'LOCAL_BROADCAST_CONTEXT_INCOMPLETE') {
      const extra = Array.isArray(err?.missingAncestors) && err.missingAncestors.length
        ? ` missingAncestors=${err.missingAncestors.join(',')}`
        : '';
      return fail(res, `${msg}${extra}`);
    }
    return fail(res, msg);
  }

  commitLocalState(state, { writeJson: true, refresh: false });
  return ok(res, state, req, {
    anchorTxid: localTxid || anchor?.txid || null,
    message: actionSuccessMessage,
  });
});

app.post('/api/orders/:id/rebroadcast', walletAuthRequired, async (req, res) => {
  const state = buildProjectionBackedState(req);
  const order = findOrder(state, req.params.id);
  if (!order) return fail(res, 'Order not found', 404);
  const limit = Math.max(1, Math.min(20, Number(req.body?.limit || 12)));
  const requireVisibility = req.body?.requireVisibility !== false;
  const txids = collectOrderRebroadcastTxids(order).slice(0, limit);
  const results = [];
  for (const txid of txids) {
    const row = typeof wallet.getTxContextByTxid === 'function'
      ? wallet.getTxContextByTxid(txid, { includeRawtx: true })
      : null;
    const rawtx = String(row?.rawtx || row?.rawtx_hex || '').trim();
    if (!rawtx) {
      results.push({ txid, rebroadcasted: false, error: 'local rawtx not found' });
      continue;
    }
    try {
      // eslint-disable-next-line no-await-in-loop
      const broadcast = await wallet.broadcastRawTx(rawtx, {
        requireVisibility,
        minDataOutputSat: 0,
        allowedP2shVouts: [0],
      });
      results.push({
        txid,
        rebroadcasted: true,
        successCount: Number(broadcast?.successCount || 0),
        attemptedCount: Number(broadcast?.attemptedCount || 0),
        observed: Boolean(broadcast?.observed),
        observedRelevant: Boolean(broadcast?.observedRelevant),
        observedConfirmed: Boolean(broadcast?.observedConfirmed),
        observedNode: String(broadcast?.observedNode || ''),
        mempoolProofHitCount: Number(broadcast?.mempoolProofHitCount || 0),
        mempoolProofNodes: Array.isArray(broadcast?.mempoolProofNodes) ? broadcast.mempoolProofNodes.slice(0, 8) : [],
      });
    } catch (err) {
      results.push({ txid, rebroadcasted: false, error: String(err?.message || err || 'rebroadcast failed') });
    }
  }
  appendMarketDebug('order_rebroadcast_done', {
    orderId: String(order?.id || ''),
    txids,
    rebroadcastedCount: results.filter((row) => row.rebroadcasted).length,
    missingCount: results.filter((row) => !row.rebroadcasted && row.error === 'local rawtx not found').length,
  });
  const fresh = buildProjectionBackedState(req);
  return ok(res, fresh, req, { orderId: order.id, results });
});

app.post('/api/orders/rebuild-chain-projection', walletAuthRequired, async (req, res) => {
  const state = buildProjectionStateFromSqlite(req);
  const beforeOrders = Array.isArray(state?.orders) ? state.orders.slice() : [];
  const beforeById = new Map(beforeOrders.map((row) => [String(row?.id || '').trim(), row]));
  const orders = rebuildOrdersFromAnchors(state, req, { includePending: false });
  const changedOrders = (Array.isArray(orders) ? orders : []).filter((row) => {
    const orderId = String(row?.id || '').trim();
    const before = beforeById.get(orderId);
    return !before || JSON.stringify(before) !== JSON.stringify(row);
  });
  persistOrderProjectionRowsSync(orders, 'orders_chain_projection_rebuild');
  commitCoreRuntimeProjectionState(state, {
    reason: 'orders_chain_projection_rebuild',
    hydrated: true,
    req,
  });
  commitLocalState(state, { writeJson: true, refresh: false });
  scheduleMappedFrontendBroadcast('order.chain.projection', 'orders_chain_projection_rebuilt', 50, true, 'orders_chain_projection_rebuild', {
    orderCount: Array.isArray(orders) ? orders.length : 0,
    changedCount: changedOrders.length,
    includePending: false,
  });
  appendMarketDebug('orders_chain_projection_rebuilt', {
    beforeCount: beforeOrders.length,
    afterCount: Array.isArray(orders) ? orders.length : 0,
    changedCount: changedOrders.length,
    changedOrderIds: changedOrders.map((row) => String(row?.id || '')).slice(0, 30),
  });
  return ok(res, state, req, {
    orderCount: Array.isArray(orders) ? orders.length : 0,
    changedCount: changedOrders.length,
    changedOrderIds: changedOrders.map((row) => String(row?.id || '')).slice(0, 30),
  });
});

app.post('/api/orders/:id/refresh-shipment-signature', walletAuthRequired, async (req, res) => {
  const state = buildProjectionStateFromSqlite(req);
  const order = findOrder(state, req.params.id);
  if (!order) return fail(res, 'Order not found', 404);
  migrateOrderModel(order);
  if (String(order.status || '') !== ORDER_STATUS.SHIPPED) return fail(res, 'Order must be SHIPPED to refresh shipment signature', 409);
  const mnemonic = wallet.getMnemonicFromPassword(getSessionPassword(req));
  const actorIdentity = {
    ...getCurrentWalletIdentity(state, req),
    receiveAddress: (() => {
      try { return String(wallet.getReceiveAddress() || '').trim(); } catch (_) { return ''; }
    })(),
    chatPubKey: (() => {
      try { return String(wallet.deriveChatPublicKeyFromMnemonic(mnemonic) || '').trim(); } catch (_) { return ''; }
    })(),
  };
  try {
    assertOrderActorAllowed(order, 'ship', actorIdentity);
    assertOrderChainValue(order, 'chain.buyerLockTxid', 'Missing buyer lock tx');
    assertOrderChainValue(order, 'chain.sellerLockTxid', 'Missing seller lock tx');
    assertOrderChainValue(order, 'chain.buyerLockRedeemScriptHex', 'Missing buyer lock redeem script');
    assertOrderChainValue(order, 'chain.sellerLockRedeemScriptHex', 'Missing seller lock redeem script');
    const completedDraft = await wallet.buildOrderSettlementDraft({
      mnemonic,
      mode: 'completed',
      priceSats: Number(order?.funds?.priceSats || 0),
      buyerSourceTxid: String(order?.chain?.buyerLockTxid || '').trim(),
      buyerSourceVout: Number(order?.chain?.buyerLockVout || 0),
      buyerSourceSats: Number(order?.chain?.buyerLockSats || order?.funds?.buyerLockedSats || 0),
      buyerSourceRedeemScriptHex: String(order?.chain?.buyerLockRedeemScriptHex || '').trim(),
      sellerSourceTxid: String(order?.chain?.sellerLockTxid || '').trim(),
      sellerSourceVout: Number(order?.chain?.sellerLockVout || 0),
      sellerSourceSats: Number(order?.chain?.sellerLockSats || order?.funds?.sellerDepositSats || 0),
      sellerSourceRedeemScriptHex: String(order?.chain?.sellerLockRedeemScriptHex || '').trim(),
      buyerChatPubKey: String(order?.chain?.buyerChatPubKey || '').trim(),
      sellerChatPubKey: String(order?.chain?.sellerChatPubKey || '').trim(),
      buyerRefundAddress: String(order?.chain?.buyerRefundAddress || '').trim(),
      sellerReceiveAddress: String(order?.chain?.sellerReceiveAddress || '').trim(),
      sellerRefundAddress: String(order?.chain?.sellerRefundAddress || '').trim(),
      spendSellerSource: true,
      preferredFeeOutpoints: [`${String(order?.chain?.sellerSettlementFeeTxid || '').trim()}:${Number(order?.chain?.sellerSettlementFeeVout || 0)}`],
    });
    order.chain.completedDraftRawtx = wallet.signOrderSettlementDraft({
      mnemonic,
      draftRawtx: String(completedDraft.rawtx || '').trim(),
      buyerSourceRedeemScriptHex: String(order?.chain?.buyerLockRedeemScriptHex || '').trim(),
      sellerSourceRedeemScriptHex: String(order?.chain?.sellerLockRedeemScriptHex || '').trim(),
      buyerSourceSats: Number(order?.chain?.buyerLockSats || order?.funds?.buyerLockedSats || 0),
      sellerSourceSats: Number(order?.chain?.sellerLockSats || order?.funds?.sellerDepositSats || 0),
      spendSellerSource: true,
      signerRole: 'seller',
    }).rawtx;
    const sellerKeypair = wallet.deriveChatKeypairFromMnemonic(mnemonic);
    const payload = buildOrderActionAnchorPayload(order, ORDER_ACTION_META.ship, '', {
      role: 'seller',
      pubKey: String(sellerKeypair.chatPubKey || '').trim(),
      privateKey: sellerKeypair.privateKey,
    });
    const shipAnchor = await tryAnchorEvent(req, state, 'order_ship', payload, {
      includeUnconfirmed: true,
      trackOutputs: true,
      notifyAddresses: [String(order?.chain?.buyerRefundAddress || '').trim()].filter(Boolean),
      excludeOutpoints: completedDraft.feeInputOutpoints,
    });
    if (shipAnchor?.error) return fail(res, String(shipAnchor.error || 'Shipment signature refresh anchor failed'));
    order.chain.shipTxid = String(shipAnchor?.txid || order.chain.shipTxid || '').trim();
    order.chain.stateAnchorTxid = order.chain.shipTxid || order.chain.stateAnchorTxid;
    order.updatedAt = Date.now();
    await orderDomain.emitOrderUpsert(order, {
      producer: 'orders_api.refresh_shipment_signature',
      dedupeKey: `order.upsert:${order.id}:${order.status}:refresh_ship:${String(order.chain.shipTxid || '')}`,
    });
    commitLocalState(state, { writeJson: true, refresh: false });
    return ok(res, state, req, {
      orderId: order.id,
      anchorTxid: order.chain.shipTxid || null,
      completedDraftRawtxLen: String(order.chain.completedDraftRawtx || '').length,
      feeSat: Number(completedDraft.feeSat || 0),
    });
  } catch (err) {
    return fail(res, String(err?.message || err || 'Refresh shipment signature failed'));
  }
});


app.post('/api/changes/push', walletAuthRequired, async (req, res) => {
  const password = String(req.body?.password || '');
  if (!password) return fail(res, 'Password is required');
  try {
    wallet.getMnemonicFromPassword(password);
  } catch (err) {
    return fail(res, err.message || 'Password invalid', 401);
  }

  const state = buildProjectionStateFromSqlite(req);
  rebuildPendingQueueFromLocalState(state);
  for (const item of getPendingQueueSorted(state, false)) {
    item.status = 'queued';
    item.queuedAt = new Date().toISOString();
    delete item.lastError;
    delete item.failedAt;
  }
  appendMarketDebug('push_start', {
    queueSize: Array.isArray(state.localChanges?.queue) ? state.localChanges.queue.length : 0,
    pending: getPendingQueueSorted(state, false).length,
  });
  await persistLocalStateSnapshotDirect(state, 'push_start_queue');
  processLocalChangeQueueInBackground(req, password).catch((err) => {
    setLocalChangePushProgress({
      active: false,
      status: 'failed',
      stage: 'push_worker_crashed',
      currentLabel: 'failed',
      currentDetail: String(err?.message || 'push worker crashed'),
      lastError: String(err?.message || 'push worker crashed'),
      finishedAt: new Date().toISOString(),
    });
    appendMarketDebug('push_worker_crashed', {
      message: String(err?.message || 'push worker crashed'),
    });
  });

  appendMarketDebug('push_done', {
    uploaded: 0,
    failed: 0,
    totalFeeSat: 0,
    remaining: (state.localChanges?.queue || []).filter((q) => q.status === 'pending' || q.status === 'queued' || q.status === 'broadcasted').length,
    background: true,
  });
  return ok(res, state, req, {
    uploaded: 0,
    failed: 0,
    failedItems: [],
    remaining: (state.localChanges?.queue || []).filter((q) => q.status === 'pending' || q.status === 'queued' || q.status === 'broadcasted').length,
    totalFeeSat: 0,
    totalFeeBsv: 0,
    background: true,
  });
});

