app.post('/api/changes/recover', walletAuthRequired, async (req, res) => {
  const changeId = String(req.body?.changeId || '').trim();
  if (!changeId) return fail(res, 'changeId is required');
  const state = buildProjectionBackedState(req);
  const queue = Array.isArray(state.localChanges?.queue) ? state.localChanges.queue : [];
  const target = queue.find((q) => String(q?.id || '') === changeId);
  if (!target) return fail(res, 'Change not found', 404);
  const targetTxid = String(target?.txid || '').trim();
  if (!targetTxid) return fail(res, 'Change has no broadcast tx', 400);
  if (!isRecoverableLocalBroadcast(state, target)) {
    return fail(res, 'Broadcast is still waiting for listener/sync confirmation; cannot recover locally', 409);
  }

  const cancelIds = collectDependentUnconfirmedChangeIds(queue, [changeId]);
  const cancelledTxids = new Set();
  for (const item of queue) {
    const id = String(item?.id || '').trim();
    if (!cancelIds.has(id)) continue;
    const txid = String(item?.txid || '').trim();
    if (txid) cancelledTxids.add(txid);
    resetQueueItemForRecovery(item);
  }
  setPendingAnchorOverlay(state, getPendingAnchorOverlay(state).filter((a) => {
    const txid = String(a?.txid || '').trim();
    if (!txid || !cancelledTxids.has(txid)) return true;
    return a?.confirmed === true;
  }));
  applyPendingChangesOnTop(state);
  const keepRawTxs = queue
    .filter((q) => {
      const txid = String(q?.txid || '').trim();
      return !cancelIds.has(String(q?.id || '').trim())
        && !!txid
        && !wallet.isTxConfirmedInSpvIndex(txid);
    })
    .sort((a, b) => Number(a?.seq || 0) - Number(b?.seq || 0))
    .map((q) => String(q?.rawtx || '').trim())
    .filter(Boolean);
  appendMarketDebug('wallet_queue_rebuild_skipped_policy', {
    source: 'push_item_recovered',
    keepRawTxCount: keepRawTxs.length,
    policy: 'manual_recovery_only',
  });
  commitChatRuntimeState(state, { writeJson: true, refresh: true });
  appendMarketDebug('push_item_recovered', {
    changeId,
    recoveredCount: cancelIds.size,
    cancelledTxids: Array.from(cancelledTxids),
  });
  const preview = buildPendingPreview(state);
  return ok(res, state, req, {
    recovered: true,
    recoveredCount: cancelIds.size,
    pendingUploads: preview.pendingUploads,
    pendingDetails: preview.pendingDetails,
    recoverableDetails: preview.recoverableDetails,
  });
});

app.post('/api/changes/discard-local', walletAuthRequired, async (req, res) => {
  const changeIds = Array.isArray(req.body?.changeIds)
    ? req.body.changeIds.map((id) => String(id || '').trim()).filter(Boolean)
    : [];
  if (req.body?.confirmDiscardLocalChanges !== true) return fail(res, 'confirmDiscardLocalChanges is required');
  const allowRecoverable = req.body?.confirmDiscardRecoverable === true;
  const resetOnly = req.body?.confirmResetLocalState === true && changeIds.length === 0;
  if (!changeIds.length && !resetOnly) return fail(res, 'changeIds is required');
  const password = String(req.body?.password || '');
  if (password) {
    try {
      wallet.getMnemonicFromPassword(password);
    } catch (err) {
      return fail(res, err.message || 'Password invalid', 401);
    }
  }
  const state = buildProjectionBackedState(req);
  if (resetOnly) {
    buildPendingPreview(state);
    await localStateDomain.resetLocalState('main');
    state.localChanges = { seq: 1, queue: [] };
    state.recentRawtxs = [];
    state.pendingAnchors = [];
    const nowIso = new Date().toISOString();
    if (state.profile && typeof state.profile === 'object') {
      state.profile.localStatus = 'synced';
      state.profile.localUpdatedAt = String(state.profile.localUpdatedAt || nowIso);
    }
    if (Array.isArray(state.users)) {
      state.users.forEach((row) => {
        if (!row || typeof row !== 'object') return;
        if (String(row.id || '') !== 'buyer') return;
        row.localStatus = 'synced';
        row.localUpdatedAt = String(row.localUpdatedAt || nowIso);
      });
    }
    if (Array.isArray(state.categories)) {
      state.categories.forEach((row) => {
        if (!row || typeof row !== 'object') return;
        if (String(row.localStatus || '') === 'synced') return;
        row.localStatus = 'synced';
        row.localUpdatedAt = String(row.localUpdatedAt || nowIso);
      });
    }
    if (Array.isArray(state.products)) {
      state.products.forEach((row) => {
        if (!row || typeof row !== 'object') return;
        if (String(row.localStatus || '') === 'synced') return;
        row.localStatus = 'synced';
        row.localUpdatedAt = String(row.localUpdatedAt || nowIso);
      });
    }
    await persistLocalStateSnapshotDirect(state, 'discard_local_changes_reset_only');
    appendMarketDebug('local_changes_discarded', {
      requested: [],
      allowRecoverable,
      resetLocalState: true,
      resetOnly: true,
      removed: [],
      skipped: [],
      cancelledTxids: [],
    });
    return ok(res, state, req, {
      discarded: 0,
      skipped: [],
      pendingUploads: 0,
      pendingDetails: [],
      recoverableDetails: [],
    });
  }
  const queue = Array.isArray(state.localChanges?.queue) ? state.localChanges.queue : [];
  const idSet = new Set(changeIds);
  const removedItems = [];
  const skippedItems = [];
  const cancelledTxids = new Set();
  state.localChanges.queue = queue.filter((item) => {
    const id = String(item?.id || '').trim();
    if (!idSet.has(id)) return true;
    const status = String(item?.status || '').trim().toLowerCase();
    const txid = String(item?.txid || '').trim();
    if (status === 'pending' && !txid) {
      removedItems.push(item);
      return false;
    }
    if (allowRecoverable && ['broadcasted', 'anchored'].includes(status) && txid) {
      if (!isRecoverableLocalBroadcast(state, item)) {
        skippedItems.push({ id, status, txid, reason: 'broadcast_waiting_confirmation_not_recoverable' });
        return true;
      }
      cancelledTxids.add(txid);
      removedItems.push(item);
      return false;
    }
    {
      skippedItems.push({ id, status, txid, reason: 'not_unbroadcast_pending' });
      return true;
    }
  });
  const nowIso = new Date().toISOString();
  for (const item of removedItems) {
    const targetType = String(item?.targetType || '').trim();
    const targetId = String(item?.targetId || '').trim();
    if (!targetId) continue;
    if (targetType === 'product' && Array.isArray(state.products)) {
      const idx = state.products.findIndex((p) => String(p?.id || '') === targetId);
      const row = idx >= 0 ? state.products[idx] : null;
      if (row) {
        const eventType = String(item?.eventType || '');
        if (eventType === 'product_add' && String(row.localStatus || '') === 'new') {
          state.products.splice(idx, 1);
          continue;
        }
        row.localStatus = 'synced';
        row.localUpdatedAt = nowIso;
        const rowMerchantId = sanitizeMerchantId(row.merchantId || '');
        const currentMerchantId = sanitizeMerchantId(state.currentMerchantId || '');
        if (rowMerchantId && currentMerchantId && rowMerchantId !== currentMerchantId) {
          row.ownedByCurrentWallet = false;
        }
      }
    }
    if (targetType === 'category' && Array.isArray(state.categories)) {
      const idx = state.categories.findIndex((c) => String(c?.id || '') === targetId);
      const row = idx >= 0 ? state.categories[idx] : null;
      if (row) {
        const eventType = String(item?.eventType || '');
        if (eventType === 'category_add' && String(row.localStatus || '') === 'new') {
          state.categories.splice(idx, 1);
          continue;
        }
        row.localStatus = 'synced';
        row.localUpdatedAt = nowIso;
        const rowMerchantId = sanitizeMerchantId(row.merchantId || '');
        const currentMerchantId = sanitizeMerchantId(state.currentMerchantId || '');
        if (rowMerchantId && currentMerchantId && rowMerchantId !== currentMerchantId) {
          row.ownedByCurrentWallet = false;
        }
      }
    }
    const reservationId = String(item?.id || '').trim();
    if (reservationId) {
      void walletTxDomain.releaseReservation(reservationId, {
        reason: 'discard_local_change',
        producer: 'discard_local_changes',
        dedupeKey: `wallet_tx.release:${reservationId}:discard_local_change`,
      }).catch(() => {});
    }
  }
  if (cancelledTxids.size > 0) {
    setPendingAnchorOverlay(state, getPendingAnchorOverlay(state).filter((a) => {
      const txid = String(a?.txid || '').trim();
      if (!txid || !cancelledTxids.has(txid)) return true;
      return a?.confirmed === true;
    }));
    dropRecentRawtxsByTxids(state, cancelledTxids, { persist: false });
  }
  await persistLocalStateSnapshotDirect(state, 'discard_local_changes');
  if (req.body?.confirmResetLocalState === true && Array.isArray(state.localChanges?.queue) && state.localChanges.queue.length === 0) {
    await localStateDomain.resetLocalState('main');
    state.localChanges = { seq: 1, queue: [] };
    state.recentRawtxs = [];
    state.pendingAnchors = [];
    getPublicViewCacheService().invalidateStateLiteSnapshotCache('discard_local_changes_reset_local_state');
  }
  appendMarketDebug('local_changes_discarded', {
    requested: changeIds,
    allowRecoverable,
    resetLocalState: req.body?.confirmResetLocalState === true,
    removed: removedItems.map((item) => ({
      id: String(item?.id || ''),
      eventType: String(item?.eventType || ''),
      targetType: String(item?.targetType || ''),
      targetId: String(item?.targetId || ''),
      txid: String(item?.txid || ''),
    })),
    skipped: skippedItems,
    cancelledTxids: Array.from(cancelledTxids),
  });
  const preview = buildPendingPreview(state);
  return ok(res, state, req, {
    discarded: removedItems.length,
    skipped: skippedItems,
    pendingUploads: preview.pendingUploads,
    pendingDetails: preview.pendingDetails,
    recoverableDetails: preview.recoverableDetails,
  });
});

function isLoopbackRequest(req) {
  const candidates = [
    String(req?.ip || '').trim(),
    String(req?.socket?.remoteAddress || '').trim(),
    String(req?.connection?.remoteAddress || '').trim(),
  ].filter(Boolean);
  return candidates.some((value) => (
    value === '127.0.0.1'
    || value === '::1'
    || value === '::ffff:127.0.0.1'
  ));
}

function isReadOnlySqlStatement(sql) {
  const normalized = String(sql || '')
    .replace(/^\uFEFF/, '')
    .replace(/\/\*[\s\S]*?\*\//g, ' ')
    .replace(/--.*$/gm, ' ')
    .trim()
    .toLowerCase();
  if (!normalized) return false;
  if (normalized.includes(';')) return false;
  return /^(select|with|pragma|explain|values)\b/.test(normalized);
}

if (ENABLE_TEST_SQL_API) {
  app.post('/api/test/sql', async (req, res) => {
    if (!isLoopbackRequest(req)) {
      return res.status(403).json({
        success: false,
        error: 'test sql api is restricted to localhost',
      });
    }
    const sql = String(req.body?.sql || '');
    const params = Array.isArray(req.body?.params) ? req.body.params : [];
    if (!isReadOnlySqlStatement(sql)) {
      return res.status(400).json({
        success: false,
        error: 'only single-statement read-only sql is allowed',
      });
    }
    try {
      const startedAt = Date.now();
      const db = marketDb.openReadDb();
      try {
        const stmt = db.prepare(sql);
        const rows = stmt.all(...params);
        return res.json({
          success: true,
          dbFile: marketDb.getDbFilePath(),
          elapsedMs: Date.now() - startedAt,
          rowCount: Array.isArray(rows) ? rows.length : 0,
          rows: Array.isArray(rows) ? rows : [],
        });
      } finally {
        try { db.close(); } catch (_) {}
      }
    } catch (error) {
      return res.status(500).json({
        success: false,
        error: String(error?.message || error || 'test sql failed'),
      });
    }
  });
}

