function getLocalWalletIdSafe() {
  try {
    return String(wallet.getWalletState()?.walletId || '').trim();
  } catch (_) {
    return '';
  }
}

function getLocalOrderIdentitySafe() {
  const identity = {
    walletIds: [],
    merchantId: '',
    receiveAddress: '',
    chatPubKey: '',
  };
  const addWalletId = (value) => {
    const safe = String(value || '').trim();
    if (safe && !identity.walletIds.includes(safe)) identity.walletIds.push(safe);
  };
  try {
    addWalletId(wallet.getWalletState()?.walletId);
  } catch (_) {}
  try {
    const profile = loadProfileSnapshotFromSqlite();
    identity.merchantId = sanitizeMerchantId(
      profile?.merchantId
      || profile?.merchant_id
      || runtimeProjectionState?.currentMerchantId
      || '',
    );
    addWalletId(profile?.walletId);
    if (identity.merchantId) addWalletId(walletIdByMerchant(identity.merchantId));
  } catch (_) {}
  try {
    identity.receiveAddress = String(wallet.getReceiveAddress() || '').trim();
  } catch (_) {}
  try {
    const runtimePassword = getRuntimeWalletPassword();
    if (runtimePassword) {
      const mnemonic = wallet.getMnemonicFromPassword(runtimePassword);
      identity.chatPubKey = String(wallet.deriveChatPublicKeyFromMnemonic(mnemonic) || '').trim();
    }
  } catch (_) {}
  return identity;
}

function anchorEventFamily(eventType = '') {
  const safeType = String(eventType || '').trim();
  if (safeType === 'wallet_key_bind') return 'chat';
  if (/^order_/i.test(safeType)) return 'order';
  if (/^chat_/i.test(safeType)) return 'chat';
  if (/^(profile_|category_|product_)/i.test(safeType)) return 'catalog';
  if (/^drive_/i.test(safeType)) return 'drive';
  return safeType ? 'anchor' : '';
}

function listAnchorTargetModules(eventType = '', payload = {}) {
  const safeType = String(eventType || '').trim();
  const modules = new Set();
  const family = anchorEventFamily(safeType);
  if (family) modules.add(family);
  if (/^order_/i.test(safeType)) modules.add('wallet');
  return Array.from(modules);
}

function orderAnchorMatchesLocalContext(eventType = '', payload = {}, txid = '') {
  if (!/^order_/i.test(String(eventType || '').trim())) return false;
  const localIdentity = getLocalOrderIdentitySafe();
  const walletIds = [
    getOrderPayloadValue(payload, 'bw', 'buyerWalletId'),
    getOrderPayloadValue(payload, 'sw', 'sellerWalletId'),
    getOrderPayloadValue(payload, 'walletId'),
    getOrderPayloadValue(payload, 'fromWalletId'),
    getOrderPayloadValue(payload, 'toWalletId'),
  ].map((value) => String(value || '').trim()).filter(Boolean);
  if (localIdentity.walletIds.some((walletId) => walletIds.includes(walletId))) return true;

  const merchantIds = [
    getOrderPayloadValue(payload, 'bm', 'buyerMerchantId'),
    getOrderPayloadValue(payload, 'sm', 'sellerMerchantId', 'merchantId'),
    getOrderPayloadValue(payload, 'fromMerchantId'),
    getOrderPayloadValue(payload, 'toMerchantId'),
  ].map((value) => sanitizeMerchantId(value)).filter(Boolean);
  if (localIdentity.merchantId && merchantIds.includes(localIdentity.merchantId)) return true;
  const productId = String(getOrderPayloadValue(payload, 'pid', 'productId', 'product_id') || '').trim();
  if (productId && localIdentity.merchantId) {
    try {
      const state = buildProjectionBackedState(buildRuntimeAuthReq());
      const product = (Array.isArray(state?.products) ? state.products : [])
        .find((row) => String(row?.id || row?.product_id || '').trim() === productId);
      const productMerchantId = sanitizeMerchantId(product?.merchantId || product?.merchant_id || product?.merchant);
      if (product && productMerchantId === localIdentity.merchantId) return true;
    } catch (_) {}
  }

  const addresses = [
    getOrderPayloadValue(payload, 'br', 'buyerRefundAddress'),
    getOrderPayloadValue(payload, 'sr', 'sellerReceiveAddress'),
    getOrderPayloadValue(payload, 'sf', 'sellerRefundAddress'),
    getOrderPayloadValue(payload, 'sa', 'sellerReceiveAddress'),
    getOrderPayloadValue(payload, 'receiveAddress'),
    getOrderPayloadValue(payload, 'refundAddress'),
  ].map((value) => String(value || '').trim()).filter(Boolean);
  if (localIdentity.receiveAddress && addresses.includes(localIdentity.receiveAddress)) return true;

  const chatPubKeys = [
    getOrderPayloadValue(payload, 'bp', 'buyerChatPubKey'),
    getOrderPayloadValue(payload, 'sp', 'sellerChatPubKey'),
    getOrderPayloadValue(payload, 'ap', 'actorPubKey'),
    getOrderPayloadValue(payload, 'actorChatPubKey'),
  ].map((value) => String(value || '').trim()).filter(Boolean);
  if (localIdentity.chatPubKey && chatPubKeys.includes(localIdentity.chatPubKey)) return true;

  const placeTxid = String(getOrderPayloadValue(payload, 'pt', 'placeTxid') || txid || '').trim().toLowerCase();
  const orderId = String(
    getOrderPayloadValue(payload, 'orderId', 'id')
    || (placeTxid && /^[0-9a-f]{64}$/i.test(placeTxid) ? `order:${placeTxid}` : '')
  ).trim();
  if (!orderId && !placeTxid) return false;
  try {
    const dbFile = marketDb.getDbFilePath();
    if (!fs.existsSync(dbFile)) return false;
    const db = marketDb.openReadDb();
    try {
      const projected = orderId
        ? db.prepare('SELECT 1 AS found FROM order_projection WHERE order_id = ? LIMIT 1').get(orderId)
        : null;
      if (projected?.found) return true;
      const likeNeedle = placeTxid || orderId;
      if (!likeNeedle) return false;
      const anchored = db.prepare(`
        SELECT 1 AS found
        FROM anchor_events
        WHERE event_type LIKE 'order_%'
          AND (txid = ? OR entity_id = ? OR payload_json LIKE ?)
        LIMIT 1
      `).get(placeTxid, orderId, `%${likeNeedle}%`);
      return Boolean(anchored?.found);
    } finally {
      db.close();
    }
  } catch (_) {
    return false;
  }
}

function chatAnchorMatchesLocalContext(payload = {}) {
  const safePayload = payload && typeof payload === 'object' ? payload : {};
  const localIdentity = getLocalOrderIdentitySafe();
  const localWalletIds = Array.from(new Set([
    getLocalWalletIdSafe(),
    ...(Array.isArray(localIdentity.walletIds) ? localIdentity.walletIds : []),
  ].map((value) => String(value || '').trim()).filter(Boolean)));
  const payloadWalletIds = [
    safePayload.selfWalletId,
    safePayload.peerWalletId,
    safePayload.fromWalletId,
    safePayload.toWalletId,
    safePayload.walletId,
  ].map((value) => String(value || '').trim()).filter(Boolean);
  if (localWalletIds.some((walletId) => payloadWalletIds.includes(walletId))) return true;

  const localChatPubKey = String(localIdentity.chatPubKey || '').trim();
  const payloadPubKeys = [
    safePayload.selfPubKey,
    safePayload.peerPubKey,
    safePayload.fromPubKey,
    safePayload.toPubKey,
    safePayload.pubKey,
  ].map((value) => String(value || '').trim()).filter(Boolean);
  if (localChatPubKey && payloadPubKeys.includes(localChatPubKey)) return true;

  appendMarketDebug('chat_anchor_relevance_miss', {
    localWalletIds,
    hasLocalChatPubKey: Boolean(localChatPubKey),
    payloadWalletIds,
    hasPayloadPubKeys: payloadPubKeys.length > 0,
    msgId: String(safePayload.msgId || ''),
    orderId: String(safePayload.orderId || ''),
  });
  return false;
}

function shouldPersistObservedAnchor(eventType = '', payload = {}, txid = '') {
  const safeType = String(eventType || '').trim();
  if (/^order_/i.test(safeType)) return isSupportedOrderAnchorPayload(safeType, payload) && orderAnchorMatchesLocalContext(safeType, payload, txid);
  if (safeType === 'wallet_key_bind') return true;
  if (/^chat_/i.test(safeType)) return chatAnchorMatchesLocalContext(payload);
  if (/^(profile_|category_|product_|drive_)/i.test(safeType)) return true;
  return false;
}

function orderPayloadProtocolVersion(payload = {}) {
  const version = Number(getOrderPayloadValue(payload, 'v', 'orderProtocolVersion') || 0);
  return Number.isFinite(version) ? version : 0;
}

function isSupportedOrderAnchorPayload(eventType = '', payload = {}) {
  if (!/^order_/i.test(String(eventType || '').trim())) return true;
  return orderPayloadProtocolVersion(payload) === 3;
}

function pruneLegacyOrderDataSync(options = {}) {
  const dryRun = options.dryRun === true;
  const keepVersion = Math.max(1, Number(options.keepVersion || 3));
  const result = {
    dryRun,
    keepVersion,
    legacyOrderIds: [],
    legacyAnchorTxids: [],
    legacyTxContextTxids: [],
    deletedOrderProjectionCount: 0,
    deletedAnchorEventCount: 0,
    deletedTxContextCount: 0,
  };
  if (!DatabaseSync) return result;
  const dbFile = marketDb.getDbFilePath();
  if (!dbFile || !fs.existsSync(dbFile)) return result;
  let db = null;
  const deleteByValues = (table, column, values) => {
    const list = Array.from(new Set(values.map((value) => String(value || '').trim()).filter(Boolean)));
    if (dryRun || list.length <= 0) return 0;
    let count = 0;
    for (let i = 0; i < list.length; i += 200) {
      const chunk = list.slice(i, i + 200);
      const stmt = db.prepare(`DELETE FROM ${table} WHERE ${column} IN (${chunk.map(() => '?').join(',')})`);
      count += Number(stmt.run(...chunk)?.changes || 0);
    }
    return count;
  };
  try {
    db = new DatabaseSync(dbFile);
    const legacyOrderIds = new Set();
    const legacyAnchorEventIds = new Set();
    const legacyAnchorTxids = new Set();
    const legacyTxContextTxids = new Set();
    const projectionRows = db.prepare(`
      SELECT order_id, payload_json
      FROM order_projection
    `).all();
    for (const row of projectionRows) {
      let payload = {};
      try { payload = JSON.parse(String(row?.payload_json || '{}')); } catch (_) {}
      const version = orderPayloadProtocolVersion(payload?.chain || payload);
      if (version !== keepVersion) legacyOrderIds.add(String(row?.order_id || '').trim());
    }
    const anchorRows = db.prepare(`
      SELECT event_id, txid, payload_json
      FROM anchor_events
      WHERE event_type LIKE 'order_%'
    `).all();
    for (const row of anchorRows) {
      let payload = {};
      try { payload = JSON.parse(String(row?.payload_json || '{}')); } catch (_) {}
      const version = orderPayloadProtocolVersion(payload);
      if (version === keepVersion) continue;
      legacyAnchorEventIds.add(Number(row?.event_id || 0));
      const txid = String(row?.txid || '').trim().toLowerCase();
      if (/^[0-9a-f]{64}$/i.test(txid)) legacyAnchorTxids.add(txid);
      const orderId = deriveOrderIdFromAnchorRow({ eventType: 'order_place', txid, payload });
      if (orderId) legacyOrderIds.add(orderId);
    }
    const txRows = db.prepare(`
      SELECT txid, rawtx_hex AS rawtx
      FROM tx_contexts
      WHERE rawtx_hex <> ''
        AND instr(lower(rawtx_hex), '424d4d4b54327c6f726465725f') > 0
    `).all();
    for (const row of txRows) {
      const txid = String(row?.txid || '').trim().toLowerCase();
      const rawtx = String(row?.rawtx || '').trim();
      if (!/^[0-9a-f]{64}$/i.test(txid) || !rawtx || !bsv || typeof bsv.Transaction !== 'function') continue;
      let tx = null;
      try { tx = new bsv.Transaction(rawtx); } catch (_) { continue; }
      for (const output of (Array.isArray(tx?.outputs) ? tx.outputs : [])) {
        const parsed = parseAnchorFromOutput(output)?.parsed || null;
        const eventType = String(parsed?.eventType || '').trim();
        if (!/^order_/i.test(eventType)) continue;
        const payload = parsed?.payload && typeof parsed.payload === 'object' ? parsed.payload : {};
        if (orderPayloadProtocolVersion(payload) !== keepVersion) {
          legacyTxContextTxids.add(txid);
        }
        break;
      }
    }
    result.legacyOrderIds = Array.from(legacyOrderIds);
    result.legacyAnchorTxids = Array.from(legacyAnchorTxids);
    result.legacyTxContextTxids = Array.from(new Set([...legacyAnchorTxids, ...legacyTxContextTxids]));
    result.deletedOrderProjectionCount = deleteByValues('order_projection', 'order_id', result.legacyOrderIds);
    result.deletedAnchorEventCount = deleteByValues('anchor_events', 'event_id', Array.from(legacyAnchorEventIds));
    result.deletedTxContextCount = deleteByValues('tx_contexts', 'txid', result.legacyTxContextTxids);
    if (!dryRun) {
      result.deletedPendingAnchorCount = Number(db.prepare(`
        DELETE FROM pending_anchor_projection
        WHERE event_type LIKE 'order_%'
          AND txid IN (${result.legacyAnchorTxids.length ? result.legacyAnchorTxids.map(() => '?').join(',') : "''"})
      `).run(...result.legacyAnchorTxids)?.changes || 0);
      result.deletedRecentRawtxCount = Number(db.prepare(`
        DELETE FROM recent_rawtx_projection
        WHERE event_type LIKE 'order_%'
          AND txid IN (${result.legacyAnchorTxids.length ? result.legacyAnchorTxids.map(() => '?').join(',') : "''"})
      `).run(...result.legacyAnchorTxids)?.changes || 0);
    }
  } finally {
    try { db?.close?.(); } catch (_) {}
  }
  return result;
}

async function handleObservedChainRawtx(payload = {}, meta = {}) {
  const rawtx = String(payload?.rawtx || '').trim();
  if (!/^[0-9a-f]+$/i.test(rawtx) || rawtx.length % 2 !== 0) return;
  let tx = null;
  try {
    tx = new bsv.Transaction(rawtx);
  } catch (_) {
    return;
  }
  const txid = String(payload?.txid || tx?.id || '').trim().toLowerCase();
  if (!/^[0-9a-f]{64}$/i.test(txid)) return;
  const confirmed = payload?.confirmed === true;
  const dedupeKey = `${txid}:${confirmed ? 'confirmed' : 'mempool'}`;
  const nowMs = Date.now();
  for (const [key, seenAtMs] of recentObservedChainRawtxKeys.entries()) {
    if ((nowMs - Number(seenAtMs || 0)) > 10 * 60 * 1000) recentObservedChainRawtxKeys.delete(key);
  }
  if (recentObservedChainRawtxKeys.has(dedupeKey)) {
    appendMarketDebug('chain_rawtx_duplicate_suppressed', {
      txid,
      confirmed,
      sourceNode: String(payload?.node || meta?.source || 'chain.rawtx.seen').trim(),
    });
    return;
  }
  recentObservedChainRawtxKeys.set(dedupeKey, nowMs);
  const sourceNode = String(payload?.node || meta?.source || 'chain.rawtx.seen').trim();
  const rows = [];
  const parsedEvents = [];
  const outputs = Array.isArray(tx?.outputs) ? tx.outputs : [];
  for (let vout = 0; vout < outputs.length; vout += 1) {
    const parsed = parseAnchorFromOutput(outputs[vout])?.parsed || null;
    const eventType = String(parsed?.eventType || '').trim();
    if (!eventType) continue;
    const ts = String(payload?.firstSeenAt || meta?.ts || new Date().toISOString());
    const normalizedPayload = normalizeEventPayload(eventType, parsed.payload || {}, ts);
    const modules = listAnchorTargetModules(eventType, normalizedPayload);
    const relevant = shouldPersistObservedAnchor(eventType, normalizedPayload, txid);
    parsedEvents.push({ eventType, vout, modules, relevant });
    appendMarketDebug('chain_rawtx_anchor_routed', {
      txid,
      eventType,
      vout,
      modules,
      relevant,
      confirmed,
      sourceNode,
    });
    if (!relevant) continue;
    rows.push({
      ts,
      eventType,
      payload: normalizedPayload,
      txid,
      rawtx,
      node: sourceNode,
      height: 0,
      confirmed,
    });
  }
  if (!rows.length) {
    if (parsedEvents.length > 0) {
      appendMarketDebug('chain_rawtx_anchor_ignored', {
        txid,
        events: parsedEvents,
        sourceNode,
      });
    }
    return;
  }
  const events = normalizeAnchorRowsForSqlite(rows);
  if (events.length > 0) {
    await marketDb.upsertAnchorEvents(events);
  }
  if (rows.some((row) => /^chat_/i.test(String(row.eventType || '')) || String(row.eventType || '') === 'wallet_key_bind')) {
    scheduleChatAnchorBridge('chain_rawtx_router', 25);
  }
  for (const row of rows) {
    if (/^order_/i.test(String(row.eventType || ''))) {
      storeOrderTxContextFromRawtx(rawtx, {
        txid,
        source: sourceNode || 'chain.rawtx.seen',
        kind: row.eventType,
        confirmed,
        height: 0,
        node: sourceNode,
      });
    }
  }
  const hasOrderRows = rows.some((row) => /^order_/i.test(String(row.eventType || '')));
  if (hasOrderRows) {
    try {
      const req = buildRuntimeAuthReq();
      const state = buildProjectionBackedState(req);
      const orders = rebuildOrdersFromAnchors(state, req, {
        anchorRows: rows,
        includeUnconfirmedActionAnchors: true,
      });
      await marketDb.applyOrderProjectionBatch({
        orders: Array.isArray(orders) ? orders : [],
      });
      if (Array.isArray(orders) && orders.length > 0) {
        const changedOrderIds = new Set(rows
          .filter((row) => /^order_/i.test(String(row?.eventType || '')))
          .map((row) => deriveOrderIdFromAnchorRow(row))
          .filter(Boolean));
        for (const order of orders) {
          const orderId = String(order?.id || order?.orderId || '').trim();
          if (!orderId || (changedOrderIds.size > 0 && !changedOrderIds.has(orderId))) continue;
          frontendEventGateway?.publishInfo?.('order.updated', 'order', { order });
        }
        scheduleFrontendDomainBroadcast('order', 'chain_rawtx_order_projection_rebuilt', 50);
      }
      appendMarketDebug('chain_rawtx_order_projection_rebuilt', {
        txid,
        eventCount: rows.filter((row) => /^order_/i.test(String(row.eventType || ''))).length,
        sourceNode,
        persistedOrders: Array.isArray(orders) ? orders.length : 0,
      });
    } catch (error) {
      appendMarketDebug('chain_rawtx_order_projection_rebuild_failed', {
        txid,
        error: String(error?.message || error || 'order projection rebuild failed'),
      });
    }
    scheduleOrderAnchorProjectionRebuild('chain_rawtx_router', {
      txid,
      eventCount: rows.filter((row) => /^order_/i.test(String(row.eventType || ''))).length,
    });
  }
  let catalogProjectionApplied = 0;
  if (rows.some((row) => /^(category|product)_/i.test(String(row.eventType || '')))) {
    try {
      const applied = await applyCatalogAnchorRowsIncremental(rows, buildRuntimeAuthReq());
      catalogProjectionApplied = Math.max(0, Number(applied?.applied || 0));
    } catch (error) {
      appendMarketDebug('catalog_incremental_anchor_apply_failed', {
        txid,
        error: String(error?.message || error || 'catalog incremental apply failed'),
      });
      scheduleFrontendDomainBroadcast('catalog', 'catalog_incremental_apply_failed', 250);
    }
  }
  const nonCatalogEventTypes = rows
    .map((row) => String(row.eventType || '').trim())
    .filter((eventType) => !/^(category|product)_/i.test(eventType));
  if (nonCatalogEventTypes.length > 0) {
    scheduleMappedFrontendBroadcast('chain.rawtx.seen', 'chain_rawtx_anchor_persisted', 50, true, 'chain_rawtx_router', {
      txid,
      eventCount: nonCatalogEventTypes.length,
      eventTypes: nonCatalogEventTypes,
    });
  }
  appendMarketDebug('chain_rawtx_anchor_persisted', {
    txid,
    eventCount: rows.length,
    eventTypes: rows.map((row) => row.eventType),
    sourceNode,
    confirmed,
    catalogProjectionApplied,
  });
}

function ensureChainRawtxRouterSubscription() {
  if (chainRawtxRouterSubscribed) return;
  chainRawtxRouterSubscribed = true;
  messageQueue.subscribe('chain.rawtx.seen', (payload, meta) => {
    void handleObservedChainRawtx(payload, meta).catch((error) => {
      appendMarketDebug('chain_rawtx_router_failed', {
        txid: String(payload?.txid || ''),
        error: String(error?.message || error || 'chain rawtx router failed'),
      });
    });
  });
}

ensureChainRawtxRouterSubscription();

async function startServer({ port = PORT, host = '0.0.0.0' } = {}) {
  ensureDataVersion(DATA_DIR, {
    onProgress(event, payload) {
      if (event === 'migration_check_started') {
        console.log(`[data-migration] current=v${payload.currentVersion} target=v${payload.targetVersion} source=${payload.source}`);
        return;
      }
      if (event === 'migration_step_started') {
        console.log(`[data-migration] starting ${payload.label}`);
        return;
      }
      if (event === 'migration_step_completed') {
        console.log(`[data-migration] completed ${payload.label}`);
        return;
      }
      if (event === 'migration_step_failed') {
        console.error(`[data-migration] failed ${payload.label}: ${payload.message}`);
        return;
      }
      if (event === 'migration_check_completed' && payload.migrated) {
        console.log(`[data-migration] ready at v${payload.currentVersion} after ${payload.stepCount} step(s)`);
      }
    },
  });
  frontendEventGateway = createFrontendEventGatewayRuntime();
  ensureFrontendEventGatewaySubscriptions();
  scheduleChatAnchorBridge('startup', 250);
  try {
    await marketDb.ensureWriterService();
  } catch (error) {
    console.error('[market_db] failed to start writer', error?.message || error);
    throw error;
  }
  async function runDeferredStartupTasks() {
    try {
      await syncDomain.startSyncDomain({ adapters: buildSyncDomainAdapters() });
    } catch (error) {
      console.error('[sync_domain] failed to start', error?.message || error);
    }
    if (!DISABLE_STARTUP_CHAIN_SYNC) {
      try {
        await recoverStartupChainSyncState();
      } catch (_) {}
    }
    if (process.env.BSV_MARKET_DISABLE_BHS !== '1') {
      startEmbeddedBlockHeadersCore();
      startBhsDrivenSyncLoop();
    }
    if (!DISABLE_STARTUP_CHAIN_SYNC) scheduleStartupChainSyncEnqueue(1500);
    startSpvListenerMaintainLoop();
    if (process.env.BSV_MARKET_DISABLE_STEWARD_WORKER !== '1') startStewardWorker();
    if (process.env.BSV_MARKET_DISABLE_CATALOG_WORKER !== '1') startCatalogWorker();
    if (process.env.BSV_MARKET_DISABLE_CHAT_SERVICE !== '1') startChatServiceWorker();
    if (USE_VIEW_STATE_WORKER && process.env.BSV_MARKET_DISABLE_VIEW_STATE_WORKER !== '1') startViewStateWorker();
    else scheduleLocalPublicStateCacheRebuild('startup', 10);
    try {
      enforceCoreMemoryOnly(buildRuntimeAuthReq(), null, 'startup_core_memory');
    } catch (_) {}
  }
  const server = app.listen(port, host, () => {
    void (async () => {
      startEventLoopLagMonitor();
      try {
        loadPublicStateCache();
      } catch (_) {}
      console.log(`bsv_market server running: http://${host}:${port}`);
      scheduleFrontendSnapshotBroadcast('server_started', 25);
      setTimeout(() => {
        void runDeferredStartupTasks();
      }, 250);
    })().catch((error) => {
      console.error('[startup] runtime initialization failed', error?.message || error);
    });
  });
  const wsServer = WebSocketServer ? new WebSocketServer({ noServer: true }) : null;
  if (wsServer) {
    server.on('upgrade', (request, socket, head) => {
      const requestPath = String(request?.url || '').split('?')[0];
      if (requestPath !== FRONTEND_WS_PATH) return;
      const upgradeRes = {
        getHeader() { return undefined; },
        setHeader() {},
        end() {},
      };
      sessionMiddleware(request, upgradeRes, () => {
        wsServer.handleUpgrade(request, socket, head, (ws) => {
          const client = frontendEventGateway.attachClient(ws, request);
          const lastSeq = Number(request.headers['x-last-event-seq'] || 0);
          if (lastSeq > 0) frontendEventGateway.replayFrom(client, lastSeq);
          void frontendEventGateway.sendBootstrap(client, 'connect');
        });
      });
    });
  }
  const originalClose = server.close.bind(server);
  server.close = (callback) => {
    Promise.resolve()
      .then(() => {
        clearFrontendSnapshotBroadcastTimer();
        for (const domain of Array.from(frontendDomainBroadcastTimers.keys())) clearFrontendDomainBroadcastTimer(domain);
        clearLocalPublicStateCacheRebuildTimer();
        stopEventLoopLagMonitor();
        stopSpvListenerMaintainLoop();
        void syncDomain.stopSyncDomain('server_close').catch(() => {});
        stopStewardWorker();
        stopChatServiceWorker();
        stopViewStateWorker();
        try { wsServer?.close(); } catch (_) {}
        frontendEventGateway?.close?.();
        frontendEventGateway = null;
      })
      .then(() => marketDb.stopWriterService())
      .catch(() => {})
      .finally(() => {
        originalClose(callback);
      });
    return server;
  };
  return server;
}

if (require.main === module) {
  startServer({ port: PORT, host: '0.0.0.0' }).catch((error) => {
    console.error('[startup] server failed to start', error?.message || error);
    process.exit(1);
  });
}

