function getIndependentSyncDisplaySnapshot() {
  const fallback = {
    active: false,
    phase: '',
    activeNodeCount: 0,
    activeNodes: [],
    successNodeCount: 0,
    successNodes: [],
    localHeight: 0,
    targetHeight: 0,
    updatedAt: '',
  };
  const syncRow = loadSyncStateRowFromSqlite();
  const heartbeatSnapshot = readJsonFile(STEWARD_HEARTBEAT_FILE, null);
  const jobState = loadJobState();
  const currentJob = jobState?.currentJob && typeof jobState.currentJob === 'object' ? jobState.currentJob : null;
  const runtimeSnapshot = (() => {
    try {
      const syncRuntime = getIndependentSyncRuntime();
      return typeof syncRuntime?.loadStatus === 'function'
        ? syncRuntime.loadStatus()
        : null;
    } catch (_) {
      return null;
    }
  })();
  const active = Boolean(runtimeSnapshot?.active === true);
  const hasActiveSyncCommand = Boolean(
    currentJob
    && ['running', 'claimed', 'pending'].includes(String(currentJob?.status || 'running'))
    && ['run_chain_sync', 'rebuild_chain_indexes'].includes(String(currentJob?.jobType || '')),
  );
  if (!active && !hasActiveSyncCommand) {
    const localFloor = Math.max(
      0,
      Number(syncRow?.local_height || 0),
      Math.max(0, Number(syncRow?.bootstrap_height || FIXED_SYNC_BOOTSTRAP_HEIGHT) - 1),
    );
    return {
      active: false,
      phase: 'idle',
      activeNodeCount: 0,
      activeNodes: [],
      successNodeCount: 0,
      successNodes: [],
      localHeight: localFloor,
      targetHeight: 0,
      updatedAt: String(syncRow?.updated_at || heartbeatSnapshot?.ts || ''),
    };
  }
  const phase = String(runtimeSnapshot?.phase || heartbeatSnapshot?.phase || '');
  const updatedAtCandidates = [
    String(runtimeSnapshot?.updatedAt || ''),
    String(heartbeatSnapshot?.ts || ''),
  ].filter(Boolean);
  const updatedAt = updatedAtCandidates
    .slice()
    .sort((a, b) => {
      const ta = Date.parse(String(a || '')) || 0;
      const tb = Date.parse(String(b || '')) || 0;
      return tb - ta;
    })[0] || '';
  const localHeight = Math.max(
    0,
    Number(runtimeSnapshot?.localHeight || 0),
  );
  const targetHeight = Math.max(
    localHeight,
    Number(runtimeSnapshot?.targetHeight || 0),
    Number(syncRow?.p2p_tip_height || 0),
  );
  return {
    active,
    phase,
    activeNodeCount: Math.max(
      0,
      Number(runtimeSnapshot?.activeNodeCount || 0),
    ),
    activeNodes: Array.isArray(runtimeSnapshot?.activeNodes)
      ? runtimeSnapshot.activeNodes.slice()
      : [],
    successNodeCount: Math.max(
      0,
      Number(runtimeSnapshot?.successNodeCount || 0),
    ),
    successNodes: Array.isArray(runtimeSnapshot?.successNodes)
      ? runtimeSnapshot.successNodes.slice()
      : [],
    localHeight,
    targetHeight,
    updatedAt,
  };
}

function buildDisplaySyncSource(syncLike = {}, independentSync = null) {
  const base = syncLike && typeof syncLike === 'object' ? { ...syncLike } : {};
  const live = independentSync && typeof independentSync === 'object' ? independentSync : null;
  if (!live) return base;
  if (!base.lastP2PAdvanceAt && live.updatedAt) base.lastP2PAdvanceAt = String(live.updatedAt || '');
  return base;
}
